window.STORY=[{"n":1,"title":"桜の枝","sub":"幼稚園編","era":"kinder","lead":"耀平は4歳で両親を亡くし、祖父と暮らしながら剣聖に憧れ、年長のスキル判定で「一花心舞」と笑われる。","scenes":[{"key":"1-1","title":"祖父の家","bg":"bg_grandpa_house","dark":false,"mood":"soft","bgm":"soft2","cast":["yohei"],"lines":[{"t":"n","s":"四歳の春、耀平は小さなリュックを背負って、祖父の家の玄関に立っていた。","f":"yohei"},{"t":"n","s":"両親が事故で亡くなったのは、つい先週のことだ。まだ四歳の耀平には、「いない」という言葉の重さが、うまく掴めていなかった。ただ、家に帰っても、誰も「おかえり」と言わない。それだけは分かっていた。","f":"yohei"},{"t":"d","s":"「……腹は減っとらんか」","f":"yohei"},{"t":"n","s":"祖父は、不器用な声で言った。皺だらけの手が、靴箱の上で行き場を失っている。","f":"yohei"},{"t":"d","s":"「ううん」","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"n","s":"会話は、それで終わった。祖父は剣のことも、スキルのことも、何も知らない普通の老人だ。どう接していいか分からないまま、耀平の隣に黙って座り続けた。","f":"yohei"},{"t":"n","s":"その夜、耀平は祖父の布団の端で、小さく丸くなって眠った。祖父は一晩中、眠らずに、その背中を見ていた。","f":"yohei"}]},{"key":"1-2","title":"乃亜の家のごはん","bg":"bg_grandpa_house","dark":false,"mood":"soft","bgm":"soft3","cast":["noa","yohei"],"lines":[{"t":"n","s":"歩いて二分のところに、乃亜の家があった。","f":"noa"},{"t":"d","s":"「あら、耀平くん。ごはん、食べていきなさい」","f":"noa"},{"t":"n","s":"乃亜の母に手を引かれ、耀平は食卓についた。味噌汁の湯気。焼き魚。祖父の家では見ない、にぎやかな食卓だ。","f":"noa"},{"t":"n","s":"向かいの席で、同い年の乃亜が、じっと耀平を見ていた。口数の少ない子だ。大きな目だけが、よく動く。","f":"noa"},{"t":"d","s":"「……なに？」","f":"noa"},{"t":"d","s":"「べつに」","f":"noa"},{"t":"n","s":"乃亜は目を逸らし、魚をほぐし始めた。そして、小さな声で言った。","f":"noa"},{"t":"d","s":"「さかな、ほね、とってあげる」","f":"noa"},{"t":"d","s":"「いいの？」","f":"noa"},{"t":"d","s":"「……ちゃんと、たべなよ」","f":"noa"},{"t":"n","s":"耀平は、こくんとうなずいた。その日から、夕方になると、耀平の足は自然と乃亜の家に向かうようになった。","f":"yohei"}]},{"key":"1-3","title":"テレビの中の剣聖","bg":"bg_grandpa_house","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei"],"lines":[{"t":"cg","v":"cg_tv_kensei"},{"t":"n","s":"五歳になる少し前。祖父の家の居間で、耀平はひとりでテレビを見ていた。","f":"yohei"},{"t":"n","s":"画面には、一人の男が映っていた。刀を腰に差し、静かに立っている。周りには荒れた街。そして、凶器を振り回す男が一人。","f":"yohei"},{"t":"d","s":"『剣聖だ！　剣聖が来たぞ！』","f":"yohei"},{"t":"n","s":"悲鳴のような歓声が上がる。","f":"yohei"},{"t":"n","s":"剣聖は、走らなかった。ただ、一歩、踏み出した。","f":"yohei"},{"t":"n","s":"次の瞬間、悪者の凶器が真っ二つに折れて、地面に落ちた。悪者は、何が起きたか分からない顔で、その場に崩れ落ちる。","f":"yohei"},{"t":"n","s":"耀平は、息をするのを忘れていた。","f":"yohei"},{"t":"d","s":"「……かっこいい」","f":"yohei"},{"t":"n","s":"その声は、自分でも驚くほど、はっきり出た。","f":"yohei"},{"t":"n","s":"気がつくと、耀平は庭に飛び出していた。落ちていた桜の枝を拾い、さっき見た剣聖と同じように構える。","f":"yohei"},{"t":"d","s":"「えいっ」","f":"yohei"},{"t":"n","s":"びゅん、と枝が空を切った。まだ、へなへなの音だった。","f":"yohei"},{"t":"d","s":"「えいっ。えいっ」","f":"yohei"},{"t":"n","s":"縁側で、祖父が黙って茶を啜っていた。何か言いたそうに口を開き、閉じ、また開いて、結局こう言った。","f":"yohei"},{"t":"d","s":"「……腹が減ったら、言いなさい」","f":"yohei"},{"t":"n","s":"祖父は、剣のことを何も知らない。教えてやれることは、何もない。だから、ただ見ていることにした。孫が、初めて自分から動き出したのだから。","f":"yohei"}]},{"key":"1-4","title":"竜馬","bg":"bg_kindergarten","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","ryoma","noa"],"lines":[{"t":"cg","v":"cg_sakura_branch"},{"t":"n","s":"公園の隅で、耀平が枝を振っていると、背後から声がした。","f":"yohei"},{"t":"d","s":"「おまえ、なにやってんだ」","f":"yohei"},{"t":"n","s":"振り向くと、同じ組の竜馬が立っていた。声が大きく、いつも誰かと喧嘩している男の子だ。","f":"ryoma"},{"t":"d","s":"「……けん」","f":"ryoma"},{"t":"d","s":"「けん？」","f":"ryoma"},{"t":"d","s":"「けんせい、みた。かっこよかった」","f":"ryoma"},{"t":"n","s":"竜馬は、枝と耀平の顔を、交互に見た。それから、耀平がもう一度振るのを、じっと見た。","f":"ryoma"},{"t":"n","s":"びゅん。さっきより、少しだけ鋭い音がした。","f":"ryoma"},{"t":"d","s":"「……いまの、すげえ」","f":"ryoma"},{"t":"d","s":"「ほんと？」","f":"ryoma"},{"t":"d","s":"「ほんと！　おれにもやらせろ！」","f":"ryoma"},{"t":"n","s":"竜馬は、足元の枝を拾って振り回し始めた。三回振って、自分の足を叩いて、「いてっ」と叫ぶ。耀平は、思わず笑った。","f":"ryoma","m":"happy"},{"t":"n","s":"そこへ、砂場の方から、乃亜が歩いてきた。","f":"noa"},{"t":"d","s":"「……なにしてるの」","f":"noa"},{"t":"d","s":"「けんせいごっこ！　耀平、めちゃくちゃつよいんだぞ！」","f":"noa"},{"t":"n","s":"竜馬が、なぜか自慢げに胸を張る。乃亜は耀平を見て、小さく言った。","f":"ryoma"},{"t":"d","s":"「……ふーん」","f":"ryoma"},{"t":"n","s":"その目は、少しだけ、笑っていた。","f":"ryoma"}]},{"key":"1-5","title":"スキル判定の日","bg":"bg_kindergarten","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"年長の秋。幼稚園の遊戯室に、組の全員が集められた。"},{"t":"d","s":"「みんな、今日は、スキルを調べる日です。ひとりずつ、前に出てきてね」"},{"t":"n","s":"先生が、透明な水晶玉を台の上に置く。手をかざすと、その子のスキルが形になって現れる。"},{"t":"n","s":"最初は竜馬だった。","f":"ryoma"},{"t":"d","s":"「いくぜ！」","f":"ryoma"},{"t":"n","s":"水晶玉に手をかざすと、赤い光が弾けた。手のひらの上に、ぼっ、と小さな炎が灯る。","f":"ryoma"},{"t":"d","s":"「紅蓮爆炎、ですね。すごい、強いスキルよ」","f":"ryoma"},{"t":"d","s":"「やった！　おれ、つえー！」","f":"ryoma"},{"t":"n","s":"歓声が上がる。竜馬は、鼻の下を擦って、耀平のほうを振り向いた。","f":"ryoma"},{"t":"d","s":"「耀平！　つぎ、おまえだぞ！　ぜったい、おれよりすげーやつだ！」","f":"ryoma"},{"t":"n","s":"次は乃亜だった。水晶玉に、青い光が滲む。空中に、小さな水の珠が、ふわりと浮かんだ。","f":"noa"},{"t":"d","s":"「碧水心希。きれいなスキルね」","f":"noa"},{"t":"n","s":"乃亜は何も言わず、ちょっとだけ頬を赤くして、耀平の隣に戻ってきた。","f":"noa"},{"t":"d","s":"「……つぎ、がんばって」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"そして、耀平の番になった。","f":"yohei"},{"t":"n","s":"水晶玉に、手をかざす。","f":"yohei"},{"t":"n","s":"……何も、起きなかった。","f":"yohei"},{"t":"n","s":"一秒。二秒。","f":"yohei"},{"t":"n","s":"やがて、ふわり、と何かが宙を舞った。","f":"yohei"},{"t":"n","s":"桜の花びらが、たった一枚。","f":"yohei"},{"t":"n","s":"ひらひらと揺れながら、床に落ちた。それきり、何も起きない。","f":"yohei"},{"t":"d","s":"「えっと……一花心舞、ですね」","f":"yohei"},{"t":"n","s":"先生が、困ったように言った。","f":"yohei"},{"t":"n","s":"どっと、笑い声が起きた。","f":"yohei"},{"t":"d","s":"「それだけ？」","f":"yohei"},{"t":"d","s":"「はなびら、いちまいだけ！」","f":"yohei"},{"t":"d","s":"「しょぼーい！」","f":"yohei"},{"t":"n","s":"耀平は、床に落ちた花びらを、じっと見ていた。笑われていることは、分かった。でも、不思議と悲しくはなかった。花びらが落ちる直前、肩に触れたとき、体が、ほんの少し、軽く感じたからだ。","f":"yohei"},{"t":"d","s":"「……なんだよ、それ」","f":"yohei"},{"t":"n","s":"低い声がした。竜馬だった。さっきまで輝いていた目から、光が消えている。","f":"ryoma"},{"t":"d","s":"「ぜったいすげーって、いったのに」","f":"ryoma"},{"t":"d","s":"「りょうま……」","f":"ryoma"},{"t":"d","s":"「おれ、おまえのことかっこいいと思ってたのに……そんなの、なんにもつよくないじゃんか！」","f":"ryoma"},{"t":"n","s":"竜馬は、そう叫んで、遊戯室を飛び出した。","f":"ryoma"},{"t":"n","s":"遊戯室が、静まり返る。","f":"ryoma"},{"t":"n","s":"そのとき、隣で、小さな声がした。","f":"ryoma"},{"t":"d","s":"「……きれい」","f":"ryoma"},{"t":"n","s":"乃亜だった。まっすぐに、床の花びらを見ていた。","f":"noa"},{"t":"d","s":"「ひとひらだけ、きれい」","f":"noa"},{"t":"n","s":"笑い声が、少しだけ、小さくなった。耀平は、乃亜の顔を見た。乃亜は、ふいと目を逸らして、耳まで赤くしていた。","f":"yohei"},{"t":"d","s":"「……べつに、ほんとのこと、いっただけ」","f":"yohei"}]},{"key":"1-6","title":"卒園まで","bg":"bg_kindergarten","dark":false,"mood":"soft","bgm":"soft3","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"それから、竜馬は耀平に話しかけなくなった。","f":"ryoma"},{"t":"n","s":"公園に行っても、竜馬は他の子たちと走り回るだけで、耀平の方を見ない。耀平も、何も言わなかった。","f":"ryoma"},{"t":"n","s":"ただ、毎日、枝を振った。","f":"ryoma"},{"t":"n","s":"朝、庭で。夕方、公園の隅で。雨の日は、縁側で。","f":"ryoma"},{"t":"n","s":"祖父は、何も言わずに、温かい麦茶を置いていく。","f":"ryoma"},{"t":"d","s":"「……すこし、力が入りすぎとる」","f":"ryoma"},{"t":"n","s":"ある日、祖父がぽつりと言った。","f":"ryoma"},{"t":"d","s":"「おじいちゃん、けんのこと、わかるの？」","f":"ryoma"},{"t":"d","s":"「いや、ちっとも分からん。ただ、おまえの背中を見とると、そんな気がしただけじゃ」","f":"ryoma"},{"t":"n","s":"耀平は少し考えてから、肩の力を抜いて、もう一度振った。","f":"yohei"},{"t":"n","s":"びゅん。","f":"yohei"},{"t":"n","s":"いい音がした。縁側の祖父が、小さく目を細めた。","f":"yohei"},{"t":"n","s":"卒園式の日。園庭の桜が、満開だった。","f":"yohei"},{"t":"n","s":"乃亜が、耀平の隣に並んで、花びらを見上げた。","f":"noa"},{"t":"d","s":"「ようへい」","f":"noa"},{"t":"d","s":"「なに？」","f":"noa"},{"t":"d","s":"「……がんばってね」","f":"noa"},{"t":"d","s":"「なにを？」","f":"noa"},{"t":"d","s":"「それは、じぶんで、かんがえて」","f":"noa"},{"t":"n","s":"乃亜はそう言って、つんと顔を逸らした。耀平は首を傾げながらも、笑った。","f":"noa","m":"happy"},{"t":"n","s":"桜の枝が、風に揺れた。","f":"noa"},{"t":"n","s":"その枝の先から、花びらが一枚、ひらりと舞った。","f":"noa"}]}]},{"n":2,"title":"入学式と運動会","sub":"小学校・低学年","era":"elem","lead":"耀平は乃亜と同じ教室で眠そうに過ごし、竜馬は少しだけ遠くなる。","scenes":[{"key":"2-1","title":"入学式","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"満開の桜の下を、三人は歩いていた。"},{"t":"n","s":"真新しいランドセルが、背中でかたかたと鳴る。六歳の春。耀平の隣には乃亜がいて、少し先を、竜馬が一人で歩いている。","f":"yohei"},{"t":"d","s":"「……りょうま、まってくれないね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「いいの？」","f":"yohei"},{"t":"d","s":"「べつに。かってに、いくから」","f":"yohei"},{"t":"n","s":"耀平は眠そうに目をこすった。今朝も夜明け前から、庭で枝を振っていたせいだ。少し後ろを、祖父が黙ってついてくる。着慣れない背広の袖を、時々引っ張りながら。","f":"yohei"},{"t":"n","s":"校門の前で、別の幼稚園から来た男の子たちが、こちらを指さした。","f":"yohei"},{"t":"d","s":"「あいつだよ。スキル、はなびらいちまいのやつ」","f":"yohei"},{"t":"d","s":"「えー、しょぼ。ほんとに？」","f":"yohei"},{"t":"n","s":"くすくすと笑う声。耀平は、聞こえていないように、ぼんやりと空を見ていた。","f":"yohei","m":"happy"},{"t":"n","s":"乃亜が、ぴたりと足を止めた。くるりと振り向いて、男の子たちをじっと見る。大きな目で、まばたきもせずに。","f":"noa"},{"t":"d","s":"「……なに？」","f":"noa"},{"t":"d","s":"「な、なんだよ」","f":"noa"},{"t":"d","s":"「いま、なんていったの」","f":"noa"},{"t":"d","s":"「べ、べつに……」","f":"noa"},{"t":"d","s":"「もういっかい、いって」","f":"noa"},{"t":"n","s":"低い声だった。六歳とは思えない、静かな圧があった。男の子たちは顔を見合わせて、そそくさと逃げていった。","f":"noa"},{"t":"d","s":"「乃亜」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「こわいよ」","f":"noa"},{"t":"d","s":"「……うるさい」","f":"noa"},{"t":"n","s":"乃亜は前を向いて、ずんずん歩き出した。耳が、少しだけ赤かった。","f":"noa"}]},{"key":"2-2","title":"ねむい日々","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"一年一組の教室。窓から入る日差しが、あたたかい。"},{"t":"d","s":"「では、この問題が分かる人」"},{"t":"n","s":"先生の声が、遠くで聞こえる。耀平の瞼が、ゆっくり落ちていく。","f":"yohei"},{"t":"d","s":"「……耀平くん？　耀平くん！」","f":"yohei"},{"t":"n","s":"ごつん、と、隣の席から肘が飛んできた。","f":"yohei"},{"t":"d","s":"「いたっ」","f":"yohei"},{"t":"d","s":"「あてられてる」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「……さんたす、に」","f":"yohei"},{"t":"d","s":"「に？」","f":"yohei"},{"t":"d","s":"「ばか」","f":"yohei"},{"t":"n","s":"乃亜が小声で答えを教える。耀平は慌てて立ち上がり、「に、です」と答えた。教室がくすくす笑う。","f":"noa","m":"happy"},{"t":"n","s":"先生は苦笑して言った。","f":"noa","m":"sweat"},{"t":"d","s":"「耀平くん、昨日は夜更かししたのかな？」","f":"noa"},{"t":"d","s":"「いえ。あさ、はやかったです」","f":"noa"},{"t":"d","s":"「朝？」","f":"noa"},{"t":"d","s":"「けんを、ふってました」","f":"noa"},{"t":"n","s":"教室が、しんとなった。それから誰かが、小さく吹き出した。","f":"noa"},{"t":"d","s":"「はなびらのひとなのに、けん？」","f":"noa"},{"t":"n","s":"乃亜が、机の下で耀平の足を踏んだ。","f":"noa"},{"t":"d","s":"「いたい」","f":"noa"},{"t":"d","s":"「しゃべりすぎ」","f":"noa"},{"t":"n","s":"放課後の廊下で、耀平は竜馬とすれ違った。一瞬、目が合う。竜馬はむっとした顔で、ふいと視線を逸らして行ってしまった。","f":"yohei"},{"t":"d","s":"「……りょうま」","f":"yohei"},{"t":"d","s":"「ほうっておけば」","f":"yohei"},{"t":"n","s":"乃亜が言った。","f":"noa"},{"t":"d","s":"「でも」","f":"noa"},{"t":"d","s":"「あっちが、むかしのことで、すねてるだけ」","f":"noa"},{"t":"d","s":"「すねてるの？」","f":"noa"},{"t":"d","s":"「ぜったい、そう」","f":"noa"},{"t":"n","s":"乃亜は、少し間を置いて、付け加えた。","f":"noa"},{"t":"d","s":"「……りょうまは、ほんとは、さびしいだけだよ」","f":"noa"},{"t":"n","s":"耀平には、よく分からなかった。ただ、その言葉だけは、なぜか胸に残った。","f":"yohei"}]},{"key":"2-3","title":"運動会","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["ryoma","noa","yohei"],"lines":[{"t":"n","s":"秋。運動会の日は、からりと晴れた。"},{"t":"n","s":"校庭には、色とりどりの旗。保護者席の隅で、祖父が膝にお重を抱えて座っている。隣では乃亜の母が、手を振っていた。","f":"noa"},{"t":"d","s":"「耀平くーん！　がんばってー！」","f":"noa"},{"t":"d","s":"「おじいさん、お茶をどうぞ」","f":"noa"},{"t":"d","s":"「……すまん」","f":"noa"},{"t":"n","s":"祖父は、なぜか居心地悪そうに、湯呑みを受け取った。","f":"noa"},{"t":"n","s":"徒競走の順番が来た。スタートラインに並ぶ六人。その中に、竜馬と、耀平がいた。","f":"ryoma"},{"t":"d","s":"「いちについて」","f":"ryoma"},{"t":"n","s":"竜馬が、ちらりと耀平を見た。何か言いたそうな顔だ。けれど、結局、何も言わずに前を向いた。","f":"ryoma"},{"t":"d","s":"「よーい、どん！」","f":"ryoma"},{"t":"n","s":"竜馬は、弾丸のように飛び出した。小さな体で地面を蹴る音が、聞こえるほどの勢い。炎のような走りだった。","f":"ryoma"},{"t":"n","s":"耀平はといえば、眠そうに、とことこと走っていた。","f":"yohei"},{"t":"n","s":"結果は、竜馬が一位。耀平は四位。","f":"ryoma"},{"t":"d","s":"「やったー！　おれ、いちばんだ！」","f":"ryoma"},{"t":"n","s":"竜馬は、旗を高く掲げて叫んだ。歓声が上がる。ゴールを出た耀平のところに、乃亜が駆け寄ってきた。むすっとした顔で。","f":"ryoma"},{"t":"d","s":"「ようへい」","f":"ryoma"},{"t":"d","s":"「なに？」","f":"ryoma"},{"t":"d","s":"「ちゃんと、はしって」","f":"ryoma"},{"t":"d","s":"「ちゃんと、はしった」","f":"ryoma"},{"t":"d","s":"「うそ。ねむそうだった」","f":"ryoma"},{"t":"d","s":"「ねむかった」","f":"ryoma"},{"t":"d","s":"「ばか」","f":"ryoma"},{"t":"n","s":"乃亜は、ぷいと顔を背けた。けれど、そのあと小さく付け加える。","f":"noa"},{"t":"d","s":"「……けが、してない？」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「ならいい」","f":"noa"},{"t":"n","s":"そのとき、竜馬が、旗を持ったままこちらに歩いてきた。","f":"ryoma"},{"t":"d","s":"「おい、乃亜」","f":"ryoma"},{"t":"d","s":"「なに」","f":"ryoma"},{"t":"d","s":"「み、みてたか？　おれ、いちばんだったろ」","f":"ryoma"},{"t":"d","s":"「……うん。みてた。おめでとう」","f":"ryoma"},{"t":"n","s":"乃亜が、ほんの少しだけ、口の端を上げて言った。竜馬の顔が、ぱっと赤くなる。","f":"noa"},{"t":"d","s":"「べ、べつに、おまえのためにはしったんじゃねーし！　かんちがいすんなよ！」","f":"noa"},{"t":"d","s":"「してないよ」","f":"noa"},{"t":"d","s":"「してねーならいいけど！」","f":"noa"},{"t":"n","s":"竜馬は、旗をぶんぶん振りながら、逃げるように走っていった。耀平は、その背中を見ながら、首をかしげた。","f":"ryoma"},{"t":"d","s":"「りょうま、なんであかいの？」","f":"ryoma"},{"t":"d","s":"「しらない」","f":"ryoma"},{"t":"d","s":"「あついのかな」","f":"ryoma"},{"t":"n","s":"乃亜は、深いため息をついた。","f":"noa"},{"t":"d","s":"「……ようへいは、ほんとに、ばか」","f":"noa"},{"t":"n","s":"お昼になった。祖父のお重には、不揃いなおにぎりが、ぎっしり詰まっていた。","f":"noa"},{"t":"d","s":"「……すまん。うまく、にぎれんかった」","f":"noa"},{"t":"d","s":"「おじいちゃん、おいしいよ」","f":"noa"},{"t":"d","s":"「……そうか」","f":"noa"},{"t":"n","s":"祖父は、そっぽを向いて茶を啜った。耳の先が、少し赤かった。","f":"noa","m":"blush"},{"t":"n","s":"乃亜も、一つもらって、じっと眺めた。","f":"noa"},{"t":"d","s":"「……おおきい」","f":"noa"},{"t":"d","s":"「いや、か？」","f":"noa"},{"t":"d","s":"「ううん。おいしい」","f":"noa"},{"t":"n","s":"祖父が、湯呑みを持つ手を、小さく震わせた。","f":"noa"}]},{"key":"2-4","title":"帰り道","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","noa"],"lines":[{"t":"cg","v":"cg_walk_home3"},{"t":"n","s":"夕焼けの道を、耀平と乃亜は並んで歩いていた。","f":"yohei"},{"t":"d","s":"「りょうま、はやかったね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「かっこよかった」","f":"yohei"},{"t":"d","s":"「……ふーん」","f":"yohei"},{"t":"n","s":"乃亜は、石ころを蹴った。","f":"noa"},{"t":"d","s":"「ようへいだって、かっこいいよ」","f":"noa"},{"t":"d","s":"「え」","f":"noa"},{"t":"d","s":"「けんふってる、とき」","f":"noa"},{"t":"d","s":"「ほんと？」","f":"noa"},{"t":"d","s":"「……べつに。みたまま、いっただけ」","f":"noa"},{"t":"n","s":"耀平は、ぽかんとして、それから、ふわっと笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"d","s":"「おれいは、いらない」","f":"yohei"},{"t":"n","s":"乃亜は、顔を前に向けたまま、歩く速度を少しだけ上げた。","f":"noa"},{"t":"n","s":"夕焼けの空に、桜はもう、咲いていなかった。それでも、耀平の肩のあたりを、一枚だけ、季節外れの花びらが、ふわりと舞って消えた。","f":"yohei"},{"t":"n","s":"誰も、それには気づかなかった。","f":"yohei"}]}]},{"n":3,"title":"夏祭りと遠足のお弁当","sub":"小学校・中学年","era":"elem","lead":"乃亜の照れと、竜馬の言えない気持ちが、少しずつ積もっていく。","scenes":[{"key":"3-1","title":"夏祭り","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft4","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"三年生の夏。神社の境内は、提灯の灯りと人の声でいっぱいだった。"},{"t":"d","s":"「おじいちゃん、りんごあめ、ほしい」"},{"t":"d","s":"「ああ、買ってやろう。……いくらじゃ」"},{"t":"d","s":"「えっと、にひゃくえん」"},{"t":"n","s":"祖父は財布を開いて、小銭をじっと数えた。祭りに来るのは、十年ぶりだという。"},{"t":"n","s":"そこへ、からん、ころん、と下駄の音が近づいてきた。"},{"t":"d","s":"「……耀平」"},{"t":"cg","v":"cg_yukata"},{"t":"n","s":"振り向くと、乃亜が立っていた。紺地に金魚の柄の浴衣。髪には、小さな花の飾り。いつもと違う姿に、乃亜は居心地悪そうに袖をつまんでいる。","f":"noa"},{"t":"n","s":"耀平は、じっと乃亜を見て、言った。","f":"yohei"},{"t":"d","s":"「あつそう」","f":"yohei"},{"t":"d","s":"「……は？」","f":"yohei"},{"t":"d","s":"「それ、あつそう」","f":"yohei"},{"t":"n","s":"乃亜の眉が、ぴくりと動いた。","f":"noa"},{"t":"d","s":"「それだけ？」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"乃亜は、ぷいと顔を背けて、すたすた歩き出した。耀平は、なぜ怒られたのか分からずに首をかしげる。その背中を見ながら、祖父が、ごほん、と咳をした。","f":"noa"},{"t":"d","s":"「耀平」","f":"noa"},{"t":"d","s":"「なに？」","f":"noa"},{"t":"d","s":"「ああいうときは、似合っとる、と言うもんじゃ」","f":"noa"},{"t":"d","s":"「にあってるって？」","f":"noa"},{"t":"d","s":"「そうじゃ」","f":"noa"},{"t":"d","s":"「……そうなの？」","f":"noa"},{"t":"n","s":"耀平は、少し考えてから、小走りで乃亜を追いかけた。","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「なに」","f":"yohei"},{"t":"d","s":"「にあってる」","f":"yohei"},{"t":"d","s":"「……いまさら、おそい」","f":"yohei"},{"t":"n","s":"そう言いながらも、乃亜は振り向かなかった。ただ、浴衣の袖から覗く耳が、提灯の光よりも赤かった。","f":"noa"},{"t":"n","s":"屋台を回った。金魚すくいで、乃亜は一匹も取れずに紙を破いた。射的で、耀平は一発も当たらなかった。りんごあめを二人で一つずつ舐めながら歩いていると、背後から声がした。","f":"noa"},{"t":"d","s":"「おまえら、きてたのか」","f":"noa"},{"t":"n","s":"竜馬が、友達三人と立っていた。その視線が、乃亜の浴衣にぶつかって、固まる。","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「なに」","f":"ryoma"},{"t":"d","s":"「な、なんでもねえ」","f":"ryoma"},{"t":"d","s":"「竜馬くん、どうしたの？　顔、まっかだよ」","f":"ryoma"},{"t":"d","s":"「うるせえ！　あつかっただけだ！」","f":"ryoma"},{"t":"n","s":"友達に囲まれて、竜馬は走って人混みへ消えた。","f":"ryoma"},{"t":"d","s":"「竜馬、へんなの」","f":"ryoma"},{"t":"d","s":"「……ほんとに、ばか」","f":"ryoma"},{"t":"d","s":"「おれ？」","f":"ryoma"},{"t":"d","s":"「どっちも」","f":"ryoma"},{"t":"n","s":"夜空に、ひゅう、と細い音が昇った。ドン、と大きな花が咲く。","f":"ryoma"},{"t":"d","s":"「きれい」","f":"ryoma"},{"t":"n","s":"乃亜が、ぽつりと言った。耀平は、返事をしなかった。見ると、眠そうに、こくり、こくり、と頭を揺らしている。","f":"noa"},{"t":"d","s":"「……耀平。ねてる」","f":"noa"},{"t":"d","s":"「ねてない」","f":"noa"},{"t":"d","s":"「ねてる」","f":"noa"},{"t":"d","s":"「ねて……」","f":"noa"},{"t":"n","s":"こて、と、耀平の頭が、乃亜の肩に落ちた。","f":"yohei"},{"t":"n","s":"乃亜は、固まった。心臓の音が、花火よりうるさく聞こえる。","f":"noa"},{"t":"d","s":"「ち、ちょっと……」","f":"noa"},{"t":"d","s":"「……すう」","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"けれど、乃亜は、そのまま動かなかった。花火が終わるまで、ずっと。","f":"noa"},{"t":"n","s":"少し離れた場所で、祖父が麦茶を飲みながら、その様子を静かに見ていた。","f":"noa"},{"t":"d","s":"「……ええ友達を持ったのう」","f":"noa"},{"t":"n","s":"誰にともなく、祖父はつぶやいた。","f":"noa"}]},{"key":"3-2","title":"遠足のお弁当","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"四年生の秋、遠足。バスの中で、竜馬は後ろの席から、前の席の乃亜をちらちらと気にしていた。","f":"ryoma"},{"t":"n","s":"昼になると、広い芝生に、みんながレジャーシートを広げた。耀平が寝転がろうとしたそのとき、乃亜が、ぶっきらぼうに弁当箱を差し出した。","f":"yohei"},{"t":"d","s":"「……ん」","f":"yohei"},{"t":"d","s":"「なに？」","f":"yohei"},{"t":"d","s":"「べんとう。あげる」","f":"yohei"},{"t":"d","s":"「乃亜のお母さんの？」","f":"yohei"},{"t":"d","s":"「ちがう。わたしの」","f":"yohei"},{"t":"n","s":"耀平は目をまたたいた。蓋を開けると、少し形の崩れたおにぎりと、焦げ目のついた玉子焼き、いびつなタコさんウインナー。","f":"yohei"},{"t":"d","s":"「……乃亜がつくったの？」","f":"yohei"},{"t":"d","s":"「よ、よけいなこと、きかなくていい」","f":"yohei"},{"t":"d","s":"「すごい」","f":"yohei"},{"t":"d","s":"「べつに。きのう、ひまだったから、つくっただけ」","f":"yohei"},{"t":"d","s":"「あまったの？」","f":"yohei"},{"t":"d","s":"「そう。あまった。たまたま」","f":"yohei"},{"t":"n","s":"本当は、前の晩、母に頼んで三時間つきっきりで教わった。玉子焼きは、五回失敗した。でも、そんなことは、絶対に言わない。","f":"yohei"},{"t":"n","s":"耀平は、玉子焼きを口に入れた。","f":"yohei"},{"t":"d","s":"「……おいしい」","f":"yohei"},{"t":"d","s":"「ほんと？」","f":"yohei"},{"t":"d","s":"「うん。しょっぱいけど、おいしい」","f":"yohei"},{"t":"d","s":"「しょっぱいは、よけい」","f":"yohei"},{"t":"n","s":"乃亜は、むっとした。けれど、口元が緩んでいる。","f":"noa"},{"t":"d","s":"「おれ、これ、すき」","f":"noa"},{"t":"d","s":"「……そう。ならいい」","f":"noa"},{"t":"n","s":"乃亜は、自分の弁当を開けた。母が作った、綺麗な弁当だ。そっちは、わざと見せなかった。","f":"noa"},{"t":"n","s":"少し離れた木の陰で、竜馬が、その様子を見ていた。母の作った弁当を、無言で口に運ぶ。味が、よく分からなかった。","f":"ryoma"},{"t":"d","s":"「……いいなあ」","f":"ryoma"},{"t":"n","s":"小さく漏れた声は、誰にも聞こえなかった。","f":"ryoma"}]},{"key":"3-3","title":"バレンタイン","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft2","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"四年生の冬。二月十四日。乃亜の机の上には、チョコの山ができていた。女子からの友チョコが半分。残りの半分は、顔を真っ赤にした男子たちが、そっと置いていったものだ。","f":"noa"},{"t":"d","s":"「のあちゃん、すごい……」","f":"noa"},{"t":"d","s":"「べつに」","f":"noa"},{"t":"n","s":"乃亜は、無表情で、紙袋にチョコを詰めていく。そして、その中から、小さな包みを一つだけ取り出して、耀平の席に歩いてきた。","f":"noa"},{"t":"d","s":"「耀平。ん」","f":"noa"},{"t":"n","s":"包みが、ぽいと机に放られた。","f":"noa"},{"t":"d","s":"「なに？」","f":"noa"},{"t":"d","s":"「ぎり」","f":"noa"},{"t":"d","s":"「ぎり？」","f":"noa"},{"t":"d","s":"「ぎりちょこ。みんなにあげてるの」","f":"noa"},{"t":"d","s":"「そうなんだ。ありがとう」","f":"noa"},{"t":"n","s":"耀平は素直に受け取って、包みを開けた。小さなハート型のチョコだった。形は不揃いで、ところどころ欠けている。","f":"yohei"},{"t":"d","s":"「……みんなにあげてるにしては、ていねいだね」","f":"yohei"},{"t":"d","s":"「う、うるさい！」","f":"yohei"},{"t":"n","s":"乃亜は、真っ赤になって走っていった。","f":"noa"},{"t":"n","s":"廊下の隅で、竜馬が、その一部始終を見ていた。ポケットの中には、昨日、小遣いで買ったチョコが入っている。何度も渡そうと思って、何度も手が止まった。","f":"ryoma"},{"t":"n","s":"そこへ、乃亜が通りかかった。","f":"noa"},{"t":"d","s":"「竜馬」","f":"noa"},{"t":"d","s":"「お、おう」","f":"noa"},{"t":"d","s":"「ん。ぎり」","f":"noa"},{"t":"n","s":"同じような小さな包みが、竜馬の手に押し付けられた。","f":"ryoma"},{"t":"d","s":"「……さ、さんきゅ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"乃亜は、それだけ言って、教室に戻っていった。竜馬は、しばらくその場に立ち尽くしていた。やがて、ポケットの中のチョコを、ぎゅっと握りしめる。","f":"noa"},{"t":"d","s":"「……へたくそ」","f":"noa"},{"t":"n","s":"自分に言い聞かせるように呟いて、包みを押し込んだ。渡せなかったチョコは、ポケットの中で、少しだけ溶けていた。","f":"noa"},{"t":"n","s":"その夜、耀平は、祖父の前でチョコを広げた。","f":"yohei"},{"t":"d","s":"「……誰からじゃ」","f":"yohei"},{"t":"d","s":"「乃亜。ぎりだって」","f":"yohei"},{"t":"d","s":"「ほう。ぎりにしては、ていねいじゃのう」","f":"yohei"},{"t":"d","s":"「ぼくもそう思った」","f":"yohei"},{"t":"n","s":"二人は、小さなハートを半分に割って、黙って口に入れた。苦くて、少し甘かった。","f":"yohei"}]}]},{"n":4,"title":"木刀選び、林間学校、クリスマス","sub":"小学校・高学年","era":"elem","lead":"五年生の耀平は、はじめて自分の刀を手にする。そして、竜馬の視線が少しずつ尖っていく。","scenes":[{"key":"4-1","title":"木刀選び","bg":"bg_grandpa_house","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei"],"lines":[{"t":"n","s":"五年生の春。祖父は、耀平を連れて、町外れの古い道具屋を訪ねた。","f":"yohei"},{"t":"d","s":"「ここじゃ」","f":"yohei"},{"t":"d","s":"「ぶきやさん？」","f":"yohei"},{"t":"d","s":"「木刀を扱っておる。お前も、もう棒切れでは足りんじゃろう」","f":"yohei"},{"t":"n","s":"耀平の目が、ぱっと開いた。毎朝、庭の枝を拾っては振っていた。手のひらの皮は、とうに厚くなっている。","f":"yohei"},{"t":"n","s":"店の奥には、何十本もの木刀が立てかけられていた。白樫、赤樫、枇杷。長さも反りも、少しずつ違う。","f":"yohei"},{"t":"d","s":"「好きなのを持ってみい」","f":"yohei"},{"t":"n","s":"耀平は、一本ずつ手に取った。重い。軽い。長い。短い。何本目かで、ぴたりと止まった。","f":"yohei"},{"t":"d","s":"「……これ」","f":"yohei"},{"t":"d","s":"「ほう。それは枇杷じゃな。重いぞ」","f":"yohei"},{"t":"d","s":"「でも、しっくりくる」","f":"yohei"},{"t":"n","s":"耀平は、ゆっくりと構えた。振り下ろす。空気が、すっと割れる音がした。","f":"yohei"},{"t":"n","s":"店主の老人が、奥から顔を出した。","f":"yohei"},{"t":"d","s":"「ほう……坊や、誰に習った」","f":"yohei"},{"t":"d","s":"「だれにも。テレビで、見ただけ」","f":"yohei"},{"t":"d","s":"「テレビ、のう」","f":"yohei"},{"t":"d","s":"「けんせいさんの、まねです」","f":"yohei"},{"t":"n","s":"老人は目を細め、祖父の顔を見た。祖父は、黙って首を横に振る。教えていない、という意味だった。","f":"yohei"},{"t":"d","s":"「……そうか。ええ振りじゃ。持っていきなされ」","f":"yohei"},{"t":"d","s":"「いくらですか」","f":"yohei"},{"t":"d","s":"「いらん。その代わり、折るなよ」","f":"yohei"},{"t":"n","s":"外に出ると、耀平は木刀を抱きしめるように持って、何度も振り返った。","f":"yohei"},{"t":"d","s":"「おじいちゃん、ありがとう」","f":"yohei"},{"t":"d","s":"「礼なら、あの店主に言うんじゃな」","f":"yohei"},{"t":"d","s":"「おじいちゃんにも」","f":"yohei"},{"t":"d","s":"「……そうか」","f":"yohei"},{"t":"n","s":"祖父の背中は、少しだけ丸くなっていた。それでも、孫の後ろ姿を見るその目は、ひどくやわらかかった。","f":"yohei"},{"t":"n","s":"その日から、耀平の朝は、木刀と一緒に始まった。","f":"yohei"},{"t":"n","s":"夜明け前に起き、庭に立つ。構える。振る。ときどき、風に乗って、どこからか桜の花びらが一枚だけ、ひらりと舞い込んでくる。","f":"yohei"},{"t":"d","s":"「……また、きた」","f":"yohei"},{"t":"n","s":"耀平は、その花びらに刀の先を触れさせた。すると、体が、ほんの一瞬だけ、軽くなる。","f":"yohei"},{"t":"d","s":"「やっぱり、へんなスキル」","f":"yohei"},{"t":"n","s":"小さく笑って、耀平は木刀を振り下ろした。","f":"yohei"}]},{"key":"4-2","title":"木刀の噂","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"翌週、教室。耀平が布袋に入れた木刀を持ってくると、さっそく人だかりができた。","f":"yohei"},{"t":"d","s":"「うわ、本物の木刀だ！」","f":"yohei"},{"t":"d","s":"「かっこいい！　ちょっと持たせて」","f":"yohei"},{"t":"d","s":"「だめ。あぶないから」","f":"yohei"},{"t":"d","s":"「ケチ」","f":"yohei"},{"t":"n","s":"そこへ、割り込む影があった。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"n","s":"竜馬だった。腕を組んで、耀平の机を見下ろしている。","f":"ryoma"},{"t":"d","s":"「なんだよ、それ」","f":"ryoma"},{"t":"d","s":"「木刀。おじいちゃんが、かってくれた」","f":"ryoma"},{"t":"d","s":"「スキルが“一花”のくせに、刀かよ」","f":"ryoma"},{"t":"n","s":"教室が、少し静かになった。","f":"ryoma"},{"t":"d","s":"「花びら出すだけのスキルで、刀なんか持って、なにするんだ」","f":"ryoma"},{"t":"d","s":"「……べつに。かっこいいから」","f":"ryoma"},{"t":"d","s":"「かっこいい？　おまえが？」","f":"ryoma"},{"t":"n","s":"竜馬は鼻で笑った。けれど、その目は笑っていない。幼稚園の頃、一緒に木の枝を振り回して遊んだ記憶が、竜馬の中にまだ残っている。自分は炎を出せるようになったのに、耀平は何も変わらない。変わらないはずなのに、毎日あんなに振っている。それが、なぜか、気に入らなかった。","f":"ryoma","m":"happy"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"n","s":"乃亜の声が、割って入った。","f":"noa"},{"t":"d","s":"「やめなよ」","f":"noa"},{"t":"d","s":"「なんだよ、乃亜。おれはほんとのこと言っただけだろ」","f":"noa"},{"t":"d","s":"「ほんとかどうかじゃなくて、いやな言い方だって言ってるの」","f":"noa"},{"t":"d","s":"「……ちっ」","f":"noa"},{"t":"n","s":"竜馬は舌打ちをして、席に戻っていった。乃亜は、深いため息をついた。","f":"ryoma"},{"t":"d","s":"「耀平。言い返さなくていいの」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「なんで」","f":"ryoma"},{"t":"d","s":"「だって、ほんとに、へんなスキルだから」","f":"ryoma"},{"t":"d","s":"「そういう問題じゃ……」","f":"ryoma"},{"t":"n","s":"乃亜は、言葉を飲み込んだ。耀平は本気で気にしていない。その顔を見ると、怒っている自分のほうが馬鹿みたいに思えてくる。","f":"noa"},{"t":"d","s":"「……もう、いい」","f":"noa"},{"t":"d","s":"「のあ、おこってる？」","f":"noa"},{"t":"d","s":"「おこってない。あきれてるだけ」","f":"noa"},{"t":"d","s":"「どっちでもおなじだよ」","f":"noa"},{"t":"d","s":"「ちがう」","f":"noa"},{"t":"n","s":"そんなやりとりを、竜馬は席から横目で見ていた。","f":"ryoma"}]},{"key":"4-3","title":"林間学校","bg":"bg_riverside","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"五年生の夏は、林間学校だった。山あいの宿泊施設で、二泊三日。班ごとに分かれて、飯ごう炊さんをし、山道を歩き、夜にはキャンプファイヤーを囲む。"},{"t":"n","s":"耀平の班は、乃亜と、あと三人の男女だった。竜馬は別の班だったが、ときどき遠くから、こちらを睨むように見ていた。","f":"yohei","m":"anger"},{"t":"d","s":"「ごはん、まだー？」","f":"yohei"},{"t":"d","s":"「耀平、つまみぐいしないで」","f":"yohei"},{"t":"d","s":"「してない」","f":"yohei"},{"t":"d","s":"「じゃあ、口のまわりについてるのは？」","f":"yohei"},{"t":"d","s":"「……ごはんつぶ」","f":"yohei"},{"t":"d","s":"「してるじゃない」","f":"yohei"},{"t":"n","s":"班のみんなが笑う。乃亜は、呆れた顔で耀平の頬を指でぬぐった。","f":"noa","m":"happy"},{"t":"d","s":"「ほんと、手がかかる」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「お礼いらないから、手伝って」","f":"noa"},{"t":"n","s":"炊きあがった飯ごうの米は、少し焦げていた。それでも、みんなで食べたカレーは、特別においしかった。","f":"noa"},{"t":"n","s":"夜。キャンプファイヤーの炎が、ぱちぱちと夜空に火の粉を飛ばす。生徒たちは輪になって、歌ったり、笑ったりしていた。","f":"noa","m":"happy"},{"t":"n","s":"耀平は、その輪から少し離れた丸太に座って、ぼんやりと炎を見ていた。","f":"yohei"},{"t":"d","s":"「ここ、いい？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜が、隣に腰を下ろした。しばらく二人とも、何も言わなかった。","f":"noa"},{"t":"d","s":"「……きれいだね」","f":"noa"},{"t":"d","s":"「うん。でも、竜馬の炎のほうが、もっときれいだよ」","f":"noa"},{"t":"d","s":"「竜馬の？」","f":"noa"},{"t":"d","s":"「うん。まっすぐで、強い。おれ、あれ、すき」","f":"noa"},{"t":"n","s":"乃亜は、驚いて耀平の横顔を見た。","f":"noa"},{"t":"d","s":"「あんなこと言われてるのに」","f":"noa"},{"t":"d","s":"「だって、ほんとのことだし。竜馬は、ずっとがんばってるから」","f":"noa"},{"t":"d","s":"「……そういうとこだよ」","f":"noa"},{"t":"d","s":"「なにが？」","f":"noa"},{"t":"d","s":"「なんでもない」","f":"noa"},{"t":"n","s":"乃亜は、膝を抱えて、小さく笑った。","f":"noa","m":"happy"},{"t":"d","s":"「耀平はさ、いつか、竜馬よりも強くなるよ」","f":"noa"},{"t":"d","s":"「ほんと？」","f":"noa"},{"t":"d","s":"「わたしが、そう決めた」","f":"noa"},{"t":"d","s":"「のあが決めたなら、なるのかな」","f":"noa"},{"t":"d","s":"「なるの」","f":"noa"},{"t":"n","s":"焚き火の向こうで、竜馬が友達と肩を組んで笑っていた。けれど、その視線がふっとこちらに向いて、すぐに逸らされる。乃亜と耀平が並んで座っている、その姿を、見たくなかったのかもしれない。","f":"ryoma"},{"t":"n","s":"翌朝。山道を歩く途中、耀平は、足を滑らせた同じ班の女の子の手を、とっさに掴んだ。","f":"yohei"},{"t":"d","s":"「あぶない！」","f":"yohei"},{"t":"d","s":"「きゃっ……」","f":"yohei"},{"t":"n","s":"崖というほどではない。けれど、斜面を転がれば怪我をする高さだった。耀平は、女の子を引き上げると、すぐに自分も体勢を戻した。","f":"yohei"},{"t":"d","s":"「だいじょうぶ？」","f":"yohei"},{"t":"d","s":"「う、うん……ありがとう。耀平くん、すごい」","f":"yohei"},{"t":"d","s":"「たまたま。毎朝、木刀を振ってるから、足腰はつよいかも」","f":"yohei"},{"t":"n","s":"遅れて駆けつけた先生が、目を丸くした。","f":"yohei","m":"surprise"},{"t":"d","s":"「今の反応は……君、何かやっているのか」","f":"yohei"},{"t":"d","s":"「いえ。ふつうです」","f":"yohei"},{"t":"n","s":"耀平はそう答えて、また眠そうな顔に戻った。桜の花びらが、ほんの一枚、風に乗って彼の肩に落ちていたことには、誰も気づかなかった。","f":"yohei"}]},{"key":"4-4","title":"クリスマス","bg":"bg_noa_house","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa"],"lines":[{"t":"n","s":"十二月。町じゅうが、赤と緑に染まった。"},{"t":"n","s":"クリスマスイブの夜、耀平は乃亜の家に招かれた。ダイニングテーブルには、ローストチキンと、サラダ、ポタージュ、そして大きなケーキ。乃亜の母が、にこにこと皿を並べていく。","f":"yohei"},{"t":"d","s":"「耀平くん、遠慮しないでね」","f":"yohei"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"d","s":"「お父さんが残業でね、今夜はちょうど席が空いてるのよ。いっぱい食べて」","f":"yohei"},{"t":"n","s":"乃亜の父の席に、耀平は座った。広くて、あたたかい食卓だった。家族の笑い声。皿の音。湯気。耀平は、ふっと、胸の奥が静かに痛んだ。","f":"noa"},{"t":"d","s":"「……どうしたの？」","f":"noa"},{"t":"d","s":"「ううん。おいしい」","f":"noa"},{"t":"d","s":"「でも、箸がとまってる」","f":"noa"},{"t":"d","s":"「だいじょうぶ」","f":"noa"},{"t":"n","s":"乃亜は、じっと耀平を見た。けれど、何も聞かなかった。","f":"noa"},{"t":"n","s":"食後、二人はベランダに出た。冬の空気は澄んでいて、星が高く瞬いていた。","f":"noa"},{"t":"d","s":"「ねえ、耀平」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「これ」","f":"noa"},{"t":"n","s":"乃亜が差し出したのは、小さな包みだった。開けると、手編みのマフラーが入っていた。少し編み目が不揃いで、端がほつれている。","f":"noa"},{"t":"d","s":"「……これ」","f":"noa"},{"t":"d","s":"「ま、まえのチョコよりは、うまくできたと思う」","f":"noa"},{"t":"d","s":"「すごい」","f":"noa"},{"t":"d","s":"「そ、そんなに見ないで。はずかしいから」","f":"noa"},{"t":"n","s":"耀平は、マフラーを首に巻いた。毛糸の匂いがした。あたたかかった。","f":"yohei"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「おれも、これ」","f":"yohei"},{"t":"n","s":"耀平がポケットから取り出したのは、小さな木の札だった。不器用な字で、「の」と「あ」の文字が彫られている。","f":"yohei"},{"t":"d","s":"「おじいちゃんに、教わって、つくった。お守り」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「へたでごめん」","f":"yohei"},{"t":"d","s":"「へたじゃ、ない」","f":"yohei"},{"t":"n","s":"乃亜は、その木札を両手で包むように持った。声が、少しだけ震えている。","f":"noa"},{"t":"d","s":"「大事にする」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「ずっと、大事にする」","f":"noa"},{"t":"n","s":"夜空に、小さな雪が舞い始めた。二人は、並んで空を見上げていた。耀平の首のマフラーが、ふわりと風に揺れる。","f":"yohei"},{"t":"n","s":"家に帰ると、祖父は炬燵で、一人で茶をすすっていた。","f":"yohei"},{"t":"d","s":"「ただいま」","f":"yohei"},{"t":"d","s":"「おかえり。……ええ顔をしとるのう」","f":"yohei"},{"t":"d","s":"「そうかな」","f":"yohei"},{"t":"d","s":"「その首のは、乃亜ちゃんか」","f":"yohei"},{"t":"d","s":"「うん。あったかい」","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"n","s":"祖父は、ゆっくりと湯呑みを置いた。","f":"yohei"},{"t":"d","s":"「耀平。覚えておけ」","f":"yohei"},{"t":"d","s":"「なに？」","f":"yohei"},{"t":"d","s":"「人から貰った温もりは、ちゃんと返せる人間になれ」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「それが、強さの、いちばん根っこじゃ」","f":"yohei"},{"t":"n","s":"耀平は、その言葉の意味を、まだ全部は分からなかった。けれど、首元のマフラーを、そっと握りしめた。","f":"yohei"},{"t":"n","s":"外では、雪が静かに降り続けていた。","f":"yohei"}]}]},{"n":5,"title":"竜馬との喧嘩","sub":"小学校・六年生","era":"elem","lead":"言い返さない耀平に、竜馬は苛立ちを募らせる。そして放課後、二人の距離は、一度だけ最悪の形で縮まる。","scenes":[{"key":"5-1","title":"見えないところで","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"六年生の春。耀平の背は伸び、手のひらの肉刺はさらに厚くなった。相変わらず、授業中はほとんど眠そうな顔をしている。","f":"yohei"},{"t":"d","s":"「耀平、起きて。先生こっち見てる」","f":"yohei"},{"t":"d","s":"「……起きてる」","f":"yohei"},{"t":"d","s":"「目、閉じてる」","f":"yohei"},{"t":"d","s":"「考えてる」","f":"yohei"},{"t":"d","s":"「考えてる顔じゃないよ」","f":"yohei"},{"t":"n","s":"隣の席から、乃亜が小声で肘をつつく。耀平は、むにゃ、と返事にならない返事をして、また瞼を落とした。","f":"noa"},{"t":"n","s":"乃亜は、ため息をつきながらも、ノートの端に今日の宿題の範囲を書いて、そっと耀平の机にずらした。毎日のことだった。","f":"noa"},{"t":"n","s":"休み時間。廊下を歩いていた耀平の耳に、数人の笑い声が届いた。","f":"yohei"},{"t":"d","s":"「あいつだろ、“一花”の」","f":"yohei"},{"t":"d","s":"「まだ木刀もってんの？　ださ」","f":"yohei"},{"t":"d","s":"「花びら出して、チャンバラごっこかよ」","f":"yohei"},{"t":"n","s":"耀平は、聞こえなかったふりをして通り過ぎた。いつものことだった。慣れていた。いや、慣れたというより、気にならなかった。祖父の言葉があったからだ。弱い人間ほど、よく吠える。そう言って笑う祖父の顔が、耀平の頭のどこかに、いつも居座っていた。","f":"yohei","m":"happy"},{"t":"n","s":"翌日の昼休み。昨日の三人組のうちの一人が、頬を腫らして登校してきた。","f":"yohei"},{"t":"d","s":"「どうしたの、それ」","f":"yohei"},{"t":"d","s":"「……転んだ」","f":"yohei"},{"t":"d","s":"「転んだにしては、変なとこ腫れてるぞ」","f":"yohei"},{"t":"d","s":"「うるさい！」","f":"yohei"},{"t":"n","s":"別の一人は、昨日まで偉そうに笑っていたくせに、廊下で耀平を見るなり、目を逸らして遠回りしていった。","f":"yohei"},{"t":"n","s":"耀平は、不思議そうに首をかしげた。","f":"yohei"},{"t":"d","s":"「ねえ、乃亜。あの人たち、最近おとなしいね」","f":"yohei"},{"t":"d","s":"「……そうだね」","f":"yohei"},{"t":"d","s":"「なんでだろう」","f":"yohei"},{"t":"d","s":"「さあ」","f":"yohei"},{"t":"n","s":"乃亜は、窓の外を見たまま答えた。校庭の隅の、焼却炉の裏。そこから、竜馬が一人で歩いてくるのが見えた。右手の拳に、小さな擦り傷がある。","f":"noa"},{"t":"n","s":"乃亜は、ほんの少しだけ眉を寄せて、それから、何も見なかったふりをした。","f":"noa"}]},{"key":"5-2","title":"放課後の呼び出し","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily2","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"それは、六月の終わりだった。梅雨の合間の、蒸し暑い日。"},{"t":"n","s":"帰りの会が終わると、竜馬が、耀平の机の前に立った。","f":"ryoma"},{"t":"d","s":"「おい、耀平」","f":"ryoma"},{"t":"d","s":"「なに？」","f":"ryoma"},{"t":"d","s":"「ちょっと来い」","f":"ryoma"},{"t":"d","s":"「どこに」","f":"ryoma"},{"t":"d","s":"「裏。誰もいないとこだ」","f":"ryoma"},{"t":"n","s":"教室が、ざわついた。乃亜が、がたん、と椅子を引いて立ち上がる。","f":"noa"},{"t":"d","s":"「竜馬、なにするつもり」","f":"noa"},{"t":"d","s":"「乃亜には関係ねえ」","f":"noa"},{"t":"d","s":"「関係ある。耀平は」","f":"noa"},{"t":"d","s":"「いいよ、乃亜」","f":"noa"},{"t":"n","s":"耀平は、のそりと立ち上がって、いつもの眠そうな顔のまま、小さく笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「すぐもどる」","f":"yohei"},{"t":"d","s":"「……ほんとに？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜は、唇を噛んだ。けれど、それ以上は止められなかった。止められないのだと、分かってしまったからだ。竜馬の目に、冗談の色は、ひとつもなかった。","f":"noa"},{"t":"n","s":"校舎の裏手。古い体育倉庫の脇の、人気のない空き地。雑草が、膝ほどまで伸びている。","f":"noa"},{"t":"n","s":"竜馬は、足を止めて、振り返った。","f":"ryoma"},{"t":"d","s":"「なあ、耀平」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「おまえ、なんで言い返さねえんだよ」","f":"ryoma"},{"t":"d","s":"「……なんでって」","f":"ryoma"},{"t":"d","s":"「バカにされてんだぞ。スキルのことも、木刀のことも。なのに、へらへらして。毎日、毎日、眠そうな顔して」","f":"ryoma"},{"t":"n","s":"竜馬の拳が、ぎゅっと握られる。","f":"ryoma"},{"t":"d","s":"「おれは、がんばってんだよ。毎日、毎日、火の出し方を練習して、親父にも殴られて。なのに、おまえは、何にもしてねえ顔して、おれより……」","f":"ryoma"},{"t":"n","s":"言葉が、途切れた。竜馬は、自分が何を言おうとしていたのか、分からなくなったようだった。","f":"ryoma"},{"t":"d","s":"「おれより、何？」","f":"ryoma"},{"t":"d","s":"「うるせえ！」","f":"ryoma"},{"t":"n","s":"竜馬が、地面を蹴った。","f":"ryoma"},{"t":"n","s":"拳が飛んでくる。耀平は、半歩だけ下がって、それをかわした。二発目。三発目。どれも、重い。竜馬は、体も大きく、力も強かった。けれど、動きが、あまりに真っ直ぐだった。","f":"yohei"},{"t":"d","s":"「くそっ、避けんな！」","f":"yohei"},{"t":"d","s":"「あたったら、いたいから」","f":"yohei"},{"t":"d","s":"「あたり前だろ！」","f":"yohei"},{"t":"n","s":"耀平は、息を吸った。毎朝、庭で木刀を振り続けてきた足腰が、自然と、体を支える。竜馬の拳が空を切った一瞬、懐に滑り込んで、掌底を腹に叩き込んだ。","f":"yohei"},{"t":"d","s":"「ぐっ……」","f":"yohei"},{"t":"n","s":"竜馬が、膝をつく。耀平は、そこで止まった。追撃はしなかった。","f":"ryoma"},{"t":"d","s":"「もう、やめよう」","f":"ryoma"},{"t":"d","s":"「……ふざけんな」","f":"ryoma"},{"t":"d","s":"「竜馬、けがするよ」","f":"ryoma"},{"t":"d","s":"「ふざけんなあああっ！」","f":"ryoma"},{"t":"n","s":"竜馬が、叫んだ。","f":"ryoma"}]},{"key":"5-3","title":"紅蓮","bg":"bg_classroom_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"空気が、変わった。"},{"t":"n","s":"竜馬の全身から、赤い熱が噴き上がる。足元の雑草が、じりじりと縮れて、灰に変わっていく。彼の掌の中で、小さな火の玉が、ぐるぐると膨らんでいった。","f":"ryoma"},{"t":"d","s":"「竜馬……？」","f":"ryoma"},{"t":"d","s":"「負けねえ……！　おまえにだけは、負けねえ……！」","f":"ryoma"},{"t":"n","s":"小学生が出す火力ではなかった。いや、出していいものではなかった。竜馬自身の顔が、青ざめている。止めたいのに、止まらない。感情が昂ぶりすぎて、スキルが、手綱を離れて暴れていた。","f":"ryoma"},{"t":"d","s":"「竜馬、それ、やばい。やめて」","f":"ryoma"},{"t":"d","s":"「うるせえ！　もう、とまんねえんだよ！」","f":"ryoma"},{"t":"n","s":"火の玉が、爆ぜた。","f":"ryoma"},{"t":"d","s":"「紅蓮――爆炎ッ！」","f":"ryoma"},{"t":"n","s":"赤い奔流が、耀平を飲み込んだ。","f":"yohei"},{"t":"n","s":"轟音と熱風が、空き地を薙ぎ払う。体育倉庫の壁が焦げて、窓ガラスが割れた。教室の窓から、悲鳴が上がる。","f":"yohei","fx":"shake"},{"t":"n","s":"煙が、ゆっくり晴れていく。","f":"yohei"},{"t":"n","s":"竜馬は、肩で息をしながら、その中心を見つめていた。そして、凍りついた。","f":"ryoma"},{"t":"n","s":"耀平は、立っていた。","f":"yohei"},{"t":"n","s":"制服の袖は焼け焦げ、頬と腕には、赤い火傷の跡がある。膝は、少し笑っている。それでも、倒れていなかった。木刀を握った右手を、前に突き出すようにして、全身で、炎を受け止めていた。","f":"yohei"},{"t":"d","s":"「……いたい」","f":"yohei"},{"t":"d","s":"「な……」","f":"yohei"},{"t":"d","s":"「でも、だいじょうぶ」","f":"yohei"},{"t":"n","s":"耀平の足元には、焦げた草の中に、小さな桜の花びらが、ひらり、ひらりと舞い落ちていた。竜馬は、それを見たはずだった。けれど、頭が追いつかなかった。","f":"yohei"},{"t":"d","s":"「なんで……」","f":"yohei"},{"t":"d","s":"「毎日、振ってるから」","f":"yohei"},{"t":"d","s":"「は……？」","f":"yohei"},{"t":"d","s":"「おじいちゃんが、毎日やってれば、体は覚えるって」","f":"yohei"},{"t":"n","s":"耀平は、ゆっくりと、一歩、前に出た。","f":"yohei"},{"t":"d","s":"「竜馬。もう、いい？」","f":"yohei"},{"t":"d","s":"「……っ」","f":"yohei"},{"t":"d","s":"「竜馬は、がんばってる。それは、おれ、知ってる」","f":"yohei"},{"t":"n","s":"竜馬の手から、火が消えた。膝が、がくりと折れる。","f":"ryoma"},{"t":"d","s":"「おれ……おれは……」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「殺す、つもりじゃ……」","f":"ryoma"},{"t":"d","s":"「うん。分かってる」","f":"ryoma"},{"t":"n","s":"竜馬の目から、ぽろぽろと、涙がこぼれ落ちた。悔しさと、恐怖と、自分への情けなさが、いっぺんに溢れ出していた。","f":"ryoma","m":"sad"},{"t":"d","s":"「ごめん……ごめん……」","f":"ryoma"},{"t":"d","s":"「いいよ」","f":"ryoma"},{"t":"d","s":"「よくねえだろ……」","f":"ryoma"},{"t":"d","s":"「いいよ。おれ、生きてるから」","f":"ryoma"},{"t":"n","s":"耀平は、へらりと笑った。竜馬は、顔を覆って泣いた。","f":"yohei","m":"sad"},{"t":"n","s":"駆けつけてきた先生と、乃亜が、同時に空き地に飛び込んできた。","f":"noa"},{"t":"d","s":"「耀平！」","f":"noa"},{"t":"n","s":"乃亜は、耀平の姿を見るなり、顔から血の気が引いた。","f":"noa"},{"t":"d","s":"「どうしたの、これ！　火傷……！」","f":"noa"},{"t":"d","s":"「だいじょうぶ。見た目ほどじゃないよ」","f":"noa"},{"t":"d","s":"「だいじょうぶじゃない！　はやく保健室！」","f":"noa"},{"t":"n","s":"先生は、焦げた地面と、倒れた竜馬と、耀平の火傷を順に見て、絶句していた。","f":"ryoma"},{"t":"d","s":"「何があった」","f":"ryoma"},{"t":"d","s":"「……おれが、やりました」","f":"ryoma"},{"t":"n","s":"竜馬が、顔を上げずに言った。","f":"ryoma"},{"t":"d","s":"「おれが、耀平に、殺す気で……」","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"n","s":"耀平は、先生を見た。","f":"yohei"},{"t":"d","s":"「ちがいます。ぼくたち、ふざけてて、ちょっとやりすぎちゃっただけです」","f":"yohei"},{"t":"d","s":"「ふざけて、って……」","f":"yohei"},{"t":"d","s":"「ほんとうに。ぼくが悪いんです」","f":"yohei"},{"t":"n","s":"先生は、何かを言いかけて、やめた。耀平の目が、あまりにも真っ直ぐだったからだ。","f":"yohei"}]},{"key":"5-4","title":"保健室","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["noa","ryoma","yohei"],"lines":[{"t":"n","s":"保健室のベッドで、耀平は、包帯を巻かれていた。","f":"yohei"},{"t":"n","s":"診察をした養護の先生が、首をひねっている。","f":"yohei"},{"t":"d","s":"「おかしいわね。あれだけの火力を受けて、ほとんど軽症だなんて」","f":"yohei"},{"t":"d","s":"「体、じょうぶなので」","f":"yohei"},{"t":"d","s":"「それだけで説明がつく範囲じゃないんだけど……」","f":"yohei"},{"t":"d","s":"「毎日、剣を振ってるので」","f":"yohei"},{"t":"n","s":"先生は、それ以上は聞かなかった。後遺症も、残りそうになかった。ただ、一週間は安静にするようにと言って、部屋を出ていった。","f":"yohei"},{"t":"n","s":"カーテンの向こうで、静かな足音が止まる。","f":"yohei"},{"t":"d","s":"「……入っていい？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"乃亜が、そっとカーテンをくぐった。目が、真っ赤に腫れている。","f":"noa"},{"t":"d","s":"「泣いたの？」","f":"noa"},{"t":"d","s":"「泣いてない」","f":"noa"},{"t":"d","s":"「目、まっか」","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"乃亜は、ベッドの端に腰かけて、ぎゅっと自分のスカートを握りしめた。","f":"noa"},{"t":"d","s":"「なんで、やられっぱなしだったの」","f":"noa"},{"t":"d","s":"「やられっぱなしじゃないよ。一回、お腹、殴った」","f":"noa"},{"t":"d","s":"「そういうことじゃなくて」","f":"noa"},{"t":"d","s":"「……うん」","f":"noa"},{"t":"d","s":"「なんで、先生に、本当のこと言わなかったの」","f":"noa"},{"t":"n","s":"耀平は、天井を見つめた。","f":"yohei"},{"t":"d","s":"「竜馬は、ほんとは、悪い子じゃないから」","f":"yohei"},{"t":"d","s":"「悪い子じゃなくても、やっちゃいけないことだよ」","f":"yohei"},{"t":"d","s":"「うん。でも、竜馬、自分が一番、分かってると思う」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「あの顔、見たでしょ」","f":"yohei"},{"t":"n","s":"乃亜は、黙った。確かに、見た。座り込んで、ぐしゃぐしゃに泣いていた、あの横顔を。","f":"noa","m":"sad"},{"t":"d","s":"「それにね」","f":"noa"},{"t":"d","s":"「それに？」","f":"noa"},{"t":"d","s":"「竜馬、おれがバカにされたとき、たぶん、陰で殴ってくれてたよね」","f":"noa"},{"t":"n","s":"乃亜が、はっと顔を上げた。","f":"noa"},{"t":"d","s":"「……知ってたの」","f":"noa"},{"t":"d","s":"「なんとなく。最近、みんな、おとなしくなったから」","f":"noa"},{"t":"d","s":"「竜馬、本人には、絶対言わないよ」","f":"noa"},{"t":"d","s":"「うん。だから、おれも、言わない」","f":"noa"},{"t":"n","s":"耀平は、小さく笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「竜馬はさ、素直じゃないだけなんだよ」","f":"yohei"},{"t":"d","s":"「……なんで、あんたが、そんなに分かってるの」","f":"yohei"},{"t":"d","s":"「だって、幼稚園のとき、いっしょに遊んだから」","f":"yohei"},{"t":"n","s":"乃亜は、何も言えなかった。胸の奥が、ぎゅっと痛んだ。耀平は、誰よりも傷ついているはずなのに、誰よりも、人を見ている。","f":"noa"},{"t":"d","s":"「ねえ、乃亜」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「おれ、強くなるよ」","f":"noa"},{"t":"n","s":"耀平の声は、静かだった。いつもの眠そうな調子とは、少し違っていた。","f":"yohei"},{"t":"d","s":"「今日、思った。おれ、まだ、全然、足りないって。竜馬が本気出したのに、おれ、立ってるだけで精一杯だった」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「もっと、強くなる。誰にも、あんな顔、させないくらいに」","f":"yohei"},{"t":"d","s":"「誰にも？」","f":"yohei"},{"t":"d","s":"「竜馬にも。乃亜にも」","f":"yohei"},{"t":"n","s":"乃亜は、息を詰めた。","f":"noa"},{"t":"d","s":"「だからさ、見ててよ」","f":"noa"},{"t":"n","s":"耀平は、顔を横に向けて、乃亜を見た。","f":"yohei"},{"t":"d","s":"「おれが、どこまで行くか」","f":"yohei"},{"t":"n","s":"乃亜の瞳が、潤んだ。けれど、今度は、泣かなかった。","f":"noa"},{"t":"d","s":"「……うん」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「見てる。ずっと、見てるから」","f":"noa"},{"t":"n","s":"カーテンの外では、夕暮れの光が、窓に長い影を落としていた。","f":"noa"},{"t":"n","s":"廊下の隅の壁に、竜馬が背を預けて、座り込んでいた。保健室から漏れてくる二人の声を、じっと、聞いていた。","f":"ryoma"},{"t":"n","s":"拳を、強く握る。爪が、掌に食い込むほどに。","f":"ryoma"},{"t":"d","s":"「……見てろ、か」","f":"ryoma"},{"t":"n","s":"誰にも聞こえない声で、竜馬は呟いた。","f":"ryoma"},{"t":"d","s":"「おれだって、見てるさ」","f":"ryoma"},{"t":"n","s":"それから、竜馬は、立ち上がった。涙の跡を、袖で乱暴に拭って、振り返らずに、廊下を歩き去っていった。","f":"ryoma","m":"sad"}]}]},{"n":6,"title":"乃亜との約束と卒業式","sub":"小学校・卒業","era":"elem","lead":"言えなかった「ごめん」と、交わした約束。三人は、それぞれの気持ちを抱えたまま小学校を終える。","scenes":[{"key":"6-1","title":"一週間","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft3","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"火傷は、一週間もすると、跡も残さず消えてしまった。"},{"t":"n","s":"保健室の先生は何度も首をかしげていたが、耀平本人は、あっけらかんとしていた。","f":"yohei"},{"t":"d","s":"「ほら、もうなおった」","f":"yohei"},{"t":"d","s":"「なおった、じゃないわよ」","f":"yohei"},{"t":"d","s":"「ほんとだって」","f":"yohei"},{"t":"d","s":"「……ちゃんと、お医者さんにも見てもらったほうがいいと思う」","f":"yohei"},{"t":"d","s":"「だいじょうぶ。おじいちゃんも、へいきって言ってた」","f":"yohei"},{"t":"n","s":"乃亜は、疑わしそうに耀平の腕を覗き込んだ。白い肌には、赤みひとつ残っていない。","f":"noa"},{"t":"d","s":"「……変な体」","f":"noa"},{"t":"d","s":"「ほめてる？」","f":"noa"},{"t":"d","s":"「ほめてない」","f":"noa"},{"t":"n","s":"教室の席に戻ると、竜馬の姿はなかった。喧嘩の翌日から、竜馬は三日間、学校を休んでいた。四日目に登校してきたときも、誰とも目を合わせようとせず、昼休みには、いつの間にか教室から消えていた。","f":"ryoma"},{"t":"d","s":"「竜馬、まだ来づらいのかな」","f":"ryoma"},{"t":"d","s":"「あんたのせいじゃないでしょ」","f":"ryoma"},{"t":"d","s":"「でも、おれのせいでもあるし」","f":"ryoma"},{"t":"d","s":"「違う」","f":"ryoma"},{"t":"n","s":"乃亜は、短く言い切った。","f":"noa"},{"t":"d","s":"「竜馬が、自分で選んだことでしょ」","f":"noa"},{"t":"n","s":"耀平は、少し考えて、それから、小さく頷いた。","f":"yohei"},{"t":"d","s":"「……そうだね」","f":"yohei"},{"t":"n","s":"先生たちは、結局、喧嘩の件を大きくはしなかった。竜馬の親が学校に呼ばれて、深く頭を下げた。耀平の祖父も呼ばれたが、祖父は、焦げた地面を眺めて、ひとことだけ言ったという。","f":"ryoma"},{"t":"d","s":"「子どもの喧嘩です。わしの孫も、悪かった」","f":"ryoma"},{"t":"n","s":"それきりだった。","f":"ryoma"}]},{"key":"6-2","title":"竜馬の背中","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily3","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"夏休み前の最後の日。教室の掃除が終わって、みんなが帰っていく中、耀平は一人で、校舎の裏の花壇に水をやっていた。","f":"yohei"},{"t":"n","s":"背後で、砂利を踏む足音がした。","f":"yohei"},{"t":"d","s":"「……おい」","f":"yohei"},{"t":"n","s":"振り向くと、竜馬が立っていた。ポケットに手を突っ込んで、そっぽを向いている。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「……水やり、当番だったか」","f":"ryoma"},{"t":"d","s":"「ううん。ひま、だったから」","f":"ryoma"},{"t":"d","s":"「ふーん」","f":"ryoma"},{"t":"n","s":"沈黙。蝉の声だけが、やけにうるさく降ってくる。","f":"ryoma"},{"t":"d","s":"「……あのさ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あの、時」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"n","s":"竜馬の口が、何度か開いて、何度か閉じた。ようやく出てきたのは、ひどく不器用な言葉だった。","f":"ryoma"},{"t":"d","s":"「……火傷、なおったのか」","f":"ryoma"},{"t":"d","s":"「うん。もう、きれいになった」","f":"ryoma"},{"t":"d","s":"「そっか」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「……そっか」","f":"ryoma"},{"t":"n","s":"竜馬は、足元の小石を蹴った。それは、かつん、と乾いた音を立てて、花壇の縁に当たった。","f":"ryoma"},{"t":"d","s":"「おれ、おまえに、あやまる気は、ねえ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あやまったって、あの火は、消えねえし」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「でも」","f":"ryoma"},{"t":"n","s":"竜馬の声が、少しだけ、震えた。","f":"ryoma"},{"t":"d","s":"「次は、ぜってえ、止めてみせる」","f":"ryoma"},{"t":"n","s":"耀平は、じょうろを下ろして、竜馬を見た。","f":"yohei"},{"t":"d","s":"「止める？」","f":"yohei"},{"t":"d","s":"「あの火を。自分で。おれの、スキルを」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「だから、おまえ、中学でも、逃げんなよ」","f":"yohei"},{"t":"d","s":"「にげないよ」","f":"yohei"},{"t":"d","s":"「おれは、強くなる。おまえよりも、ぜってえ強くなる」","f":"yohei"},{"t":"d","s":"「いいね」","f":"yohei"},{"t":"d","s":"「だから……」","f":"yohei"},{"t":"n","s":"竜馬は、そこで言葉を切った。そして、小さな声で、ほとんど独り言のように言った。","f":"ryoma"},{"t":"d","s":"「……もう、あんな顔、させねえ」","f":"ryoma"},{"t":"n","s":"耀平には、それが何を指しているのか、よく分からなかった。でも、聞き返しはしなかった。","f":"yohei"},{"t":"d","s":"「じゃあ、おれも、もっと強くなる」","f":"yohei"},{"t":"d","s":"「は？」","f":"yohei"},{"t":"d","s":"「竜馬が強くなるなら、おれも、置いてかれたくないから」","f":"yohei"},{"t":"d","s":"「……ちっ」","f":"yohei"},{"t":"n","s":"竜馬は、舌打ちをして、背を向けた。けれど、その背中は、前よりも少しだけ、まっすぐに見えた。","f":"ryoma"},{"t":"d","s":"「じゃあな」","f":"ryoma"},{"t":"d","s":"「うん。またね」","f":"ryoma"},{"t":"d","s":"「……おう」","f":"ryoma"},{"t":"n","s":"去っていく竜馬の背中を見送りながら、耀平は、じょうろの水を、花壇にゆっくりと注いだ。","f":"ryoma"}]},{"key":"6-3","title":"秋の約束","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["noa","yohei"],"lines":[{"t":"n","s":"秋になった。中学受験をする子たちが、少しずつ、教室から机を空けていく。"},{"t":"n","s":"耀平の進学先は、もう決まっていた。祖父が、役所で取り寄せてくれた案内書の、一番上の学校。全寮制の、スキル持ちの子どもたちを集めた中学校だった。","f":"yohei"},{"t":"d","s":"「……やっぱり、行くんだね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「寮、なんだよね」","f":"yohei"},{"t":"d","s":"「うん。おじいちゃん、ひとりになるけど、行けって」","f":"yohei"},{"t":"d","s":"「……そう」","f":"yohei"},{"t":"n","s":"乃亜は、ブランコの鎖を握ったまま、俯いた。","f":"noa"},{"t":"n","s":"夕暮れの公園。ブランコがきい、きい、と小さく軋む。","f":"noa"},{"t":"d","s":"「乃亜は、受かったんでしょ」","f":"noa"},{"t":"d","s":"「うん。同じとこ」","f":"noa"},{"t":"d","s":"「やった」","f":"noa"},{"t":"d","s":"「やった、じゃないでしょ。わたしが、勉強、どれだけ」","f":"noa"},{"t":"d","s":"「ごめん。ありがとう」","f":"noa"},{"t":"d","s":"「……ふん」","f":"noa"},{"t":"n","s":"乃亜は、ふいっと顔を逸らした。耳が、夕日の色に染まっている。","f":"noa"},{"t":"d","s":"「でもね、耀平」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「中学に行ったら、きっと、いろんなことが変わる」","f":"noa"},{"t":"d","s":"「そうかな」","f":"noa"},{"t":"d","s":"「規格外とか、強い人とか、いっぱい出てくる。わたしは、たぶん、ついていけなくなる」","f":"noa"},{"t":"d","s":"「そんなことないよ」","f":"noa"},{"t":"d","s":"「あるよ」","f":"noa"},{"t":"n","s":"乃亜は、静かに言った。","f":"noa"},{"t":"d","s":"「わたしのスキルは、水を、少しだけ操れるだけ。耀平みたいに、強くなれるわけじゃない」","f":"noa"},{"t":"d","s":"「乃亜」","f":"noa"},{"t":"d","s":"「だから、ね」","f":"noa"},{"t":"n","s":"乃亜が、ブランコから降りた。そして、耀平の前に立って、小さな手を差し出した。","f":"noa"},{"t":"d","s":"「約束して」","f":"noa"},{"t":"d","s":"「なにを」","f":"noa"},{"t":"d","s":"「どこまで強くなっても、どこに行っても、最後は、ちゃんと、わたしのところに帰ってくるって」","f":"noa"},{"t":"n","s":"耀平は、きょとんとして、乃亜の手を見た。","f":"yohei"},{"t":"d","s":"「……帰る？」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「おれの家、おじいちゃんの家だけど」","f":"yohei"},{"t":"d","s":"「そういうことじゃない」","f":"yohei"},{"t":"d","s":"「どういうこと？」","f":"yohei"},{"t":"d","s":"「……ばか」","f":"yohei"},{"t":"n","s":"乃亜は、真っ赤になって俯いた。それでも、手は引っ込めなかった。","f":"noa"},{"t":"n","s":"耀平は、しばらく考えていた。それから、ゆっくりと、乃亜の手を握った。","f":"yohei"},{"t":"d","s":"「うん。分かった」","f":"yohei"},{"t":"d","s":"「ほんとに、分かってる？」","f":"yohei"},{"t":"d","s":"「分かってない」","f":"yohei"},{"t":"d","s":"「……ほら」","f":"yohei"},{"t":"d","s":"「でも、帰ってくる。それは、約束する」","f":"yohei"},{"t":"cg","v":"cg_promise"},{"t":"n","s":"乃亜は、顔を上げた。夕日が、彼女の瞳に映っている。","f":"noa"},{"t":"d","s":"「どこに行っても？」","f":"noa"},{"t":"d","s":"「どこに行っても」","f":"noa"},{"t":"d","s":"「ずっと？」","f":"noa"},{"t":"d","s":"「ずっと」","f":"noa"},{"t":"n","s":"乃亜の目から、ぽろ、と一粒、涙がこぼれた。慌てて拭って、無理やり笑う。","f":"noa","m":"sad"},{"t":"d","s":"「……約束、したからね」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「破ったら、水ぶっかけるから」","f":"noa"},{"t":"d","s":"「それは、いやだ」","f":"noa"},{"t":"d","s":"「じゃあ、破らないで」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"握り合った手の上に、枯れかけた桜の葉が、ひらりと一枚、落ちてきた。","f":"noa"}]},{"key":"6-4","title":"卒業式","bg":"bg_graduation","dark":false,"mood":"climax","bgm":"climax1","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"三月。校庭の桜は、まだ蕾だった。"},{"t":"n","s":"卒業式の朝、耀平は、慣れない制服の襟を引っ張りながら、体育館の隅に立っていた。保護者席には、背広を着た祖父が、静かに座っている。少し、痩せたように見えた。","f":"yohei"},{"t":"d","s":"「……おじいちゃん、きたね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「痩せた？」","f":"yohei"},{"t":"d","s":"「そう、かな」","f":"yohei"},{"t":"d","s":"「ちゃんと、食べてる？」","f":"yohei"},{"t":"d","s":"「たぶん」","f":"yohei"},{"t":"n","s":"隣の列から、乃亜が不安そうに覗き込む。耀平は、「だいじょうぶ」と笑ってみせたが、その視線は、祖父の背中から離れなかった。","f":"noa"},{"t":"n","s":"式は、粛々と進んだ。卒業証書を受け取って、校歌を歌って、拍手の中を退場する。","f":"noa"},{"t":"n","s":"校庭に出ると、桜の枝が風に揺れていた。蕾の先が、ほんの少しだけ、ほころびかけている。","f":"noa"},{"t":"d","s":"「おい」","f":"noa"},{"t":"n","s":"聞き慣れた声に振り向くと、竜馬が立っていた。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「同じ中学、なんだろ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「ま、そうだと思ってた」","f":"ryoma"},{"t":"d","s":"「竜馬も、同じ？」","f":"ryoma"},{"t":"d","s":"「あたり前だろ。親父が、どうしても行けって」","f":"ryoma"},{"t":"d","s":"「そっか」","f":"ryoma"},{"t":"d","s":"「……なあ」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「中学で、決着、つけっからな」","f":"ryoma"},{"t":"d","s":"「いいよ」","f":"ryoma"},{"t":"d","s":"「おまえ、軽いな」","f":"ryoma"},{"t":"d","s":"「だって、約束したから。強くなるって」","f":"ryoma"},{"t":"d","s":"「だれと」","f":"ryoma"},{"t":"d","s":"「乃亜と、竜馬と」","f":"ryoma"},{"t":"n","s":"竜馬は、一瞬、固まった。それから、鼻をこすって、そっぽを向いた。","f":"ryoma"},{"t":"d","s":"「……へっ。じゃあ、約束、守れよ」","f":"ryoma"},{"t":"d","s":"「うん。竜馬も」","f":"ryoma"},{"t":"d","s":"「当然だ」","f":"ryoma"},{"t":"n","s":"二人は、拳を軽く、ごつ、とぶつけ合った。幼稚園の頃、木の枝を振り回して遊んだ、あの日と同じように。","f":"ryoma"},{"t":"n","s":"少し離れた木の下で、乃亜が、その様子を見ていた。胸の奥に、あたたかいものと、ちくりとした痛みが、同時に広がる。","f":"noa"},{"t":"d","s":"「……ほんと、ばか」","f":"noa"},{"t":"n","s":"呟いた声は、風に溶けた。","f":"noa"},{"t":"n","s":"式の後、耀平は、祖父と並んで校門を出た。","f":"yohei"},{"t":"d","s":"「おじいちゃん」","f":"yohei"},{"t":"d","s":"「なんじゃ」","f":"yohei"},{"t":"d","s":"「ありがとう。卒業、見に来てくれて」","f":"yohei"},{"t":"d","s":"「当たり前じゃ。孫の晴れ舞台じゃ」","f":"yohei"},{"t":"d","s":"「……ねえ」","f":"yohei"},{"t":"d","s":"「ん？」","f":"yohei"},{"t":"d","s":"「寮に入ったら、おじいちゃん、ひとりになるよ」","f":"yohei"},{"t":"d","s":"「構わん」","f":"yohei"},{"t":"d","s":"「ほんとに？」","f":"yohei"},{"t":"d","s":"「わしは、ひとりでも、やっていける」","f":"yohei"},{"t":"n","s":"祖父は、そう言って、小さく咳き込んだ。耀平は、思わずその背中を支える。","f":"yohei"},{"t":"d","s":"「だいじょうぶ？」","f":"yohei"},{"t":"d","s":"「ああ。少し、風邪気味でな」","f":"yohei"},{"t":"d","s":"「ほんとに？」","f":"yohei"},{"t":"d","s":"「ほんとじゃ」","f":"yohei"},{"t":"n","s":"耀平は、祖父の顔を、じっと見つめた。その目は、穏やかで、少しだけ、遠くを見ているようだった。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"d","s":"「なに」","f":"yohei"},{"t":"d","s":"「おまえは、強くなる。わしには、分かる」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「だから、迷うな。前だけ見ていろ」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「それで、ええんじゃ」","f":"yohei"},{"t":"n","s":"祖父は、孫の頭を、ぽん、と撫でた。大きくて、ごつごつした手だった。いつもと同じ手のはずなのに、なぜか、いつもより、少しだけ軽く感じた。","f":"yohei"},{"t":"n","s":"校門の脇で、桜の蕾が、風に揺れていた。もうすぐ、春が来る。","f":"yohei"},{"t":"n","s":"耀平の、新しい春が。","f":"yohei"}]}]},{"n":7,"title":"祖父の死と学生寮","sub":"中学・1年","era":"middle","lead":"新しい春、新しい部屋。そして、いちばん静かな別れ。","scenes":[{"key":"7-1","title":"入学式","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily3","cast":["yohei","ren","noa"],"lines":[{"t":"n","s":"中学校の入学式は、体育館ではなく、広い講堂で行われた。"},{"t":"n","s":"高い天井。磨かれた床。壇上に並ぶ教師たちの背筋は、どれも不思議なほど真っ直ぐだった。新入生は百二十人ほど。全員が、何かしらのスキルを持つ子どもたちだ。"},{"t":"d","s":"「……ひろいな」"},{"t":"d","s":"「当たり前でしょ。全国から集まってるんだから」"},{"t":"d","s":"「そうなんだ」"},{"t":"d","s":"「知らなかったの？」"},{"t":"d","s":"「寝てた」"},{"t":"n","s":"隣の席の乃亜は、頭を押さえた。","f":"noa"},{"t":"n","s":"壇上に、一人の生徒が上がった。","f":"noa"},{"t":"n","s":"制服の着こなしは完璧で、背筋が一本の線のようだった。三年生。生徒会長。胸のバッジが、静かに光っている。","f":"ren"},{"t":"d","s":"「新入生の皆さん。入学おめでとう」","f":"ren"},{"t":"n","s":"よく通る声だった。大きくはないのに、講堂の隅々まで届く。","f":"ren"},{"t":"d","s":"「生徒会長の九条蓮です。この学校には、多くの先輩がいて、多くの仲間がいます。困ったときは、遠慮なく頼ってください」","f":"ren"},{"t":"n","s":"そこまで言って、蓮は、ふと、会場全体を見渡した。","f":"ren"},{"t":"n","s":"ほんの一瞬だけ、耀平と、視線が合った気がした。","f":"yohei"},{"t":"d","s":"「……あの人、強い」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「なんとなく。立ってるだけで、すごい」","f":"yohei"},{"t":"d","s":"「耀平、あんたが言うと説得力あるよね」","f":"yohei"},{"t":"d","s":"「え、そう？」","f":"yohei"},{"t":"d","s":"「いい意味じゃないけど」","f":"yohei"},{"t":"n","s":"蓮は、何事もなかったように壇を降りていった。","f":"ren"},{"t":"n","s":"その夜、耀平は荷物を抱えて、学生寮の扉の前に立っていた。","f":"yohei"},{"t":"n","s":"白い壁。木の廊下。二人部屋。同室の少年は、人懐っこく手を振ってきた。","f":"yohei"},{"t":"d","s":"「よろしく！　おれ、佐野。スキルは『加速』。足、ちょっと速くなるだけだけどな！」","f":"yohei"},{"t":"d","s":"「耀平です。スキルは、『一花心舞』」","f":"yohei"},{"t":"d","s":"「いっか、しんぶ？　なんだそれ、かっこいいな！」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「……ううん、なんでも」","f":"yohei"},{"t":"n","s":"耀平は、少し驚いた。馬鹿にされなかったのは、いつ以来だろう。","f":"yohei"},{"t":"n","s":"窓の外では、夜桜が一本、街灯の下で静かに咲いていた。","f":"yohei"}]},{"key":"7-2","title":"ひとりの部屋","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night2","cast":["ren","yohei","ryoma"],"lines":[{"t":"n","s":"寮の朝は早い。耀平は、日の出前に起きて、裏庭に出た。","f":"yohei"},{"t":"n","s":"木刀を握る。構える。振る。","f":"yohei"},{"t":"n","s":"家の庭とは違う、広い芝生。冷たい空気。遠くで、鳥が鳴いている。","f":"yohei"},{"t":"d","s":"「……おじいちゃんの庭と、ちがうな」","f":"yohei"},{"t":"n","s":"ひとりごとのように呟いて、また振る。何度も、何度も。風に乗って、桜の花びらが一枚、また一枚と舞い降りてくる。","f":"yohei"},{"t":"d","s":"「こんな朝から、精が出るな」","f":"yohei"},{"t":"n","s":"不意に、背後から声がした。振り向くと、蓮が立っていた。制服の上着を肩にかけ、静かにこちらを見ている。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「九条でいい。……今の太刀筋、独学か」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「そうか」","f":"ren"},{"t":"n","s":"蓮は、短く頷いただけで、それ以上は何も言わなかった。ただ、足元に落ちた桜の花びらを、ほんの少しだけ長く見つめていた。","f":"ren"},{"t":"d","s":"「あまり無理をしすぎるな。寮は、朝食に遅れると冷める」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「それだけだ」","f":"ren"},{"t":"n","s":"蓮は、そのまま去っていった。耀平は、首をかしげる。","f":"ren"},{"t":"d","s":"「……いい人、なのかな」","f":"ren"},{"t":"n","s":"授業は、ほとんど寝ていた。教師が板書をしているあいだに、まぶたが重くなる。気づけば、乃亜がノートの端に宿題の範囲を書いて、机の隅にそっと置いてくれている。","f":"noa"},{"t":"d","s":"「また寝てた」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝るなら起きて」","f":"noa"},{"t":"d","s":"「がんばる」","f":"noa"},{"t":"d","s":"「がんばれてない」","f":"noa"},{"t":"n","s":"竜馬も、同じクラスだった。","f":"ryoma"},{"t":"d","s":"「おい、耀平」","f":"ryoma"},{"t":"d","s":"「ん？」","f":"ryoma"},{"t":"d","s":"「放課後、訓練場いくぞ。ひとりだと、つまんねえ」","f":"ryoma"},{"t":"d","s":"「いいの？」","f":"ryoma"},{"t":"d","s":"「別に。おれが勝手に付き合わせるだけだ」","f":"ryoma"},{"t":"n","s":"竜馬の言い方は相変わらず乱暴だったが、小学校の頃のような棘は、もうなかった。","f":"ryoma"}]},{"key":"7-3","title":"電話","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa"],"lines":[{"t":"n","s":"五月の連休が明けた頃だった。"},{"t":"n","s":"寮の電話が鳴ったのは、夜の九時を過ぎてからだった。"},{"t":"d","s":"「耀平くん、電話よ。……おうちから」"},{"t":"n","s":"寮母さんの声が、いつもより少し硬かった。受話器を受け取ると、聞き慣れない女性の声がした。"},{"t":"d","s":"「もしもし。耀平くん？　隣の、山口です」"},{"t":"d","s":"「山口さん。どうしたんですか」"},{"t":"d","s":"「あのね、落ち着いて聞いてね。おじいちゃんが、今朝から、体調をくずして……入院したの」"},{"t":"n","s":"耀平の指先が、冷たくなった。","f":"yohei"},{"t":"d","s":"「……どこの、病院ですか」","f":"yohei"},{"t":"d","s":"「市立の。でもね、お医者さんが、できれば耀平くんを、すぐ呼んだほうがいいって」","f":"yohei"},{"t":"n","s":"受話器を置いた耀平は、しばらく、動けなかった。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"振り向くと、乃亜が立っていた。寮母さんから、聞いたのだろう。顔が青い。","f":"noa"},{"t":"d","s":"「……行こう」","f":"noa"},{"t":"d","s":"「乃亜」","f":"noa"},{"t":"d","s":"「一緒に行く。タクシー、呼んでもらった」","f":"noa"},{"t":"d","s":"「いいの？」","f":"noa"},{"t":"d","s":"「あんたを、ひとりで行かせるわけないでしょ」","f":"noa"},{"t":"n","s":"乃亜は、耀平の手を、ぎゅっと握った。冷たい指先だった。けれど、その握力は、驚くほど強かった。","f":"noa"}]},{"key":"7-4","title":"祖父の最期","bg":"bg_classroom_middle","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","noa"],"lines":[{"t":"n","s":"病院の廊下は、静かで、薬品の匂いがした。"},{"t":"n","s":"白い病室。小さなベッド。その上で、祖父は、細い呼吸をしていた。"},{"t":"d","s":"「……おじいちゃん」"},{"t":"n","s":"祖父は、ゆっくりと目を開けた。そして、孫の姿を見て、ほんの少しだけ、笑った。","m":"happy"},{"t":"d","s":"「……来たか」"},{"t":"d","s":"「うん」"},{"t":"d","s":"「学校は、どうじゃ」"},{"t":"d","s":"「だいじょうぶ。たのしいよ」"},{"t":"d","s":"「そうか。それは、よかった」"},{"t":"n","s":"声は、かすれていた。耀平は、祖父の手を握った。以前より、ずっと細くなっている。","f":"yohei"},{"t":"d","s":"「おじいちゃん、病気だったの？」","f":"yohei"},{"t":"d","s":"「いや。歳じゃ。ただの、歳」","f":"yohei"},{"t":"d","s":"「でも」","f":"yohei"},{"t":"d","s":"「老いて死ぬのは、ええもんじゃ。……ようやく、そこへ行ける」","f":"yohei"},{"t":"d","s":"「そこ、って」","f":"yohei"},{"t":"d","s":"「おまえのお父さんと、お母さんのところじゃ」","f":"yohei"},{"t":"n","s":"耀平の喉が、ひくりと鳴った。四歳のとき、いなくなった人たち。顔も、声も、もう輪郭しか覚えていない。","f":"yohei"},{"t":"d","s":"「……おじいちゃん」","f":"yohei"},{"t":"d","s":"「泣くな。泣くのは、後でええ」","f":"yohei"},{"t":"d","s":"「でも」","f":"yohei"},{"t":"d","s":"「わしの話を、聞け」","f":"yohei"},{"t":"n","s":"祖父は、ゆっくりと息を吸った。","f":"yohei"},{"t":"d","s":"「耀平。おまえの、一花心舞はな」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「バカにされとるじゃろう」","f":"yohei"},{"t":"d","s":"「……うん」","f":"yohei"},{"t":"d","s":"「それでええ。むしろ、ええんじゃ」","f":"yohei"},{"t":"d","s":"「なんで？」","f":"yohei"},{"t":"d","s":"「バカにされとるあいだは、誰も、おまえを警戒せん。……その間に、力を蓄えられる」","f":"yohei"},{"t":"n","s":"祖父の目が、静かに光った。","f":"yohei","fx":"flash"},{"t":"d","s":"「いつか、おまえのスキルが、本物の形を見せる日が来る。そのとき、桜は、ただの桜ではなくなる」","f":"yohei"},{"t":"d","s":"「おじいちゃん、知ってたの？」","f":"yohei"},{"t":"d","s":"「いや。何も知らん。わしは、ただのじいさんじゃ。……ただ、おまえを見ておれば、分かる」","f":"yohei"},{"t":"n","s":"祖父は、ふ、と笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「前だけ見ろ。迷うな。人から貰った温もりは、ちゃんと返せ。……それだけ守れば、おまえは、どこまでも行ける」","f":"yohei"},{"t":"d","s":"「うん。うん」","f":"yohei"},{"t":"d","s":"「乃亜ちゃん」","f":"yohei"},{"t":"n","s":"祖父の視線が、扉の脇で立ち尽くしていた乃亜に向いた。","f":"noa"},{"t":"d","s":"「はい」","f":"noa"},{"t":"d","s":"「この子を、頼む。……だらしのない孫じゃが」","f":"noa"},{"t":"d","s":"「……はい」","f":"noa"},{"t":"d","s":"「頼まれてくれるか」","f":"noa"},{"t":"d","s":"「はい。ずっと」","f":"noa"},{"t":"n","s":"乃亜は、唇を噛んで、深く頭を下げた。","f":"noa"},{"t":"n","s":"祖父は、満足そうに目を閉じた。そして、孫の手を、もう一度だけ、握り返した。","f":"noa"},{"t":"d","s":"「ええ孫を、持ったのう」","f":"noa"},{"t":"n","s":"それが、最後の言葉だった。","f":"noa"},{"t":"n","s":"窓の外では、夜明け前の空が、少しずつ白んできていた。耀平の手の中で、祖父の手の温度が、ゆっくりと、遠くなっていく。","f":"yohei"},{"t":"d","s":"「おじいちゃん……」","f":"yohei"},{"t":"n","s":"返事は、なかった。","f":"yohei"},{"t":"n","s":"病室の窓の隙間から、どこからか風が入り込んで、桜の花びらが一枚、ベッドの上にひらりと落ちた。この季節に、桜が咲いているはずもないのに。","f":"yohei"},{"t":"n","s":"耀平は、声を出さずに、泣いた。","f":"yohei","m":"sad"}]},{"key":"7-5","title":"葬儀と、寮","bg":"bg_dorm","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"葬儀は、小さく、静かに行われた。"},{"t":"cg","v":"cg_grandpa_funeral"},{"t":"n","s":"参列者は、近所の人たちと、祖父の古い知り合いが数人。耀平は、喪服代わりの制服を着て、黙って最前列に座っていた。","f":"yohei"},{"t":"n","s":"焼香の列の中に、見慣れた背中があった。","f":"yohei"},{"t":"n","s":"竜馬だった。","f":"ryoma"},{"t":"n","s":"黒い礼服。ぎこちなく手を合わせて、深く頭を下げる。それから、耀平の前に来て、何か言いかけて、やめた。","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「ありがとう、来てくれて」","f":"yohei"},{"t":"d","s":"「……おう」","f":"yohei"},{"t":"d","s":"「竜馬」","f":"yohei"},{"t":"d","s":"「……なんだよ」","f":"yohei"},{"t":"d","s":"「ありがとう」","f":"yohei"},{"t":"d","s":"「だから、言うなって」","f":"yohei"},{"t":"n","s":"竜馬は、乱暴に袖で目元を拭った。そして、乱暴な足取りで去っていった。","f":"ryoma"},{"t":"n","s":"葬儀のあと、耀平は、祖父の家に一人で戻った。","f":"yohei"},{"t":"n","s":"縁側。炬燵。古い茶箪笥。庭の隅には、耀平が毎朝木刀を振った跡が、地面にうっすらと残っている。","f":"yohei"},{"t":"n","s":"箪笥の引き出しから、一通の封筒が出てきた。宛名は、不器用な字で、「耀平へ」。","f":"yohei"},{"t":"n","s":"封を切ると、短い手紙が入っていた。","f":"yohei"},{"t":"d","s":"『耀平へ。 この手紙を読んでいるということは、わしは、もうおらんのじゃろう。 おまえは、わしの自慢の孫じゃ。 強くなれ。優しくなれ。そして、ちゃんと、笑え。 乃亜ちゃんを、大事にな。 　　　　　　　　　　　　　　　　　　祖父』","f":"yohei"},{"t":"n","s":"耀平は、その手紙を、胸に抱いた。声を殺して、泣いた。誰もいない縁側で、桜の花びらが、さらさらと舞っていた。","f":"yohei","m":"sad"},{"t":"d","s":"「おじいちゃん……おれ、強くなるよ」","f":"yohei"},{"t":"n","s":"呟いた声は、庭に吸い込まれて消えた。","f":"yohei"},{"t":"cg","v":"cg_dorm_visit"},{"t":"n","s":"その夜、寮に戻ると、乃亜が、玄関で待っていた。","f":"noa"},{"t":"d","s":"「おかえり」","f":"noa"},{"t":"d","s":"「……ただいま」","f":"noa"},{"t":"d","s":"「ごはん、食べた？」","f":"noa"},{"t":"d","s":"「食べてない」","f":"noa"},{"t":"d","s":"「食堂、まだ開いてる。一緒に行こう」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"cg","v":"cg_noa_dinner"},{"t":"n","s":"乃亜は、何も聞かなかった。ただ、並んで歩いた。食堂のテーブルで、向かい合って座った。耀平の前に、湯気の立つ味噌汁が置かれる。","f":"noa"},{"t":"d","s":"「……あったかい」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「おじいちゃんの味噌汁、思い出した」","f":"noa"},{"t":"d","s":"「そう」","f":"noa"},{"t":"d","s":"「また、泣きそう」","f":"noa"},{"t":"d","s":"「泣いていいよ」","f":"noa"},{"t":"d","s":"「でも、ここ食堂だし」","f":"noa"},{"t":"d","s":"「いいよ。見ないでおく」","f":"noa"},{"t":"n","s":"乃亜は、横を向いて、窓の外を見た。耀平は、俯いたまま、味噌汁の湯気に、ぽたりと一粒、涙を落とした。","f":"noa","m":"sad"},{"t":"n","s":"約束は、まだ、守られていた。","f":"noa"}]}]},{"n":8,"title":"修学旅行と肝試し","sub":"中学・1年","era":"middle","lead":"山あいの旅館に、一年生から三年生までが集まった。何も知らない子どもたちの夜は、静かに、それでも確実に近づいてくる。","scenes":[{"key":"8-1","title":"バスの窓","bg":"bg_riverside","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","ryoma","noa"],"lines":[{"t":"n","s":"十月。中学の合同修学旅行は、県境の山あいにある旅館での二泊三日だった。"},{"t":"n","s":"一年生から三年生までの全員が、大型バスに分かれて乗り込む。窓の外には、色づき始めた山の稜線が流れていく。"},{"t":"d","s":"「耀平、起きてる？」"},{"t":"d","s":"「起きてる」"},{"t":"d","s":"「目、閉じてるけど」"},{"t":"d","s":"「景色を、楽しんでる」"},{"t":"d","s":"「嘘つき」"},{"t":"n","s":"通路を挟んだ席から、乃亜が呆れた顔でこちらを見ていた。","f":"noa"},{"t":"n","s":"耀平はあくびを噛み殺して、窓の外に目を向けた。寮に入って半年。祖父のいない最初の秋だった。","f":"yohei"},{"t":"d","s":"「……山、きれいだね」","f":"yohei"},{"t":"d","s":"「うん。おじいちゃんの庭の、桜の葉っぱに似てる」","f":"yohei"},{"t":"d","s":"「葉っぱ、って」","f":"yohei"},{"t":"d","s":"「赤いところが」","f":"yohei"},{"t":"d","s":"「あんた、ほんとに桜が好きね」","f":"yohei"},{"t":"d","s":"「好きっていうか、気づくと、そこにあるから」","f":"yohei"},{"t":"n","s":"耀平は小さく笑った。","f":"yohei","m":"happy"},{"t":"n","s":"後ろの席で、竜馬が窓にもたれて腕を組んでいた。目を閉じているが、眠ってはいない。耳だけが、前の席の会話を拾っている。","f":"ryoma"},{"t":"d","s":"「……好きなもん、あるだけ、ましだろ」","f":"ryoma"},{"t":"n","s":"誰にも聞こえない声で、竜馬は呟いた。","f":"ryoma"}]},{"key":"8-2","title":"黒い影","bg":"bg_classroom_middle","dark":true,"mood":"tense","bgm":"tense2","cast":["ren","yohei","noa"],"lines":[{"t":"n","s":"二日目の午後は、旅館の裏山のハイキングだった。"},{"t":"n","s":"学年ごとに列を作り、先生の先導で木漏れ日の道を登る。耀平は列の真ん中あたりを、のんびりと歩いていた。","f":"yohei"},{"t":"d","s":"「ねえ、耀平。さっきから、なんか静かじゃない？」","f":"yohei"},{"t":"d","s":"「そう？」","f":"yohei"},{"t":"d","s":"「鳥の声。さっきまで、すごかったのに」","f":"yohei"},{"t":"n","s":"耀平は足を止めて、耳を澄ませた。確かに、鳥の声がない。風も止んでいる。","f":"yohei"},{"t":"d","s":"「……ほんとだ」","f":"yohei"},{"t":"d","s":"「でしょ？」","f":"yohei"},{"t":"d","s":"「なんか、いやな感じ」","f":"yohei"},{"t":"n","s":"その瞬間だった。","f":"yohei"},{"t":"n","s":"列の最後尾の、さらに後ろ。木々の奥で、枝がばきりと折れる音がした。","f":"yohei"},{"t":"d","s":"「誰だ」","f":"yohei"},{"t":"n","s":"低い声が、静寂を切り裂いた。","f":"yohei"},{"t":"n","s":"振り向くと、生徒会長の九条蓮が、列から外れた斜面に立っていた。その視線の先に、黒い外套の男が一人、木の陰からこちらを覗き込んでいる。","f":"ren"},{"t":"d","s":"「……チッ。気づかれたか」","f":"ren"},{"t":"d","s":"「ここは学校行事の最中だ。部外者は立ち入り禁止だぞ」","f":"ren"},{"t":"d","s":"「ガキの遠足に、目を光らせてんじゃねえよ」","f":"ren"},{"t":"n","s":"男が、口の端を持ち上げた。次の瞬間、男の足元の落ち葉が、ぶわりと舞い上がった。","f":"ren"},{"t":"d","s":"「下がっていろ」","f":"ren"},{"t":"n","s":"蓮は短く言った。生徒たちが、ざわつく。先生たちが慌てて前に出ようとして、蓮に手で制された。","f":"ren"},{"t":"d","s":"「大丈夫です。私が対応します」","f":"ren"},{"t":"d","s":"「会長、しかし――」","f":"ren"},{"t":"d","s":"「列を、そのまま進めてください。いつもの行程を崩さないように」","f":"ren"},{"t":"n","s":"蓮の声は静かだった。けれど、有無を言わせない響きがあった。","f":"ren"},{"t":"n","s":"男が、地面を蹴る。拳が、風を割いて蓮の顔面へ迫る。蓮は半歩だけ身を引いて、それをかわし、掌底を男の脇腹に叩き込んだ。","f":"ren"},{"t":"d","s":"「ぐっ……！」","f":"ren"},{"t":"n","s":"鈍い音。男の体が、くの字に折れて吹き飛ぶ。木の幹に叩きつけられて、落ち葉の上に転がった。","f":"ren","fx":"shake"},{"t":"d","s":"「……なんだ、てめえ……ただの中坊じゃ、ねえな」","f":"ren"},{"t":"d","s":"「去れ。今回は見逃す」","f":"ren"},{"t":"n","s":"男は、よろよろと立ち上がって、蓮を睨んだ。それから、舌打ちを一つして、森の奥へ消えていった。","f":"ren","m":"anger"},{"t":"d","s":"「……今の、なに？」","f":"ren"},{"t":"d","s":"「会長、すごい……」","f":"ren"},{"t":"d","s":"「見えた？　今の動き、全然見えなかった」","f":"ren"},{"t":"n","s":"列がざわめく中、耀平は、じっと蓮の背中を見つめていた。","f":"yohei"},{"t":"d","s":"「……あの人、わざと、全力を出してなかった」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「全力を出したら、みんなが気づくから。だから、あんなふうに」","f":"yohei"},{"t":"n","s":"乃亜が、驚いた顔で耀平の横顔を見た。","f":"noa"},{"t":"d","s":"「耀平……見えてたの？」","f":"noa"},{"t":"d","s":"「なんとなく。立ち方で、分かる」","f":"noa"},{"t":"n","s":"蓮が、ふと、こちらを振り向いた。ほんの一瞬、視線が合う。蓮は何も言わず、わずかに目を細めただけだった。","f":"ren"}]},{"key":"8-3","title":"会議","bg":"bg_classroom_middle","dark":true,"mood":"tense","bgm":"tense2","cast":["ren","yohei"],"lines":[{"t":"n","s":"その夜。旅館の一番奥の小さな和室に、三人の教師と、蓮が集まっていた。","f":"ren"},{"t":"n","s":"障子は閉められ、廊下には教師が一人、見張りに立っている。","f":"ren"},{"t":"d","s":"「先ほどの男は、おそらく斥候だ」","f":"ren"},{"t":"n","s":"蓮が、静かに切り出した。","f":"ren"},{"t":"d","s":"「斥候……？　どこの、ですか」","f":"ren"},{"t":"d","s":"「分からない。ただ、あの動き、あの口ぶり。ただの不審者ではないでしょう」","f":"ren"},{"t":"d","s":"「しかし会長、生徒たちは何も気づいていません。このまま日程を進めれば、問題は――」","f":"ren"},{"t":"d","s":"「問題は、明日の夜です」","f":"ren"},{"t":"n","s":"蓮は、机の上の行程表を指でなぞった。","f":"ren"},{"t":"d","s":"「一年生の、肝試し」","f":"ren"},{"t":"n","s":"担任の木村が、はっとして顔を上げた。","f":"ren"},{"t":"d","s":"「あの森の、山道を、一年生が班ごとに歩くのですね」","f":"ren"},{"t":"d","s":"「そうです。生徒が分散して、しかも夜に、人気のない森の中へ入る。……もし私が襲撃する側なら、この機会を逃しません」","f":"ren"},{"t":"d","s":"「では、中止にしましょう」","f":"ren"},{"t":"d","s":"「中止にすれば、相手は別の機会を探すだけです。それに、生徒たちに不安を与える」","f":"ren"},{"t":"n","s":"蓮は、一呼吸おいて、続けた。","f":"ren"},{"t":"d","s":"「ですから、予定どおり実施します。ただし、先生方と私が、森の周囲に潜みます。襲撃があれば、すぐに動けるように」","f":"ren"},{"t":"d","s":"「それは……」","f":"ren"},{"t":"d","s":"「生徒たちは、何も知らなくていい。今夜、見聞きしたことは、口外しないでください」","f":"ren"},{"t":"n","s":"教師たちは、しばらく黙っていた。やがて、木村が重い息を吐いた。","f":"ren"},{"t":"d","s":"「……分かりました。会長の判断に、従います」","f":"ren"},{"t":"d","s":"「ありがとうございます」","f":"ren"},{"t":"n","s":"蓮は、窓の外の暗い山を見つめた。","f":"ren"},{"t":"d","s":"「それと、もう一つ」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「一年生に、気になる生徒が一人います」","f":"ren"},{"t":"d","s":"「気になる、というと」","f":"ren"},{"t":"d","s":"「いえ。今は、まだ」","f":"ren"},{"t":"n","s":"蓮は、それ以上は言わなかった。耀平の名前も、あの視線のことも、口にしなかった。","f":"ren"}]},{"key":"8-4","title":"班決め","bg":"bg_classroom_middle","dark":true,"mood":"night","bgm":"night3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"翌日の午後。旅館の大広間に、一年生が集められた。"},{"t":"d","s":"「それでは、今夜の肝試しの班を発表します。六人一組で、森の山道を一周してきてください」"},{"t":"n","s":"木村が、名簿を読み上げる。"},{"t":"d","s":"「第三班。山下、田中、小川……」"},{"t":"d","s":"「第五班。佐野、耀平、乃亜、中野、小川……」"},{"t":"n","s":"耀平は、乃亜と目を合わせた。","f":"yohei"},{"t":"d","s":"「同じ班だね」","f":"yohei"},{"t":"d","s":"「みたいね」","f":"yohei"},{"t":"d","s":"「よかった」","f":"yohei"},{"t":"d","s":"「なにが」","f":"yohei"},{"t":"d","s":"「知ってる人がいるから」","f":"yohei"},{"t":"d","s":"「……ふん」","f":"yohei"},{"t":"n","s":"乃亜は、そっぽを向いた。耳が少し赤い。","f":"noa","m":"blush"},{"t":"d","s":"「おーい、耀平！　同じ班だな！」","f":"noa"},{"t":"n","s":"寮の同室の佐野が、駆け寄ってきた。","f":"noa"},{"t":"d","s":"「うん、よろしく」","f":"noa"},{"t":"d","s":"「肝試し、楽しみだなあ。お化け役、先輩がやるんだろ？」","f":"noa"},{"t":"d","s":"「そうみたい」","f":"noa"},{"t":"d","s":"「怖がらせてくれるかなあ」","f":"noa"},{"t":"d","s":"「佐野は、怖がり？」","f":"noa"},{"t":"d","s":"「いや、全然！　足が速いから、逃げ切れる！」","f":"noa"},{"t":"d","s":"「それ、怖がりの人が言うやつ」","f":"noa"},{"t":"n","s":"班の残り二人、中野と小川は、少し離れたところで緊張した顔をしていた。","f":"noa"},{"t":"d","s":"「竜馬は、別の班か」","f":"noa"},{"t":"d","s":"「そうみたい」","f":"noa"},{"t":"d","s":"「ふーん」","f":"noa"},{"t":"n","s":"耀平は何気なく呟いて、広間の反対側を見た。竜馬は、別の班の輪の端で、腕を組んでこちらを睨んでいた。目が合うと、ふいと顔を背ける。","f":"yohei","m":"anger"},{"t":"d","s":"「あいつ、まだ睨んでる」","f":"yohei"},{"t":"d","s":"「そう？」","f":"yohei"},{"t":"d","s":"「あんたのこと気にしてるのよ、たぶん」","f":"yohei"},{"t":"d","s":"「なんで？」","f":"yohei"},{"t":"d","s":"「……さあね」","f":"yohei"},{"t":"n","s":"乃亜は、軽く肩をすくめた。","f":"noa"}]},{"key":"8-5","title":"肝試し","bg":"bg_grave","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","ren","ryoma"],"lines":[{"t":"cg","v":"cg_kimodameshi"},{"t":"n","s":"夜。山道の入口には、小さな提灯が一つだけ吊るされていた。"},{"t":"n","s":"森の中は、真っ暗だった。木々の枝が空を覆い、月明かりもほとんど届かない。風が吹くたびに、葉がざわざわと鳴る。"},{"t":"d","s":"「じゃあ、第五班、出発！」"},{"t":"n","s":"木村の声に送り出されて、六人は山道に足を踏み入れた。"},{"t":"d","s":"「うわ、思ったより暗いな……」"},{"t":"d","s":"「足元、気をつけて」"},{"t":"d","s":"「お、おい、押すなよ」"},{"t":"d","s":"「押してない」"},{"t":"n","s":"先頭を行くのは佐野。その後ろに中野、小川。最後尾に、耀平と乃亜。","f":"yohei"},{"t":"d","s":"「……ねえ、耀平」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「さっきから、変じゃない？」","f":"yohei"},{"t":"d","s":"「うん。気づいてた」","f":"yohei"},{"t":"d","s":"「やっぱり」","f":"yohei"},{"t":"n","s":"風が止んでいる。昨日のハイキングのときと同じだった。","f":"yohei"},{"t":"n","s":"鳥の声も、虫の音もしない。","f":"yohei"},{"t":"d","s":"「お化け役の先輩、まだ出てこないね」","f":"yohei"},{"t":"d","s":"「出てこないんじゃなくて、出られないんだと思う」","f":"yohei"},{"t":"d","s":"「え？」","f":"yohei"},{"t":"d","s":"「先輩たち、たぶん、持ち場に誰もいない」","f":"yohei"},{"t":"n","s":"耀平は、木刀を握る手に力を込めた。布袋から取り出したのは、旅館を出る直前だった。","f":"yohei"},{"t":"d","s":"「佐野」","f":"yohei"},{"t":"d","s":"「ん？」","f":"yohei"},{"t":"d","s":"「止まって」","f":"yohei"},{"t":"d","s":"「どうした？」","f":"yohei"},{"t":"d","s":"「……来る」","f":"yohei"},{"t":"n","s":"耀平の声が、いつもの眠そうな調子ではなかった。","f":"yohei"},{"t":"n","s":"その一瞬後、茂みの奥から、黒い影が飛び出した。","f":"yohei"},{"t":"n","s":"一方、遠く離れた森の外れ。","f":"yohei"},{"t":"n","s":"九条蓮は、旅館の屋根の上から山道を見下ろしていた。傍らには、木村ら三人の教師。","f":"ren"},{"t":"d","s":"「会長、そろそろ配置につきましょう」","f":"ren"},{"t":"d","s":"「ええ。……ですが」","f":"ren"},{"t":"n","s":"蓮は、眉をひそめた。","f":"ren"},{"t":"d","s":"「妙ですね。見回りに出ているはずの先生の姿が、いない」","f":"ren"},{"t":"d","s":"「え？」","f":"ren"},{"t":"d","s":"「第三班が出発したときから、持ち場の先輩の気配が、一つ消えている」","f":"ren"},{"t":"n","s":"蓮の顔色が、変わった。","f":"ren"},{"t":"d","s":"「しまった――誘い込まれた。急ぎます、全員、森へ！」","f":"ren"},{"t":"n","s":"蓮が屋根を蹴る。教師たちが、慌ててその後を追う。","f":"ren"},{"t":"n","s":"森の奥では、すでに、悲鳴が上がっていた。","f":"ren"},{"t":"n","s":"そして、その悲鳴を、少し離れた木の陰で聞いていた少年がいた。","f":"ren"},{"t":"n","s":"竜馬だった。別の班の列から、いつの間にか抜け出して、耀平たちの後を追っていたのだ。","f":"ryoma"},{"t":"d","s":"「……あいつら、なんで……」","f":"ryoma"},{"t":"n","s":"竜馬は、息を呑んで、木の幹にしがみついた。足が、動かなかった。","f":"ryoma","m":"surprise"},{"t":"n","s":"闇の向こうで、黒い外套の男が、ゆっくりと笑っていた。","f":"ryoma"}]}]},{"n":9,"title":"覚醒（百花繚乱）","sub":"中学・1年","era":"middle","lead":"「一花心舞」は、ただの捨てスキルではなかった。そして、その夜、耀平の目に桜が咲いた。","scenes":[{"key":"9-1","title":"襲撃","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle1","cast":["noa","yohei"],"lines":[{"t":"n","s":"茂みが、割れた。"},{"t":"n","s":"黒い影が三つ、子どもたちの前に躍り出た。うち二つは、黒い衣を着た屈強な男。最後の一人は、昨日、蓮に吹き飛ばされた、あの黒い外套の男だった。","fx":"shake"},{"t":"d","s":"「ようやく、あつまってくれたようだな」"},{"t":"n","s":"男は、腹を押さえながら、へらへらと笑った。","m":"happy"},{"t":"d","s":"「明日は帰るって言うから、待ったんだ。ガキどもの救助は、ここには来ねえ」"},{"t":"d","s":"「……あ、あの。お化け役の、先輩ですか？」"},{"t":"d","s":"「とんでもねえ。お前らを、買い取ってくれるお客さんがいるんだよ」"},{"t":"n","s":"佐野のいつもの笑顔が、凍りついた。"},{"t":"d","s":"「……は？」"},{"t":"d","s":"「スキル持ちの子どもは、高く売れる。特に、この学校のやつはな」"},{"t":"n","s":"男が手を振ると、後ろの二人が動いた。"},{"t":"d","s":"「うわっ――」"},{"t":"d","s":"「きゃあっ！」"},{"t":"n","s":"中野と小川が、一瞬で地面に押さえ込まれた。首筋に手刀が入る。二人の目が、ぐるりと白目をむいて、そのまま動かなくなった。"},{"t":"d","s":"「中野！　小川！」"},{"t":"d","s":"「大丈夫だ。気絶させただけだ。傷をつけたら、値が下がるからな」"},{"t":"n","s":"佐野が叫んで駆け出した。けれど、黒い外套の男の手が、すっと延びる。影が、地面からするりと立ち上がって、佐野の足を絡め取った。"},{"t":"d","s":"「うっ……あ、足が――」"},{"t":"d","s":"「足が速いって、実は、俺の影には勝てねえんだよ」"},{"t":"n","s":"佐野の体が、影に引きずり込まれ、ぶらりと逆さに吊り上げられた。"},{"t":"d","s":"「佐野っ！」"},{"t":"n","s":"耀平が叫んだ。木刀を押し出すように構えて、一歩、前へ出る。","f":"yohei"},{"t":"d","s":"「やめろ。その子を、離せ」","f":"yohei"},{"t":"d","s":"「ほう。ガキが、いっぱしに木刀か」","f":"yohei"},{"t":"n","s":"男は、面白そうに目を細めた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"乃亜が、耀平の前に立った。袖を、きゅっと握りしめて。","f":"noa"},{"t":"d","s":"「下がってて」","f":"noa"},{"t":"d","s":"「乃亜、でも」","f":"noa"},{"t":"d","s":"「下がってて。……お願い」","f":"noa"},{"t":"n","s":"乃亜の声は、震えていた。けれど、その手は、水のように静かに構えを取った。","f":"noa"},{"t":"d","s":"「碧水――心希」","f":"noa"},{"t":"n","s":"乃亜の周囲の空気が、ゆらりと揺れた。地面から、透明な水が湧き出して、乃亜の手の平の上で、細い紐のようによじれた。","f":"noa"}]},{"key":"9-2","title":"乃亜","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","noa"],"lines":[{"t":"d","s":"「……ガキの水使いというわけか」"},{"t":"n","s":"男は、鼻で笑った。","m":"happy"},{"t":"d","s":"「やってみろ。できるならな」"},{"t":"n","s":"乃亜が、腕を振る。水の紐が、錐のようにピンと張って男の顔面に飛んだ。","f":"noa"},{"t":"n","s":"こともなげに、男は首を傾ける。水の錐は、頬をかすめて、背後の木に穴を穿った。","f":"noa"},{"t":"d","s":"「ある程度は、できるようだな」","f":"noa"},{"t":"n","s":"男の影が、るる、と走る。乃亜の足元に黒い手が、三本、四本と延びてくる。","f":"noa"},{"t":"d","s":"「……っ」","f":"noa"},{"t":"n","s":"乃亜は、跳んでかわす。水の壁を作る。だが、影は、水を飲み込みながら進む。","f":"noa"},{"t":"d","s":"「乃亜！」","f":"noa"},{"t":"n","s":"耀平が、木刀を振り下ろした。影の手を、一本、断ち切る。","f":"yohei"},{"t":"d","s":"「ほう。このガキも、多少はやるか」","f":"yohei"},{"t":"n","s":"男の顔に、初めて余裕の消える色が浮かんだ。","f":"yohei"},{"t":"d","s":"「だが、ガキはガキだ」","f":"yohei"},{"t":"n","s":"男が、一歩、踏み込んだ。それだけで、距離が消えた。","f":"yohei"},{"t":"n","s":"蹴りが、耀平の脇腹にめり込んだ。","f":"yohei"},{"t":"d","s":"「がはっ……！」","f":"yohei"},{"t":"n","s":"耀平の体が、宙を舞った。木の幹に叩きつけられて、肺から空気が押し出される。視界が、赤く点滅した。","f":"yohei","fx":"shake"},{"t":"d","s":"「耀平っ！」","f":"yohei"},{"t":"n","s":"乃亜の悲鳴が、耳にこだまする。","f":"noa"},{"t":"d","s":"「……だいじょうぶ。まだ、立てる」","f":"noa"},{"t":"n","s":"耀平は、木刀を杖にして立ち上がった。口の端から、血が一筋、垂れている。","f":"yohei"},{"t":"d","s":"「ほう、まだ立つか。こいつ、頭のネジが飛んでるな」","f":"yohei"},{"t":"d","s":"「……二人とも、逃げて。おれが、時間を稼ぐ」","f":"yohei"},{"t":"d","s":"「耀平、無理よ！　相手は大人で――」","f":"yohei"},{"t":"d","s":"「分かってる」","f":"yohei"},{"t":"n","s":"耀平は、笑って見せた。","f":"yohei"},{"t":"d","s":"「でも、逃げるって、約束してないから」","f":"yohei"},{"t":"n","s":"男が、つまらなそうに首を鳴らした。","f":"yohei"},{"t":"d","s":"「バカが。じゃあ、もう少しだけ、やってやる」","f":"yohei"},{"t":"n","s":"黒い影が、耀平を飲み込もうとする。耀平は木刀を振った。踊った。踏み込んだ。けれど、どれも、届かない。逆に、一発、二発、三発と、体に重いものが入る。","f":"yohei"},{"t":"n","s":"やがて、耀平は膝をついた。","f":"yohei"},{"t":"d","s":"「……くっ」","f":"yohei"},{"t":"d","s":"「終わりだ」","f":"yohei"},{"t":"n","s":"男の拳が、耀平の頭を狙った。","f":"yohei"},{"t":"n","s":"その瞬間、乃亜が、体ごとぶつかった。","f":"noa"},{"t":"d","s":"「やめて！」","f":"noa"},{"t":"n","s":"拳が乃亜の肩をかすめ、乃亜の体が地面に強く叩きつけられた。","f":"noa","fx":"shake"},{"t":"d","s":"「乃亜っ！」","f":"noa"}]},{"key":"9-3","title":"桃色","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","noa"],"lines":[{"t":"d","s":"「あんまり顔を傷つけると、値が下がる。だから、こっちにしようかな」"},{"t":"n","s":"男は、乃亜の腕を、引きずり起こした。小さな手首を、片手でつかむ。","f":"noa"},{"t":"d","s":"「……離して。いやっ」","f":"noa"},{"t":"d","s":"「スキル持ちの子どもの体というのは、部位でも売れるんだよ。化け物のお客さんとかな」","f":"noa"},{"t":"n","s":"男は、へらへらと笑った。","f":"noa","m":"happy"},{"t":"d","s":"「腕の一本や二本、あってもいいだろ。むしろ、水を操れるやつなんざ、買い手はいくらでもつく――」","f":"noa"},{"t":"n","s":"男の影が、刀の形に延びた。黒い刃が、乃亜の肩にあてがわれる。","f":"noa"},{"t":"d","s":"「……やめろ」","f":"noa"},{"t":"n","s":"声がした。耐えるように、でも、あまりに小さな声で。","f":"noa"},{"t":"d","s":"「あん？」","f":"noa"},{"t":"d","s":"「……やめろ。乃亜に、触るな」","f":"noa"},{"t":"n","s":"男が振り返る。","f":"noa"},{"t":"n","s":"耀平が、立っていた。","f":"yohei"},{"t":"n","s":"血だらけの顔で、木刀を握りしめて、ゆらりと。","f":"yohei"},{"t":"d","s":"「やめろって、言ってるだろ」","f":"yohei"},{"t":"n","s":"ことばの、重さが、変わった。","f":"yohei"},{"t":"n","s":"耀平の胸の奥で、何かが、ぷつりと、切れた。","f":"yohei"},{"t":"n","s":"空っぽになるほどの怒り。強く、強く、心臓を揺さぶられる。視界が滲む。乃亜が傷つく。祖父の手の温度が、遠くなったあの日が、頭の中で重なる。","f":"noa"},{"t":"d","s":"「もう、誰も――」","f":"noa"},{"t":"n","s":"耀平の口から、ひどく小さな声がこぼれた。","f":"yohei"},{"t":"d","s":"「……誰も、奪うなよ」","f":"yohei"},{"t":"n","s":"ふわりと、風が吹いた。","f":"yohei"},{"t":"n","s":"さっきまで止まっていた風が、耀平を中心に、渦を巻く。","f":"yohei"},{"t":"n","s":"小さな桜の花びらが、一枚。二枚。三枚。いや、次々と、数え切れないほどの花びらが、耀平の周囲の空中に現れていく。","f":"yohei"},{"t":"d","s":"「……なんだ、こりゃ」","f":"yohei"},{"t":"n","s":"男が、無意識に一歩、下がった。","f":"yohei"},{"t":"n","s":"耀平が、ゆっくりと顔を上げる。","f":"yohei"},{"t":"n","s":"その目に、桜が咲いていた。","f":"yohei"},{"t":"n","s":"瞳の奥で、淡い桃色の光が、小さく、しかし確かに、灯っている。","f":"yohei"},{"t":"d","s":"「一花――」","f":"yohei"},{"t":"n","s":"耀平の口が、勝手に動いた。","f":"yohei"},{"t":"d","s":"「――百花繚乱」","f":"yohei","fx":"bloom"},{"t":"n","s":"桜の嵐が、弾けた。","f":"yohei"}]},{"key":"9-4","title":"百花繚乱","bg":"bg_grave","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei"],"lines":[{"t":"cg","v":"cg_hyakka"},{"t":"n","s":"最初に感じたのは、あまりにも静かな感覚だった。"},{"t":"n","s":"さっきまでの痛みが、遠のいていく。袖をかすめる桜の花びらが、スローモーションのように見える。男の影の一本一本が、どこを通ってくるのか、分かった。"},{"t":"d","s":"「……見える」"},{"t":"n","s":"耀平は、木刀を、すっと構え直した。桜の花びらが、木刀の刀身に絡んで、淡い桃色の光を帯びる。","f":"yohei"},{"t":"d","s":"「てめえ……どこから、そんな――」","f":"yohei"},{"t":"n","s":"男の影が、怒涛のように迫る。耀平は、ひらりと身を翻した。影の手が、花びらに触れるたび、軽くいなされて、空を切る。","f":"yohei"},{"t":"d","s":"「なんだ、この動きは！」","f":"yohei"},{"t":"n","s":"桜を踏むたび、体が先に反応する。視線より、恐怖より、思考よりも、速く。","f":"yohei"},{"t":"n","s":"耀平は、木刀を、振った。","f":"yohei"},{"t":"n","s":"黒い影が、横一閃に、割れる。","f":"yohei","fx":"flash"},{"t":"d","s":"「ぐうっ……！」","f":"yohei"},{"t":"n","s":"男が、後ろによろめく。しかし、完全には崩れない。影を、盾のように張り直して、体勢を立て直す。","f":"yohei"},{"t":"d","s":"「調子に乗るなよガキ――！」","f":"yohei"},{"t":"n","s":"男の影が、拳の形に膨らんだ。巨大な黒い拳が、耀平に落とされる。","f":"yohei"},{"t":"n","s":"耀平は、その真下で、足を踏んだ。桜を踏む。踏む。踏む。踊るように拳の内側に滑り込み、横一閃。","f":"yohei","fx":"flash"},{"t":"n","s":"影が、散る。","f":"yohei"},{"t":"d","s":"「――っ、があああっ！」","f":"yohei"},{"t":"n","s":"男の口から、悲鳴と血が吹き出た。黒い外套が、胸から縦に裂けている。","f":"yohei"},{"t":"d","s":"「てめえ……ガキのくせに……」","f":"yohei"},{"t":"n","s":"男は、膝をついた。けれど、その目はまだ死んではいなかった。黒い影が、足元の地面を、ずる、と進む。","f":"yohei"},{"t":"d","s":"「これで、終わりにしてやる」","f":"yohei"},{"t":"n","s":"影が、耀平の足を絡め取る。耀平は、構わなかった。影の拘束を、木刀で断ち切る。あと一歩。あと一閃。","f":"yohei","fx":"flash"},{"t":"n","s":"だが、耀平の膝は、限界だった。","f":"yohei"},{"t":"d","s":"「……っ」","f":"yohei"},{"t":"n","s":"視界が、白くなる。桜の花びらが、ひらひらと、散っていく。","f":"yohei"},{"t":"d","s":"「今度こそ、終わりだ」","f":"yohei"},{"t":"n","s":"男が、拳を引いた。耀平は、それを、見ていた。ゆっくりと。分かっていたのに、体が動かない。","f":"yohei"},{"t":"n","s":"――そのとき。","f":"yohei"},{"t":"d","s":"「……痛いのは、いやですよね」","f":"yohei"},{"t":"n","s":"やさしい声がした。","f":"yohei"}]},{"key":"9-5","title":"白い少女","bg":"bg_grave","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","noa"],"lines":[{"t":"n","s":"その声は、風のように、すっと耀平の背中に入ってきた。","f":"yohei"},{"t":"n","s":"振り返る余裕もなかった。けれど、耳元に、人の気配が、ふっと降りてくる。","f":"yohei"},{"t":"d","s":"「淡雪」","f":"yohei"},{"t":"n","s":"ふわりと、白い光が、耀平を包んだ。","f":"yohei"},{"t":"n","s":"痛みが、消えた。血の味が、薄れていく。さっきまでの疲弊が、体の外に押し出されていくようだった。","f":"yohei"},{"t":"d","s":"「……誰だ、てめえ」","f":"yohei"},{"t":"n","s":"男が、警戒して一歩、下がる。","f":"yohei"},{"t":"n","s":"耀平の背中の暗闇から、一人の少女が、ゆっくりと歩いてきた。","f":"yohei"},{"t":"n","s":"長い水色の髪。白い美しい肌。淡い水色のコートの裾が、夜風に揺れている。まるで、物語の中から、押し出されてきたような姿だった。","f":"yohei"},{"t":"d","s":"「ここは、あなたの来るところではありませんよ」","f":"yohei"},{"t":"d","s":"「……なんだと？」","f":"yohei"},{"t":"d","s":"「ここは、人が傷つく場所ではありません。……だから、拒絶します」","f":"yohei"},{"t":"n","s":"少女は、指をそっと、空にかざした。","f":"yohei"},{"t":"d","s":"「――風花」","f":"yohei"},{"t":"n","s":"男の拳が、止まった。","f":"yohei"},{"t":"n","s":"いや、拒絶された。見えない壁に弾かれるように、男の体が、彼女の目の前で、大きく後ろへ弾き飛ばされた。","f":"yohei"},{"t":"d","s":"「がはっ……！　規格外……！？」","f":"yohei"},{"t":"n","s":"男の目が、初めて、恐怖に染まった。","f":"yohei"},{"t":"d","s":"「聞いてねーぞ……こんなところに、二人も……！」","f":"yohei"},{"t":"n","s":"男は、よろけながら立ち上がって、後ずさる。場の空気が、はっきりと変わった。","f":"yohei"},{"t":"d","s":"「こりゃヤバい」","f":"yohei"},{"t":"n","s":"男は影を蹴って、森の奥へ消えようとした。けれど、耀平がそれを許さなかった。","f":"yohei"},{"t":"d","s":"「……逃がさない」","f":"yohei"},{"t":"n","s":"桜を踏む。影を穿つ。最後の一閃。","f":"yohei","fx":"flash"},{"t":"d","s":"「百花繚乱――」","f":"yohei","fx":"bloom"},{"t":"n","s":"桜吹雪が、横一文字に走った。","f":"yohei"},{"t":"n","s":"男は、一言も発せず、崩れ落ちた。","f":"yohei"},{"t":"n","s":"静寂。","f":"yohei"},{"t":"n","s":"耀平は、木刀を落とした。と同時に、膝が崩れ、地面に倒れ込んだ。","f":"yohei"},{"t":"d","s":"「……のあ。ぶじ、か……」","f":"yohei"},{"t":"n","s":"とっさに起き上がろうとした乃亜は、起き上がれなかった。耀平の袖を握ったまま、目の前に起こった光景を、じっと見つめていた。","f":"noa"},{"t":"n","s":"はらはらと、桃色の花びらが、天から降り続ける。その真ん中で、少年が、安らかに目を閉じている。","f":"noa"},{"t":"d","s":"「……耀平」","f":"noa"},{"t":"n","s":"乃亜の視界が、ゆっくりと、暗くなっていく。意識が遠のく直前、白い少女が、耀平のもとにしゃがみ込んでいるのが、見えた。","f":"noa"},{"t":"n","s":"少女は、少年の頬の血を、指先でそっと拭った。","f":"noa"},{"t":"d","s":"「……耀平くんって、いうんですね」","f":"noa"},{"t":"n","s":"乃亜がさっき、何度も呼んでいたからだろう。少女は、小さく、優しく、微笑んだ。","f":"noa","m":"happy"},{"t":"d","s":"「あなたの桜、きれいでした」","f":"noa"},{"t":"n","s":"静かな声だった。いつまでも、ここで聞いていたいと思う、やさしい声。","f":"noa"},{"t":"d","s":"「また、会えますかね、耀平くん」","f":"noa"},{"t":"n","s":"少女は、立ち上がった。淡い水色のコートが、ふわりと夜風に揺れる。その姿は、白い光に溶けるように、すうっと遠のいていく。","f":"noa"},{"t":"n","s":"乃亜は、そこで、意識を手放した。","f":"noa"}]},{"key":"9-6","title":"あとに残ったもの","bg":"bg_classroom_middle","dark":true,"mood":"night","bgm":"night1","cast":["ren","yohei","noa"],"lines":[{"t":"d","s":"「――何だ、これは」"},{"t":"n","s":"九条蓮が、森の奥をのぞき込んだとき、そこには、戦いの跡だけが残っていた。","f":"ren"},{"t":"n","s":"倒れた黒い外套の男。気絶した二人の黒衣の男。そして、地面に倒れ込んでいる、五人の生徒たち。","f":"ren"},{"t":"n","s":"その足元に、桃色の花びらが、ひらり、ひらりと、降り積もっている。","f":"ren"},{"t":"d","s":"「会長、これは……」","f":"ren"},{"t":"d","s":"「……そうですね。何があったのか、分かりません」","f":"ren"},{"t":"n","s":"蓮は、足元の花びらを一枚、拾い上げた。指先で潰せば散って消えるそれは、確かに、誇り高い桜の御魂のように、暖かかった。","f":"ren"},{"t":"d","s":"「これは……」","f":"ren"},{"t":"n","s":"蓮は、倒れている生徒の中の、一人の顔を見た。","f":"ren"},{"t":"n","s":"血だらけの顔で、安らかに目を閉じている。手には、まだ木刀が握られている。","f":"ren"},{"t":"d","s":"「……耀平、か」","f":"ren"},{"t":"n","s":"蓮は、何も言わなかった。","f":"ren"},{"t":"d","s":"「とりあえず、全員を回収しましょう。この男たちも拘束を」","f":"ren"},{"t":"d","s":"「はい。……会長、この件は」","f":"ren"},{"t":"d","s":"「……あとで考えます」","f":"ren"},{"t":"n","s":"蓮は、そっと耀平を抱き上げた。軽い。この体のどこに、あんな力があったというのか。","f":"ren"},{"t":"n","s":"少し離れた木の陰で、竜馬が、息を殺していた。","f":"ryoma"},{"t":"n","s":"手足が、小刻みに震えている。視線の先で、桃色の花びらが、静かに消えていく。","f":"ryoma"},{"t":"d","s":"「……おれは、あのとき……」","f":"ryoma"},{"t":"n","s":"竜馬は、拳を、強く握りしめた。悔しさと、恐怖と、憧れと。それらが、胸の中でぐちゃぐちゃに混ざっていた。","f":"ryoma"},{"t":"d","s":"「何も、できなかった」","f":"ryoma"},{"t":"n","s":"こぼれた声は、誰にも届かなかった。","f":"ryoma"},{"t":"n","s":"翌朝。旅館の医務室で、乃亜は目を覚ました。","f":"noa"},{"t":"d","s":"「……耀平は？」","f":"noa"},{"t":"d","s":"「ここにいる。まだ寝てる」","f":"noa"},{"t":"n","s":"隣のベッドに、耀平がいた。顔の傷は、すでに消えている。","f":"yohei"},{"t":"d","s":"「……無事で、よかった」","f":"yohei"},{"t":"d","s":"「あなたも、無事ですよ」","f":"yohei"},{"t":"n","s":"医務室の先生が、優しく笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「明日には、起きられるでしょう」","f":"yohei"},{"t":"n","s":"乃亜は、耀平の寝顔を、じっと見つめた。昨夜、見たものが、脳裏で、くりかえされる。","f":"noa"},{"t":"n","s":"あれは、規格外だ。","f":"noa"},{"t":"n","s":"あの白い少女と、同じ。世界に数十人しかいないとされる、成長限界のない、特別な存在。","f":"noa"},{"t":"d","s":"「……言わない」","f":"noa"},{"t":"n","s":"乃亜は、小さく、呟いた。","f":"noa"},{"t":"d","s":"「会長にも、先生にも。耀平が、遠くに行ってしまうかもしれないから」","f":"noa"},{"t":"n","s":"胸の奥が、きゅっと痛んだ。おなじくらい、誇らしい気持ちもあった。この人は、やっぱり、すごい人だった。","f":"noa"},{"t":"d","s":"「だけど、約束したからね。どこに行っても、帰ってくるって」","f":"noa"},{"t":"n","s":"隣のベッドで、耀平が、寝返りを打った。","f":"yohei"},{"t":"d","s":"「……ん、のあ……」","f":"yohei"},{"t":"n","s":"寝言だった。乃亜は、思わず、小さく笑った。","f":"noa","m":"happy"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"n","s":"窓の外では、朝日が、山の稜線をゆっくりと照らしていた。","f":"noa"}]}]},{"n":10,"title":"竜馬との喧嘩と改心","sub":"中学・1年","era":"middle","lead":"何も知らないふりをする耀平と、すべてを見ていた竜馬。ぶつかった末に、竜馬は一人で答えを出す。","scenes":[{"key":"10-1","title":"帰りのバス","bg":"bg_classroom_middle","dark":true,"mood":"night","bgm":"night2","cast":["yohei","noa","ren"],"lines":[{"t":"n","s":"修学旅行の最終日。帰りのバスの中は、行きよりもずっと静かだった。"},{"t":"d","s":"「昨夜、不審者が侵入したが、生徒会長の九条くんと先生方がすぐに対応した。怪我をした生徒はいない」"},{"t":"n","s":"担任の木村が、前の席で淡々と説明した。"},{"t":"d","s":"「なお、詳しいことは警察に任せている。皆さんは、気にしなくていい」"},{"t":"n","s":"生徒たちは、ほっとした顔と、少し不満げな顔に分かれた。何も知らないまま、あっさりと日常に戻される。それが、大人たちの選んだやり方だった。"},{"t":"d","s":"「……会長が、一人でやっつけたんだって」"},{"t":"d","s":"「やっぱ、すげえな」"},{"t":"d","s":"「お化け役の先輩たち、全員無事だったらしいよ」"},{"t":"n","s":"耀平は、窓にもたれて、目を閉じていた。眠っているのではない。あの夜のことを、頭の中で何度も繰り返していた。","f":"yohei"},{"t":"d","s":"「……耀平」","f":"yohei"},{"t":"d","s":"「ん」","f":"yohei"},{"t":"d","s":"「体、もう大丈夫なの」","f":"yohei"},{"t":"d","s":"「うん。ふしぎなくらい」","f":"yohei"},{"t":"d","s":"「そう」","f":"yohei"},{"t":"n","s":"隣の席の乃亜は、前を向いたまま、短く答えた。それ以上は、何も聞かなかった。","f":"noa"},{"t":"n","s":"聞かない代わりに、乃亜の指が、耀平の袖をそっとつまんでいた。","f":"noa"},{"t":"n","s":"バスが山を下りていく。窓の外を、秋の景色が流れていく。","f":"noa"},{"t":"n","s":"後ろの席から、じっと耀平の後頭部を見つめる視線があることに、耀平だけが気づいていなかった。","f":"yohei"}]},{"key":"10-2","title":"生徒会長","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily2","cast":["ren","yohei"],"lines":[{"t":"n","s":"学校に戻って三日後。昼休みの廊下で、耀平は呼び止められた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"n","s":"振り向くと、九条蓮が立っていた。制服の襟まで整った、いつもの姿だった。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「九条でいいと言っただろう」","f":"ren"},{"t":"d","s":"「はい、九条先輩」","f":"ren"},{"t":"d","s":"「……先日は、大変だったな」","f":"ren"},{"t":"n","s":"蓮の声は静かだった。けれど、その視線は、耀平の顔から指先まで、ゆっくりと確かめるように動いていた。","f":"ren"},{"t":"d","s":"「いえ。ぼくは、寝てただけなので」","f":"ren"},{"t":"d","s":"「寝ていた、か」","f":"ren"},{"t":"d","s":"「はい。気づいたら、朝でした」","f":"ren"},{"t":"n","s":"耀平は、あっさりと答えた。嘘ではなかった。少なくとも、最後の部分は。","f":"yohei"},{"t":"n","s":"蓮は、ポケットから何かを取り出した。薄桃色の、小さな花びらだった。","f":"ren"},{"t":"d","s":"「あの現場に、これが落ちていてな」","f":"ren"},{"t":"d","s":"「桜、ですね」","f":"ren"},{"t":"d","s":"「ああ。季節外れの、桜だ」","f":"ren"},{"t":"d","s":"「ふしぎですね」","f":"ren"},{"t":"d","s":"「……そうだな」","f":"ren"},{"t":"n","s":"蓮は、花びらを指先で潰した。ふ、と消える。","f":"ren"},{"t":"d","s":"「君は、桜が好きなのか」","f":"ren"},{"t":"d","s":"「好きというか、気づくと、そこにあるんです」","f":"ren"},{"t":"d","s":"「そうか」","f":"ren"},{"t":"n","s":"蓮は、それだけ言うと、小さく笑った。","f":"ren","m":"happy"},{"t":"d","s":"「いや、すまない。気にしないでくれ。……まさかな、と思っただけだ」","f":"ren"},{"t":"d","s":"「まさか、ですか？」","f":"ren"},{"t":"d","s":"「忘れてくれ。それより、朝の素振りは続けているのか」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「そうか。無理はするなよ」","f":"ren"},{"t":"n","s":"蓮は、片手を軽く上げて、廊下の向こうへ歩いていった。","f":"ren"},{"t":"n","s":"耀平は、その背中を見送りながら、ほんの少しだけ、胸の奥で息をついた。","f":"yohei"},{"t":"i","s":"（……あの人、たぶん、少し疑ってる）","f":"yohei"},{"t":"n","s":"けれど、疑いは確信に変わらない。耀平の力は、まだ、証拠として残るほどのものではない。","f":"yohei"},{"t":"n","s":"それに、蓮自身が、自分の疑いを「まさか」で済ませようとしていた。生徒会長として、守るべき範囲を、あえて広げすぎないように。","f":"ren"}]},{"key":"10-3","title":"見てたぜ","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily3","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"その日の放課後、訓練場。"},{"t":"n","s":"耀平がいつものように木刀を振っていると、背後から、足音が近づいてきた。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"n","s":"振り返ると、竜馬が立っていた。腕を組み、いつもより低い声で。","f":"ryoma"},{"t":"d","s":"「竜馬。どうしたの」","f":"ryoma"},{"t":"d","s":"「見てたぜ」","f":"ryoma"},{"t":"d","s":"「なにを」","f":"ryoma"},{"t":"d","s":"「修学旅行の夜だ」","f":"ryoma"},{"t":"n","s":"耀平の手が、一瞬だけ止まった。","f":"yohei"},{"t":"d","s":"「……なんのこと」","f":"yohei"},{"t":"d","s":"「とぼけんな。おまえ、あの男を倒しただろ」","f":"yohei"},{"t":"d","s":"「倒してないよ。ぼくは、気絶してた」","f":"yohei"},{"t":"d","s":"「嘘つけ。桜が、見えた」","f":"yohei"},{"t":"n","s":"竜馬の声が、わずかに震えていた。怒りではない。もっと別の、うまく名前のつかないものだった。","f":"ryoma"},{"t":"d","s":"「おれは、あのとき、動けなかった。手も足も、ぜんぜん」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「怖かった。あの男も、おまえも」","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「でもな」","f":"ryoma"},{"t":"n","s":"竜馬は、拳を握りしめた。","f":"ryoma"},{"t":"d","s":"「おまえが、何か隠してんのは分かる。それが、むかつくんだよ」","f":"ryoma"},{"t":"d","s":"「隠してないよ」","f":"ryoma"},{"t":"d","s":"「じゃあ、証明しろ」","f":"ryoma"},{"t":"n","s":"竜馬の全身から、赤い熱が立ち上がった。","f":"ryoma"},{"t":"d","s":"「やるぞ、耀平。小学校のときの、続きだ」","f":"ryoma"},{"t":"d","s":"「やめようよ」","f":"ryoma"},{"t":"d","s":"「やめねえ。ここで逃げたら、おれはずっと、あの夜に置いてかれたままだ」","f":"ryoma"},{"t":"n","s":"耀平は、ゆっくりと息を吐いた。","f":"yohei"},{"t":"i","s":"（……逃げてるのは、おれのほうかもしれない）","f":"yohei"},{"t":"n","s":"そう思いながらも、桜の力を使うつもりはなかった。あれは、人に向けていいものではない。少なくとも、友達に向けるものでは。","f":"yohei"},{"t":"d","s":"「いいよ。でも、おれは、普通にやる」","f":"yohei"},{"t":"d","s":"「は？」","f":"yohei"},{"t":"d","s":"「木刀だけで。それ以外は、使わない」","f":"yohei"},{"t":"d","s":"「ふざけんなあっ！」","f":"yohei"},{"t":"n","s":"竜馬が、地面を蹴った。","f":"ryoma"}]},{"key":"10-4","title":"ぐだぐだの喧嘩","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"炎が、訓練場の空気を焼いた。"},{"t":"n","s":"小学生の頃とは違う。中学生になった竜馬の炎は、より太く、より速くなっていた。拳に火を纏わせ、連続で叩き込んでくる。","f":"ryoma"},{"t":"n","s":"耀平は、木刀で受け流した。避けた。いなした。けれど、桜の力は使わない。","f":"yohei"},{"t":"d","s":"「くそっ、本気出せ！」","f":"yohei"},{"t":"d","s":"「出してるよ」","f":"yohei"},{"t":"d","s":"「嘘つけ！」","f":"yohei"},{"t":"d","s":"「ほんとだよ。だって、ぼくは、竜馬より弱いもん」","f":"yohei"},{"t":"d","s":"「ふざけんな！」","f":"yohei"},{"t":"n","s":"拳が、耀平の頬をかすめた。熱が肌を焼く。耀平は、一歩下がって、体勢を立て直した。","f":"yohei"},{"t":"n","s":"毎朝の素振りで鍛えた体は、確かに強くなっていた。けれど、純粋な技術と力だけでは、竜馬の炎には押される。","f":"ryoma"},{"t":"d","s":"「ほら見ろ！　やっぱり、大したことねえじゃねえか！」","f":"ryoma"},{"t":"d","s":"「そうだよ」","f":"ryoma"},{"t":"d","s":"「なんで言い返さねえんだよ！」","f":"ryoma"},{"t":"d","s":"「だって、本当のことだから」","f":"ryoma"},{"t":"n","s":"竜馬の顔が、ゆがんだ。","f":"ryoma"},{"t":"d","s":"「……だから、そういうところが、むかつくんだよ」","f":"ryoma"},{"t":"n","s":"竜馬は、一歩、下がった。両手を前に突き出す。空気が、ごうごうと渦を巻き始める。","f":"ryoma"},{"t":"d","s":"「竜馬、それ、やめて」","f":"ryoma"},{"t":"d","s":"「うるせえ。おまえが本気を出さねえなら、出させてやる」","f":"ryoma"},{"t":"d","s":"「あの火は、人に向けちゃだめだ」","f":"ryoma"},{"t":"d","s":"「うるせえっ！」","f":"ryoma"},{"t":"n","s":"小学校のときの、あの記憶が、二人の頭に同時によみがえった。","f":"ryoma"},{"t":"n","s":"竜馬の掌に、巨大な火球が膨らんでいく。焦げた地面。泣いていた自分。立っていた友達。","f":"ryoma","m":"sad"},{"t":"d","s":"「紅蓮――爆炎！」","f":"ryoma"},{"t":"n","s":"赤い奔流が、耀平に向かって放たれた。","f":"yohei"},{"t":"n","s":"耀平は、木刀を握りしめた。避けようとした。けれど、背後には、訓練場の壁がある。その向こうには、生徒たちの教室がある。","f":"yohei"},{"t":"i","s":"（……ここで避けたら、誰かが傷つく）","f":"yohei"},{"t":"n","s":"耀平の足が、止まった。","f":"yohei"},{"t":"n","s":"同時に、風が吹いた。","f":"yohei"},{"t":"n","s":"桜の花びらが、一枚、耀平の肩に舞い降りた。","f":"yohei"},{"t":"d","s":"「あ……」","f":"yohei"},{"t":"n","s":"その瞬間、耀平の体が、勝手に動いた。","f":"yohei"},{"t":"n","s":"桜を踏む。炎の流れが、見える。木刀に花びらが絡みつく。淡い桃色の光が、刀身を満たしていく。","f":"yohei"},{"t":"d","s":"「――百花繚乱」","f":"yohei","fx":"bloom"},{"t":"n","s":"耀平の口が、呟いた。","f":"yohei"},{"t":"n","s":"桜の嵐が、炎を飲み込んだ。","f":"yohei"},{"t":"n","s":"赤と桃色が、ぶつかり合い、やがて、桜が炎を包み込んで、ふっと消し去った。","f":"yohei"},{"t":"d","s":"「な……」","f":"yohei"},{"t":"n","s":"竜馬の目が、見開かれる。","f":"ryoma"},{"t":"n","s":"気づいたときには、耀平が、竜馬の目の前にいた。木刀の切っ先が、喉元に突きつけられている。","f":"yohei"},{"t":"n","s":"峰打ち。刃のない木刀だからこそ、できる止め方だった。","f":"yohei"},{"t":"d","s":"「……もう、いい？」","f":"yohei"},{"t":"n","s":"耀平の声は、静かだった。","f":"yohei"},{"t":"n","s":"竜馬の足から、力が抜けた。膝が、がくりと折れる。","f":"ryoma"},{"t":"d","s":"「おれは……」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「おれは、おまえに……」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"竜馬の口が、何度か開いて、何度か閉じた。やがて、小さな声が漏れた。","f":"ryoma"},{"t":"d","s":"「……見てたんだ。ずっと」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「おまえが、毎朝、剣を振ってるのを」","f":"ryoma"},{"t":"d","s":"「え？」","f":"ryoma"},{"t":"d","s":"「寮の窓から、見えるんだよ。毎日、毎日」","f":"ryoma"},{"t":"n","s":"耀平は、目を丸くした。","f":"yohei","m":"surprise"},{"t":"d","s":"「それ、知らなかった」","f":"yohei"},{"t":"d","s":"「言うかよ、そんなこと」","f":"yohei"},{"t":"n","s":"竜馬は、地面に座り込んだまま、顔を伏せた。","f":"ryoma"}]},{"key":"10-5","title":"竜馬のひとり","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["ryoma","yohei"],"lines":[{"t":"n","s":"耀平は、竜馬を残して、訓練場を後にした。","f":"yohei"},{"t":"n","s":"何も言わなかった。言えなかった、という方が近い。ここで声をかけたら、竜馬のプライドが、粉々になってしまう気がした。","f":"ryoma"},{"t":"n","s":"一人きりになった訓練場で、竜馬は、しばらく動けなかった。","f":"ryoma"},{"t":"n","s":"夕暮れの光が、焦げた地面を照らしている。焼けた土の匂い。遠くで、運動部の掛け声が聞こえる。","f":"ryoma"},{"t":"d","s":"「……くそっ」","f":"ryoma"},{"t":"n","s":"竜馬は、地面に拳を叩きつけた。","f":"ryoma","fx":"shake"},{"t":"n","s":"悔しかった。","f":"ryoma"},{"t":"n","s":"負けたことが、ではない。","f":"ryoma"},{"t":"i","s":"（あいつは、あの炎を、止めやがった）","f":"ryoma"},{"t":"n","s":"人を傷つけないように。自分の後ろにあるものを、守るように。","f":"ryoma"},{"t":"n","s":"小学校のときも、そうだった。あのとき、竜馬は、本気で耀平を殺すつもりで火を出した。耀平は、それを受け止めて、笑って、「いいよ」と言った。","f":"ryoma"},{"t":"i","s":"（……何なんだよ、おまえは）","f":"ryoma"},{"t":"n","s":"頭の奥で、ずっと前の記憶が、浮かんできた。","f":"ryoma"},{"t":"n","s":"幼稚園の園庭。木の枝を持った、小さな男の子が二人。","f":"ryoma"},{"t":"d","s":"「ぼく、けんせいになる！」","f":"ryoma"},{"t":"d","s":"「おれもなる！」","f":"ryoma"},{"t":"d","s":"「じゃあ、おれが、ぜったいつよくなる！」","f":"ryoma"},{"t":"d","s":"「ぼくも！」","f":"ryoma"},{"t":"d","s":"「どっちがつよくなるか、しょうぶだ！」","f":"ryoma"},{"t":"d","s":"「うん！」","f":"ryoma"},{"t":"n","s":"笑っていた。あの頃は、ただ、楽しかった。","f":"ryoma"},{"t":"n","s":"竜馬は、気づいた。いつから、自分は、耀平を睨むようになったのだろう。いつから、あいつの努力を、馬鹿にするようになったのだろう。","f":"ryoma","m":"anger"},{"t":"n","s":"スキルが、先に目覚めた。炎を出せるようになった。周りが褒めてくれた。耀平は、花びらを出すだけだった。周りが笑った。","f":"yohei","m":"happy"},{"t":"n","s":"だから、自分のほうが上だと思った。","f":"yohei"},{"t":"n","s":"でも、違った。","f":"yohei"},{"t":"i","s":"（おれは、あいつに、憧れてたんだ）","f":"yohei"},{"t":"n","s":"毎朝、飽きもせず剣を振る背中に。バカにされても、笑っている顔に。何も隠さず、まっすぐ生きているあの目に。","f":"yohei"},{"t":"d","s":"「……ちくしょう」","f":"yohei"},{"t":"n","s":"竜馬の目から、涙がこぼれた。止まらなかった。悔しくて、情けなくて、そして、少しだけ、うれしくて。","f":"ryoma","m":"sad"},{"t":"d","s":"「おれは、あいつに、勝ちたい」","f":"ryoma"},{"t":"n","s":"絞り出すような声だった。","f":"ryoma"},{"t":"d","s":"「バカにするんじゃなくて、ちゃんと、勝ちたい」","f":"ryoma"},{"t":"n","s":"竜馬は、袖で乱暴に目をこすった。それから、ゆっくりと立ち上がった。","f":"ryoma"},{"t":"n","s":"夕日が、彼の背中を赤く染めていた。","f":"ryoma"},{"t":"n","s":"その夜から、竜馬は変わった。","f":"ryoma"},{"t":"n","s":"耀平をバカにする生徒に、拳を向けることはなくなった。代わりに、毎朝、誰よりも早く訓練場に現れるようになった。","f":"yohei"},{"t":"n","s":"耀平には、何も言わなかった。耀平も、何も聞かなかった。","f":"yohei"},{"t":"n","s":"二人の間には、気まずい空気だけが残った。それは、距離というより、お互いに、何かを待っているような沈黙だった。","f":"yohei"}]},{"key":"10-6","title":"ふたり分の距離","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily1","cast":["noa","ryoma","yohei"],"lines":[{"t":"n","s":"数日後。放課後の教室。"},{"t":"n","s":"乃亜が、荷物をまとめながら、ぽつりと聞いた。","f":"noa"},{"t":"d","s":"「竜馬と、何かあったの」","f":"noa"},{"t":"d","s":"「うん。ちょっとだけ」","f":"noa"},{"t":"d","s":"「ちょっと、ね」","f":"noa"},{"t":"d","s":"「ちゃんと話そうとは思ってる。でも、今は、話しかけないほうがいい気がする」","f":"noa"},{"t":"d","s":"「……そう」","f":"noa"},{"t":"n","s":"乃亜は、荷物を鞄に入れる手を止めた。","f":"noa"},{"t":"d","s":"「あいつ、最近、変わったよね」","f":"noa"},{"t":"d","s":"「そう？」","f":"noa"},{"t":"d","s":"「悪口、言わなくなった」","f":"noa"},{"t":"d","s":"「竜馬は、もともと、悪いやつじゃないから」","f":"noa"},{"t":"d","s":"「あんたって、ほんと、お人好し」","f":"noa"},{"t":"d","s":"「そうかな」","f":"noa"},{"t":"d","s":"「そうよ」","f":"noa"},{"t":"n","s":"乃亜は、小さく笑った。それから、窓の外を見た。校庭の隅で、竜馬が一人、黙々と素振りをしている。","f":"noa","m":"happy"},{"t":"d","s":"「……あいつも、がんばってるんだね」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「あんたも」","f":"noa"},{"t":"d","s":"「おれは、ふつうだよ」","f":"noa"},{"t":"d","s":"「ふつうじゃない」","f":"noa"},{"t":"n","s":"乃亜は、静かに言った。","f":"noa"},{"t":"d","s":"「ふつうじゃないから、怖いの。いつか、遠くに行っちゃいそうで」","f":"noa"},{"t":"n","s":"耀平は、少し考えて、乃亜の顔を見た。","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「なに」","f":"yohei"},{"t":"d","s":"「約束、覚えてる」","f":"yohei"},{"t":"d","s":"「……覚えてる」","f":"yohei"},{"t":"d","s":"「なら、だいじょうぶ」","f":"yohei"},{"t":"n","s":"乃亜の目が、わずかに潤んだ。けれど、すぐに顔を背けて、鞄を持ち上げた。","f":"noa"},{"t":"d","s":"「帰るよ」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"d","s":"「晩ごはん、食堂でいい？」","f":"noa"},{"t":"d","s":"「いい」","f":"noa"},{"t":"d","s":"「また、玉子焼き残さないでね」","f":"noa"},{"t":"d","s":"「がんばる」","f":"noa"},{"t":"d","s":"「がんばれてない」","f":"noa"},{"t":"n","s":"二人は、並んで教室を出た。","f":"noa"},{"t":"n","s":"校庭の隅で、竜馬の素振りの音が、夕空に響いていた。","f":"ryoma"}]}]},{"n":11,"title":"冬の行事と、はじめての刀","sub":"中学・1年冬〜2年春","era":"middle","lead":"クリスマス、初詣、バレンタイン。静かな日常の中で、耀平は自分の刀を探しはじめる。","scenes":[{"key":"11-1","title":"寮のクリスマス","bg":"bg_dorm","dark":true,"mood":"night","bgm":"night3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"十二月。寮の食堂には、誰かが飾りつけた小さなツリーが置かれていた。"},{"t":"d","s":"「本日は、クリスマス会です。ケーキは一人一切れまでですよ」"},{"t":"n","s":"寮母の山口さんが、にこにこと宣言する。食堂のあちこちから歓声が上がった。"},{"t":"d","s":"「やった！　耀平、おれの分もあげるからさ、おまえの分のチキンくれよ！」"},{"t":"d","s":"「佐野。ケーキを一切れ渡して、チキンを一本もらうの、交換レートおかしくない？」"},{"t":"d","s":"「おかしくない！　おれの足の速さは、チキンの価値を上回る！」"},{"t":"d","s":"「関係ないよ、それ」"},{"t":"n","s":"同室の佐野との掛け合いにも、すっかり慣れた。耀平は、笑って紙皿を差し出す。","f":"yohei"},{"t":"n","s":"窓際の席には、乃亜が座っていた。ツリーの電飾が、横顔に淡く映っている。","f":"noa"},{"t":"d","s":"「耀平」","f":"noa"},{"t":"d","s":"「ん」","f":"noa"},{"t":"d","s":"「これ」","f":"noa"},{"t":"n","s":"乃亜が、小さな紙袋を差し出した。","f":"noa"},{"t":"d","s":"「プレゼント。去年のマフラーは、ちゃんと使ってるでしょ」","f":"noa"},{"t":"d","s":"「使ってるよ。今年も、毎朝巻いてる」","f":"noa"},{"t":"d","s":"「だから、手袋」","f":"noa"},{"t":"n","s":"紙袋の中には、濃い紺色の手袋が入っていた。指先に、薄く滑り止めがついている。","f":"noa"},{"t":"d","s":"「素振りのとき、手が冷たいでしょ。それなら、握りやすいほうがいいと思って」","f":"noa"},{"t":"d","s":"「……これ、乃亜が選んだの」","f":"noa"},{"t":"d","s":"「ま、まあ。店員さんに聞きながら」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「べつに。お礼を言われるほどじゃ」","f":"noa"},{"t":"d","s":"「あったかい」","f":"noa"},{"t":"n","s":"耀平は手袋をはめて、拳を握った。ぴたり、と手に馴染む。","f":"yohei"},{"t":"d","s":"「ぴったり」","f":"yohei"},{"t":"d","s":"「サイズ、前に測ったから」","f":"yohei"},{"t":"d","s":"「いつ」","f":"yohei"},{"t":"d","s":"「……あんたが寝てるとき」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「な、なんでもない！」","f":"yohei"},{"t":"n","s":"乃亜は、真っ赤になってそっぽを向いた。","f":"noa"},{"t":"n","s":"耀平は少し考えて、ポケットから小さな包みを取り出した。","f":"yohei"},{"t":"d","s":"「おれも、これ」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「去年は木札だったから。今年は、ちゃんと買ってみた」","f":"yohei"},{"t":"n","s":"包みの中には、小さな髪留めが入っていた。淡い水色の石が、一粒だけ光っている。","f":"yohei"},{"t":"d","s":"「……耀平が、買ったの」","f":"yohei"},{"t":"d","s":"「佐野に相談した。女の子には、これがいいって」","f":"yohei"},{"t":"d","s":"「……佐野くんに」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「あんたって、ほんとに」","f":"yohei"},{"t":"d","s":"「だめだった？」","f":"yohei"},{"t":"d","s":"「だめじゃない」","f":"yohei"},{"t":"cg","v":"cg_hairclip"},{"t":"n","s":"乃亜は、髪留めを両手で包んだ。声が、少しだけ震えている。","f":"noa"},{"t":"d","s":"「……つけて、みる」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"乃亜は、前髪を軽く留めた。水色の石が、電飾の光を受けてきらりと光る。","f":"noa"},{"t":"d","s":"「どう」","f":"noa"},{"t":"d","s":"「似合ってる」","f":"noa"},{"t":"d","s":"「……ちゃんと言えるようになったじゃない」","f":"noa"},{"t":"d","s":"「おじいちゃんに教わったから」","f":"noa"},{"t":"n","s":"乃亜は、ふ、と小さく笑った。その笑顔を、少し離れた席から竜馬が見ていた。何かを言いかけて、やめる。ケーキを黙って口に運ぶ。","f":"noa","m":"happy"},{"t":"d","s":"「竜馬、ケーキ食べないの」","f":"noa"},{"t":"d","s":"「うるせえ。食ってる」","f":"noa"},{"t":"d","s":"「もう一個あげようか」","f":"noa"},{"t":"d","s":"「いらねえよ！」","f":"noa"},{"t":"n","s":"佐野の軽口に、竜馬が怒鳴り返す。けれど、その声には、以前のような棘がなかった。","f":"ryoma","m":"anger"}]},{"key":"11-2","title":"初詣","bg":"bg_riverside","dark":false,"mood":"soft","bgm":"soft1","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"年が明けて、一月。初詣は、地元の神社に行くことにした。"},{"t":"d","s":"「明けましておめでとう」"},{"t":"cg","v":"cg_hatsumode"},{"t":"d","s":"「おめでとう。……着物、着てきたんだ」"},{"t":"d","s":"「お母さんが、どうしてもって」"},{"t":"d","s":"「似合ってる」"},{"t":"d","s":"「それ、毎回言わなくていいから」"},{"t":"d","s":"「じゃあ、言わない」"},{"t":"d","s":"「それはそれで、いやなの」"},{"t":"n","s":"乃亜は、赤い振り袖の袖をつまんで、ぷいと前を歩き出した。耀平は、その背中を追いかける。","f":"noa"},{"t":"n","s":"神社の境内は、人でごった返していた。屋台の匂い。鈴の音。白い息があちこちで揺れている。","f":"noa"},{"t":"n","s":"二人は、列に並んで、賽銭を投げ、手を合わせた。","f":"noa"},{"t":"i","s":"（……おじいちゃん。ぼく、少し強くなれたよ）","f":"noa"},{"t":"n","s":"耀平は、目を閉じて、心の中でそう呟いた。祖父はいない。けれど、祖父に向けた言葉だけは、変わらず胸の中にあった。","f":"yohei"},{"t":"i","s":"（これからも、見ててください）","f":"yohei"},{"t":"n","s":"目を開けると、隣の乃亜も、まだ手を合わせていた。長いまつげが、白い息の向こうで揺れている。","f":"noa"},{"t":"d","s":"「長いね」","f":"noa"},{"t":"d","s":"「……聞かないで」","f":"noa"},{"t":"d","s":"「何をお願いしたの」","f":"noa"},{"t":"d","s":"「言ったら、叶わなくなるでしょ」","f":"noa"},{"t":"d","s":"「そうなの」","f":"noa"},{"t":"d","s":"「そうなの」","f":"noa"},{"t":"n","s":"乃亜は、ちらりと耀平を見て、すぐに目を逸らした。","f":"noa"},{"t":"i","s":"（……耀平が、遠くに行きませんように。行っても、ちゃんと帰ってきますように）","f":"noa"},{"t":"n","s":"そんな祈りを、乃亜は胸の中にしまった。言えるはずがなかった。","f":"noa"},{"t":"n","s":"おみくじを引いた。耀平は小吉。乃亜は、中吉。","f":"yohei"},{"t":"d","s":"「小吉って、何がいいの」","f":"yohei"},{"t":"d","s":"「『焦るな、基本を大切に』だって」","f":"yohei"},{"t":"d","s":"「耀平らしいね」","f":"yohei"},{"t":"d","s":"「乃亜は？」","f":"yohei"},{"t":"d","s":"「『待ち人、来る。ただし素直になるべし』」","f":"yohei"},{"t":"d","s":"「待ち人って、誰」","f":"yohei"},{"t":"d","s":"「……知らない」","f":"yohei"},{"t":"n","s":"乃亜は、おみくじをくしゃっと握って、結び場に走っていった。耀平は首をかしげる。","f":"noa"},{"t":"n","s":"境内の端で、竜馬が一人、おみくじを引いていた。結果を見て、無言でポケットに突っ込む。それから、ふと顔を上げて、こちらと目が合った。","f":"ryoma"},{"t":"d","s":"「……よお」","f":"ryoma"},{"t":"d","s":"「あけましておめでとう、竜馬」","f":"ryoma"},{"t":"d","s":"「……おう」","f":"ryoma"},{"t":"n","s":"それだけだった。竜馬は、すぐに背を向けて去っていった。でも、その短い会話は、これまでの沈黙とは、少しだけ違っていた。","f":"ryoma"}]},{"key":"11-3","title":"バレンタイン","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft2","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"二月十四日。"},{"t":"n","s":"乃亜の机の上は、また、チョコレートの山になっていた。","f":"noa"},{"t":"d","s":"「乃亜さん、これ」","f":"noa"},{"t":"d","s":"「ありがとう。でも、わたし、お返しできないよ」","f":"noa"},{"t":"d","s":"「いいの！　渡したいだけだから！」","f":"noa"},{"t":"n","s":"女子たちが、顔を赤くして去っていく。乃亜は、淡々と紙袋にチョコを詰めていく。中学に入って、乃亜のモテ具合はさらに上がった。男子からも、女子からも。","f":"noa","m":"blush"},{"t":"n","s":"一方、耀平の机には、一つだけ。","f":"yohei"},{"t":"d","s":"「あの……耀平くん」","f":"yohei"},{"t":"d","s":"「ん」","f":"yohei"},{"t":"d","s":"「これ、よかったら」","f":"yohei"},{"t":"n","s":"見たことのない女子生徒が、小さな箱を差し出していた。耳まで赤い。","f":"yohei"},{"t":"d","s":"「ありがとう。でも、どうして」","f":"yohei"},{"t":"d","s":"「その……修学旅行のとき、みんなが怖がってる中で、耀平くんだけ、ちゃんと前に立ってたから」","f":"yohei"},{"t":"d","s":"「あ、あれは、たまたま」","f":"yohei"},{"t":"d","s":"「かっこよかった、です」","f":"yohei"},{"t":"n","s":"女子は、それだけ言って走り去った。耀平は、箱を持ったまま、きょとんとしている。","f":"yohei"},{"t":"d","s":"「……へえ」","f":"yohei"},{"t":"n","s":"背後から、冷たい声が降ってきた。","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「モテるんだ」","f":"yohei"},{"t":"d","s":"「え、これは、たまたま」","f":"yohei"},{"t":"d","s":"「たまたま、ね」","f":"yohei"},{"t":"n","s":"乃亜は、つかつかと耀平の机に近づいた。紙袋から、小さな包みを一つ取り出して、わざとらしく、耀平の目の前に置く。","f":"noa"},{"t":"d","s":"「これ。ぎり」","f":"noa"},{"t":"d","s":"「ありがとう」","f":"noa"},{"t":"d","s":"「ぎりだから。他の人のと、同じ」","f":"noa"},{"t":"d","s":"「同じにしては、包みが大きいね」","f":"noa"},{"t":"d","s":"「うるさい！」","f":"noa"},{"t":"n","s":"乃亜は、真っ赤になって声を張り上げた。教室中が、ざわつく。","f":"noa"},{"t":"d","s":"「乃亜さん、耀平くんと仲いいよね」","f":"noa"},{"t":"d","s":"「幼なじみ、なんだって」","f":"noa"},{"t":"d","s":"「いいなあ」","f":"noa"},{"t":"n","s":"ひそひそ声が、あちこちから聞こえてくる。乃亜は、耳まで赤くしたまま、すとんと自分の席に座った。","f":"noa"},{"t":"i","s":"（……わたし、何やってるんだろう）","f":"noa"},{"t":"n","s":"頭を抱える乃亜を、少し離れた席から竜馬がちらりと見ていた。机の中には、昨日買ったチョコが入っている。渡すつもりだった。でも、今日も、渡せなかった。","f":"noa"},{"t":"i","s":"（……まだ、早えか）","f":"noa"},{"t":"n","s":"竜馬は、小さく息を吐いて、チョコを鞄の奥にしまい込んだ。","f":"ryoma"},{"t":"n","s":"その日の夕方、校庭の隅で、竜馬が一人、素振りをしていた。耀平は、窓越しにそれを見ながら、乃亜がくれた包みを開けた。小さなトリュフが三つ、並んでいる。","f":"ryoma"},{"t":"d","s":"「……ほんとに、同じなのかな」","f":"ryoma"},{"t":"n","s":"一つ口に入れる。ほろ苦くて、少し甘かった。","f":"ryoma"}]},{"key":"11-4","title":"刀を探しに","bg":"bg_principal","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"春。二年生に進級する直前の三月の終わり。"},{"t":"d","s":"「耀平。ちょっと来てくれ」"},{"t":"n","s":"放課後の廊下で、木村先生に呼び止められた。"},{"t":"d","s":"「はい」"},{"t":"d","s":"「君は、毎朝、素振りをしているそうだな」"},{"t":"d","s":"「はい」"},{"t":"d","s":"「うちの学校は、二年生から、実技で刃引きの刀を使う授業がある。君も、そろそろ、木刀から卒業してはどうだ」"},{"t":"d","s":"「刀、ですか」"},{"t":"d","s":"「ああ。自分で選んで、学校に申請を出すんだ。街の刀剣店を、いくつか紹介してやる」"},{"t":"n","s":"耀平は、少しだけ目を丸くして、それから、ゆっくりと頷いた。","f":"yohei","m":"surprise"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"n","s":"日曜日。二人で、街の古い刀剣店を訪ねた。","f":"yohei"},{"t":"d","s":"「こんなところ、初めて入る」","f":"yohei"},{"t":"d","s":"「おれも」","f":"yohei"},{"t":"d","s":"「それなのに、緊張してないんだね」","f":"yohei"},{"t":"d","s":"「緊張してるよ」","f":"yohei"},{"t":"d","s":"「全然、見えない」","f":"yohei"},{"t":"d","s":"「顔に出ないだけ」","f":"yohei"},{"t":"n","s":"暖簾をくぐると、薄暗い店内に、ずらりと刀が並んでいた。刃引きの練習刀もあれば、本物の刃のついた古刀もある。","f":"yohei"},{"t":"d","s":"「いらっしゃい」","f":"yohei"},{"t":"n","s":"奥から、無口そうな老人が顔を出した。","f":"yohei"},{"t":"d","s":"「学校の申請か」","f":"yohei"},{"t":"d","s":"「はい。刃引きのものを」","f":"yohei"},{"t":"d","s":"「好きに握ってみなさい」","f":"yohei"},{"t":"n","s":"耀平は、壁にかけられた刀を、一本ずつ、慎重に握った。重い。軽い。長い。短い。どれも、少しずつ違う。","f":"yohei"},{"t":"d","s":"「ねえ、耀平。これ、かっこよくない？」","f":"yohei"},{"t":"d","s":"「それは、飾り用じゃないかな」","f":"yohei"},{"t":"d","s":"「あ、本当だ。値札が、ゼロ多い」","f":"yohei"},{"t":"d","s":"「乃亜、触らないほうがいいよ」","f":"yohei"},{"t":"n","s":"乃亜が、慌てて手を引っ込める。","f":"noa"},{"t":"n","s":"何本目だっただろう。ふと、耀平の手が止まった。","f":"yohei"},{"t":"n","s":"黒い鞘に収まった、地味な一振りだった。装飾はない。刃引きの練習刀として、店の端に並べられている。","f":"yohei"},{"t":"n","s":"握った瞬間、指先に、じんわりと温かさが伝わってきた。","f":"yohei"},{"t":"d","s":"「……これ」","f":"yohei"},{"t":"d","s":"「それかい」","f":"yohei"},{"t":"n","s":"老人が、目を細めた。","f":"yohei"},{"t":"d","s":"「無銘の練習刀だ。特に変わったところはない。ただ、持ち主を選ぶ癖があってな。誰が握っても、冷たいままだった」","f":"yohei"},{"t":"d","s":"「冷たい、ままだった」","f":"yohei"},{"t":"d","s":"「そう。だが、君が握ると、温かい」","f":"yohei"},{"t":"n","s":"耀平は、鞘から少しだけ刀身を引き抜いた。白い刃が、静かに光る。","f":"yohei"},{"t":"n","s":"そのとき、どこからともなく、窓の隙間を抜けて、桜の花びらが一枚、舞い込んだ。","f":"yohei"},{"t":"n","s":"刀の上に、ふわりと落ちる。花びらは、消えなかった。刀身の上に静かにとどまって、ほんの一瞬だけ、淡く光った。","f":"yohei","fx":"flash"},{"t":"d","s":"「……」","f":"yohei"},{"t":"d","s":"「……」","f":"yohei"},{"t":"n","s":"老人が、何も言わずに耀平を見ていた。乃亜も、息を詰めて、その光景を見つめている。","f":"yohei"},{"t":"d","s":"「……不思議なことも、あるもんだ」","f":"yohei"},{"t":"d","s":"「あ、あの、季節外れの桜が、時々……」","f":"yohei"},{"t":"d","s":"「そうかい。……それなら、その刀は、君が持っていきなさい」","f":"yohei"},{"t":"d","s":"「いくらですか」","f":"yohei"},{"t":"d","s":"「学校の申請額でいい。……大切に使うことだ」","f":"yohei"},{"t":"n","s":"耀平は、深く頭を下げた。","f":"yohei"},{"t":"n","s":"店を出ると、通りの向こうから、見覚えのある背中が歩いてきた。","f":"yohei"},{"t":"d","s":"「……竜馬」","f":"yohei"},{"t":"d","s":"「……よお」","f":"yohei"},{"t":"n","s":"竜馬は、腰に新しい刃引きの刀を提げていた。赤い鞘に、炎のような模様が彫られている。","f":"ryoma"},{"t":"d","s":"「おまえも、刀か」","f":"ryoma"},{"t":"d","s":"「うん。さっき、決めた」","f":"ryoma"},{"t":"d","s":"「そうか。おれも、決めたとこだ」","f":"ryoma"},{"t":"n","s":"気まずい沈黙が流れた。乃亜が、二人を交互に見ている。","f":"noa"},{"t":"d","s":"「……そ、そっか」","f":"noa"},{"t":"d","s":"「おう」","f":"noa"},{"t":"d","s":"「いい刀だね」","f":"noa"},{"t":"d","s":"「おまえのも、な」","f":"noa"},{"t":"n","s":"短い会話だった。それだけだった。竜馬は、それ以上何も言わず、少しだけ頷いて、歩き去っていった。","f":"ryoma"},{"t":"d","s":"「……あいつ、ちゃんと話したそうだったね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「いつか、ちゃんと話せるといいね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"耀平は、腰に提げた新しい刀に、そっと手を置いた。","f":"yohei"},{"t":"n","s":"夕暮れの空に、春の風が吹いていた。鞘の中で、刃が小さく、ことりと鳴った。","f":"yohei"}]}]},{"n":12,"title":"体育祭、文化祭、受験、卒業","sub":"中学・2年〜3年","era":"middle","lead":"行事の日々が過ぎていく。竜馬との距離は、少しずつ、少しずつ変わっていく。","scenes":[{"key":"12-1","title":"体育祭","bg":"bg_schoolyard_middle","dark":false,"mood":"daily","bgm":"daily3","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"二年生の秋。体育祭は、よく晴れた日に行われた。"},{"t":"n","s":"校庭には色とりどりの旗が並び、スピーカーからは行進曲が流れている。生徒たちは、赤、青、白、緑の四つの組に分かれて、朝からずっと落ち着かない様子だった。"},{"t":"d","s":"「耀平、起きて。開会式」"},{"t":"d","s":"「起きてる」"},{"t":"d","s":"「立ったまま寝ないで」"},{"t":"d","s":"「寝てない。目を閉じて、風を感じてる」"},{"t":"d","s":"「それを寝てるって言うの」"},{"t":"n","s":"乃亜に背中をつつかれて、耀平はあくびを噛み殺す。同じ赤組の佐野が、隣で屈伸をしていた。","f":"noa"},{"t":"d","s":"「いやあ、今日こそ俺の出番だな！　最終種目、組対抗リレー！　アンカーは俺！」","f":"noa"},{"t":"d","s":"「佐野、足、速いもんね」","f":"noa"},{"t":"d","s":"「だろ！　スキルも『加速』だし！」","f":"noa"},{"t":"d","s":"「スキルは使用禁止だよ」","f":"noa"},{"t":"d","s":"「……あ」","f":"noa"},{"t":"n","s":"佐野の顔が、みるみる青くなった。","f":"noa"},{"t":"n","s":"種目は順調に進んだ。耀平は、障害物競走で三位。借り物競走では「眠そうな人」の札を引いて、自分自身を連れてゴールした。","f":"yohei"},{"t":"d","s":"「それ、ありなの？」","f":"yohei"},{"t":"d","s":"「審判の先生がいいって言った」","f":"yohei"},{"t":"d","s":"「あんたの運、変なところで強いよね」","f":"yohei"},{"t":"n","s":"乃亜は笑いながら、水筒を差し出す。冷たい麦茶が、喉に染みた。","f":"noa"},{"t":"n","s":"そして、最終種目。組対抗リレー。","f":"noa"},{"t":"n","s":"赤組のアンカーは、竜馬だった。佐野は第三走者。青組のアンカーは、別のクラスの運動部のエースだった。","f":"ryoma"},{"t":"d","s":"「竜馬、頼んだぞ！」","f":"ryoma"},{"t":"d","s":"「うるせえ。任せとけ」","f":"ryoma"},{"t":"n","s":"バトンが、佐野から竜馬へ。ほんの少し、遅れて渡った。青組との差は、三メートル。","f":"ryoma"},{"t":"d","s":"「くそ……！」","f":"ryoma"},{"t":"n","s":"竜馬が、地面を蹴った。","f":"ryoma"},{"t":"n","s":"速い。小さい頃から鍛えてきた脚が、校庭を切り裂いていく。一歩ごとに差が縮まる。歓声が、どよめきに変わった。","f":"ryoma"},{"t":"d","s":"「いけ、竜馬ー！」","f":"ryoma"},{"t":"n","s":"気づけば、耀平も叫んでいた。自分でも驚くほど、大きな声で。","f":"yohei"},{"t":"n","s":"竜馬が、青組のエースを抜いた。わずかに、ほんのわずかに、胸一つ分。テープを切る。","f":"ryoma"},{"t":"d","s":"「おおおっ！」","f":"ryoma"},{"t":"n","s":"歓声と拍手が、校庭に響いた。竜馬は膝に手をついて、荒い息を吐いた。ゆっくりと顔を上げる。その視線が、赤組の応援席に向いた。","f":"ryoma"},{"t":"n","s":"耀平と、目が合った。","f":"yohei"},{"t":"n","s":"竜馬は、一瞬だけ固まって、それから、ふいと顔を背けた。けれど、その口元が、ほんの少しだけ、緩んでいた。","f":"ryoma"},{"t":"d","s":"「……竜馬、笑ってた」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「あんた、嬉しそう」","f":"ryoma"},{"t":"d","s":"「うん。嬉しい」","f":"ryoma"},{"t":"n","s":"耀平は、小さく頷いた。","f":"yohei"},{"t":"n","s":"夕暮れの校庭で、片付けをしていると、背後から声がした。","f":"yohei"},{"t":"d","s":"「おい」","f":"yohei"},{"t":"d","s":"「竜馬」","f":"yohei"},{"t":"d","s":"「……さっき、叫んでたろ」","f":"yohei"},{"t":"d","s":"「聞こえた？」","f":"yohei"},{"t":"d","s":"「あんだけでかい声、聞こえねえわけねえだろ」","f":"yohei"},{"t":"n","s":"竜馬は、頭をがしがしと掻いた。","f":"ryoma"},{"t":"d","s":"「……ありがとな」","f":"ryoma"},{"t":"d","s":"「え」","f":"ryoma"},{"t":"d","s":"「一回しか言わねえからな」","f":"ryoma"},{"t":"d","s":"「うん。聞こえた」","f":"ryoma"},{"t":"d","s":"「聞こえてたなら、いい」","f":"ryoma"},{"t":"n","s":"竜馬は、それだけ言って、足早に去っていった。耀平は、その背中を見送りながら、小さく笑った。","f":"ryoma","m":"happy"}]},{"key":"12-2","title":"お化け屋敷","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily4","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"十一月。文化祭の出し物は、お化け屋敷に決まった。"},{"t":"d","s":"「なんでお化け屋敷なの……」"},{"t":"d","s":"「去年の肝試しが、不完全燃焼だったから！」"},{"t":"d","s":"「あんた、あの夜、さんざんな目に遭ったでしょ」"},{"t":"d","s":"「だからこそ！　今度は、俺たちが驚かせる側だ！」"},{"t":"n","s":"佐野が、胸を張って宣言する。教室中が、おお、と沸いた。もちろん、あの夜の本当のことを知っているのは、ほんの数人だけだった。"},{"t":"d","s":"「耀平は何の役やる？」"},{"t":"d","s":"「寝てる幽霊」"},{"t":"d","s":"「それ、ただの地味な人じゃないか」"},{"t":"d","s":"「じゃあ、ずっと布団に入ってる人」"},{"t":"d","s":"「採用！」"},{"t":"n","s":"結局、耀平は教室の隅の布団の中で、じっとしている係になった。お客さんが通りかかると、突然むくりと起き上がる。ただそれだけの役だった。","f":"yohei"},{"t":"n","s":"本番の日。意外にも、評判は上々だった。","f":"yohei"},{"t":"d","s":"「きゃああっ！」","f":"yohei"},{"t":"d","s":"「うわあああっ！」","f":"yohei"},{"t":"d","s":"「寝てたはずなのに、すごい勢いで起き上がった……！」","f":"yohei"},{"t":"n","s":"悲鳴が、ひっきりなしに聞こえてくる。耀平は、布団の中でぼんやりと考える。","f":"yohei"},{"t":"i","s":"（……おれ、そんなに怖いかな）","f":"yohei"},{"t":"d","s":"「耀平、お疲れ」","f":"yohei"},{"t":"d","s":"「乃亜」","f":"yohei"},{"t":"d","s":"「お客さんが、あんたの起き上がり方、一番怖いって言ってた」","f":"yohei"},{"t":"d","s":"「そうなの」","f":"yohei"},{"t":"d","s":"「うん。あの勢いは、反則」","f":"yohei"},{"t":"d","s":"「普通に起きただけなのに」","f":"yohei"},{"t":"d","s":"「それが一番怖いのよ」","f":"yohei"},{"t":"n","s":"乃亜は、くすくすと笑った。","f":"noa","m":"happy"},{"t":"n","s":"休憩時間、二人は校内を歩いた。屋台の匂い。呼び込みの声。教室ごとに違う飾り付け。","f":"noa"},{"t":"d","s":"「あ」","f":"noa"},{"t":"n","s":"乃亜が、ふと足を止めた。廊下の突き当たりに、竜馬のクラスの出し物があった。大きな看板に「焼き鳥」と書いてある。","f":"noa"},{"t":"d","s":"「竜馬、焼いてるよ」","f":"noa"},{"t":"d","s":"「ほんとだ。火加減が、うまい」","f":"noa"},{"t":"d","s":"「そりゃ、火のスキルだからでしょ」","f":"noa"},{"t":"n","s":"煙の向こうで、竜馬は真剣な顔で串を回していた。ふと顔を上げて、こちらに気づく。","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"n","s":"竜馬は、無言で串を二本、紙皿に載せて差し出した。","f":"ryoma"},{"t":"d","s":"「え」","f":"ryoma"},{"t":"d","s":"「余ってんだよ。食え」","f":"ryoma"},{"t":"d","s":"「いいの？」","f":"ryoma"},{"t":"d","s":"「いいから食え」","f":"ryoma"},{"t":"n","s":"耀平は、おそるおそる受け取って、一口かじった。皮がぱりっとして、中がじゅわりと柔らかい。","f":"yohei"},{"t":"d","s":"「おいしい」","f":"yohei"},{"t":"d","s":"「当たり前だ」","f":"yohei"},{"t":"d","s":"「ほんとに。すごく、おいしい」","f":"yohei"},{"t":"d","s":"「……そうかよ」","f":"yohei"},{"t":"n","s":"竜馬は、鼻をこすって、そっぽを向いた。乃亜が、小さく笑った。","f":"ryoma","m":"happy"}]},{"key":"12-3","title":"進路","bg":"bg_classroom_middle","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa","ryoma"],"lines":[{"t":"n","s":"三年生の春。進路面談の日がやってきた。"},{"t":"d","s":"「耀平。志望校は決まっているか」"},{"t":"d","s":"「はい。学園の高等部を」"},{"t":"d","s":"「そうか。倍率は高いぞ。成績も、最近は上がってきているが」"},{"t":"d","s":"「がんばります」"},{"t":"d","s":"「眠そうな顔で言われると、説得力に欠けるんだがな」"},{"t":"d","s":"「すみません」"},{"t":"n","s":"担任の木村が、苦笑いで書類をめくった。","m":"sweat"},{"t":"n","s":"学園。国内でも名の知られた、スキル持ちの子どもたちが集まる高等部。入るには、筆記試験と実技の両方に合格しなければならない。"},{"t":"i","s":"（そこに行けば、おじいちゃんが、話してくれなかったことも、わかるかもしれない）"},{"t":"n","s":"耀平は、そう思っていた。何かが、あの学園にある気がしていた。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「君は、きっと受かる」","f":"yohei"},{"t":"d","s":"「ありがとうございます」","f":"yohei"},{"t":"d","s":"「根拠は、毎朝の素振りだ。続けられる人間は、強い」","f":"yohei"},{"t":"n","s":"耀平は、小さく頭を下げた。","f":"yohei"},{"t":"n","s":"受験勉強は、乃亜が仕切った。","f":"noa"},{"t":"d","s":"「耀平、ここ。さっきも間違えた」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝るなら解いて」","f":"noa"},{"t":"d","s":"「がんばる」","f":"noa"},{"t":"d","s":"「がんばれてない」","f":"noa"},{"t":"d","s":"「……ねむい」","f":"noa"},{"t":"d","s":"「寝たら、水かける」","f":"noa"},{"t":"d","s":"「それは、いやだ」","f":"noa"},{"t":"d","s":"「じゃあ、起きて」","f":"noa"},{"t":"n","s":"寮の談話室。ノートと参考書が積まれた机の向かいで、乃亜はずっと耀平の隣に座っていた。自分の勉強もあるのに、耀平の手元ばかり見ている。","f":"noa"},{"t":"d","s":"「乃亜は、自分のやらなくていいの」","f":"noa"},{"t":"d","s":"「わたしは、大丈夫」","f":"noa"},{"t":"d","s":"「ほんとに？」","f":"noa"},{"t":"d","s":"「あんたよりは、ね」","f":"noa"},{"t":"d","s":"「ひどい」","f":"noa"},{"t":"d","s":"「事実」","f":"noa"},{"t":"n","s":"夜が更けても、乃亜は部屋に戻らなかった。やがて、耀平のノートの上に、こて、と頭が落ちる。","f":"noa"},{"t":"d","s":"「……」","f":"noa"},{"t":"n","s":"寝息が聞こえた。耀平は、そっと自分のマフラーを乃亜の肩にかけた。","f":"yohei"},{"t":"i","s":"（いつも、ありがとう）","f":"yohei"},{"t":"n","s":"声には出さずに、そう呟いた。","f":"yohei"},{"t":"n","s":"図書室では、時々、竜馬を見かけた。机に向かって、参考書をにらんでいる。目が合っても、お互い会釈をするだけ。それでも、以前の刺々しさは、もうなかった。","f":"ryoma"}]},{"key":"12-4","title":"文化祭と先輩","bg":"bg_classroom_middle","dark":false,"mood":"soft","bgm":"soft4","cast":["ren","yohei"],"lines":[{"t":"n","s":"三年生の文化祭は、受験前の最後の思い出作りだった。"},{"t":"d","s":"「耀平、見て。ほら、お客さんが一杯」"},{"t":"d","s":"「ほんとだ」"},{"t":"d","s":"「今年は、喫茶店だもんね」"},{"t":"d","s":"「楽だ」"},{"t":"d","s":"「楽じゃない。注文取るの、あんたの係」"},{"t":"d","s":"「え」"},{"t":"n","s":"耀平がエプロン姿でお盆を運んでいると、見覚えのある背中が、入口に現れた。","f":"yohei"},{"t":"n","s":"制服ではない、紺色のブレザー。学園の高等部の制服だった。","f":"yohei"},{"t":"d","s":"「久しぶりだな」","f":"yohei"},{"t":"n","s":"九条蓮だった。","f":"ren"},{"t":"d","s":"「九条先輩」","f":"ren"},{"t":"d","s":"「元気そうだ。いい店だな」","f":"ren"},{"t":"d","s":"「ありがとうございます。……どうして、ここに」","f":"ren"},{"t":"d","s":"「高等部の代表として、母校の文化祭を見に来た。受験生に、少し話もしたくてな」","f":"ren"},{"t":"n","s":"蓮は、窓際の席に腰を下ろし、コーヒーを注文した。耀平が運んでいくと、静かに口を開いた。","f":"ren"},{"t":"d","s":"「学園を、受けるそうだな」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「いい選択だ。待っている」","f":"ren"},{"t":"d","s":"「待って、ますか」","f":"ren"},{"t":"d","s":"「ああ。高等部の生徒会長は、三年生が務める。私は、君が入学する年に、会長になる」","f":"ren"},{"t":"n","s":"蓮は、コーヒーを一口飲んで、続けた。","f":"ren"},{"t":"d","s":"「あの学園は、強い人間が集まる。同時に、危険も多い。だが、君ならきっと、うまくやれる」","f":"ren"},{"t":"d","s":"「どうして、そう思うんですか」","f":"ren"},{"t":"d","s":"「勘だ」","f":"ren"},{"t":"d","s":"「勘、ですか」","f":"ren"},{"t":"d","s":"「勘が当たる人間は、案外、強いんだ」","f":"ren"},{"t":"n","s":"蓮は、少しだけ笑った。それは、中学の入学式で見た、完璧な笑顔とは違う、自然な笑顔だった。","f":"ren","m":"happy"},{"t":"i","s":"（……やっぱり、この人は、いい人だ）","f":"ren"},{"t":"n","s":"耀平は、そう思った。そして同時に、胸のどこかで、小さく警鐘が鳴るのを感じていた。この人は、いつか、自分の秘密に辿り着くかもしれない。","f":"yohei"},{"t":"i","s":"（でも、その時は、その時だ）","f":"yohei"},{"t":"d","s":"「ごゆっくりどうぞ」","f":"yohei"},{"t":"n","s":"耀平は、軽く頭を下げて、持ち場に戻った。","f":"yohei"}]},{"key":"12-5","title":"卒業式","bg":"bg_graduation","dark":false,"mood":"climax","bgm":"climax1","cast":["noa","ryoma","yohei"],"lines":[{"t":"n","s":"三月。寒さの残る朝。"},{"t":"n","s":"合格発表の日、耀平は掲示板の前に立っていた。人だかりの向こう、自分の受験番号を探す。","f":"yohei"},{"t":"d","s":"「……あった」","f":"yohei"},{"t":"n","s":"小さく、息を吐いた。隣では、乃亜が自分の番号を見つけて、ほっとしたように肩の力を抜いている。","f":"noa"},{"t":"d","s":"「やった」","f":"noa"},{"t":"d","s":"「おめでとう、乃亜」","f":"noa"},{"t":"d","s":"「あんたもね。……あ、竜馬」","f":"noa"},{"t":"n","s":"少し離れたところに、竜馬が立っていた。掲示板を見上げたまま、何も言わない。やがて、ゆっくりとこちらを振り向いた。","f":"ryoma"},{"t":"d","s":"「……受かった」","f":"ryoma"},{"t":"d","s":"「おれも」","f":"ryoma"},{"t":"d","s":"「おまえも、か」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「そうか。……じゃあ、高校でも、決着つけられるな」","f":"ryoma"},{"t":"d","s":"「いいよ。約束したから」","f":"ryoma"},{"t":"d","s":"「おう」","f":"ryoma"},{"t":"n","s":"竜馬は、短く頷いて、背を向けた。耀平は、その背中に、小さな声で呼びかけた。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「あ？」","f":"ryoma"},{"t":"d","s":"「また、よろしく」","f":"ryoma"},{"t":"d","s":"「……ああ」","f":"ryoma"},{"t":"n","s":"振り返らずに、竜馬は片手を上げた。それだけだった。","f":"ryoma"},{"t":"n","s":"そして、卒業式の日。","f":"ryoma"},{"t":"n","s":"講堂での式は、粛々と進んだ。卒業証書を受け取り、校歌を歌い、拍手の中で退場する。三年間。いろいろなことがあった。祖父を見送ったこと。桜の力に目覚めたこと。竜馬と、ぶつかったこと。","f":"ryoma"},{"t":"n","s":"校庭に出ると、桜の枝が、風に揺れていた。蕾が、少しだけ膨らんでいる。","f":"ryoma"},{"t":"d","s":"「耀平」","f":"ryoma"},{"t":"d","s":"「乃亜」","f":"ryoma"},{"t":"d","s":"「卒業、したね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「次は、高校だね」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"乃亜は、一歩、耀平に近づいた。","f":"noa"},{"t":"d","s":"「ねえ、耀平」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「高校でも、約束、覚えてる？」","f":"noa"},{"t":"d","s":"「覚えてる」","f":"noa"},{"t":"d","s":"「どこに行っても？」","f":"noa"},{"t":"d","s":"「どこに行っても」","f":"noa"},{"t":"d","s":"「……ありがと」","f":"noa"},{"t":"n","s":"乃亜は、小さく笑った。その瞳が、少し潤んでいる。","f":"noa","m":"happy"},{"t":"d","s":"「次は、どんな三年間になるのかな」","f":"noa"},{"t":"d","s":"「分からない。でも」","f":"noa"},{"t":"d","s":"「でも？」","f":"noa"},{"t":"d","s":"「たぶん、楽しいと思う」","f":"noa"},{"t":"d","s":"「根拠は？」","f":"noa"},{"t":"d","s":"「乃亜がいるから」","f":"noa"},{"t":"n","s":"乃亜の顔が、一瞬で真っ赤になった。","f":"noa"},{"t":"d","s":"「……ばか」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝らなくていい」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"桜の蕾が、風に揺れる。二人の足元に、一枚、薄桃色の花びらが、ひらりと舞い降りた。","f":"noa"}]}]},{"n":13,"title":"入学と、E組","sub":"高校・1年春","era":"high","lead":"四月。学園の門をくぐった耀平は、はじめて「桜が多すぎる場所」を知った。","scenes":[{"key":"13-1","title":"入学式","bg":"bg_graduation","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","ren","ryoma"],"lines":[{"t":"cg","v":"cg_reunion"},{"t":"n","s":"学園の正門から校舎までは、長い桜並木が続いていた。"},{"t":"n","s":"満開の花が風に揺れて、足元には薄桃色の絨毯ができている。新入生たちは、真新しい制服の襟を正しながら、その下を歩いていく。"},{"t":"d","s":"「すごい……」"},{"t":"d","s":"「耀平、口、開いてる」"},{"t":"d","s":"「あ」"},{"t":"d","s":"「あんた、桜の前だとすぐそうなる」"},{"t":"d","s":"「だって、きれいだから」"},{"t":"d","s":"「はいはい。行くよ」"},{"t":"n","s":"乃亜に袖を引かれて、耀平は歩き出す。肩にかかった花びらが、一枚だけ、ふわりと落ちた。","f":"noa"},{"t":"n","s":"講堂には、新入生が四百人ほど集まっていた。壇上には教職員が並び、その中央に、紺色のブレザーを着た青年が立っている。","f":"noa"},{"t":"n","s":"九条蓮だった。","f":"ren"},{"t":"d","s":"「新入生の皆さん。入学おめでとう。生徒会長の九条蓮です」","f":"ren"},{"t":"n","s":"落ち着いた声が、講堂の隅々まで届く。ざわめいていた新入生が、自然と口をつぐんだ。","f":"ren"},{"t":"d","s":"「この学園には、さまざまな力を持つ者が集まっている。強い者もいる。そうでない者もいる。だが、ここで覚えておいてほしいことが一つある」","f":"ren"},{"t":"n","s":"蓮は、ゆっくりと講堂を見渡した。","f":"ren"},{"t":"d","s":"「強さは、誰かを守るためにある。これだけだ。三年間、よろしく頼む」","f":"ren"},{"t":"n","s":"拍手が起きた。耀平も手を叩きながら、壇上を見つめる。蓮と、一瞬だけ、目が合った気がした。","f":"yohei"},{"t":"i","s":"（……気のせい、かな）","f":"yohei"},{"t":"d","s":"「耀平、見て。竜馬いる」","f":"yohei"},{"t":"d","s":"「どこ」","f":"yohei"},{"t":"d","s":"「前から三列目。背筋、ぴんとしてる」","f":"yohei"},{"t":"d","s":"「ほんとだ」","f":"yohei"},{"t":"n","s":"三列目の端に、見覚えのある赤茶色の頭があった。竜馬は、壇上を睨みつけるように見ていた。たぶん、睨んでいるつもりはない。ただ、真剣なだけだ。","f":"ryoma","m":"anger"},{"t":"n","s":"式が終わると、新入生は掲示板の前に集められた。クラス分けの発表だ。","f":"ryoma"}]},{"key":"13-2","title":"クラス分け","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily5","cast":["ryoma","noa","yohei"],"lines":[{"t":"n","s":"掲示板には、五枚の大きな紙が貼られていた。A組からE組まで。"},{"t":"d","s":"「A組は、成績上位者とスキル評価の高い人。E組が……」"},{"t":"d","s":"「E組が？」"},{"t":"d","s":"「その、いちばん下の評価の人、らしいよ」"},{"t":"d","s":"「そっか」"},{"t":"n","s":"乃亜が、A組の紙から順に目で追っていく。そして、C組の紙のところで、ぴたりと止まった。","f":"noa"},{"t":"d","s":"「あった。C組」","f":"noa"},{"t":"d","s":"「おめでとう」","f":"noa"},{"t":"d","s":"「おめでとうじゃないよ。あんたは？」","f":"noa"},{"t":"d","s":"「えっと……」","f":"noa"},{"t":"n","s":"A組、B組、C組、D組。耀平の名前は、どこにもない。","f":"yohei"},{"t":"n","s":"最後に、E組の紙を見上げる。いちばん下の段に、小さく、でも確かに、書かれていた。","f":"yohei"},{"t":"n","s":"〈E組　金井耀平〉","f":"yohei"},{"t":"d","s":"「……あった」","f":"yohei"},{"t":"d","s":"「E組か」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「ほんとに、いいの？」","f":"yohei"},{"t":"d","s":"「いいよ。実技、手を抜いたし」","f":"yohei"},{"t":"d","s":"「あんた、ちゃんとやらなかったの？」","f":"yohei"},{"t":"d","s":"「ちゃんとやったよ。ちゃんと、普通に」","f":"yohei"},{"t":"n","s":"乃亜は、疑わしげに耀平を見つめた。","f":"noa"},{"t":"d","s":"「……ふうん」","f":"noa"},{"t":"d","s":"「なに」","f":"noa"},{"t":"d","s":"「なんでもない。ただ、あんたが本気で手を抜くと、ほんとに普通なんだなって」","f":"noa"},{"t":"d","s":"「それ、褒めてる？」","f":"noa"},{"t":"d","s":"「褒めてない」","f":"noa"},{"t":"n","s":"乃亜は、ふいと顔をそらす。けれど、その口元が、ほんの少しだけ緩んでいた。","f":"noa"},{"t":"d","s":"「おい」","f":"noa"},{"t":"n","s":"背後から声がかかった。振り向くと、竜馬が立っていた。","f":"ryoma"},{"t":"d","s":"「竜馬」","f":"ryoma"},{"t":"d","s":"「おまえ、何組だ」","f":"ryoma"},{"t":"d","s":"「E組」","f":"ryoma"},{"t":"d","s":"「は？」","f":"ryoma"},{"t":"d","s":"「E組」","f":"ryoma"},{"t":"d","s":"「……そうか」","f":"ryoma"},{"t":"n","s":"竜馬は、一瞬だけ眉を寄せた。それから、掲示板のA組の紙を指差す。","f":"ryoma"},{"t":"d","s":"「おれはA組だ」","f":"ryoma"},{"t":"d","s":"「すごいね」","f":"ryoma"},{"t":"d","s":"「すごくねえ。……おまえ、手ぇ抜いたろ」","f":"ryoma"},{"t":"d","s":"「抜いたよ」","f":"ryoma"},{"t":"d","s":"「ちっ。だと思った」","f":"ryoma"},{"t":"d","s":"「約束は、守るよ」","f":"ryoma"},{"t":"d","s":"「あ？」","f":"ryoma"},{"t":"d","s":"「決着の話」","f":"ryoma"},{"t":"d","s":"「……ああ」","f":"ryoma"},{"t":"n","s":"竜馬は、鼻を鳴らした。","f":"ryoma"},{"t":"d","s":"「まあいい。おれが先に上に行って、待ってる」","f":"ryoma"},{"t":"d","s":"「うん。待ってて」","f":"ryoma"},{"t":"d","s":"「待たせんなよ」","f":"ryoma"},{"t":"n","s":"竜馬は、それだけ言って、人混みの中へ歩いていった。","f":"ryoma"},{"t":"d","s":"「……あいつ、相変わらずだね」","f":"ryoma"},{"t":"d","s":"「うん。でも」","f":"ryoma"},{"t":"d","s":"「でも？」","f":"ryoma"},{"t":"d","s":"「前より、いい顔してる」","f":"ryoma"},{"t":"n","s":"乃亜は、少し驚いたように耀平を見て、それから、小さく頷いた。","f":"noa"}]},{"key":"13-3","title":"最後の一人","bg":"bg_gate","dark":false,"mood":"daily","bgm":"daily1","cast":["yohei","yuzuki"],"lines":[{"t":"n","s":"E組の教室は、校舎のいちばん端にあった。窓の外には、古い桜の木が一本だけ立っている。"},{"t":"n","s":"三十人ほどの生徒が、ばらばらに座っていた。緊張している者、あくびをしている者、すでに隣と話し込んでいる者。耀平は、窓際の後ろから二番目の席に座る。","f":"yohei"},{"t":"n","s":"担任が教室に入ってきた。","f":"yohei"},{"t":"d","s":"「全員、揃っているな。出席を取る」","f":"yohei"},{"t":"n","s":"名前が順番に読み上げられていく。耀平の名前が呼ばれ、返事をする。やがて、最後の名前までたどりついた時、担任は少しだけ首をかしげた。","f":"yohei"},{"t":"d","s":"「一人、来ていないな」","f":"yohei"},{"t":"d","s":"「あの、どの人ですか」","f":"yohei"},{"t":"d","s":"「名簿の最後の生徒だ。入学式にも、クラス分けの場にも、姿が見えなかったらしい」","f":"yohei"},{"t":"n","s":"教室が、少しだけざわついた。","f":"yohei"},{"t":"d","s":"「入学初日に欠席って」","f":"yohei"},{"t":"d","s":"「度胸あるな」","f":"yohei"},{"t":"d","s":"「それとも、やばい人かも」","f":"yohei"},{"t":"n","s":"耀平は、窓の外の桜を見ていた。風が、枝を揺らしている。その時だった。","f":"yohei"},{"t":"n","s":"がらり、と教室の扉が開いた。","f":"yohei"},{"t":"cg","v":"cg_collapsed"},{"t":"n","s":"水色の髪の少女が、そこに立っていた。","f":"yohei"},{"t":"n","s":"制服の襟は乱れている。肩で、小さく息をしている。顔色が、ひどく青白い。そして、片方の手に、見覚えのある水色の髪留めを握りしめていた。","f":"yohei"},{"t":"i","s":"（……あ）","f":"yohei"},{"t":"n","s":"耀平の心臓が、どくんと鳴った。","f":"yohei"},{"t":"d","s":"「遅れて……すみません」","f":"yohei"},{"t":"n","s":"少女は、そう言って、一歩踏み出した。けれど、その足が、ふらりと崩れた。","f":"yohei"},{"t":"d","s":"「あぶな——」","f":"yohei"},{"t":"n","s":"気づけば、耀平は席を立っていた。数歩の距離を駆け抜けて、倒れかけた肩を受け止める。冷たい。まるで、雪に触れたような肌だった。","f":"yohei"},{"t":"d","s":"「大丈夫ですか」","f":"yohei"},{"t":"d","s":"「……あ、なた」","f":"yohei"},{"t":"d","s":"「喋らなくていいから。保健室に」","f":"yohei"},{"t":"d","s":"「……名前」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「あなたの、名前……教えて」","f":"yohei"},{"t":"n","s":"少女の瞳が、とろんと潤んでいた。意識が朦朧としているのが、はっきり分かる。それでも彼女は、確かに、耀平の目を見つめていた。","f":"yohei"},{"t":"d","s":"「……耀平。金井耀平」","f":"yohei"},{"t":"d","s":"「ようへい」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「……いい、名前」","f":"yohei"},{"t":"n","s":"少女は、かすかに微笑んだ。そのまま、耀平の腕の中で、力を失った。","f":"yohei","m":"happy"},{"t":"d","s":"「おい、保健室だ！」","f":"yohei"},{"t":"d","s":"「先生、呼んできます！」","f":"yohei"},{"t":"n","s":"教室がどよめく。担任が慌てて駆け寄ってきた。耀平は、少女を背負って、廊下へ走り出す。","f":"yohei"},{"t":"i","s":"（軽い。冷たい。でも）","f":"yohei"},{"t":"n","s":"背中に伝わる鼓動は、確かに、生きている。","f":"yohei"},{"t":"i","s":"（……この子、前にも）","f":"yohei"},{"t":"n","s":"耀平の胸の奥で、あの夜の記憶が、ざわりと揺れた。肝試しの夜。吹雪の中に立っていた少女。淡雪と、風花と。拒絶の、冷たい声。","f":"yohei"},{"t":"i","s":"（柚月、さん）","f":"yohei"},{"t":"n","s":"その名前は、まだ、口には出さなかった。","f":"yohei"}]},{"key":"13-4","title":"保健室","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft1","cast":["yohei","noa","yuzuki"],"lines":[{"t":"cg","v":"cg_yuzuki_infirmary"},{"t":"n","s":"保健室のベッドに少女を寝かせると、養護教諭が手早く診てくれた。"},{"t":"d","s":"「熱はないわね。脈も安定してる。極度の疲労と、寝不足かしら」"},{"t":"d","s":"「そう、ですか」"},{"t":"d","s":"「あなた、この子の知り合い？」"},{"t":"d","s":"「いえ。たまたま、倒れるところに居合わせただけで」"},{"t":"d","s":"「そう。ありがとう。あとは先生に任せて、教室に戻って」"},{"t":"d","s":"「はい」"},{"t":"n","s":"耀平は、ベッドの傍らに立ったまま、動けなかった。少女の寝顔は、思っていたよりも、ずっと幼く見えた。握りしめていた髪留めが、枕元に置かれている。","f":"yohei"},{"t":"i","s":"（あの時の子だ。間違いない）","f":"yohei"},{"t":"n","s":"水色の髪留め。それは、去年のクリスマス、寮の前で別の誰かが落とした——いや、違う。あれは、乃亜と交換したものとは別物だ。同じ色でも、形が違う。","f":"noa"},{"t":"i","s":"（でも、どうして）","f":"noa"},{"t":"n","s":"分からないまま、耀平は保健室を出た。","f":"yohei"},{"t":"n","s":"廊下の窓から、桜が見えた。風に揺れる花びらが、さっき見たときよりも、ずっと静かに感じられた。","f":"yohei"},{"t":"n","s":"教室に戻ると、担任が名簿に何かを書き込んでいた。","f":"yohei"},{"t":"d","s":"「金井。戻ったか」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「彼女の名前は、朝霧柚月だ。入学試験は、実技が満点に近かったらしい。本来ならA組のはずだったが」","f":"yohei"},{"t":"d","s":"「えっ」","f":"yohei"},{"t":"d","s":"「クラス分けの場に来なかったため、規定により、最下位のE組に編入になった」","f":"yohei"},{"t":"d","s":"「そんな」","f":"yohei"},{"t":"d","s":"「規則だ。仕方ない」","f":"yohei"},{"t":"n","s":"担任は、淡々とそう言った。耀平は、思わず拳を握る。","f":"yohei"},{"t":"i","s":"（……それって、理不尽じゃないか）","f":"yohei"},{"t":"d","s":"「何か言いたそうだな」","f":"yohei"},{"t":"d","s":"「いえ。……あの、朝霧さんは」","f":"yohei"},{"t":"d","s":"「今日は、保健室で休ませる。明日から、通常通りだ」","f":"yohei"},{"t":"d","s":"「分かりました」","f":"yohei"},{"t":"n","s":"耀平は、席に戻った。窓の外の桜が、風に花びらを散らしている。","f":"yohei"},{"t":"i","s":"（強い子が、いちばん下のクラスに来る）","f":"yohei"},{"t":"i","s":"（それって、偶然かな）","f":"yohei"},{"t":"n","s":"耀平は、そう思った。そして、背筋を、すっと伸ばした。","f":"yohei"},{"t":"n","s":"放課後。寮の自室に戻った耀平は、窓際に腰を下ろした。真新しい制服のポケットから、無銘の刃引き刀の鞘に付けた小さなお守りを取り出す。祖父の形見だ。","f":"yohei"},{"t":"d","s":"「おじいちゃん」","f":"yohei"},{"t":"n","s":"小さく呟く。","f":"yohei"},{"t":"d","s":"「学園、来たよ。でも、まだ何も分からない。でも、とりあえず、E組で、がんばってみる」","f":"yohei"},{"t":"n","s":"返事はない。けれど、窓の外の夕焼けが、あたたかく部屋を照らしていた。","f":"yohei"},{"t":"n","s":"鞘の中で、刃が、ことり、と小さく鳴った。","f":"yohei"},{"t":"i","s":"（……見てるのかな）","f":"yohei"},{"t":"n","s":"耀平は、そう思って、少しだけ笑った。","f":"yohei","m":"happy"}]}]},{"n":14,"title":"行事と、迅との出会い","sub":"高校・1年春〜初夏","era":"high","lead":"E組の日々は、思っていたよりも穏やかに始まった。そして、ゴールデンウィークの墓前で、耀平は一人の少年と出会う。","scenes":[{"key":"14-1","title":"朝霧柚月","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft3","cast":["yohei","yuzuki"],"lines":[{"t":"cg","v":"cg_yuzuki_seat"},{"t":"n","s":"翌朝。E組の教室に入ると、耀平の隣の席に、水色の髪の少女が座っていた。","f":"yohei"},{"t":"d","s":"「…………」","f":"yohei"},{"t":"n","s":"少女は、窓の外を見ている。昨日の青白い顔色は、もうなかった。背筋を伸ばして、静かに座っている。","f":"yohei"},{"t":"d","s":"「おはよう」","f":"yohei"},{"t":"d","s":"「…………」","f":"yohei"},{"t":"d","s":"「あ、えっと。体調、大丈夫？」","f":"yohei"},{"t":"n","s":"少女は、ゆっくりとこちらを向いた。切れ長の目が、耀平を見る。冷たい色の瞳だった。けれど、ほんの少しだけ、揺れていた。","f":"yohei"},{"t":"d","s":"「……昨日は、ありがとう」","f":"yohei"},{"t":"d","s":"「いえ」","f":"yohei"},{"t":"d","s":"「朝霧柚月。よろしく」","f":"yohei"},{"t":"d","s":"「金井耀平。よろしく」","f":"yohei"},{"t":"d","s":"「……知ってる」","f":"yohei"},{"t":"n","s":"柚月は、それだけ言って、また窓の外を向いた。","f":"yuzuki"},{"t":"i","s":"（知ってる、か）","f":"yuzuki"},{"t":"n","s":"名前を答えたのは、確かに自分だ。意識が朦朧としていたはずなのに、覚えていたらしい。","f":"yuzuki"},{"t":"i","s":"（それとも、別の理由で）","f":"yuzuki"},{"t":"n","s":"肝試しの夜のことは、聞けなかった。聞いてはいけない気がした。あの日、彼女は耀平を拒絶して、去っていったのだから。","f":"yohei"},{"t":"d","s":"「なあなあ、隣の子と知り合いなの？」","f":"yohei"},{"t":"d","s":"「違うよ。昨日、倒れたところに居合わせただけで」","f":"yohei"},{"t":"d","s":"「へえ。美人じゃん」","f":"yohei"},{"t":"d","s":"「あんまり、そういう目で見ない方がいいと思う」","f":"yohei"},{"t":"d","s":"「なんで？」","f":"yohei"},{"t":"d","s":"「なんとなく」","f":"yohei"},{"t":"n","s":"前の席の男子が、にやにやしている。耀平は苦笑いして、教科書を開いた。","f":"yohei","m":"sweat"},{"t":"n","s":"担任の授業は、淡々と進んだ。スキルの基礎理論。属性と系統。使用時の消耗。耀平には、ほとんど知っていることばかりだった。","f":"yohei"},{"t":"i","s":"（……寝そう）","f":"yohei"},{"t":"n","s":"窓の外の桜が、風に揺れている。まぶたが、ゆっくりと降りていく。","f":"yohei"},{"t":"d","s":"「金井」","f":"yohei"},{"t":"d","s":"「はいっ」","f":"yohei"},{"t":"d","s":"「起きていたか」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「では、スキルの発動条件を三つ述べよ」","f":"yohei"},{"t":"d","s":"「意志、集中、そして……えっと、消耗に耐える身体です」","f":"yohei"},{"t":"d","s":"「正解だ。座れ」","f":"yohei"},{"t":"n","s":"クラスが、少しだけざわついた。柚月が、横目でこちらを見ている。","f":"yuzuki"},{"t":"i","s":"（……あ、見られた）","f":"yuzuki"},{"t":"n","s":"耀平は、そっと目をそらして、背筋を伸ばした。","f":"yohei"}]},{"key":"14-2","title":"実技テスト","bg":"bg_arena","dark":false,"mood":"daily","bgm":"daily1","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"四月の終わり。最初の実技テストの日がやってきた。"},{"t":"n","s":"体育館に、各クラスの生徒が集められていた。的を撃つ。標的を斬る。障害を越える。先生たちが、一人ずつ評価を付けていく。"},{"t":"d","s":"「E組、前へ」"},{"t":"n","s":"耀平は、一列に並んだ生徒の中に混ざった。隣には柚月が立っている。","f":"yohei"},{"t":"d","s":"「次、金井」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"n","s":"耀平は、木刀を構えた。刃引きの練習刀は、腰に差したまま。","f":"yohei"},{"t":"i","s":"（目立たない。目立たない。ちゃんと、普通に）","f":"yohei"},{"t":"n","s":"的に向かって、一閃。桜の花びらが、ひらり、と舞った。的に、浅い傷が一つ。","f":"yohei","fx":"flash"},{"t":"d","s":"「……合格。次」","f":"yohei"},{"t":"d","s":"「あれだけ?」「地味だな」「でも、涼しい顔してた」","f":"yohei"},{"t":"n","s":"そんな声が、後ろから聞こえてくる。耀平は、何も聞こえないふりをして下がった。","f":"yohei"},{"t":"d","s":"「次、朝霧」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"n","s":"柚月が、静かに前へ出る。","f":"yuzuki"},{"t":"n","s":"体育館の空気が、すっと冷えた。吐いた息が、白くなる。","f":"yuzuki"},{"t":"i","s":"（……え）","f":"yuzuki"},{"t":"n","s":"柚月は、手のひらを前に出した。淡い雪が、どこからともなく舞い降りた。","f":"yuzuki"},{"t":"d","s":"「淡雪」","f":"yuzuki"},{"t":"n","s":"的が、静かに凍りついた。ぱき、と音を立てて、氷の花が咲く。","f":"yuzuki"},{"t":"n","s":"体育館が、しんとなった。","f":"yuzuki"},{"t":"d","s":"「……合格だ。朝霧、力を抑えているな」","f":"yuzuki"},{"t":"d","s":"「…………はい」","f":"yuzuki"},{"t":"d","s":"「なぜだ」","f":"yuzuki"},{"t":"d","s":"「理由は、ありません」","f":"yuzuki"},{"t":"n","s":"先生は、何か言いたげな顔をしたが、結局、頷いただけだった。","f":"yuzuki"},{"t":"n","s":"柚月は、列に戻ってくる。耀平の隣を通り過ぎる時、ほんの一瞬、目が合った。","f":"yuzuki"},{"t":"d","s":"「…………」","f":"yuzuki"},{"t":"d","s":"「…………」","f":"yuzuki"},{"t":"n","s":"言葉は、なかった。けれど、お互いに、同じことを思っている気がした。","f":"yuzuki"},{"t":"i","s":"（この人も、抑えてる）","f":"yuzuki"},{"t":"n","s":"その日、E組の評価は、全員が最下位のままだった。","f":"yuzuki"}]},{"key":"14-3","title":"墓前","bg":"bg_grave","dark":false,"mood":"daily","bgm":"daily2","cast":["yohei","jin","noa"],"lines":[{"t":"n","s":"ゴールデンウィーク。寮は閑散としていた。実家に帰る生徒が多いのだ。"},{"t":"n","s":"耀平は、電車を乗り継いで、祖父の墓へ向かった。","f":"yohei"},{"t":"n","s":"小さな墓地は、町外れの丘にあった。桜はすっかり終わって、新緑が風に揺れている。白い花を手向け、線香に火を付ける。","f":"yohei"},{"t":"d","s":"「おじいちゃん。入学、したよ」","f":"yohei"},{"t":"n","s":"手を合わせて、目を閉じる。","f":"yohei"},{"t":"d","s":"「E組になった。最下位のクラス。でも、悪くないんだ。隣に、すごい人がいて」","f":"yohei"},{"t":"n","s":"風が、草を揺らした。","f":"yohei"},{"t":"d","s":"「乃亜も、竜馬も、同じ学園にいる。蓮先輩は、生徒会長だった。……ぜんぶ、じいちゃんが見たら、笑うかな」","f":"yohei"},{"t":"n","s":"目を開けると、少し離れた墓の前に、人影があった。","f":"yohei"},{"t":"n","s":"黒い髪。鋭い目。耀平と同じくらいの年の少年が、一つの墓石の前に立っていた。手には何も持っていない。花も、線香も。","f":"yohei"},{"t":"i","s":"（……誰だろう）","f":"yohei"},{"t":"n","s":"少年は、じっと墓石を見つめている。その背中は、不思議と、孤独に見えた。","f":"yohei"},{"t":"n","s":"耀平が立ち去ろうとした時、少年がこちらを振り返った。","f":"yohei"},{"t":"d","s":"「…………」","f":"yohei"},{"t":"n","s":"目が、合った。","f":"yohei"},{"t":"n","s":"鋭い視線が、耀平の腰の刀を見る。それから、顔を見る。","f":"yohei"},{"t":"d","s":"「おまえ」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「その刀。誰に教わった」","f":"yohei"},{"t":"d","s":"「祖父に」","f":"yohei"},{"t":"d","s":"「……そうか」","f":"yohei"},{"t":"n","s":"少年は、それ以上何も聞かなかった。","f":"yohei"},{"t":"d","s":"「名前は」","f":"yohei"},{"t":"d","s":"「金井耀平」","f":"yohei"},{"t":"d","s":"「迅だ」","f":"yohei"},{"t":"d","s":"「ジン？」","f":"yohei"},{"t":"d","s":"「それだけでいい」","f":"yohei"},{"t":"n","s":"迅と名乗った少年は、懐から一枚の紙切れを取り出した。何も書かれていない、白い紙。それを墓石の前に置く。","f":"jin"},{"t":"d","s":"「……花も線香も、嫌いなんだ」","f":"jin"},{"t":"d","s":"「え」","f":"jin"},{"t":"d","s":"「刀を、持って来ればよかったな」","f":"jin"},{"t":"n","s":"迅は、そう呟いた。そして、耀平の脇を通り過ぎていく。","f":"jin"},{"t":"d","s":"「おい」","f":"jin"},{"t":"d","s":"「はい」","f":"jin"},{"t":"d","s":"「また会うかもしれん。その時は、手を抜くな」","f":"jin"},{"t":"d","s":"「え、どういう——」","f":"jin"},{"t":"n","s":"振り返った時には、もう、少年の姿はなかった。","f":"jin"},{"t":"i","s":"（……誰だったんだろう）","f":"jin"},{"t":"n","s":"耀平は、ただ、立ち尽くしていた。白い紙が、風に飛ばされて、桜の若葉の中へ消えた。","f":"yohei"},{"t":"n","s":"鞘の中で、刃が、ことり、と鳴った。","f":"yohei"}]},{"key":"14-4","title":"連休明け","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily3","cast":["noa","yohei","ryoma"],"lines":[{"t":"n","s":"連休が明けた。"},{"t":"d","s":"「耀平、聞いて。C組の担任、スパルタすぎ」"},{"t":"d","s":"「大変そうだね」"},{"t":"d","s":"「あんたのところは?」"},{"t":"d","s":"「普通。のんびり」"},{"t":"d","s":"「いいな。E組」"},{"t":"n","s":"昼休みの中庭で、乃亜がパンをかじる。向かいのベンチでは、竜馬がA組の友人たちと、なにやら騒いでいた。","f":"noa"},{"t":"d","s":"「竜馬、楽しそうだね」","f":"noa"},{"t":"d","s":"「うん。友達、できたみたい」","f":"noa"},{"t":"d","s":"「あんたは?」","f":"noa"},{"t":"d","s":"「おれは、まだ。隣の人と、ちょっと話した」","f":"noa"},{"t":"d","s":"「朝霧さん?」","f":"noa"},{"t":"d","s":"「うん。知ってるの?」","f":"noa"},{"t":"d","s":"「有名よ。入学試験、首席だったって」","f":"noa"},{"t":"d","s":"「え」","f":"noa"},{"t":"n","s":"乃亜は、声を落とした。","f":"noa"},{"t":"d","s":"「でも、クラス分けに来なくて、E組になったって。みんな噂してる」","f":"noa"},{"t":"d","s":"「そうなんだ」","f":"noa"},{"t":"d","s":"「あんた、気をつけなさいよ」","f":"noa"},{"t":"d","s":"「何を?」","f":"noa"},{"t":"d","s":"「あの子、普通じゃないから」","f":"noa"},{"t":"n","s":"耀平は、少し考えた。","f":"yohei"},{"t":"d","s":"「……乃亜だって、普通じゃないよ」","f":"yohei"},{"t":"d","s":"「は?」","f":"yohei"},{"t":"d","s":"「あ、いや」","f":"yohei"},{"t":"d","s":"「どういう意味」","f":"yohei"},{"t":"d","s":"「なんでもない」","f":"yohei"},{"t":"n","s":"乃亜は、じろりと耀平を睨んだ。それから、小さく溜息をついた。","f":"noa","m":"anger"},{"t":"d","s":"「……あんたって、時々、鋭いよね」","f":"noa"},{"t":"d","s":"「そう?」","f":"noa"},{"t":"d","s":"「そう。気をつけて」","f":"noa"},{"t":"d","s":"「何に?」","f":"noa"},{"t":"d","s":"「全部」","f":"noa"},{"t":"n","s":"乃亜は、パンの袋を丸めて、立ち上がる。","f":"noa"},{"t":"d","s":"「あたし、行くね。ちゃんと食べなさいよ」","f":"noa"},{"t":"d","s":"「うん」","f":"noa"},{"t":"n","s":"去っていく背中を見送りながら、耀平は思った。","f":"yohei"},{"t":"i","s":"（乃亜は、いつも、おれのことを見てくれている）","f":"yohei"},{"t":"n","s":"そして、その少し離れた場所から、窓際の席の少女が、静かにこちらを見ていたことに——","f":"yohei"},{"t":"n","s":"耀平は、まだ、気づいていなかった。","f":"yohei"}]},{"key":"14-x4","title":"教科書","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily4","cast":["yuzuki","yohei"],"lines":[{"t":"cg","v":"cg_yuzuki_textbook"},{"t":"n","s":"数学の時間。耀平は、鞄の中を三回探して、ようやく諦めた。","f":"yohei"},{"t":"i","s":"（教科書、寮に置いてきた）","f":"yohei"},{"t":"n","s":"隣から、机の脚が床をこする小さな音がした。柚月が、黙って自分の机を寄せてくる。","f":"yuzuki"},{"t":"d","s":"「……見れば」","f":"yuzuki"},{"t":"d","s":"「ありがとう、朝霧さん」","f":"yuzuki"},{"t":"d","s":"「別に。先生に当てられて、あなたが答えられないと、隣の私まで目立つから」","f":"yuzuki"},{"t":"n","s":"教科書が、二人の机のちょうど真ん中に置かれた。肩と肩が、触れそうで触れない。","f":"yuzuki"},{"t":"n","s":"耀平は、黒板と教科書を見比べながら、ノートを取った。ふと横を見ると、柚月はページではなく、窓の外を見ていた。耳の先が、ほんの少しだけ赤い。","f":"yohei","m":"blush"},{"t":"d","s":"「……何」","f":"yohei"},{"t":"d","s":"「なんでもない」","f":"yohei"},{"t":"d","s":"「前を見て」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"n","s":"授業が終わるまで、教科書は、真ん中から一ミリも動かなかった。","f":"yohei"}],"extra":true},{"key":"14-x5","title":"昼休みの屋上","bg":"bg_rooftop","dark":false,"mood":"daily","bgm":"daily5","cast":["yohei","noa","yuzuki"],"lines":[{"t":"cg","v":"cg_rival_glare"},{"t":"n","s":"昼休みの廊下で、それは起きた。"},{"t":"d","s":"「耀平。お昼、屋上ね」"},{"t":"n","s":"C組の教室から出てきた乃亜が、当たり前のように言った。その手には、包みが二つある。","f":"noa"},{"t":"d","s":"「金井くん。今日、購買のパンが売り切れていたでしょう」","f":"noa"},{"t":"n","s":"反対側から、柚月の静かな声がした。その手にも、包みが二つ。","f":"yuzuki"},{"t":"n","s":"乃亜と柚月の目が、廊下の真ん中で、ぶつかった。","f":"noa"},{"t":"d","s":"「……誰」","f":"noa"},{"t":"d","s":"「同じクラスの、朝霧です。あなたは」","f":"noa"},{"t":"d","s":"「幼馴染の、乃亜」","f":"noa"},{"t":"d","s":"「そう。幼馴染の」","f":"noa"},{"t":"d","s":"「うん。幼馴染の」","f":"noa"},{"t":"n","s":"二人とも、笑っていた。笑っているのに、廊下の温度が、三度くらい下がった気がした。耀平の背中を、冷たい汗が伝う。","f":"yohei","m":"sweat"},{"t":"d","s":"「えっと……三人で、食べる？」","f":"yohei"},{"t":"n","s":"二人が、同時に耀平を見た。","f":"yohei"},{"t":"cg","v":"cg_rival_lunch"},{"t":"n","s":"屋上のベンチに、三人で並んだ。","f":"yohei"},{"t":"d","s":"「はい。卵焼き、甘いほう」","f":"yohei"},{"t":"d","s":"「金井くん。こちらは、だし巻きです」","f":"yohei"},{"t":"n","s":"左右から、同時に弁当箱が差し出される。耀平は、箸を持ったまま固まった。","f":"yohei"},{"t":"d","s":"「……どっちから、食べればいいの」","f":"yohei"},{"t":"d","s":"「好きなほうから」","f":"yohei"},{"t":"d","s":"「好きなほうからで、いいですよ」","f":"yohei"},{"t":"n","s":"声は優しい。目は、まったく優しくない。","f":"yohei"},{"t":"n","s":"耀平は、両方の卵焼きを一切れずつ取って、同時に口に入れた。","f":"yohei"},{"t":"d","s":"「……どっちも、おいしい」","f":"yohei"},{"t":"n","s":"乃亜が、ため息をついた。柚月が、小さく吹き出した。","f":"noa"},{"t":"d","s":"「ずるい答え」","f":"noa"},{"t":"d","s":"「ずるいですね」","f":"noa"},{"t":"n","s":"その日、二人の意見が合ったのは、それだけだった。","f":"noa"}],"extra":true},{"key":"14-x6","title":"雨の帰り道","bg":"bg_gate","dark":false,"mood":"daily","bgm":"daily1","cast":["yuzuki","yohei"],"lines":[{"t":"cg","v":"cg_yuzuki_umbrella"},{"t":"n","s":"放課後、昇降口の外は、どしゃ降りだった。"},{"t":"n","s":"柚月は、空を見上げたまま立ち尽くしていた。傘を持っていないらしい。","f":"yuzuki"},{"t":"d","s":"「朝霧さん。これ」","f":"yuzuki"},{"t":"d","s":"「……あなたの分は」","f":"yuzuki"},{"t":"d","s":"「一本しかないから、一緒に入ろう。寮まで、同じ方向だし」","f":"yuzuki"},{"t":"n","s":"柚月は少し迷ってから、傘の下に入ってきた。","f":"yuzuki"},{"t":"n","s":"並んで歩く。雨の音が、二人だけを閉じ込める。","f":"yuzuki"},{"t":"n","s":"しばらく歩いて、柚月が、ふと耀平の肩を見た。傘は、ずっと柚月のほうに傾いていて、耀平の左肩は、ぐっしょりと濡れていた。","f":"yuzuki"},{"t":"d","s":"「……濡れてる」","f":"yuzuki"},{"t":"d","s":"「平気。すぐ乾く」","f":"yuzuki"},{"t":"d","s":"「平気じゃない」","f":"yuzuki"},{"t":"n","s":"柚月は、傘の柄に、そっと手を添えた。傘が、少しだけ耀平のほうへ戻る。","f":"yuzuki"},{"t":"d","s":"「……これで、半分ずつ」","f":"yuzuki"},{"t":"n","s":"雨の中で、その声だけが、妙にはっきりと聞こえた。","f":"yuzuki"}],"extra":true}]},{"n":15,"title":"剣聖の死と、葬儀の朝","sub":"高校・1年初夏","era":"high","lead":"六月。梅雨の入りの朝、学園に一通の訃報が届いた。","scenes":[{"key":"15-1","title":"訃報","bg":"bg_classroom_e","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","principal","yuzuki"],"lines":[{"t":"n","s":"朝のホームルームで、担任はいつもより長く黙っていた。"},{"t":"d","s":"「……全員、聞いてくれ」"},{"t":"d","s":"「先生？」"},{"t":"d","s":"「今朝、剣聖が亡くなった」"},{"t":"n","s":"教室の空気が、止まった。"},{"t":"n","s":"剣聖。この国で、もっとも名の知れた剣士。スキルを持つ者なら、誰もがその名を知っている。"},{"t":"d","s":"「え、嘘でしょ」"},{"t":"d","s":"「病気だったの？」"},{"t":"d","s":"「死因は、まだ公表されていない」"},{"t":"d","s":"「公表されてない、って」"},{"t":"d","s":"「分からん。私も、今朝知らされたばかりだ」"},{"t":"n","s":"担任は、いつもの淡々とした口調だった。けれど、書類を持つ手が、わずかに震えている。"},{"t":"i","s":"（……この人、知り合いだったのかな）"},{"t":"n","s":"耀平は、ふとそう思った。","f":"yohei"},{"t":"n","s":"学園長と剣聖が旧知の仲だという噂は、入学前から聞いていた。担任もきっと、その縁で学園に来たのだろう。","f":"principal"},{"t":"d","s":"「葬儀は、三日後。学園からも、代表者が参列する。生徒会長の九条と、学年首席の数名だ」","f":"principal"},{"t":"d","s":"「E組は？」","f":"principal"},{"t":"d","s":"「参列しない。当然だ」","f":"principal"},{"t":"n","s":"担任は、そう言い切った。","f":"principal"},{"t":"i","s":"（……そう、だよね）","f":"principal"},{"t":"n","s":"耀平は、窓の外を見た。雨が、校庭を静かに濡らしている。","f":"yohei"},{"t":"n","s":"横の席で、柚月がじっと机の上を見ていた。何も言わない。表情も変わらない。けれど、細い指が、膝の上でぎゅっと握られていた。","f":"yuzuki"}]},{"key":"15-2","title":"雨の中庭","bg":"bg_classroom_e","dark":false,"mood":"sad","bgm":"sad1","cast":["yohei","noa","jin"],"lines":[{"t":"n","s":"昼休み。耀平は、傘を差して中庭に出た。","f":"yohei"},{"t":"n","s":"古い桜の木の下。葉桜になった枝が、雨粒を受けて静かに揺れている。","f":"yohei"},{"t":"d","s":"「……何してんの」","f":"yohei"},{"t":"n","s":"後ろから声がした。乃亜だった。傘の下で、腕を組んでいる。","f":"noa"},{"t":"d","s":"「ちょっと、考えてた」","f":"noa"},{"t":"d","s":"「剣聖のこと？」","f":"noa"},{"t":"d","s":"「うん。知らないはずなのに、なんだか、変な感じがして」","f":"noa"},{"t":"d","s":"「あんた、会ったことある？」","f":"noa"},{"t":"d","s":"「ない。と思う」","f":"noa"},{"t":"d","s":"「思う？」","f":"noa"},{"t":"d","s":"「たぶん。でも」","f":"noa"},{"t":"n","s":"耀平は、そこで言葉を切った。","f":"yohei"},{"t":"i","s":"（あの墓の前の、迅って人）","f":"yohei"},{"t":"n","s":"黒い髪。鋭い目。「刀を持って来ればよかった」と呟いた声。","f":"yohei"},{"t":"n","s":"関係があるとは、限らない。けれど、なぜか、頭から離れなかった。","f":"yohei"},{"t":"d","s":"「耀平」","f":"yohei"},{"t":"d","s":"「ん」","f":"yohei"},{"t":"d","s":"「あんた、また顔、怖いよ」","f":"yohei"},{"t":"d","s":"「ごめん」","f":"yohei"},{"t":"d","s":"「謝らなくていい。ただ、あんまり抱え込まないで」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「約束」","f":"yohei"},{"t":"d","s":"「うん。約束」","f":"yohei"},{"t":"n","s":"乃亜は、それ以上何も言わず、そっと隣に立っていた。","f":"noa"},{"t":"n","s":"雨の音だけが、二人の間に降っていた。","f":"noa"}]},{"key":"15-3","title":"九条蓮","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily3","cast":["ren","yohei"],"lines":[{"t":"n","s":"放課後。耀平は、昇降口で呼び止められた。","f":"yohei"},{"t":"d","s":"「金井」","f":"yohei"},{"t":"n","s":"振り向くと、傘を持った蓮が立っていた。いつもの完璧な笑顔は、そこにはなかった。","f":"ren"},{"t":"d","s":"「九条先輩」","f":"ren"},{"t":"d","s":"「少し、いいか」","f":"ren"},{"t":"n","s":"二人は、人気のない渡り廊下に移った。雨が、屋根を叩く音だけが響いている。","f":"ren"},{"t":"d","s":"「剣聖のことは、知っているか」","f":"ren"},{"t":"d","s":"「今日、聞きました」","f":"ren"},{"t":"d","s":"「そうか」","f":"ren"},{"t":"n","s":"蓮は、しばらく黙っていた。それから、静かに口を開いた。","f":"ren"},{"t":"d","s":"「あの方は、私の剣の師でもあった」","f":"ren"},{"t":"d","s":"「え」","f":"ren"},{"t":"d","s":"「幼い頃、少しだけ、手ほどきを受けた。だから、私は参列する」","f":"ren"},{"t":"n","s":"蓮の横顔は、いつもよりも、ずっと疲れて見えた。","f":"ren"},{"t":"d","s":"「死因は、公表されていない。だが、私は、病ではないと思っている」","f":"ren"},{"t":"d","s":"「どうして、そう」","f":"ren"},{"t":"d","s":"「勘だ」","f":"ren"},{"t":"n","s":"蓮は、ほんの少しだけ口の端を持ち上げた。","f":"ren"},{"t":"d","s":"「私の勘は、よく当たる」","f":"ren"},{"t":"d","s":"「……はい」","f":"ren"},{"t":"d","s":"「金井。もし、学園に何かあったら」","f":"ren"},{"t":"n","s":"蓮は、そこで言葉を止めた。それから、首を横に振った。","f":"ren"},{"t":"d","s":"「……いや。何でもない。今のは忘れてくれ」","f":"ren"},{"t":"d","s":"「先輩？」","f":"ren"},{"t":"d","s":"「引き止めて悪かったな。気をつけて帰れ」","f":"ren"},{"t":"n","s":"蓮は、そう言って、背を向けた。","f":"ren"},{"t":"n","s":"耀平は、その背中を見送りながら、胸の奥が、ざわりとするのを感じた。","f":"yohei"},{"t":"i","s":"（何かあったら）","f":"yohei"},{"t":"i","s":"（……何か、って）","f":"yohei"}]},{"key":"15-4","title":"葬儀の朝","bg":"bg_graduation","dark":false,"mood":"sad","bgm":"sad1","cast":["yuzuki","yohei","ren"],"lines":[{"t":"n","s":"葬儀の日は、雨が上がった。"},{"t":"n","s":"朝の空は、薄い灰色で、雲の切れ間から、細い光が差している。学園の中は、いつもより静かだった。生徒会長の蓮と、数名の上級生や代表者は、すでに会場へ向かっている。","f":"ren"},{"t":"n","s":"残された生徒たちは、普段通りの授業を受けた。けれど、誰もが、どこか落ち着かない顔をしていた。","f":"ren"},{"t":"d","s":"「……今日、静かだな」","f":"ren"},{"t":"d","s":"「剣聖の葬儀だもんな」","f":"ren"},{"t":"d","s":"「なんか、嫌な予感がするんだけど」","f":"ren"},{"t":"d","s":"「やめろよ、縁起でもない」","f":"ren"},{"t":"n","s":"教室の後ろで、そんな会話が聞こえる。","f":"ren"},{"t":"n","s":"耀平は、窓の外を見ていた。古い桜の木が、濡れた葉を光らせている。","f":"yohei"},{"t":"i","s":"（……おじいちゃんが、いたら）","f":"yohei"},{"t":"i","s":"（今日、どうしただろう）","f":"yohei"},{"t":"n","s":"祖父は、剣聖と面識があっただろうか。聞いたことはない。けれど、あの人は、何も話さない人だった。","f":"yohei"},{"t":"d","s":"「……金井」","f":"yohei"},{"t":"n","s":"隣から、小さな声がした。柚月だった。","f":"yuzuki"},{"t":"d","s":"「なに」","f":"yuzuki"},{"t":"d","s":"「……あなたは、行かなくていいの」","f":"yuzuki"},{"t":"d","s":"「え」","f":"yuzuki"},{"t":"d","s":"「葬儀」","f":"yuzuki"},{"t":"d","s":"「E組は、参列しないって」","f":"yuzuki"},{"t":"d","s":"「そう」","f":"yuzuki"},{"t":"n","s":"柚月は、それだけ言って、また前を向いた。けれど、少しして、小さく付け足した。","f":"yuzuki"},{"t":"d","s":"「……わたしも、行かない」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"d","s":"「行けない、から」","f":"yuzuki"},{"t":"d","s":"「そっか」","f":"yuzuki"},{"t":"n","s":"耀平は、それ以上は聞かなかった。","f":"yohei"},{"t":"n","s":"柚月の横顔は、やっぱり、どこか遠くを見ているようだった。","f":"yuzuki"},{"t":"d","s":"「朝霧さん」","f":"yuzuki"},{"t":"d","s":"「……なに」","f":"yuzuki"},{"t":"d","s":"「肝試しの時のこと」","f":"yuzuki"},{"t":"d","s":"「…………」","f":"yuzuki"},{"t":"n","s":"柚月の肩が、ぴくりと動いた。","f":"yuzuki"},{"t":"d","s":"「聞かないほうが、いい？」","f":"yuzuki"},{"t":"d","s":"「…………」","f":"yuzuki"},{"t":"d","s":"「聞かない。ごめん」","f":"yuzuki"},{"t":"d","s":"「……ううん」","f":"yuzuki"},{"t":"n","s":"柚月は、小さく首を横に振った。","f":"yuzuki"},{"t":"d","s":"「いつか、話す。たぶん」","f":"yuzuki"},{"t":"d","s":"「うん。待ってる」","f":"yuzuki"},{"t":"d","s":"「……待たなくて、いいのに」","f":"yuzuki"},{"t":"d","s":"「待つよ。約束、してる人がいるから」","f":"yuzuki"},{"t":"d","s":"「……約束？」","f":"yuzuki"},{"t":"d","s":"「待つって、そういう人間になるって、約束したんだ」","f":"yuzuki"},{"t":"n","s":"柚月は、不思議そうに耀平を見た。それから、ほんの少しだけ、口元を緩めた。","f":"yuzuki"},{"t":"d","s":"「……へんな人」","f":"yuzuki"},{"t":"d","s":"「よく言われる」","f":"yuzuki"},{"t":"n","s":"窓の外で、風が吹いた。桜の葉が、さらりと揺れる。","f":"yuzuki"}]},{"key":"15-5","title":"予感","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense1","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"昼過ぎだった。"},{"t":"n","s":"空が、急に暗くなった。雲が厚くなったのではない。もっと、別の何かが、空を覆い始めている。"},{"t":"d","s":"「……あれ」"},{"t":"d","s":"「なに、あれ」"},{"t":"d","s":"「空、おかしくない？」"},{"t":"n","s":"教室がざわめく。耀平は、窓際に走った。","f":"yohei"},{"t":"n","s":"灰色の空の向こうに、黒い影が、じわりと広がっていた。まるで、墨を水に落としたように。","f":"yohei"},{"t":"i","s":"（……これ、あの夜と同じ）","f":"yohei"},{"t":"n","s":"肝試しの夜。影の男が現れた時と、同じ空気。","f":"yohei"},{"t":"d","s":"「全員、席に着け！」","f":"yohei"},{"t":"n","s":"担任の声が響いた。いつもの淡々とした声ではなかった。鋭く、張り詰めている。","f":"yohei"},{"t":"d","s":"「窓から離れろ。カーテンを閉めろ。出口を確認しろ」","f":"yohei"},{"t":"d","s":"「先生、何が——」","f":"yohei"},{"t":"d","s":"「説明は後だ！」","f":"yohei"},{"t":"n","s":"担任は、廊下に飛び出していった。教室が、一気にパニックになる。","f":"yohei"},{"t":"d","s":"「どうなってんだよ！」","f":"yohei"},{"t":"d","s":"「襲撃？ 嘘でしょ？」","f":"yohei"},{"t":"d","s":"「落ち着いて！ 先生が戻るまで、ここにいて！」","f":"yohei"},{"t":"n","s":"誰かが叫んでいる。誰かが泣いている。耀平は、木刀を握り締めて、立ち尽くした。","f":"yohei","m":"sad"},{"t":"i","s":"（……来る）","f":"yohei"},{"t":"n","s":"理由は分からない。けれど、確かに、そう思った。","f":"yohei"},{"t":"d","s":"「金井」","f":"yohei"},{"t":"n","s":"隣から、冷たい声がした。柚月だった。立ち上がって、窓の外をじっと見ている。","f":"yuzuki"},{"t":"d","s":"「朝霧さん」","f":"yuzuki"},{"t":"d","s":"「……あれは、天冠の影」","f":"yuzuki"},{"t":"d","s":"「天冠？」","f":"yuzuki"},{"t":"d","s":"「あとで、話す。今は、逃げないで」","f":"yuzuki"},{"t":"d","s":"「うん。逃げない」","f":"yuzuki"},{"t":"n","s":"柚月は、静かに頷いた。その手の中に、薄い氷の結晶が、きらりと光った。","f":"yuzuki","fx":"flash"},{"t":"n","s":"遠くで、鐘の音が鳴り響く。","f":"yuzuki"},{"t":"n","s":"学園全体が、息を呑んだ。","f":"yuzuki","m":"surprise"},{"t":"n","s":"——そして、襲撃が、始まった。","f":"yuzuki"}]}]},{"n":16,"title":"一度目の襲撃・E組","sub":"高校・1年初夏","era":"high","lead":"黒い影が、校舎を飲み込んでいく。最弱と呼ばれるクラスの教室で、耀平は、はじめて「手を抜く」ことの重さを知る。","scenes":[{"key":"16-1","title":"影の兵","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle2","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"最初に聞こえたのは、窓ガラスが割れる音だった。"},{"t":"d","s":"「きゃああっ！」"},{"t":"d","s":"「な、なんだあれ！」"},{"t":"n","s":"上の階から、悲鳴が降ってくる。廊下の向こうで、重い足音がいくつも、いくつも、近づいてくる。"},{"t":"n","s":"E組の教室は、校舎のいちばん端にある。逃げ道は、前の扉と、後ろの扉と、窓。そのどれも、すでに影に塞がれていた。"},{"t":"d","s":"「開かない！　扉が開かないよ！」"},{"t":"d","s":"「窓もだ！　びくともしない」"},{"t":"d","s":"「先生は！　先生はどこ！」"},{"t":"n","s":"生徒たちが、教室の真ん中に身を寄せ合う。二十人の息遣いが、熱を帯びている。"},{"t":"d","s":"「落ち着いて。相手は、影でできた兵だ。走っているやつを、殺さないというなら、まだ、勝てる」"},{"t":"n","s":"落ち着いた声だった。柚月だ。彼女は、教室の真ん中で立ち上がり、みんなの顔をゆっくり見渡した。","f":"yuzuki"},{"t":"d","s":"「……朝霧さん？」","f":"yuzuki"},{"t":"d","s":"「承知のうえで言う。このクラスの人間は、評価は低いけど、弱くはない」","f":"yuzuki"},{"t":"d","s":"「えっ、俺たちが？」","f":"yuzuki"},{"t":"d","s":"「評価は、理由があって低くなっているだけ」","f":"yuzuki"},{"t":"n","s":"柚月は、ちらりと耀平を見た。","f":"yuzuki"},{"t":"i","s":"（……ここで、俺に振るの）","f":"yuzuki"},{"t":"n","s":"耀平は、木刀を握り直した。","f":"yohei"},{"t":"n","s":"その時、前の扉が、黒い影ごと吹き飛んだ。","f":"yohei","fx":"shake"}]},{"key":"16-2","title":"教室で","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle2","cast":["yohei"],"lines":[{"t":"n","s":"影の兵は、人の形をしていた。けれど、顔には何もなかった。黒い塊に、赤い光が二つ。それだけだ。"},{"t":"n","s":"教室に、五体。すぐに七体。さらに増える。"},{"t":"d","s":"「うわああっ！」"},{"t":"n","s":"窓際の男子が、椅子を投げつけた。影の腕が、椅子を粉々に砕いた。"},{"t":"d","s":"「くそっ、俺の『筋力増強』、腕しか強くなんねえのに——」"},{"t":"d","s":"「腕でいい！　的を、こっちに引き付けて！　そこの眼鏡の子、足元に糸！」"},{"t":"d","s":"「う、うん！『糸結小縁』！」"},{"t":"n","s":"地味なスキルが、つながっていく。赤い印をつけられた影の足元に、細い糸が絡まる。影の動きが、わずかに鐘る。"},{"t":"i","s":"（……すごい）"},{"t":"n","s":"耀平は、思わず息を呑んだ。このクラスの人間は、ちゃんと、戦っている。評価は最下位でも、心は折れていない。","f":"yohei","m":"surprise"},{"t":"d","s":"「金井！　ぼさっとしてんな！　お前も手伝え！」","f":"yohei"},{"t":"d","s":"「あ、うん！」","f":"yohei"},{"t":"n","s":"耀平は、木刀を構えた。","f":"yohei"},{"t":"i","s":"（目立たない。目立たない。……でも、誰も死なせない）","f":"yohei"},{"t":"n","s":"一体の影が、耀平に飛びかかってくる。耀平は、一歩だけ横にずらした。木刀が、影の腕を、すっと受け流す。","f":"yohei"},{"t":"n","s":"桜の花びらが、一枚、舞った。","f":"yohei"},{"t":"n","s":"影の兵は、勢いを殺されて、教室の壁に激突した。粉々にはならない。ただ、動けなくなる。","f":"yohei"},{"t":"d","s":"「……やった？」","f":"yohei"},{"t":"d","s":"「やってない。動かなくしただけ」","f":"yohei"},{"t":"d","s":"「起き上がってくるぞ！」","f":"yohei"},{"t":"n","s":"影は、また立ち上がる。赤い目が、耀平をじっと見る。","f":"yohei"},{"t":"i","s":"（これ、キリがない）","f":"yohei"},{"t":"n","s":"このままでは、体力が先に尽きる。誰かが傷つく。耀平は、子どもの頃の朝を思い出した。祖父の声。「強くなれ。優しくなれ」。","f":"yohei"},{"t":"i","s":"（……ほんの少しだけ）","f":"yohei"},{"t":"n","s":"耀平は、木刀を一振りした。","f":"yohei"},{"t":"n","s":"影の足元から、一陣の花びらが舞い上がった。薄桃色。この教室にあるはずのない、桜の吹雪。","f":"yohei"},{"t":"d","s":"「……え。桜、？」","f":"yohei"},{"t":"d","s":"「金井、いま——」","f":"yohei"},{"t":"n","s":"花びらが、影の腕を、胴を、すっと通り抜けた。無数の切り目が影に走り、黒い塊は、音もなく、砂のように崩れ落ちた。","f":"yohei"},{"t":"n","s":"教室が、しんとした。","f":"yohei"},{"t":"d","s":"「……今の、何」","f":"yohei"},{"t":"d","s":"「分かんねえ……」","f":"yohei"},{"t":"d","s":"「金井がやったの？」","f":"yohei"},{"t":"n","s":"耀平は、木刀を下ろして、ゆっくりと首を横に振った。","f":"yohei"},{"t":"d","s":"「えっと。たぶん、偶然です」","f":"yohei"},{"t":"d","s":"「偶然でこんなの出てたまるか！」","f":"yohei"},{"t":"d","s":"「でも、ポケットの中に、桜の花びらが入ってたかも」","f":"yohei"},{"t":"d","s":"「そんなわけねえだろ！」","f":"yohei"},{"t":"n","s":"ツッコミが飛ぶ。緊張が、少しだけ、ゆるんだ。","f":"yohei"}]},{"key":"16-3","title":"氷の花","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle2","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"けれど、まだ終わってはいなかった。"},{"t":"n","s":"廊下の向こうから、さらに多くの影が、ゆらりと現れた。数は、十を超えた。いや、二十。"},{"t":"d","s":"「……多すぎる」"},{"t":"d","s":"「逆に、ここが狙われてるんじゃねえのか」"},{"t":"d","s":"「なんで、俺たちが——」"},{"t":"n","s":"その時。空気が、変わった。"},{"t":"n","s":"冷たい。とても、冷たい。息を吐くと、白くなる。"},{"t":"d","s":"「……下がって」"},{"t":"n","s":"柚月の声だった。細くて、でも、強い。","f":"yuzuki"},{"t":"d","s":"「朝霧さん？」","f":"yuzuki"},{"t":"d","s":"「最小限だけ。みんなを氷に左右されないように、壁を作る」","f":"yuzuki"},{"t":"n","s":"柚月が、手のひらを廊下へ向けた。","f":"yuzuki"},{"t":"d","s":"「風花」","f":"yuzuki"},{"t":"n","s":"教室の入口をふさぐように、薄い氷の壁が立ち上がった。薄いけれど、確かに、硝い。影の兵が、壁に体当たりをしている。ひびが入る。でも、突破できない。","f":"yuzuki"},{"t":"d","s":"「……また、すごいの出た」","f":"yuzuki"},{"t":"d","s":"「このクラス、何なんだよ……」","f":"yuzuki"},{"t":"n","s":"クラスメイトたちの視線が、柚月に集まる。柚月は、まっすぐ前を見ている。","f":"yuzuki"},{"t":"d","s":"「……先生が来るまでです。それまで、持ちこたえて」","f":"yuzuki"},{"t":"n","s":"壁の向こうで、どん、どん、と重い音が鳴り続ける。柚月の額に、汗が浮いている。","f":"yuzuki","m":"sweat"},{"t":"i","s":"（……限界が近い）","f":"yuzuki"},{"t":"n","s":"耀平は、そう思った。入学日に倒れたときも、彼女はこうやって、力を使いすぎたのかもしれない。","f":"yohei"},{"t":"d","s":"「朝霧さん」","f":"yohei"},{"t":"d","s":"「……何」","f":"yohei"},{"t":"d","s":"「交代する」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「壁の外をおれが見る。朝霧さんは休んで」","f":"yohei"},{"t":"d","s":"「……あなたは」","f":"yohei"},{"t":"d","s":"「木刀だけで、いけるから」","f":"yohei"},{"t":"n","s":"柚月は、耀平を見た。その目の奥に、不思議な色が浮かんでいた。疑いと、期待と、そして少しだけの安心。","f":"yuzuki"},{"t":"d","s":"「……無理、しないで」","f":"yuzuki"},{"t":"d","s":"「しないよ」","f":"yuzuki"},{"t":"n","s":"柚月が、手を下ろした。氷の壁に、細かいヒビが走る。","f":"yuzuki"},{"t":"n","s":"耀平は、一歩、前に出た。","f":"yohei"}]},{"key":"16-4","title":"桜の刀","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","hotaru"],"lines":[{"t":"n","s":"壁が、砂のように崩れた。"},{"t":"n","s":"廊下の影の兵が、一気に流れ込んでくる。赤い目が、数え切れないほど。"},{"t":"d","s":"「うわああっ！」"},{"t":"n","s":"耀平は、走った。","f":"yohei"},{"t":"n","s":"木刀が、弧を描く。桜の花びらが、彼の周りに舞い上がる。","f":"yohei"},{"t":"k","s":"【百花繚乱】","f":"yohei","fx":"bloom"},{"t":"n","s":"影の兵が、花びらの渦に飲まれていく。見た目は、美しい。けれど、影は一体、また一体と、墨を落とすように消える。","f":"yohei"},{"t":"i","s":"（大丈夫。まだ、大丈夫）","f":"yohei"},{"t":"n","s":"耀平は、力の割合を、厳しく抑えていた。薄い花びら。最小限の範囲。誰かに見られても、強いとは思われないように。","f":"yohei"},{"t":"n","s":"けれど、クラスメイトたちの目は、迷いなくこちらを見ていた。","f":"yohei"},{"t":"d","s":"「……いや、偶然じゃねえだろ、これ」","f":"yohei"},{"t":"d","s":"「あいつ、ポケットに花びら入れてたって言ってたよな」","f":"yohei"},{"t":"d","s":"「言い訳が苦しすぎる……」","f":"yohei"},{"t":"n","s":"でも、誰も、それ以上は、言わなかった。","f":"yohei"},{"t":"n","s":"耀平の背中を、みんなが、黙って見つめていた。","f":"yohei"},{"t":"n","s":"影の最後の一体が、花びらの渦に飲まれていく。","f":"yohei"},{"t":"n","s":"その時、廊下の奥から、硬い靴音が一つ、ゆっくりと近づいてきた。","f":"yohei"},{"t":"n","s":"この影の兵とは、明らかに違う。もっと、重い。もっと、深い。","f":"yohei"},{"t":"d","s":"「……あら。面白い」","f":"yohei"},{"t":"n","s":"甘い声が、廊下に響いた。","f":"yohei"},{"t":"d","s":"「最弱のクラスに、こんな花を咲かせる子がいるなんて」","f":"yohei"},{"t":"n","s":"紫の光が、ひとつ、ふたつ。蛍のように、暗い廊下を漂ってくる。その光に照らされて、一人の女が、教室の入口に現れた。","f":"hotaru"},{"t":"n","s":"緩く波打つ、薄紫の長い髪。深い紫のコートに、銀の鎖。指先を頬に添えて、彼女は、楽しそうに目を細めた。","f":"hotaru"},{"t":"d","s":"「……誰だ」","f":"hotaru"},{"t":"d","s":"「名乗るくらいは、してあげる」","f":"hotaru"},{"t":"n","s":"女は、スカートの裾をつまんで、優雅に一礼した。","f":"hotaru"},{"t":"d","s":"「天冠、第六席。紫苑蛍。ここにいる——『色のついた花』を、回収しに来たの」","f":"hotaru"},{"t":"n","s":"耀平の背筋を、冷たいものが走った。","f":"yohei"},{"t":"i","s":"（色のついた花。……おれの、ことか）","f":"yohei"},{"t":"n","s":"蛍の視線が、耀平を、まっすぐに捉えた。","f":"hotaru"}]}]},{"n":17,"title":"一度目の襲撃・C組、A組、上級生","sub":"高校・1年初夏","era":"high","lead":"同じ黒い空の下で、いくつもの教室が、各々の戦いを始めていた。","scenes":[{"key":"17-1","title":"C組の乃亜","bg":"bg_classroom_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["noa","yohei"],"lines":[{"t":"d","s":"「窓から離れろ！　廊下側の壁に寄れ！」"},{"t":"n","s":"C組の担任の声が、教室中に響く。このクラスは、さまざまなスキル持ちが、バランスよく並んでいる。学園の平均を象徴するようなクラスだ。"},{"t":"d","s":"「乃亜ちゃん、こっち！」"},{"t":"d","s":"「うん。ありがと、真帆」"},{"t":"n","s":"友達に袖を引かれて、乃亜は壁際に身を寄せた。窓の外には、黒い影がびっしりと張り付いている。","f":"noa"},{"t":"i","s":"（……あの夜と、同じだ）","f":"noa"},{"t":"n","s":"肘の内側が、ちりちりと痛む。肝試しの夜に、自分が使った力の記憶が、身体の奥でざわめいている。","f":"noa"},{"t":"d","s":"「窓ガラスが——」","f":"noa"},{"t":"n","s":"ガラスが割れる。影の兵が、数体、教室に雪崩れ込んでくる。","f":"noa"},{"t":"d","s":"「みんな、逃げて！」","f":"noa"},{"t":"n","s":"担任が目の前でスキルを発動する。地面から、岩の壁がせり上がる。影の兵が、壁にぶつかって、止まる。","f":"noa"},{"t":"d","s":"「これで、時間を稼げる。その間に、非常口から——」","f":"noa"},{"t":"n","s":"その壁の上を、影が乗り越えた。真帆の背後で、影の腕が振り上がる。","f":"noa"},{"t":"d","s":"「——あっ」","f":"noa"},{"t":"n","s":"乃亜は、考えるより先に、手を伸ばしていた。","f":"noa"},{"t":"n","s":"影の腕が、真帆の肩に届く直前、薄い水の葉が、その腕を包んだ。影の腕が、すっと横にそれる。","f":"noa"},{"t":"d","s":"「え」","f":"noa"},{"t":"d","s":"「真帆、低くして」","f":"noa"},{"t":"n","s":"乃亜は、真帆を引き寄せて、自分の背中で影を受けた。影の腕が、乃亜の肩スレスレを掠め、壁に激突する。","f":"noa"},{"t":"d","s":"「すご……今の、なんで避けたの」","f":"noa"},{"t":"d","s":"「えっと。偏っただけ」","f":"noa"},{"t":"d","s":"「偏っただけで、あんなに綺麗に黒いのが曲がる？」","f":"noa"},{"t":"d","s":"「今は、逃げよう」","f":"noa"},{"t":"n","s":"乃亜は、真帆の手を引いて走り出した。肉眼では見えない薄い水の膜が、二人の背中を守っている。","f":"noa"},{"t":"i","s":"（見られてはいけない。でも、見捨てるわけにもいかない）","f":"noa"},{"t":"n","s":"乃亜は、走りながら、窓の外を見た。校舎のいちばん端。あの教室のあるあたりを。","f":"noa"},{"t":"i","s":"（耀平。あんた、無理してないでしょうね、まさか）","f":"noa"},{"t":"n","s":"胸の奥が、きゅっと縮んだ。","f":"noa"}]},{"key":"17-2","title":"A組の竜馬","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["ryoma","yohei"],"lines":[{"t":"d","s":"「うるせえっ！　黙って見てろ！」"},{"t":"n","s":"A組の教室は、すでに渦の中にあった。"},{"t":"n","s":"竜馬は、窓際に立ち、拳を握っていた。赤い炎が、こぶしの周りでゆらゆらと揺れている。","f":"ryoma"},{"t":"d","s":"「竜馬、デカいのはやめろよ！　校舎が燃える！」","f":"ryoma"},{"t":"d","s":"「分かってる。この程度でいいんだろ」","f":"ryoma"},{"t":"n","s":"竜馬は、拳を振り抜いた。赤い炎が、影の兵の跡を、一直線に貫く。焦げるにおい。影は、埃になって消えていく。","f":"ryoma"},{"t":"d","s":"「……やっぱり、A組は違うな」","f":"ryoma"},{"t":"d","s":"「竜馬がいるの、心強すぎる」","f":"ryoma"},{"t":"n","s":"竜馬の背後で、クラスメイトがこそこそと囁いた。竜馬は、耳の後ろを掻いて、ぶっきら棒に言う。","f":"ryoma"},{"t":"d","s":"「褒めるな。ついてこい」","f":"ryoma"},{"t":"d","s":"「「「はい！」」」","f":"ryoma"},{"t":"n","s":"けれど、竜馬の頭の片隅は、ここにはなかった。","f":"ryoma"},{"t":"i","s":"（……耀平のクラス。一番端だったな）","f":"ryoma"},{"t":"n","s":"校舎のいちばん端にある、E組。襲撃の最初の波が引き寄せられるのは、いちばん外側、つまり、そこだ。","f":"ryoma"},{"t":"i","s":"（あいつ、手を抜くって言ってた）","f":"ryoma"},{"t":"i","s":"（自分を守るためでも、守らないで、抜くのか）","f":"ryoma"},{"t":"n","s":"竜馬の拳が、ぶるっと震えた。","f":"ryoma"},{"t":"d","s":"「……おい。ここは任せた」","f":"ryoma"},{"t":"d","s":"「えっ、竜馬はどこ行くの！」","f":"ryoma"},{"t":"d","s":"「ちょっと、端を見てくる」","f":"ryoma"},{"t":"d","s":"「危ないよ！　先生が——」","f":"ryoma"},{"t":"d","s":"「先生は、竜馬のクラスをなめてるのか？」","f":"ryoma"},{"t":"n","s":"A組の担任が、ぶっと吹き出した。","f":"ryoma"},{"t":"d","s":"「……行け、竜馬。ここは、俺たちでどうにかする」","f":"ryoma"},{"t":"d","s":"「わりぃ。すぐ戻る」","f":"ryoma"},{"t":"n","s":"竜馬は、窓を蹴り破って、走り出した。","f":"ryoma"},{"t":"n","s":"黒い空の下。赤い炎を引き連れて、竜馬は、校舎の端を目指した。","f":"ryoma"}]},{"key":"17-3","title":"上級生たち","bg":"bg_gate","dark":true,"mood":"battle","bgm":"battle1","cast":["ren"],"lines":[{"t":"n","s":"一方、校門前。"},{"t":"d","s":"「……数が、多いな」"},{"t":"n","s":"黄金色の髪をした長身の青年が、腹の底から笑った。獅子堂豪。三年生で、生徒会の副会長を務める男だ。","f":"ren","m":"happy"},{"t":"d","s":"「でも、面白いじゃないか。会長が留守の日を狙ってくるとは」","f":"ren"},{"t":"d","s":"「笑っている場合じゃありません、豪先輩」","f":"ren"},{"t":"d","s":"「紬は、相変わらず真面目だな」","f":"ren"},{"t":"n","s":"獅子堂の隣で、静かな目の少女が小さく首を傾げた。水無月紬。彼女は、落ち着いた手つきで、新入生たちに避難の指示を出している。","f":"ren"},{"t":"d","s":"「獅子堂さん、前をお願いします。朱雀院さんと荒神さんは左。金子くんは、新入生の避難誘導を」","f":"ren"},{"t":"d","s":"「了解です、水無月さん」","f":"ren"},{"t":"d","s":"「真面目ではありません。最小限です」","f":"ren"},{"t":"n","s":"紬は、浅く息を吸って、手を上げた。","f":"ren"},{"t":"n","s":"黒い影の兵が、校庭に雪崩れ込んでくる。獅子堂は、一歩、前に出た。","f":"ren"},{"t":"d","s":"「さて。会長の留守に、学園を汚されて、黙っているわけにはいかないでしょう」","f":"ren"},{"t":"n","s":"獅子堂の拳から、金色の光が吐き出された。","f":"ren"},{"t":"n","s":"校門の前で、影の兵が、一度に吹き飛んだ。","f":"ren","fx":"shake"},{"t":"d","s":"「すげぇ……」","f":"ren"},{"t":"d","s":"「副会長、かっこいいっ！」","f":"ren"},{"t":"d","s":"「慌てて動くと隙が出ます……隊列を崩さないでください」","f":"ren"},{"t":"n","s":"紬の声が、淀みなく届く。","f":"ren"},{"t":"n","s":"学園の上級生は、訓練されていた。この日を想定したわけではなかった。けれど、何かが起こることを、ずっと想定していた。","f":"ren"},{"t":"n","s":"その後ろで、荒神猛と金子守が、正面と側面を押さえている。朱雀院灯の姿も、あちこちに見える。","f":"ren"},{"t":"n","s":"学園の、見えない守りは、この日、確かに機能していた。","f":"ren"},{"t":"n","s":"この正面の混戦は、ほとんど突破されなかった。でも、影の波は、止まらない。","f":"ren"},{"t":"d","s":"「……紬。これ、どこかを狙ってるな」","f":"ren"},{"t":"d","s":"「はい。正面の数は囮です。本命は、別です」","f":"ren"},{"t":"d","s":"「どこだ」","f":"ren"},{"t":"d","s":"「校舎の東端。——E組のあたりです」","f":"ren"},{"t":"n","s":"獅子堂の笑顔が、消えた。","f":"ren"},{"t":"d","s":"「俺は行く」","f":"ren"},{"t":"d","s":"「豪先輩」","f":"ren"},{"t":"d","s":"「子供達が、狙われてる。紬、ここを任せる」","f":"ren"},{"t":"d","s":"「はい。行ってください」","f":"ren"},{"t":"n","s":"獅子堂は、地を蹴った。金色の光が、校庭を切り裂く。","f":"ren"}]},{"key":"17-4","title":"廊下で","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense1","cast":["ryoma","noa","yohei"],"lines":[{"t":"n","s":"乃亜と竜馬が、E組の廊下で鉢合わせしたのは、ほとんど同じ時刻だった。","f":"noa"},{"t":"d","s":"「竜馬！」","f":"noa"},{"t":"d","s":"「……乃亜。おまえもか」","f":"noa"},{"t":"d","s":"「耀平を、見に来た。あいつ、最下位のクラスで、一番端で」","f":"noa"},{"t":"d","s":"「同じことを、考えてた」","f":"noa"},{"t":"n","s":"二人は、一瞬だけ目を合わせた。ここに来るまでに、二人とも、同じ顔で、同じ方向を見ていた。","f":"noa"},{"t":"n","s":"その時、廊下の奥で、重い音がした。","f":"noa"},{"t":"n","s":"ど、ん。","f":"noa"},{"t":"n","s":"壁が、崩れる音。それに続いて、甘い女の声が、廊下に響いた。","f":"noa"},{"t":"d","s":"「……色のついた花を、回収しに来た」","f":"noa"},{"t":"n","s":"竜馬と乃亜の足が、同時に止まった。","f":"ryoma"},{"t":"d","s":"「……色のついた花。って」","f":"ryoma"},{"t":"d","s":"「耀平のことだ」","f":"ryoma"},{"t":"d","s":"「知ってるのか、竜馬」","f":"ryoma"},{"t":"d","s":"「……あいつの、あの桜の色を、見たことがある。肝試しの夜、ヤツを追いかけたときに」","f":"ryoma"},{"t":"n","s":"竜馬は、苦い顔で、唇を噛んだ。","f":"ryoma"},{"t":"n","s":"乃亜は、静かに息を吸った。この人も、同じことに気づいていたのか。","f":"noa"},{"t":"d","s":"「竜馬。このこと、だれにも」","f":"noa"},{"t":"d","s":"「言わねえよ。言うわけねえ」","f":"noa"},{"t":"d","s":"「……うん。ありがと」","f":"noa"},{"t":"d","s":"「礼なんて言うな。ただ——」","f":"noa"},{"t":"n","s":"竜馬は、拳を握り直した。","f":"ryoma"},{"t":"d","s":"「——行くぞ。あいつを、一人にするな」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"n","s":"二人は、同時に走り出した。","f":"ryoma"},{"t":"n","s":"廊下の奥。崩れた壁の向こうで、さらに重い空気が、渦を巻いていた。","f":"ryoma"}]}]},{"n":18,"title":"実力がバレる","sub":"高校・1年初夏","era":"high","lead":"守るために抜いた刀は、もう鞘には戻らない。耀平の秘密は、この日、いくつもの目に触れた。","scenes":[{"key":"18-1","title":"色のついた花","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle2","cast":["yohei","ryoma","hotaru"],"lines":[{"t":"n","s":"廊下の空気が、甘く、重く沈んでいた。"},{"t":"n","s":"蛍は、崩れた壁の欠片をつま先でよけながら、ゆっくりと歩いてくる。その周りを、紫の光の粒が、ふわふわと漂っていた。","f":"hotaru"},{"t":"n","s":"蛍——いや、違う。よく見ると、それは光る羽を持った、小さな虫だった。虫が触れた床の板が、じゅっ、と小さな音を立てて黒く溶ける。","f":"hotaru"},{"t":"d","s":"「色のついた花。あなたね」","f":"hotaru"},{"t":"d","s":"「……何のことですか」","f":"hotaru"},{"t":"d","s":"「とぼけないで。さっきの桜、この国では、もう誰も咲かせられないはずの色よ」","f":"hotaru"},{"t":"n","s":"蛍の視線は、耀平の木刀に注がれていた。","f":"hotaru"},{"t":"d","s":"「上からの命令でね。大人しく来てくれたら、ほかの子には手を出さないわ」","f":"hotaru"},{"t":"d","s":"「断ります」","f":"hotaru"},{"t":"d","s":"「そう。残念」","f":"hotaru"},{"t":"n","s":"少しも残念そうではない顔で、蛍は指を鳴らした。次の瞬間、紫の光が、廊下いっぱいに弾けた。","f":"hotaru"},{"t":"d","s":"「耀平、下がれ！」","f":"hotaru"},{"t":"n","s":"壁際から飛び出した赤い炎が、光の群れを真横から薙いだ。竜馬だった。その後ろから、乃亜も駆けてくる。","f":"ryoma"},{"t":"d","s":"「竜馬！　乃亜！」","f":"ryoma"},{"t":"d","s":"「ひとりで出るな、馬鹿」","f":"ryoma"},{"t":"d","s":"「ひとりじゃないよ。後ろに、みんなが」","f":"ryoma"},{"t":"d","s":"「そのみんなが危ねえって話だ！」","f":"ryoma"},{"t":"n","s":"怒鳴りながらも、竜馬は耀平の隣に立った。肩が、触れるほど近い。","f":"ryoma","m":"anger"},{"t":"d","s":"「手を抜くな。今日だけは」","f":"ryoma"},{"t":"d","s":"「……でも」","f":"ryoma"},{"t":"d","s":"「約束しただろ。決着は、もっと先だ。こんなところで、お前が潰れんのは許さねえ」","f":"ryoma"},{"t":"n","s":"竜馬の横顔は、怒っているようで、少し泣きそうにも見えた。","f":"ryoma","m":"sad"},{"t":"d","s":"「……分かった」","f":"ryoma"},{"t":"n","s":"耀平は、木刀を構え直した。","f":"yohei"}]},{"key":"18-2","title":"千毒万蠱","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle2","cast":["ryoma","hotaru","noa"],"lines":[{"t":"d","s":"「千毒万蠱」"},{"t":"n","s":"蛍が囁くと、光の粒が、一斉に羽を広げた。何百、何千という紫の蛍が、廊下の天井を埋め尽くす。","f":"hotaru"},{"t":"d","s":"「紅蓮爆炎！」","f":"hotaru"},{"t":"n","s":"竜馬の炎が、群れを焼いた。けれど、焼けた虫の粉が、紫の煙になって漂う。それを吸った竜馬が、激しく咳き込んだ。","f":"ryoma"},{"t":"d","s":"「げほっ……なんだ、これ」","f":"ryoma"},{"t":"d","s":"「毒よ。燃やせば燃やすほど、広がるの。かわいいでしょ」","f":"ryoma"},{"t":"d","s":"「竜馬、息止めて！」","f":"ryoma"},{"t":"n","s":"乃亜の声と同時に、薄い水の膜が、竜馬の顔の前を走った。紫の煙が、水に絡め取られて床に落ちる。","f":"noa"},{"t":"d","s":"「……今の、乃亜か」","f":"noa"},{"t":"d","s":"「偏っただけ。いいから前を見て」","f":"noa"},{"t":"d","s":"「偏っただけで、水の膜は張れねえだろ」","f":"noa"},{"t":"d","s":"「今は黙って戦って」","f":"noa"},{"t":"d","s":"「あら。水の子もいるのね。いいわね、この学校」","f":"noa"},{"t":"n","s":"蛍は、楽しそうに首を傾げた。紫の群れが、また一段、濃くなる。","f":"hotaru"},{"t":"n","s":"その時、金色の光が、廊下を横切った。","f":"hotaru"},{"t":"d","s":"「そこまでだ」","f":"hotaru"},{"t":"n","s":"獅子堂豪の拳が、群れのど真ん中を撃ち抜いた。虫たちが、一瞬だけ散る。","f":"hotaru"},{"t":"d","s":"「副会長！」","f":"hotaru"},{"t":"d","s":"「遅れてすまない。お前たち、よく持ちこたえた」","f":"hotaru"},{"t":"n","s":"獅子堂は笑った。けれど、次の一撃を構えようとして、その腕が、だらりと下がった。","f":"hotaru","m":"happy"},{"t":"d","s":"「……腕が、痺れる」","f":"hotaru"},{"t":"d","s":"「当然よ。わたしの子たちは、触れるだけで効くの。殴るなんて、いちばんやっちゃだめ」","f":"hotaru"},{"t":"n","s":"獅子堂が、片膝をついた。廊下の窓が、紫の光に照らされて、まるで夜のように暗く見えた。","f":"hotaru"}]},{"key":"18-3","title":"桜と毒","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle2","cast":["yohei","hotaru","ren"],"lines":[{"t":"n","s":"廊下の窓の向こう、割れたガラスの縁に、ひとつの影が立った。"},{"t":"n","s":"紺色のブレザー。濡れたような黒髪。右手に、一本の刀。"},{"t":"d","s":"「……遅れたな」"},{"t":"n","s":"九条蓮だった。葬儀の黒い喪章を、まだ胸につけたままだった。","f":"ren"},{"t":"d","s":"「会長！」","f":"ren"},{"t":"d","s":"「豪、下がれ。毒だ。動けば回る」","f":"ren"},{"t":"n","s":"蓮は、窓枠から静かに飛び降りた。刀が一閃し、獅子堂の周りの群れだけが、きれいに断ち割られる。","f":"ren","fx":"flash"},{"t":"d","s":"「剣聖の葬儀の日を選ぶとは。礼儀を知らん連中だ」","f":"ren"},{"t":"d","s":"「礼儀？　ふふ。あのおじいさんは、もう用済みだったのよ」","f":"ren"},{"t":"n","s":"蓮の肩が、ぴくりと動いた。けれど、刀は動かなかった。","f":"ren"},{"t":"d","s":"「……斬っても斬っても、湧くか」","f":"ren"},{"t":"d","s":"「そう。わたしは広いところを、まとめて消すのが仕事なの。一人ずつ斬る剣士とは、相性がいいのよね。わたしにとって」","f":"ren"},{"t":"n","s":"蓮は、ちらりと耀平を見た。","f":"ren"},{"t":"d","s":"「金井」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「虫は、私と仲間で払う。お前は、本体だけを見ろ」","f":"ren"},{"t":"d","s":"「……おれが、ですか」","f":"ren"},{"t":"d","s":"「お前の桜なら、触れずに斬れる。違うか」","f":"ren"},{"t":"n","s":"耀平は、息を呑んだ。","f":"yohei","m":"surprise"},{"t":"i","s":"（触れずに）","f":"yohei"},{"t":"n","s":"桜の花びらに触れたものに、身体が勝手に応える。幼い頃から、ずっとそうだった。それなら——。","f":"yohei"},{"t":"d","s":"「やってみます」","f":"yohei"},{"t":"n","s":"耀平は、目を閉じた。","f":"yohei"},{"t":"n","s":"百花繚乱。","f":"yohei","fx":"bloom"},{"t":"n","s":"桜の花びらが、廊下いっぱいに咲いた。教室で見せた薄い花びらとは違う。濃く、深く、渦を巻く桜の嵐だった。","f":"yohei"},{"t":"n","s":"紫の蛍と、薄紅の花びらが、廊下の中で混ざり合う。","f":"yohei"},{"t":"n","s":"虫が、花びらに触れる。そのたびに、耀平の身体が、勝手に半歩ずれる。木刀が、勝手に向きを変える。","f":"yohei"},{"t":"n","s":"一歩。また一歩。","f":"yohei"},{"t":"n","s":"毒の群れの真ん中を、耀平は、一度も触れられずに歩いていった。","f":"yohei"},{"t":"d","s":"「……当たらない？」","f":"yohei"},{"t":"n","s":"蛍の笑みが、初めて、消えた。","f":"hotaru"},{"t":"d","s":"「どうして。わたしの子たちが、一匹も」","f":"hotaru"},{"t":"d","s":"「花びらが、教えてくれるんです。どこから来るか」","f":"hotaru"},{"t":"n","s":"蛍が、両手を広げた。紫の群れが、壁のように耀平の前に積み重なる。","f":"hotaru"},{"t":"d","s":"「千毒万蠱——蠱壁！」","f":"hotaru"},{"t":"n","s":"耀平は、止まらなかった。木刀に、花びらがまとわりつく。桜色の刃が、紫の壁を、真っ二つに割った。","f":"yohei"},{"t":"n","s":"その向こうに、蛍の、驚いた顔があった。","f":"hotaru"},{"t":"n","s":"木刀が、蛍の脇腹を打った。","f":"hotaru"},{"t":"d","s":"「——っ、あ」","f":"hotaru"},{"t":"n","s":"蛍の膝が、崩れた。紫の光が、ひとつ、またひとつと消えていく。廊下に、本物の窓の光が戻ってきた。","f":"hotaru"},{"t":"n","s":"耀平は、木刀の先を、蛍の喉元に向けた。それ以上は、振らなかった。","f":"yohei"},{"t":"d","s":"「……もう、やめてください」","f":"yohei"},{"t":"n","s":"蛍は、床に手をついたまま、顔を上げた。","f":"hotaru"},{"t":"n","s":"薄紅の花びらが、ひらり、と彼女の髪に落ちた。逆光の中に、桜をまとった少年が立っていた。","f":"hotaru"},{"t":"i","s":"（……なに、これ）","f":"hotaru"},{"t":"cg","v":"cg_hotaru_kirei"},{"t":"n","s":"蛍の頬が、ゆっくりと、赤く染まった。","f":"hotaru","m":"blush"},{"t":"d","s":"「……きれい」","f":"hotaru"},{"t":"d","s":"「え」","f":"hotaru"}]},{"key":"18-4","title":"捕縛","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense2","cast":["yohei","hotaru","noa"],"lines":[{"t":"d","s":"「ねえ、あなた。名前は」"},{"t":"d","s":"「……え？」"},{"t":"d","s":"「名前。教えて」"},{"t":"d","s":"「……金井、耀平です」"},{"t":"d","s":"「耀平くん」"},{"t":"n","s":"蛍は、その名前を、舌の上で転がすように繰り返した。それから、なぜか、とても嬉しそうに笑った。","f":"hotaru","m":"happy"},{"t":"d","s":"「ふふ。負けちゃった」","f":"hotaru"},{"t":"d","s":"「……何なの、この人」","f":"hotaru"},{"t":"n","s":"乃亜が、低い声で呟いた。竜馬は、咳き込みながら、ぽかんと口を開けている。","f":"noa"},{"t":"n","s":"蓮だけが、刀を下ろさなかった。","f":"ren"},{"t":"i","s":"（……桜。この色は）","f":"ren"},{"t":"n","s":"中学の入学式の日に、見た気がした。肝試しの夜に、遠くで感じた気がした。ずっと胸の奥で引っかかっていたものが、ようやく、形を結ぶ。","f":"ren"},{"t":"i","s":"（やはり、お前だったのか）","f":"ren"},{"t":"n","s":"言葉にはしなかった。ただ、蓮の口元が、ほんのわずかに、緩んだ。","f":"ren"},{"t":"n","s":"その時、窓の外の空に、黒い亀裂が走った。校庭の向こうで、天冠の幹部たちの気配が、一斉に引いていく。","f":"ren"},{"t":"d","s":"「……帰還命令。あーあ」","f":"ren"},{"t":"n","s":"蛍は、空を見上げて、小さく肩をすくめた。","f":"hotaru"},{"t":"d","s":"「わたし、もう動けないし。それに」","f":"hotaru"},{"t":"n","s":"彼女の視線が、耀平に戻る。","f":"yohei"},{"t":"d","s":"「もう少し、見ていたいかも」","f":"yohei"},{"t":"n","s":"その視線が、ふと、廊下の奥に流れた。E組の教室の入口に、柚月が立っていた。顔は青白く、手のひらには、氷の欠片が光っている。","f":"yuzuki"},{"t":"d","s":"「……あら。もう一輪、見つけた」","f":"yuzuki"},{"t":"d","s":"「え」","f":"yuzuki"},{"t":"d","s":"「ううん。こっちの話」","f":"yuzuki"},{"t":"d","s":"「そこまでにしておきなさい」","f":"yuzuki"},{"t":"n","s":"穏やかな声がした。いつの間にか、廊下の端に、白髪まじりの紳士が立っていた。学園長だった。","f":"principal"},{"t":"n","s":"学園長が、蛍の肩にそっと手を置く。それだけで、彼女の周りに残っていた紫の光が、すべて消えた。","f":"principal"},{"t":"d","s":"「天冠第六席、紫苑蛍。身柄は、学園が預かる」","f":"principal"},{"t":"d","s":"「はあい」","f":"principal"},{"t":"n","s":"蛍は、抵抗しなかった。連れて行かれる途中で、彼女は一度だけ、振り返った。","f":"hotaru"},{"t":"d","s":"「また会いに来てね、耀平くん。……ううん。わたしが、会いに行く」","f":"hotaru"},{"t":"d","s":"「……は？」","f":"hotaru"},{"t":"n","s":"乃亜の声が、廊下に冷たく響いた。教室の入口で、柚月が、ほんの少しだけ眉を寄せた。","f":"noa"},{"t":"n","s":"天井の穴から、雲の切れ間の光が差し込んできた。","f":"noa"},{"t":"n","s":"静寂が、廊下を満たした。","f":"noa"},{"t":"d","s":"「……終わった、のか」","f":"noa"},{"t":"d","s":"「撤退したようだ。気を緩めるな。まだ校内に残党がいるかもしれん」","f":"noa"},{"t":"n","s":"蓮は、刀を納めた。それから、ゆっくりと耀平を振り返った。","f":"ren"},{"t":"d","s":"「金井」","f":"ren"},{"t":"d","s":"「は、はい」","f":"ren"},{"t":"d","s":"「あとで、話を聞かせてもらう。逃げるな」","f":"ren"},{"t":"d","s":"「……はい」","f":"ren"},{"t":"n","s":"耀平は、小さく頷いた。","f":"yohei"},{"t":"n","s":"振り返ると、E組の廊下の入口に、クラスメイトたちが集まっていた。誰も何も言わない。ただ、全員が、耀平を見ていた。","f":"yohei"},{"t":"d","s":"「あの」","f":"yohei"},{"t":"d","s":"「金井」","f":"yohei"},{"t":"d","s":"「は、はい」","f":"yohei"},{"t":"d","s":"「お前、ポケットに桜の花びら、どんだけ入れてたんだ」","f":"yohei"},{"t":"n","s":"誰かがぼそりと言った。","f":"yohei"},{"t":"n","s":"一瞬の沈黙のあと、教室中が、どっと笑った。","f":"yohei","m":"happy"},{"t":"d","s":"「いや、もう無理があるって」","f":"yohei"},{"t":"d","s":"「ごめん……」","f":"yohei"},{"t":"d","s":"「謝んなよ。助けてもらったんだ」","f":"yohei"},{"t":"d","s":"「……ありがと、金井」","f":"yohei"},{"t":"n","s":"笑いながら、目の端に涙を浮かべている生徒もいた。耀平は、どう返していいか分からず、ただ頭を掻いた。","f":"yohei","m":"sad"},{"t":"n","s":"隣で、乃亜が小さく息をついた。","f":"noa"},{"t":"d","s":"「ほんと、あんたって」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝らなくていい。……でも、もう隠せないよ」","f":"noa"},{"t":"d","s":"「うん。分かってる」","f":"noa"},{"t":"n","s":"竜馬は、少し離れたところで、腕を組んで壁にもたれていた。何も言わない。けれど、その口元は、ほんの少しだけ緩んでいた。","f":"ryoma"}]},{"key":"18-5","title":"学園長室","bg":"bg_principal","dark":false,"mood":"daily","bgm":"daily3","cast":["principal","ren","yohei"],"lines":[{"t":"n","s":"翌日。耀平は、学園長室に呼ばれた。","f":"yohei"},{"t":"n","s":"部屋には、学園長と、E組の担任と、蓮がいた。窓の外には、雨上がりの空が広がっている。","f":"principal"},{"t":"d","s":"「座りなさい、金井くん」","f":"principal"},{"t":"d","s":"「はい」","f":"principal"},{"t":"n","s":"学園長は、穏やかな目をした、白髪まじりの紳士だった。仕立てのいい黒いスーツの襟を、ゆっくりと正している。","f":"principal"},{"t":"d","s":"「昨日は、君たちに助けられた。礼を言う」","f":"principal"},{"t":"d","s":"「いえ。おれは、何も」","f":"principal"},{"t":"d","s":"「謙遜することはない。君の桜は、報告で聞いている」","f":"principal"},{"t":"d","s":"「それと、第六席の件だ。彼女の身柄は、学園の地下で預かっている。……もっとも」","f":"principal"},{"t":"n","s":"学園長は、困ったように顎を撫でた。","f":"principal"},{"t":"d","s":"「取り調べには、何ひとつ答えん。そのくせ、君の名前ばかり口にしているそうだ」","f":"principal"},{"t":"d","s":"「……え」","f":"principal"},{"t":"d","s":"「『耀平くんに会わせてくれたら、考えてあげる』、だそうだ」","f":"principal"},{"t":"n","s":"蓮が、小さく咳払いをした。耀平は、どんな顔をすればいいのか分からなかった。","f":"ren"},{"t":"n","s":"学園長は、静かに言葉を続けた。","f":"principal"},{"t":"d","s":"「単刀直入に聞こう。君は、あれを、いつから使えるようになった」","f":"principal"},{"t":"d","s":"「……中学一年の、修学旅行の夜からです」","f":"principal"},{"t":"d","s":"「その前は？」","f":"principal"},{"t":"d","s":"「ありません。一度も」","f":"principal"},{"t":"d","s":"「そうか」","f":"principal"},{"t":"n","s":"学園長は、蓮に視線を向けた。蓮が、静かに頷く。","f":"principal"},{"t":"d","s":"「会長。彼は、規格外と見て間違いないかね」","f":"principal"},{"t":"d","s":"「はい。私が見る限り、間違いありません」","f":"principal"},{"t":"n","s":"担任が、わずかに眉を寄せた。","f":"principal"},{"t":"d","s":"「……やはり、そうでしたか」","f":"principal"},{"t":"d","s":"「先生は、知っていたんですか」","f":"principal"},{"t":"d","s":"「疑ってはいた。実技テストで、君は明らかに手を抜いていた。評価を最下位に留めたのは、私の判断だ」","f":"principal"},{"t":"d","s":"「え」","f":"principal"},{"t":"d","s":"「規格外は、天冠に狙われる。目立たないほうが、守りやすい」","f":"principal"},{"t":"n","s":"担任は、いつもの淡々とした声で言った。けれど、その目は、わずかに柔らかかった。","f":"principal"},{"t":"d","s":"「しかし、昨日の件で、君の力は、校内に知れ渡った。もう、隠し通すことは難しい」","f":"principal"},{"t":"d","s":"「……はい」","f":"principal"},{"t":"d","s":"「だから、君に選んでほしい」","f":"principal"},{"t":"n","s":"学園長が、穏やかに言った。","f":"principal"},{"t":"d","s":"「力を隠して、E組に留まるか。それとも、堂々と力を磨くか。どちらを選んでも、学園は君を守る」","f":"principal"},{"t":"n","s":"耀平は、少しだけ考えた。","f":"yohei"},{"t":"d","s":"「……E組に、いたいです」","f":"yohei"},{"t":"d","s":"「理由は？」","f":"yohei"},{"t":"d","s":"「あのクラスの人たちが、好きだから。それに、おれは、強くなりたいけど、目立ちたいわけじゃない」","f":"yohei"},{"t":"n","s":"学園長は、にこりと笑った。","f":"principal","m":"happy"},{"t":"d","s":"「よろしい。ならば、E組のままで構わん。ただし、授業とは別に、蓮くんと鍛錬の時間を持ちなさい」","f":"principal"},{"t":"d","s":"「会長と、ですか」","f":"principal"},{"t":"d","s":"「私でよければ、喜んで」","f":"principal"},{"t":"n","s":"蓮が、静かに微笑んだ。","f":"ren","m":"happy"},{"t":"d","s":"「金井。お前の桜は、まだ蕾だ。咲ききるには、時間がかかる」","f":"ren"},{"t":"d","s":"「……はい」","f":"ren"},{"t":"d","s":"「だが、咲いた時には、誰より綺麗な花になる。私が、保証する」","f":"ren"},{"t":"n","s":"耀平の胸に、温かいものが広がった。","f":"yohei"}]},{"key":"18-x5","title":"放課後の校門","bg":"bg_gate","dark":false,"mood":"daily","bgm":"daily4","cast":["yohei","noa","yuzuki"],"lines":[{"t":"cg","v":"cg_rival_tug"},{"t":"n","s":"実力がバレた翌週。放課後の校門で、耀平は、両腕を同時に掴まれていた。","f":"yohei"},{"t":"d","s":"「耀平。今日は、寮でご飯作るから。食べに来て」","f":"yohei"},{"t":"d","s":"「金井くん。今日は、会長との鍛錬の前に、練習に付き合ってくれる約束です」","f":"yohei"},{"t":"n","s":"左に乃亜。右に柚月。二人とも、静かな顔で、少しずつ腕を引っ張っている。","f":"noa"},{"t":"d","s":"「あの、両方、行けるかも」","f":"noa"},{"t":"d","s":"「時間、かぶってる」","f":"noa"},{"t":"d","s":"「かぶっていますね」","f":"noa"},{"t":"n","s":"遠巻きに見ていたE組のクラスメイトたちが、腹を抱えて笑っていた。","f":"noa"},{"t":"d","s":"「金井、規格外なのは剣だけじゃなかったな！」","f":"noa"},{"t":"d","s":"「両手に花ってやつだ！」","f":"noa"},{"t":"d","s":"「花びらだけに！」","f":"noa"},{"t":"d","s":"「うまくないから！」","f":"noa"},{"t":"n","s":"耀平の叫びが、夕方の校門に響いた。","f":"yohei"}],"extra":true},{"key":"18-6","title":"墓前、ふたたび","bg":"bg_grave","dark":true,"mood":"night","bgm":"night1","cast":["jin","yohei"],"lines":[{"t":"n","s":"数日後の日曜日。耀平は、剣聖の墓を訪れた。","f":"yohei"},{"t":"n","s":"町外れの丘の上。祖父の墓とは別の、広い霊園の一角に、その墓はあった。真新しい墓石の前には、花束と供物が、山のように積まれている。","f":"yohei"},{"t":"i","s":"（葬儀には、行けなかったから）","f":"yohei"},{"t":"n","s":"耀平は、白い花を一輪、そっと供えた。手を合わせて、目を閉じる。","f":"yohei"},{"t":"d","s":"「……花は、嫌いだと言ったはずだ」","f":"yohei"},{"t":"n","s":"背後から、聞き覚えのある声がした。","f":"yohei"},{"t":"n","s":"振り向くと、迅が立っていた。黒い髪。鋭い目。今日は、腰に一本の刀を差している。","f":"jin"},{"t":"d","s":"「迅さん」","f":"jin"},{"t":"d","s":"「花も線香も、嫌いだ。死んだ人間に、何を渡したところで、返事は来ない」","f":"jin"},{"t":"d","s":"「でも」","f":"jin"},{"t":"d","s":"「でも、何だ」","f":"jin"},{"t":"d","s":"「……来たかったんです。この人に、会ったことはないけど、祖父の知り合いだったかもしれないから」","f":"jin"},{"t":"n","s":"迅は、鼻で笑った。","f":"jin","m":"happy"},{"t":"d","s":"「祖父、か。……お前の祖父は、誰だ」","f":"jin"},{"t":"d","s":"「金井という、ただの老人です。刀のことは、何も知らない人でした」","f":"jin"},{"t":"d","s":"「金井。……そうか」","f":"jin"},{"t":"n","s":"迅は、墓石に目を向けた。しばらく黙って、それから、ぼそりと言った。","f":"jin"},{"t":"d","s":"「ここに眠ってるのは、俺の親父だ」","f":"jin"},{"t":"n","s":"耀平は、息を呑んだ。","f":"yohei","m":"surprise"},{"t":"d","s":"「剣聖、が」","f":"yohei"},{"t":"d","s":"「ああ。世間では、立派な剣士だったらしいな。俺にとっては、ただの無口な親父だったが」","f":"yohei"},{"t":"d","s":"「葬儀には」","f":"yohei"},{"t":"d","s":"「出てない。出られるか、あんなもの。群がる連中の顔が、全員、嘘に見えた」","f":"yohei"},{"t":"n","s":"迅の拳が、ぎゅっと握られた。","f":"jin"},{"t":"d","s":"「親父は、病気で死んだんじゃない」","f":"jin"},{"t":"d","s":"「え」","f":"jin"},{"t":"d","s":"「……いや。まだ、確証はない。だが、誰かに、殺された」","f":"jin"},{"t":"n","s":"風が、墓地を吹き抜けた。耀平は、言葉が出なかった。","f":"yohei"},{"t":"d","s":"「お前、学園の生徒だろう。昨日の桜の噂は、聞いた」","f":"yohei"},{"t":"d","s":"「どうして」","f":"yohei"},{"t":"d","s":"「耳は、早いほうだ。天冠とやり合って、生き残った一年がいる、とな」","f":"yohei"},{"t":"n","s":"迅は、耀平の腰の刃引き刀に目をやった。","f":"jin"},{"t":"d","s":"「その刀。まだ、本物じゃないな」","f":"jin"},{"t":"d","s":"「はい。練習刀です」","f":"jin"},{"t":"d","s":"「……いずれ、本物を持て。そして、そのとき」","f":"jin"},{"t":"n","s":"迅が、刀の柄に手をかけた。","f":"jin"},{"t":"d","s":"「手を抜くなと言ったはずだ。俺は、本気のお前と、やりたい」","f":"jin"},{"t":"d","s":"「迅さん」","f":"jin"},{"t":"d","s":"「待ってる。それまで、死ぬなよ」","f":"jin"},{"t":"n","s":"迅は、それだけ言うと、背を向けて歩き出した。丘を下りる背中は、やっぱり、どこか孤独に見えた。","f":"jin"},{"t":"n","s":"耀平は、白い花の前で、もう一度、手を合わせた。","f":"yohei"},{"t":"i","s":"（あの人の父を、誰かが）","f":"yohei"},{"t":"n","s":"鞘の中で、刃が、ことり、と鳴った。耀平は、その音を聞きながら、静かに拳を握った。","f":"yohei"}]}]},{"n":19,"title":"二度目の襲撃・E組","sub":"高校・1年夏〜秋","era":"high","lead":"夏が過ぎ、二学期の朝。結界の切れる音が、校舎の端から響いた。","scenes":[{"key":"19-1","title":"夏のあいだ","bg":"bg_classroom_e","dark":false,"mood":"soft","bgm":"soft4","cast":["noa","ren","yohei"],"lines":[{"t":"n","s":"夏休みの学園は、蝉の声に満ちていた。"},{"t":"d","s":"「遅い。三秒、遅れた」"},{"t":"d","s":"「すみません！」"},{"t":"d","s":"「謝る暇があるなら、踏み込め」"},{"t":"n","s":"早朝の訓練場。蓮の黒い刀が、耀平の木刀を軽々と弾き飛ばした。耀平は尻もちをついて、空を仰ぐ。","f":"ren"},{"t":"d","s":"「……会長、手加減してますよね」","f":"ren"},{"t":"d","s":"「している。これでも」","f":"ren"},{"t":"d","s":"「これでも」","f":"ren"},{"t":"d","s":"「お前が本気の三割も出していないからだ。私が七割で止めているのは、釣り合いを取るためだ」","f":"ren"},{"t":"n","s":"蓮は、刀を納めて手を差し出した。","f":"ren"},{"t":"d","s":"「桜は、怒りや焦りでは咲ききらない。お前が咲かせたのは、守りたいと願った時だけだ。その感覚を、意図して引き出せ」","f":"ren"},{"t":"d","s":"「意図して、守りたい、と」","f":"ren"},{"t":"d","s":"「難しいことを言っているのは承知している。だが、お前ならできる」","f":"ren"},{"t":"n","s":"耀平は、蓮の手を取って立ち上がった。","f":"yohei"},{"t":"i","s":"（根拠は、勘、なんだろうな）","f":"yohei"},{"t":"n","s":"それでも、この人の言葉は、不思議と胸に残る。","f":"yohei"},{"t":"n","s":"夕方には、乃亜と並んで、寮の屋上で線香花火をした。","f":"noa"},{"t":"d","s":"「ちっちゃいね」","f":"noa"},{"t":"d","s":"「ちっちゃいな」","f":"noa"},{"t":"d","s":"「あんた、さっきから落としてばっかり」","f":"noa"},{"t":"d","s":"「だって、風が」","f":"noa"},{"t":"d","s":"「風のせいにしない」","f":"noa"},{"t":"n","s":"乃亜の花火は、最後までぷっくりと丸い火の玉を保っていた。耀平のは、すぐにぽとりと落ちた。","f":"noa"},{"t":"d","s":"「……ねえ、耀平」","f":"noa"},{"t":"d","s":"「ん」","f":"noa"},{"t":"d","s":"「あの日のこと、もう誰にも聞かれなかった？　わたしのこと」","f":"noa"},{"t":"d","s":"「聞かれなかった。竜馬も、言ってない」","f":"noa"},{"t":"d","s":"「そっか」","f":"noa"},{"t":"n","s":"乃亜は、最後の花火を見つめたまま、小さく言った。","f":"noa"},{"t":"d","s":"「わたしね、ずっと怖かったの。規格外って言われること。自分が、ほかの人と違うって決まってしまうこと」","f":"noa"},{"t":"d","s":"「……うん」","f":"noa"},{"t":"d","s":"「でも、あんたが隠さなくなったのを見て、ちょっとだけ、いいなって思った」","f":"noa"},{"t":"d","s":"「隠さなくなったわけじゃ、ないけど」","f":"noa"},{"t":"d","s":"「いいの。わたしの話」","f":"noa"},{"t":"n","s":"花火が、ぽとりと落ちて、消えた。","f":"noa"},{"t":"n","s":"暗くなった屋上で、乃亜は静かに笑った。","f":"noa","m":"happy"}]},{"key":"19-2","title":"二学期の朝","bg":"bg_classroom_e","dark":false,"mood":"daily","bgm":"daily1","cast":["yuzuki","ren","yohei"],"lines":[{"t":"n","s":"九月。二学期の初日。"},{"t":"n","s":"教室には、夏の名残の熱気が残っていた。クラスメイトたちは、日焼けした顔で、久しぶりの再会を喜んでいる。"},{"t":"d","s":"「金井、おはよう！」"},{"t":"d","s":"「おはよう」"},{"t":"d","s":"「夏、どうだった？　会長と特訓だって？」"},{"t":"d","s":"「うん。ぼこぼこにされてた」"},{"t":"d","s":"「だろうな」"},{"t":"n","s":"クラスメイトたちが、遠慮なく笑う。あの襲撃の日から、E組の空気は変わった。壁は消えて、みんなが耀平に普通に話しかけてくれる。","f":"yohei","m":"happy"},{"t":"n","s":"そして、隣の席には、柚月がいた。","f":"yuzuki"},{"t":"d","s":"「……おはよう」","f":"yuzuki"},{"t":"d","s":"「おはよう、朝霧さん」","f":"yuzuki"},{"t":"d","s":"「夏のあいだ、会長と」","f":"yuzuki"},{"t":"d","s":"「うん。毎朝」","f":"yuzuki"},{"t":"d","s":"「……わたしは、ひとりで」","f":"yuzuki"},{"t":"cg","v":"cg_yuzuki_window"},{"t":"n","s":"柚月は、窓の外を見ていた。夏のあいだに、少しだけ髪が伸びた気がする。","f":"yuzuki"},{"t":"d","s":"「ひとりで、何してたの」","f":"yuzuki"},{"t":"d","s":"「……調べもの。天冠のことを」","f":"yuzuki"},{"t":"d","s":"「わかったこと、ある？」","f":"yuzuki"},{"t":"d","s":"「少しだけ。……あとで、話す。放課後」","f":"yuzuki"},{"t":"d","s":"「うん」","f":"yuzuki"},{"t":"n","s":"柚月の横顔は、いつもより少しだけ、張り詰めて見えた。","f":"yuzuki"},{"t":"n","s":"昼休みを過ぎて、午後の授業が始まったころだった。","f":"yuzuki"},{"t":"d","s":"「……あれ？」","f":"yuzuki"},{"t":"n","s":"窓際の生徒が、小さく声を上げた。","f":"yuzuki"},{"t":"d","s":"「どうした」","f":"yuzuki"},{"t":"d","s":"「いや、結界の光が、さっきまで窓に映ってたのに。消えてる」","f":"yuzuki"},{"t":"n","s":"担任の顔つきが、変わった。","f":"yuzuki"},{"t":"d","s":"「全員、動くな」","f":"yuzuki"},{"t":"n","s":"教室の空気が、凍った。","f":"yuzuki"}]},{"key":"19-x2","title":"袖","bg":"bg_classroom_e","dark":true,"mood":"night","bgm":"night2","cast":["yuzuki","yohei","noa"],"lines":[{"t":"cg","v":"cg_yuzuki_sleeve"},{"t":"n","s":"二学期が始まって数日。夕方の廊下で、耀平は、背中の袖を引かれた。","f":"yohei"},{"t":"n","s":"振り向くと、柚月が、袖の端をつまんだまま、俯いていた。","f":"yuzuki"},{"t":"d","s":"「……朝霧さん？」","f":"yuzuki"},{"t":"d","s":"「最近、ひとりで帰ってる」","f":"yuzuki"},{"t":"d","s":"「え」","f":"yuzuki"},{"t":"d","s":"「乃亜さんとも、竜馬くんとも。会長との鍛錬の後も、すぐいなくなる」","f":"yuzuki"},{"t":"n","s":"耀平は、言葉に詰まった。天冠の目が、自分の周りの人間に向かうのが、怖かった。だから、少しずつ距離を取り始めていた。","f":"yohei"},{"t":"d","s":"「……気のせいだよ」","f":"yohei"},{"t":"d","s":"「嘘」","f":"yohei"},{"t":"n","s":"柚月の指に、少しだけ力がこもった。","f":"yuzuki"},{"t":"d","s":"「顔を見れば、分かるから」","f":"yuzuki"},{"t":"n","s":"夕日が、廊下を橙色に染めていた。柚月は、それ以上何も言わずに、そっと袖を離した。","f":"yuzuki"}],"extra":true},{"key":"19-3","title":"孤立","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["yuzuki","yohei"],"lines":[{"t":"n","s":"がたん、と音がして、教室の電灯が消えた。"},{"t":"n","s":"窓の外は、昼間なのに、薄暗かった。校舎を覆っていた透明な結界が、端から剥がれていくのが見える。"},{"t":"d","s":"「先生、これって」"},{"t":"d","s":"「結界が切られた。しかも、この一角だけ、完全に隔離されている」"},{"t":"n","s":"担任の声は、いつもの淡々としたものだった。けれど、その額には、汗が浮かんでいた。","m":"sweat"},{"t":"d","s":"「連絡がつかない。外の様子も分からない。——全員、聞け」"},{"t":"n","s":"担任は、生徒たちを見回した。"},{"t":"d","s":"「ここは、一度目より危険だ。相手は、周到に準備してきた。私は外に出て、状況を確認する。お前たちは、教室で待機しろ」"},{"t":"d","s":"「先生、置いていくんですか！」"},{"t":"d","s":"「置いていかない。必ず戻る」"},{"t":"n","s":"担任は、扉に手をかけた。そして、振り返らずに言った。"},{"t":"d","s":"「金井、朝霧。もしもの時は、お前たちが頼りだ」"},{"t":"d","s":"「……はい」"},{"t":"d","s":"「……はい」"},{"t":"n","s":"担任が出ていった。"},{"t":"n","s":"数秒の静寂のあと、廊下の向こうから、重い足音がいくつも近づいてきた。"},{"t":"d","s":"「来た！」"},{"t":"d","s":"「窓際から離れろ！」"},{"t":"d","s":"「陣形を作れ！　前衛は——」"},{"t":"n","s":"誰かが叫ぶ。E組の生徒たちが、一斉に動き出した。"},{"t":"n","s":"一度目とは、違っていた。"},{"t":"d","s":"「筋力増強、三体押さえた！」"},{"t":"d","s":"「糸結小縁、足元に！」"},{"t":"d","s":"「俺が止める！　その隙に叩いて！」"},{"t":"n","s":"地味なスキルたちが、驚くほど緻密につながっていく。前に立つ者、後ろから支える者、目印をつける者。誰もが、自分の役目を知っていた。"},{"t":"i","s":"（みんな、夏のあいだに、鍛えてたんだ）"},{"t":"n","s":"耀平は、胸が熱くなるのを感じた。","f":"yohei"},{"t":"d","s":"「金井！　右から来る！」","f":"yohei"},{"t":"d","s":"「分かった！」","f":"yohei"},{"t":"n","s":"木刀を握って、走る。桜の花びらが、影を迎え撃つ。","f":"yohei"},{"t":"n","s":"以前よりも、ずっと細やかに。以前よりも、ずっと自然に。蓮との鍛錬で磨いた感覚が、確かに身体に残っていた。","f":"yohei"},{"t":"d","s":"「いける！　いけるぞ！」","f":"yohei"},{"t":"d","s":"「このまま押し返せ！」","f":"yohei"},{"t":"n","s":"歓声が上がった。","f":"yohei"},{"t":"n","s":"けれど。","f":"yohei"},{"t":"d","s":"「……おかしい」","f":"yohei"},{"t":"n","s":"柚月が、小さく呟いた。","f":"yuzuki"},{"t":"d","s":"「朝霧さん？」","f":"yuzuki"},{"t":"d","s":"「数が、減らない。倒しても、倒しても、同じ数が戻ってくる」","f":"yuzuki"},{"t":"d","s":"「それって」","f":"yuzuki"},{"t":"d","s":"「どこかに、本体がいる。この影を、供給しているものが」","f":"yuzuki"},{"t":"n","s":"柚月の視線が、廊下の突き当たりに向いた。","f":"yuzuki"},{"t":"n","s":"そこに、ひとつの人影が、静かに立っていた。","f":"yuzuki"}]},{"key":"19-4","title":"柚月の告白","bg":"bg_classroom_e","dark":true,"mood":"battle","bgm":"battle1","cast":["yuzuki","yohei","setsuka"],"lines":[{"t":"n","s":"黒いローブ。深く被ったフード。先日の紫の女とは、明らかに違う。もっと小さくて、もっと細い。"},{"t":"n","s":"けれど、その身体から滲み出る空気は、あの女よりも、はるかに重かった。"},{"t":"d","s":"「……見つけた」"},{"t":"n","s":"幼い、少女のような声だった。"},{"t":"n","s":"柚月が、息を呑んだ。","f":"yuzuki","m":"surprise"},{"t":"d","s":"「……あなた、まさか」","f":"yuzuki"},{"t":"d","s":"「久しぶり、お姉ちゃん。ずいぶん探したよ」","f":"yuzuki"},{"t":"n","s":"フードが、静かに落ちた。","f":"yuzuki"},{"t":"n","s":"現れたのは、柚月と同じ、水色の髪をした少女だった。年は、柚月より少し下だろうか。その瞳は、感情の色が薄く、硝子玉のようだった。","f":"yuzuki"},{"t":"d","s":"「……やっぱり、天冠に」","f":"yuzuki"},{"t":"d","s":"「うん。お姉ちゃんが逃げたあと、わたしが残ったの。お姉ちゃんの代わりに」","f":"yuzuki"},{"t":"d","s":"「……ごめん」","f":"yuzuki"},{"t":"d","s":"「謝らなくていい。わたしは、これが役目だから」","f":"yuzuki"},{"t":"n","s":"少女は、淡々と答えた。その淡々とした声が、かえって痛かった。","f":"yuzuki"},{"t":"i","s":"（……妹、なのか）","f":"yuzuki"},{"t":"n","s":"耀平は、息を呑んだ。柚月の肩が、小さく震えている。","f":"yohei","m":"surprise"},{"t":"d","s":"「朝霧さん」","f":"yohei"},{"t":"d","s":"「……ごめんなさい。黙っていて」","f":"yohei"},{"t":"d","s":"「いや」","f":"yohei"},{"t":"d","s":"「わたしは、天冠で作られた、色のついた花の一輪。この子も、そう。……逃げたのは、わたしだけ」","f":"yohei"},{"t":"n","s":"柚月は、拳を握りしめた。","f":"yuzuki"},{"t":"d","s":"「肝試しの夜、あなたを拒絶したのは、天冠の影が、わたしを追ってきていたから。あなたを巻き込みたくなかった」","f":"yuzuki"},{"t":"d","s":"「……そうだったんだ」","f":"yuzuki"},{"t":"d","s":"「でも、結局、巻き込んだ」","f":"yuzuki"},{"t":"d","s":"「巻き込んでないよ」","f":"yuzuki"},{"t":"n","s":"耀平は、柚月の前に出た。","f":"yohei"},{"t":"d","s":"「おれは、おれの意志でここにいる」","f":"yohei"},{"t":"n","s":"少女が、ほんの少しだけ、首を傾げた。","f":"yohei"},{"t":"d","s":"「あなたが、桜の人？　お姉ちゃんが気にかけた、色のついた花」","f":"yohei"},{"t":"d","s":"「……そうなんだと思う」","f":"yohei"},{"t":"d","s":"「ふうん。たしかに、綺麗」","f":"yohei"},{"t":"n","s":"少女の手が、ゆっくりと持ち上がった。廊下の床が、黒く染まっていく。","f":"yohei"},{"t":"d","s":"「わたしの名前は、雪華。お姉ちゃんを、連れて帰りに来た」","f":"yohei"},{"t":"n","s":"教室中の空気が、冷たく張り詰めた。","f":"yohei"},{"t":"d","s":"「連れて帰らせない」","f":"yohei"},{"t":"n","s":"耀平は、木刀を構えた。","f":"yohei"},{"t":"d","s":"「柚月は、うちのクラスの人だ」","f":"yohei"},{"t":"n","s":"雪華と名乗った少女は、初めて、ほんの少しだけ、興味を持ったように耀平を見た。","f":"setsuka"},{"t":"d","s":"「……そう。なら、あなたも一緒に、連れていく」","f":"setsuka"},{"t":"n","s":"黒い影が、一斉に廊下へ溢れ出した。","f":"setsuka"},{"t":"n","s":"教室の中で、E組の生徒たちが、息を呑んで耀平の背中を見つめていた。","f":"yohei","m":"surprise"},{"t":"n","s":"夏の終わりの空は、ますます暗く沈んでいった。","f":"yohei"}]}]},{"n":20,"title":"二度目の襲撃と別れ","sub":"高校編","era":"high","lead":"結界が落ちた学園に、八天の第一席が降り立つ。耀平は初めて、守れなかったものの数を知る。","scenes":[{"key":"20-1","title":"第一席","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["genzo","yohei","setsuka"],"lines":[{"t":"n","s":"影の群れが、ふっと途切れた。"},{"t":"n","s":"雪華の姿も、いつの間にか消えている。","f":"setsuka"},{"t":"d","s":"「……引いた？」","f":"setsuka"},{"t":"d","s":"「いや、違う」","f":"setsuka"},{"t":"n","s":"担任が、窓の外を睨んだ。","f":"setsuka","m":"anger"},{"t":"n","s":"校庭の中央。夏の終わりの空気が、そこだけ重く沈んでいる。草が、地面に押しつけられるように倒れていく。","f":"setsuka"},{"t":"n","s":"黒い外套の男が、ひとり、歩いてきた。","f":"setsuka"},{"t":"n","s":"大柄だった。歳は五十に届くかどうか。顔に表情はなく、ただ歩くたびに、足元の土が数センチずつ沈んだ。","f":"setsuka"},{"t":"d","s":"「八天、第一席。黒鉄玄蔵」","f":"setsuka"},{"t":"d","s":"「……名乗るんだな」","f":"setsuka"},{"t":"d","s":"「死ぬ者には、名乗る主義だ」","f":"setsuka"},{"t":"n","s":"低い声だった。","f":"setsuka"},{"t":"d","s":"「用件は二つ。一つは、朝霧柚月。もう一つは、金井耀平。この二人を、いただいていく」","f":"setsuka"},{"t":"d","s":"「断る」","f":"setsuka"},{"t":"n","s":"耀平が答える前に、担任が前に出た。","f":"yohei"},{"t":"d","s":"「私の生徒だ。どちらも渡さん」","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"n","s":"玄蔵は、軽く片手を下ろした。","f":"genzo"},{"t":"n","s":"それだけで、校舎が軋んだ。","f":"genzo"},{"t":"d","s":"「重圧天墜」","f":"genzo"},{"t":"n","s":"窓ガラスが、一斉に砕けた。担任が膝をつく。蓮が歯を食いしばって耐えている。教室の中では、生徒たちが机に押さえつけられていた。","f":"ren","fx":"shake"},{"t":"i","s":"（重い……体が、床に縫いつけられる……！）","f":"ren"},{"t":"d","s":"「剣聖と同じ技ですよ」","f":"ren"},{"t":"n","s":"玄蔵が、静かに言った。","f":"genzo"},{"t":"d","s":"「あの男も、これで死んだ」","f":"genzo"},{"t":"n","s":"耀平の目の奥で、何かが切れた。","f":"yohei"}]},{"key":"20-2","title":"盾","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["genzo","yohei"],"lines":[{"t":"d","s":"「動けるやつ、動け！」"},{"t":"n","s":"叫んだのは、陽太だった。"},{"t":"n","s":"重圧の中で、誰よりも先に立ち上がっている。足が震えていた。それでも、笑っていた。"},{"t":"d","s":"「……ははっ、重いな、これ。俺のスキル、こういう時、何の役にも立たねえのが悔しいわ」"},{"t":"d","s":"「陽太、無理すんな」"},{"t":"d","s":"「無理すんだよ。今は」"},{"t":"n","s":"陽太は、教室を見渡した。"},{"t":"d","s":"「みんな、笑え。今だけでいい。笑え！」"},{"t":"n","s":"誰かが、引きつった声で笑った。","m":"happy"},{"t":"n","s":"それが、隣に伝わった。そのまた隣に伝わった。"},{"t":"n","s":"陽気伝染。"},{"t":"n","s":"教室に、奇妙な軽さが広がっていく。体にかかる重みは変わらない。それでも、気持ちだけが、ふっと持ち上がった。"},{"t":"d","s":"「……行くぞ、E組」"},{"t":"d","s":"「おう！」"},{"t":"n","s":"巌が、窓を蹴り破って外へ出た。"},{"t":"d","s":"「俺は、動けない」"},{"t":"d","s":"「巌？」"},{"t":"d","s":"「だから、ここに立つ」"},{"t":"n","s":"校庭の真ん中で、巌は両足を地面に突き立てた。頑強不動。動けないスキルのまま、巌は、玄蔵の前に立ちふさがった。","f":"genzo"},{"t":"d","s":"「ほう」","f":"genzo"},{"t":"d","s":"「通さねえ。ここから先には、誰も」","f":"genzo"},{"t":"d","s":"「邪魔だ」","f":"genzo"},{"t":"n","s":"玄蔵が、拳を握った。","f":"genzo"},{"t":"n","s":"重圧が、巌ひとりに集まる。地面が割れた。巌の足が、膝まで地面に埋まる。それでも、倒れなかった。","f":"genzo"},{"t":"d","s":"「……巌！」","f":"genzo"},{"t":"d","s":"「行け、耀平！　俺が、一番頑丈なんだ！」","f":"genzo"},{"t":"n","s":"その背中に、もう言葉は届かなかった。","f":"genzo"},{"t":"d","s":"「巌……！」","f":"genzo"},{"t":"n","s":"巌は、立ったまま、動かなくなった。","f":"genzo"},{"t":"n","s":"最後まで、笑っていた。","f":"genzo"}]},{"key":"20-3","title":"影武者","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["ren","principal"],"lines":[{"t":"n","s":"戦いは、乱戦になった。"},{"t":"n","s":"八天の配下が、再び影の中から湧いてくる。蓮が前線を支え、九十九先輩と結城先輩が左右を守った。生徒会の副会長が、学園長の前に立つ。","f":"ren"},{"t":"d","s":"「会長、持ちこたえます！」","f":"ren"},{"t":"d","s":"「無理をするな！」","f":"ren"},{"t":"d","s":"「無理は、仕事のうちです！」","f":"ren"},{"t":"n","s":"E組の面々も、必死だった。","f":"ren"},{"t":"d","s":"「慎吾、後ろ！」","f":"ren"},{"t":"d","s":"「分かってる！」","f":"ren"},{"t":"n","s":"慎吾は、もう三体目の分身を作っていた。身代分身。本体の代わりに攻撃を受ける、ただそれだけのスキル。","f":"ren"},{"t":"d","s":"「これ、ほんと地味だよな。俺」","f":"ren"},{"t":"d","s":"「何言ってんの、今めちゃくちゃ助かってるよ！」","f":"ren"},{"t":"d","s":"「そっか。……なら、いいや」","f":"ren"},{"t":"n","s":"慎吾は、小春の前に立った。","f":"ren"},{"t":"n","s":"影の槍が、小春めがけて伸びた。慎吾の分身が、それを受けた。次の槍も。その次も。","f":"ren"},{"t":"n","s":"分身が消えるたびに、慎吾の顔色が悪くなっていく。","f":"ren"},{"t":"d","s":"「慎吾くん、もう、いいよ！　もう——」","f":"ren"},{"t":"d","s":"「小春ちゃん、走って。治癒の風、まだ必要な人がいる」","f":"ren"},{"t":"d","s":"「でも！」","f":"ren"},{"t":"d","s":"「みんなを、頼む」","f":"ren"},{"t":"n","s":"慎吾は、振り返って笑った。","f":"ren","m":"happy"},{"t":"d","s":"「影武者は、本物の代わりに死ぬのが仕事だから」","f":"ren"},{"t":"n","s":"小春は、泣きながら走った。","f":"ren","m":"sad"},{"t":"n","s":"慎吾は、四体目の分身を作ろうとして、できなかった。","f":"ren"},{"t":"n","s":"影の槍が、慎吾の胸を貫いた。","f":"ren"}]},{"key":"20-4","title":"花","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["yuzuki","genzo","yohei"],"lines":[{"t":"n","s":"気がつくと、耀平は走っていた。","f":"yohei"},{"t":"n","s":"重圧の中を、一歩ずつ、前へ。","f":"yohei"},{"t":"d","s":"「金井！　待て！」","f":"yohei"},{"t":"d","s":"「やめろ、勝てる相手じゃ——」","f":"yohei"},{"t":"n","s":"蓮の声が、遠くなった。","f":"ren"},{"t":"i","s":"（百花繚乱）","f":"ren","fx":"bloom"},{"t":"n","s":"花びらが舞った。桜、梅、藤、菫。色とりどりの花が、玄蔵に向かって流れていく。","f":"genzo"},{"t":"n","s":"玄蔵は、それを見て、小さく息をついた。","f":"genzo"},{"t":"d","s":"「花か」","f":"genzo"},{"t":"n","s":"手のひらを、一度だけ握る。","f":"genzo"},{"t":"n","s":"花は、すべて地面に叩きつけられた。","f":"genzo","fx":"shake"},{"t":"d","s":"「軽い。お前の花は、軽すぎる」","f":"genzo"},{"t":"d","s":"「……っ！」","f":"genzo"},{"t":"n","s":"衝撃が、体の中心を打った。耀平は、校庭の端まで転がった。口の中に、鉄の味が広がる。","f":"yohei","fx":"shake"},{"t":"d","s":"「耀平！」","f":"yohei"},{"t":"n","s":"柚月が、駆け寄ってきた。","f":"yuzuki"},{"t":"d","s":"「来るな！」","f":"yuzuki"},{"t":"d","s":"「嫌」","f":"yuzuki"},{"t":"d","s":"「柚月！」","f":"yuzuki"},{"t":"d","s":"「嫌。……もう、誰も、いなくなるのは」","f":"yuzuki"},{"t":"n","s":"柚月は、耀平の前に立った。","f":"yuzuki"},{"t":"n","s":"両手を広げて。","f":"yuzuki"},{"t":"d","s":"「淡雪静華」","f":"yuzuki"},{"t":"n","s":"白い風が、柚月の周りに広がった。玄蔵の動きが、ほんの一瞬、止まる。","f":"yuzuki"},{"t":"d","s":"「ほう。氷か」","f":"yuzuki"},{"t":"d","s":"「これ以上、誰も傷つけさせない」","f":"yuzuki"},{"t":"d","s":"「痛みを拒むスキルか。珍しい」","f":"yuzuki"},{"t":"n","s":"玄蔵は、一歩踏み出した。","f":"genzo"},{"t":"n","s":"柚月の氷が、軋んだ。ひびが入る。","f":"yuzuki"},{"t":"d","s":"「柚月、下がれ！」","f":"yuzuki"},{"t":"d","s":"「下がらない！」","f":"yuzuki"},{"t":"d","s":"「死ぬぞ！」","f":"yuzuki"},{"t":"d","s":"「それでも、嫌！」","f":"yuzuki"},{"t":"n","s":"氷が、砕けた。","f":"yuzuki","fx":"shake"},{"t":"n","s":"柚月の体が、重圧に叩きつけられた。小さな体が、地面に沈む。","f":"yuzuki","fx":"shake"},{"t":"n","s":"声は、出なかった。","f":"yuzuki"}]},{"key":"20-5","title":"万花繚乱","bg":"bg_schoolyard_middle","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["yohei","yuzuki","genzo"],"lines":[{"t":"n","s":"耀平は、這った。","f":"yohei"},{"t":"n","s":"柚月の手を、握った。冷たかった。息は、あった。ほんのわずか。","f":"yuzuki"},{"t":"d","s":"「柚月。……柚月」","f":"yuzuki"},{"t":"d","s":"「……よう、へい」","f":"yuzuki"},{"t":"d","s":"「喋るな。いま、いま——」","f":"yuzuki"},{"t":"d","s":"「……ごめん。話す、って、約束……したのに」","f":"yuzuki"},{"t":"n","s":"柚月の目が、閉じかけた。","f":"yuzuki"},{"t":"i","s":"（嫌だ）","f":"yuzuki"},{"t":"i","s":"（失いたくない。もう、誰も）","f":"yuzuki"},{"t":"i","s":"（桜は、守りたいと願った時だけ咲く）","f":"yuzuki"},{"t":"n","s":"蓮の言葉が、頭の中で鳴った。","f":"ren"},{"t":"i","s":"（咲け）","f":"ren"},{"t":"i","s":"（咲け、咲け、咲け——！）","f":"ren"},{"t":"n","s":"耀平の体から、光があふれた。","f":"yohei"},{"t":"n","s":"桜だけではなかった。百の花が、千の花が、一斉に開いた。校庭が、春よりも濃い色に染まっていく。花びらは、重圧に押しつぶされることなく、空へ舞い上がった。","f":"yohei"},{"t":"d","s":"「……これは」","f":"yohei"},{"t":"n","s":"玄蔵の目が、わずかに見開かれた。","f":"genzo"},{"t":"cg","v":"cg_banka"},{"t":"d","s":"「万花繚乱」","f":"genzo","fx":"bloom"},{"t":"n","s":"耀平の声は、自分でも驚くほど静かだった。","f":"yohei"},{"t":"n","s":"花びらが、柚月の体を包んだ。傷が、ゆっくりと塞がっていく。小春の風が、そこに重なった。","f":"yuzuki"},{"t":"d","s":"「柚月の傷、塞がってる……！」","f":"yuzuki"},{"t":"d","s":"「お願い、間に合って……！」","f":"yuzuki"},{"t":"n","s":"玄蔵が、再び手を下ろした。","f":"genzo"},{"t":"n","s":"重圧が、落ちた。","f":"genzo"},{"t":"n","s":"しかし今度は、花が潰れなかった。","f":"genzo"},{"t":"d","s":"「……ほう」","f":"genzo"},{"t":"d","s":"「軽いかどうかは、もう一度、確かめてみろ」","f":"genzo"},{"t":"n","s":"耀平は立ち上がった。","f":"yohei"},{"t":"n","s":"足元の花びらが、風に乗って、玄蔵の周りを取り囲んだ。","f":"genzo"}]},{"key":"20-6","title":"天城無明","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["ren","principal","mumyo"],"lines":[{"t":"n","s":"拳が、ぶつかった。"},{"t":"n","s":"玄蔵の重圧と、耀平の花。押し合い、弾き合い、校庭が割れていく。蓮が側面から斬り込み、担任が背後を取った。","f":"genzo"},{"t":"d","s":"「畳みかけろ！」","f":"genzo"},{"t":"d","s":"「はい！」","f":"genzo"},{"t":"n","s":"三人がかりで、玄蔵が初めて、膝をついた。","f":"genzo"},{"t":"d","s":"「……見事だ」","f":"genzo"},{"t":"n","s":"玄蔵は、静かに言った。","f":"genzo"},{"t":"d","s":"「だが、時間切れだ」","f":"genzo"},{"t":"n","s":"空が、暗くなった。","f":"genzo"},{"t":"n","s":"夕方でもないのに、日が落ちたように。校庭の端から、夜が染み込んでくる。視界が狭まる。花びらの色が、褪せていく。","f":"genzo"},{"t":"i","s":"（これは……）","f":"genzo"},{"t":"d","s":"「無明長夜」","f":"genzo"},{"t":"n","s":"誰かが、そう呟いた。","f":"genzo"},{"t":"n","s":"そして、その男は、ゆっくりと、校門から歩いてきた。","f":"genzo"},{"t":"n","s":"背は高くなかった。黒い着流しに、白い手袋。穏やかな目をしていた。","f":"genzo"},{"t":"d","s":"「ご苦労だった、玄蔵」","f":"genzo"},{"t":"d","s":"「ボス。お出ましになるとは」","f":"genzo"},{"t":"d","s":"「少し、整理を急ぎたくなった」","f":"genzo"},{"t":"n","s":"男は、校庭を見渡した。","f":"genzo"},{"t":"n","s":"倒れた生徒。折れた木。咲き残った花。","f":"genzo"},{"t":"d","s":"「ああ。やはり、色のついた花は美しいな」","f":"genzo"},{"t":"n","s":"天城無明。","f":"mumyo"},{"t":"n","s":"名乗らなくても、分かった。","f":"mumyo"},{"t":"n","s":"夜が、降りてくる。スキルが、鈍る。花びらが、ひとつ、またひとつと消えていく。","f":"mumyo"},{"t":"d","s":"「学園長、下がってください！」","f":"mumyo"},{"t":"d","s":"「私が止める」","f":"mumyo"},{"t":"n","s":"学園長が、前に出た。蓮も続いた。","f":"principal"},{"t":"n","s":"無明は、二人を見て、微笑んだ。","f":"mumyo","m":"happy"},{"t":"d","s":"「久しぶりだね。学園長」","f":"mumyo"},{"t":"d","s":"「……無明」","f":"mumyo"},{"t":"d","s":"「ずいぶん、老けた」","f":"mumyo"},{"t":"n","s":"次の瞬間、学園長の体が、宙を舞った。","f":"principal"},{"t":"n","s":"何をされたのか、耀平には見えなかった。蓮も、同じように弾き飛ばされた。","f":"yohei"},{"t":"d","s":"「会長！」","f":"yohei"},{"t":"n","s":"副会長が、学園長の前に飛び込んだ。","f":"ren"},{"t":"d","s":"「学園長に、触れるな！」","f":"ren"},{"t":"n","s":"無明の指が、わずかに動いた。","f":"mumyo"},{"t":"n","s":"副会長は、声もなく、崩れ落ちた。","f":"ren"}]},{"key":"20-7","title":"夜の終わり","bg":"bg_schoolyard_middle","dark":true,"mood":"sad","bgm":"sad2","cast":["mumyo","genzo","setsuka"],"lines":[{"t":"n","s":"夜が明けたのは、それからしばらく後のことだった。"},{"t":"n","s":"いや、明けたのではない。無明が、去ったのだ。","f":"mumyo"},{"t":"d","s":"「今日は、ここまでにしよう」","f":"mumyo"},{"t":"d","s":"「待て！」","f":"mumyo"},{"t":"d","s":"「また来るよ。卒業式の頃にでも」","f":"mumyo"},{"t":"n","s":"無明は、微笑んだまま、闇に溶けた。玄蔵と雪華も、それに続いた。","f":"mumyo","m":"happy"},{"t":"n","s":"静寂が、戻ってきた。","f":"mumyo"},{"t":"n","s":"校庭には、花びらが一面に散っていた。その下に、動かない人影が、いくつも横たわっていた。","f":"mumyo"},{"t":"n","s":"数えた。","f":"mumyo"},{"t":"n","s":"数えたくなかったが、数えた。","f":"mumyo"},{"t":"n","s":"巌。慎吾。それから、陽太。椿。","f":"mumyo"},{"t":"n","s":"生徒会の副会長と、書記の先輩。","f":"ren"},{"t":"n","s":"六人だった。","f":"ren"},{"t":"d","s":"「……陽太」","f":"ren"},{"t":"n","s":"陽太は、校舎の入口で倒れていた。最後まで、みんなを立たせ続けた体は、まだ温かかった。","f":"ren"},{"t":"d","s":"「バカ。笑えって言ったの、お前だろ」","f":"ren"},{"t":"d","s":"「…………」","f":"ren"},{"t":"d","s":"「なんで、お前が笑ってないんだよ」","f":"ren"},{"t":"n","s":"誰も答えなかった。","f":"ren"},{"t":"n","s":"乃亜が、耀平の隣に立っていた。","f":"noa"},{"t":"n","s":"何も言わなかった。ただ、その袖を、強く握っていた。","f":"noa"}]},{"key":"20-8","title":"別れ","bg":"bg_graduation","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei","noa","principal"],"lines":[{"t":"n","s":"三日後。"},{"t":"n","s":"学園は、臨時休校になった。"},{"t":"n","s":"体育館で、六人の葬儀が行われた。柚月は、車椅子で参列していた。傷は塞がったが、まだ立てなかった。","f":"yuzuki"},{"t":"d","s":"「耀平」","f":"yuzuki"},{"t":"d","s":"「……なに」","f":"yuzuki"},{"t":"d","s":"「私のせい？」","f":"yuzuki"},{"t":"d","s":"「違う」","f":"yuzuki"},{"t":"d","s":"「私が、ここにいたから」","f":"yuzuki"},{"t":"d","s":"「違う。……違うよ、柚月」","f":"yuzuki"},{"t":"n","s":"耀平は、首を振った。","f":"yohei"},{"t":"n","s":"それ以上は、言えなかった。","f":"yohei"},{"t":"n","s":"葬儀のあと、学園長室に呼ばれた。","f":"principal"},{"t":"n","s":"学園長は、片腕を吊っていた。顔色は悪かったが、目だけは、鋭いままだった。","f":"principal"},{"t":"d","s":"「金井君」","f":"principal"},{"t":"d","s":"「はい」","f":"principal"},{"t":"d","s":"「君たちは、この学園にいる限り、また狙われる」","f":"principal"},{"t":"d","s":"「……はい」","f":"principal"},{"t":"d","s":"「そして、ここの警備は、もう、あてにならない」","f":"principal"},{"t":"n","s":"学園長は、一枚の紙を、机に置いた。","f":"principal"},{"t":"d","s":"「ある組織が、君に会いたいと言っている。国の、闇の部分だ。……天冠と、真正面から戦える、唯一の部隊」","f":"principal"},{"t":"d","s":"「SHITだ」","f":"principal"},{"t":"n","s":"部屋の隅で、迅が言った。","f":"jin"},{"t":"d","s":"「迅さん」","f":"jin"},{"t":"d","s":"「行くか、行かないかは、お前が決めろ」","f":"jin"},{"t":"n","s":"耀平は、窓の外を見た。","f":"yohei"},{"t":"n","s":"校庭では、生徒たちが、花を植えていた。倒れた場所に、ひとつずつ。","f":"yohei"},{"t":"n","s":"乃亜が、その中にいた。","f":"noa"},{"t":"n","s":"乃亜は、耀平に気づくと、手を振った。","f":"noa"},{"t":"n","s":"何も知らないふりをして。","f":"noa"},{"t":"n","s":"耀平は、拳を握った。","f":"yohei"},{"t":"d","s":"「……行きます」","f":"yohei"},{"t":"d","s":"「いいのか」","f":"yohei"},{"t":"d","s":"「ここにいたら、また誰かが死にます。僕のせいで」","f":"yohei"},{"t":"d","s":"「それは違う」","f":"yohei"},{"t":"d","s":"「違わなくていいです。……強くなりたいんです。もう、誰も、僕の前で死なせないために」","f":"yohei"},{"t":"n","s":"学園長は、しばらく黙っていた。","f":"principal"},{"t":"n","s":"そして、静かに、頷いた。","f":"principal"},{"t":"cg","v":"cg_rooftop_farewell"},{"t":"n","s":"夜、耀平は、乃亜を屋上に呼んだ。","f":"yohei"},{"t":"n","s":"星が、よく見えた。","f":"yohei"},{"t":"d","s":"「行くんでしょ」","f":"yohei"},{"t":"d","s":"「……なんで分かるの」","f":"yohei"},{"t":"d","s":"「分かるよ。何年、一緒にいると思ってんの」","f":"yohei"},{"t":"n","s":"乃亜は、笑っていた。目だけが、赤かった。","f":"noa"},{"t":"d","s":"「いつ、戻ってくる」","f":"noa"},{"t":"d","s":"「分からない」","f":"noa"},{"t":"d","s":"「そっか」","f":"noa"},{"t":"d","s":"「ごめん」","f":"noa"},{"t":"d","s":"「謝んないでよ。……待ってる。待ってるから」","f":"noa"},{"t":"n","s":"乃亜は、耀平の胸を、とん、と拳で叩いた。","f":"noa"},{"t":"d","s":"「強くなって、帰ってきて。その時は、あんたが一番の、E組の誇りだから」","f":"noa"},{"t":"d","s":"「……うん」","f":"noa"},{"t":"d","s":"「約束」","f":"noa"},{"t":"d","s":"「約束」","f":"noa"},{"t":"n","s":"夜風が、二人の間を通り抜けた。","f":"noa"},{"t":"n","s":"翌朝、耀平は、誰にも見送られずに、学園を出た。","f":"yohei"},{"t":"n","s":"門の脇に、ひとつだけ、小さな桜の花が咲いていた。","f":"yohei"},{"t":"n","s":"季節外れの、狂い咲きだった。","f":"yohei"},{"t":"n","s":"耀平は、それを一度だけ振り返って、そして、前を向いた。","f":"yohei"}]}]},{"n":21,"title":"SHIT","sub":"高校編","era":"high","lead":"学園を出た耀平が辿り着いたのは、地図に載らない部隊だった。強くなることだけを望んだ少年は、その途中で、色を失い始める。","scenes":[{"key":"21-1","title":"地下","bg":"bg_shit_base","dark":false,"mood":"sad","bgm":"sad1","cast":["jin","yohei"],"lines":[{"t":"n","s":"迅に連れられて降りたのは、古い地下鉄の駅だった。","f":"jin"},{"t":"n","s":"使われなくなって何十年も経つ。壁のタイルは剥がれ、天井からは水が滴っている。","f":"jin"},{"t":"d","s":"「ここが、入口だ」","f":"jin"},{"t":"d","s":"「……駅、ですよね」","f":"jin"},{"t":"d","s":"「表向きはな。廃線の保守点検という名目で、この区画は国が買い上げている」","f":"jin"},{"t":"n","s":"迅は、ホームの端の古い改札を、鍵もなしに開けた。","f":"jin"},{"t":"n","s":"長い階段を降りる。さらに降りる。耀平は途中から段数を数えるのをやめた。","f":"yohei"},{"t":"n","s":"最後の扉の前で、迅が足を止めた。","f":"jin"},{"t":"d","s":"「先に言っておく。ここの連中は、まともじゃない」","f":"jin"},{"t":"d","s":"「まともじゃない、というのは」","f":"jin"},{"t":"d","s":"「会えば分かる。……ただ、全員、腕だけは確かだ」","f":"jin"},{"t":"n","s":"扉が開いた。","f":"jin"},{"t":"n","s":"広い部屋だった。壁には地図が貼られ、机の上には書類が山になっている。その奥のソファに、五人が座っていた。","f":"jin"},{"t":"n","s":"正確には、四人と、一人。","f":"jin"},{"t":"d","s":"「お、来た来た。例の桜の子だ」","f":"jin"},{"t":"d","s":"「ほんとに高校生じゃん。ちっちゃ」","f":"jin"},{"t":"d","s":"「お前らが言うな」","f":"jin"},{"t":"n","s":"口々に声が飛ぶ。迅がため息をついた。","f":"jin"},{"t":"d","s":"「紹介する。ここが、SHITだ」","f":"jin"},{"t":"d","s":"「……あの」","f":"jin"},{"t":"d","s":"「何だ」","f":"jin"},{"t":"d","s":"「名前、もう少しどうにかならなかったんですか」","f":"jin"},{"t":"d","s":"「俺に言うな。決めたのは上だ」","f":"jin"},{"t":"n","s":"四人のうち一人が、腹を抱えて笑っていた。","f":"jin"}]},{"key":"21-2","title":"A、B、C、D","bg":"bg_shit_base","dark":true,"mood":"night","bgm":"night1","cast":["yohei","jin"],"lines":[{"t":"n","s":"SHITの隊員は、名前を持たない。呼び名は、AからDまでの記号だった。"},{"t":"d","s":"「俺がAだ。隊長って呼べ」"},{"t":"d","s":"「呼ばなくていいよ。Aは飾りだから」"},{"t":"d","s":"「うるせえ、Bは黙ってろ」"},{"t":"n","s":"Aは大柄で、無精髭を生やした男だった。Bは細身の女で、爪の手入れをしながら話を聞いている。Cは眼鏡の男で、ずっと何かの計算をしていた。Dは無口な、背の高い女だった。"},{"t":"d","s":"「で、こっちが」"},{"t":"n","s":"Aが、一番端のソファを指さした。"},{"t":"n","s":"小学生くらいの子供が、足をぶらぶらさせてお菓子を食べていた。"},{"t":"d","s":"「……あの」"},{"t":"d","s":"「ああ、こいつはね」"},{"t":"d","s":"「こいつ呼ばわり、しない」"},{"t":"n","s":"子供が、口をとがらせた。"},{"t":"d","s":"「ぼくは、ちゃんとした隊員だよ。いちばん強いんだから」"},{"t":"d","s":"「そういうことにしといてやる」"},{"t":"d","s":"「ほんとだってば！」"},{"t":"n","s":"耀平は、迅を見た。迅は、目を逸らした。","f":"yohei"},{"t":"d","s":"「……本当だ」","f":"yohei"},{"t":"d","s":"「え」","f":"yohei"},{"t":"d","s":"「SHITの中で、ボスと一番長く戦えたのは、そいつだ」","f":"yohei"},{"t":"n","s":"耀平は、もう一度、子供を見た。","f":"yohei"},{"t":"n","s":"子供は、チョコレートの包み紙を丁寧に畳んでいた。","f":"yohei"}]},{"key":"21-3","title":"九条蓮","bg":"bg_shit_base","dark":true,"mood":"night","bgm":"night1","cast":["ren","yohei","principal"],"lines":[{"t":"n","s":"翌日、もう一人、扉の前に立った。"},{"t":"n","s":"九条蓮だった。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「会長ではない。学園は、辞めてきた」","f":"ren"},{"t":"d","s":"「……辞めた、んですか」","f":"ren"},{"t":"d","s":"「責任を取る形でな。学園長は止めたが」","f":"ren"},{"t":"n","s":"蓮の顔は、以前より痩せていた。それでも、背筋は変わらず伸びている。","f":"ren"},{"t":"d","s":"「副会長と書記を、私は守れなかった」","f":"ren"},{"t":"d","s":"「会長のせいじゃ——」","f":"ren"},{"t":"d","s":"「金井」","f":"ren"},{"t":"n","s":"蓮は、静かに言った。","f":"ren"},{"t":"d","s":"「責任の話をしているのではない。私は、強くなる必要がある。ただ、それだけだ」","f":"ren"},{"t":"n","s":"耀平は、何も返せなかった。","f":"yohei"},{"t":"n","s":"同じだった。自分と、同じだった。","f":"yohei"},{"t":"d","s":"「ここにいるなら、まず約束しろ」","f":"yohei"},{"t":"d","s":"「はい」","f":"yohei"},{"t":"d","s":"「一人で突っ込むな。あの日のように」","f":"yohei"},{"t":"d","s":"「……はい」","f":"yohei"},{"t":"d","s":"「約束できるか」","f":"yohei"},{"t":"d","s":"「……はい」","f":"yohei"},{"t":"n","s":"蓮は、少しだけ眉を寄せた。","f":"ren"},{"t":"n","s":"返事が早すぎる、とでも言うように。","f":"ren"}]},{"key":"21-4","title":"訓練","bg":"bg_shit_base","dark":true,"mood":"night","bgm":"night1","cast":["yohei"],"lines":[{"t":"n","s":"SHITの訓練は、学園のそれとは別物だった。"},{"t":"d","s":"「はい、次。Dと一対一」"},{"t":"d","s":"「えっ、いきなり」"},{"t":"d","s":"「実戦で、準備の時間をくれる敵はいない」"},{"t":"n","s":"Dは、一言も喋らなかった。"},{"t":"n","s":"構えた次の瞬間に、耀平は壁に叩きつけられていた。","f":"yohei","fx":"shake"},{"t":"n","s":"何をされたのか分からない。起き上がる前に、もう一度。","f":"yohei"},{"t":"d","s":"「立て」","f":"yohei"},{"t":"d","s":"「は、はい」","f":"yohei"},{"t":"d","s":"「立て」","f":"yohei"},{"t":"n","s":"何度やられたか、数えていない。","f":"yohei"},{"t":"n","s":"夜になると、Bが傷の手当てをしてくれた。","f":"yohei"},{"t":"d","s":"「あんた、頑丈だねえ」","f":"yohei"},{"t":"d","s":"「……ありがとうございます」","f":"yohei"},{"t":"d","s":"「褒めてないよ。直し甲斐があるってだけ」","f":"yohei"},{"t":"n","s":"Bは、爪を見ながら言った。","f":"yohei"},{"t":"d","s":"「でもね、坊や。頑丈なのと、強いのは、違うんだよ」","f":"yohei"},{"t":"d","s":"「分かってます」","f":"yohei"},{"t":"d","s":"「分かってない顔してる」","f":"yohei"},{"t":"n","s":"耀平は、答えなかった。","f":"yohei"},{"t":"n","s":"翌日も、その翌日も、耀平は一番早く起きて、一番遅くまで訓練場に残った。","f":"yohei"}]},{"key":"21-5","title":"聞き出されたもの","bg":"bg_shit_base","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","hotaru","mumyo"],"lines":[{"t":"n","s":"三週間が経った頃だった。"},{"t":"n","s":"夜中に目が覚めて、水を飲みに廊下へ出ると、奥の部屋に灯りがついていた。"},{"t":"n","s":"扉が、わずかに開いている。"},{"t":"d","s":"「……はい。第六席は、相変わらずです。こちらの質問には、何ひとつ答えません」"},{"t":"d","s":"「締め上げても吐かんか」"},{"t":"d","s":"「吐かないどころか、笑っています。『耀平くんを連れてきて』の一点張りで」"},{"t":"n","s":"Cと、隊長のAの声だった。"},{"t":"n","s":"耀平は、廊下の角で、息を殺した。","f":"yohei"},{"t":"n","s":"第六席。紫苑蛍。あの日、自分が倒した、紫の女だ。","f":"hotaru"},{"t":"d","s":"「……聞いていたな、金井」","f":"hotaru"},{"t":"n","s":"Aが、振り返りもせずに言った。","f":"hotaru"},{"t":"d","s":"「……すみません」","f":"hotaru"},{"t":"d","s":"「謝らなくていい。むしろ、ちょうどいい。行ってこい」","f":"hotaru"},{"t":"n","s":"学園の地下。SHITが預かる、窓のない部屋。","f":"hotaru"},{"t":"n","s":"分厚い硝子の向こうで、蛍は、簡素な椅子に脚を組んで座っていた。耀平の顔を見た瞬間、その目が、ぱっと輝いた。","f":"hotaru"},{"t":"d","s":"「耀平くん！　やっと来てくれた」","f":"hotaru"},{"t":"d","s":"「……元気そうですね」","f":"hotaru"},{"t":"d","s":"「元気じゃないわよ。ここ、ごはんがまずいの。……でも、今、元気になった」","f":"hotaru"},{"t":"n","s":"蛍は、硝子に両手をついて、子供のように笑った。耀平は、どこを見ればいいのか分からず、視線を床に落とした。","f":"hotaru","m":"happy"},{"t":"d","s":"「天冠のボスのこと、聞きに来たんでしょ」","f":"hotaru"},{"t":"d","s":"「……はい」","f":"hotaru"},{"t":"d","s":"「いいわよ。耀平くんにだけ、教えてあげる」","f":"hotaru"},{"t":"n","s":"蛍の声から、ふっと、甘さが消えた。","f":"hotaru"},{"t":"d","s":"「無明長夜。あの人の領域に入ったら、スキルは全部鈍る。わたしの子たちも、あの中じゃ飛べない。……でもね」","f":"hotaru"},{"t":"d","s":"「でも」","f":"hotaru"},{"t":"d","s":"「領域を張る、その瞬間だけ。あの人、ほんの一瞬、目を閉じるの。息を吸うみたいに。わたし、何度も隣で見てきたから、間違いない」","f":"hotaru"},{"t":"n","s":"耀平は、顔を上げた。","f":"yohei"},{"t":"d","s":"「どうして、それを、おれに」","f":"yohei"},{"t":"d","s":"「決まってるじゃない」","f":"yohei"},{"t":"n","s":"蛍は、硝子越しに、まっすぐ耀平を見た。","f":"hotaru"},{"t":"d","s":"「耀平くんが死んじゃうの、いやだもの」","f":"hotaru"},{"t":"n","s":"冗談めかした口調だった。けれど、その目だけは、少しも笑っていなかった。","f":"hotaru"},{"t":"d","s":"「それとね。決戦の日は、わたしもここから出して」","f":"hotaru"},{"t":"d","s":"「え」","f":"hotaru"},{"t":"d","s":"「天冠を裏切ったんだから、どうせもう戻れないし。翠嵐ちゃんか朔くらいなら、足止めしてあげる。……その代わり」","f":"hotaru"},{"t":"d","s":"「その代わり？」","f":"hotaru"},{"t":"d","s":"「終わったら、デートして」","f":"hotaru"},{"t":"n","s":"硝子の向こうで、蛍が片目をつぶった。後ろで記録をとっていたCが、ごほん、と咳払いをした。","f":"hotaru"},{"t":"n","s":"部屋を出ると、Cが、手元の資料をめくりながら言った。","f":"hotaru"},{"t":"d","s":"「……裏は取れた。第六席の証言は、これまで集めた射程の情報と矛盾しない。出すかどうかは、隊長が決める」","f":"hotaru"},{"t":"n","s":"Cは眼鏡を押し上げた。","f":"hotaru"},{"t":"d","s":"「お前は、ボスと戦う時、最初に何を狙う」","f":"hotaru"},{"t":"d","s":"「何を、って」","f":"hotaru"},{"t":"d","s":"「第六席の言う通りなら、領域を張る時、ボスは一瞬だけ動けなくなる。その一瞬に、何ができるかだ」","f":"hotaru"},{"t":"n","s":"耀平は、考えた。","f":"yohei"},{"t":"n","s":"それから、小さく答えた。","f":"yohei"},{"t":"d","s":"「……花びらを、先に撒いておく」","f":"yohei"},{"t":"d","s":"「ほう」","f":"yohei"},{"t":"d","s":"「領域が張られても、先にある花びらなら、鈍る前に動かせる」","f":"yohei"},{"t":"d","s":"「悪くない」","f":"yohei"},{"t":"n","s":"Cは、初めて少しだけ笑った。","f":"yohei","m":"happy"},{"t":"n","s":"耀平は、胸の奥に灯った小さな温かさを、すぐに消した。","f":"yohei"},{"t":"i","s":"（強くならなきゃ）","f":"yohei"},{"t":"i","s":"（もっと、もっと）","f":"yohei"}]},{"key":"21-6","title":"小学生","bg":"bg_shit_base","dark":true,"mood":"night","bgm":"night1","cast":["yohei"],"lines":[{"t":"d","s":"「ねえ、おにいちゃん」"},{"t":"n","s":"訓練場の隅で、あの子供が声をかけてきた。"},{"t":"d","s":"「……何」"},{"t":"d","s":"「おにいちゃん、さいきん、笑ってないでしょ」"},{"t":"d","s":"「笑う理由が、ないから」"},{"t":"d","s":"「ふーん」"},{"t":"n","s":"子供は、耀平の隣に座った。","f":"yohei"},{"t":"d","s":"「ぼくね、むかし、すごく怒ってた時があったの」","f":"yohei"},{"t":"d","s":"「そうなんだ」","f":"yohei"},{"t":"d","s":"「うん。誰も信じられなくて、全部こわしたくて。そしたらね、スキルが、真っ黒になったの」","f":"yohei"},{"t":"n","s":"子供は、足をぶらぶらさせたまま続けた。","f":"yohei"},{"t":"d","s":"「あのまま行ったら、たぶん、戻れなかったんだ」","f":"yohei"},{"t":"d","s":"「……どうして、戻れたの」","f":"yohei"},{"t":"d","s":"「ともだちがね、怒ってくれたの。ぼくのこと、ぶん殴って」","f":"yohei"},{"t":"n","s":"耀平は、子供の顔を見た。","f":"yohei"},{"t":"n","s":"子供は、本当に楽しそうに笑っていた。","f":"yohei"},{"t":"d","s":"「おにいちゃんのスキル、さいきん、色がうすいよ」","f":"yohei"},{"t":"d","s":"「……え」","f":"yohei"},{"t":"d","s":"「花の色。きっと、おにいちゃん自身が、気づいてないだけ」","f":"yohei"},{"t":"n","s":"耀平は、掌を見た。","f":"yohei"},{"t":"n","s":"小さな桜の花びらを、一枚出した。","f":"yohei"},{"t":"n","s":"白かった。","f":"yohei"},{"t":"n","s":"以前は、確かに薄紅色をしていたはずだった。","f":"yohei"},{"t":"d","s":"「……気のせい、だよ」","f":"yohei"},{"t":"d","s":"「そっか」","f":"yohei"},{"t":"n","s":"子供は、それ以上は何も言わなかった。","f":"yohei"},{"t":"n","s":"ただ、耀平の肩を、ぽん、と叩いた。","f":"yohei"}]},{"key":"21-7","title":"夜桜","bg":"bg_shit_base","dark":true,"mood":"night","bgm":"night1","cast":["yohei","ren","yuzuki"],"lines":[{"t":"n","s":"その夜、耀平は一人で訓練場にいた。","f":"yohei"},{"t":"n","s":"誰もいない。灯りも落ちている。","f":"yohei"},{"t":"cg","v":"cg_meikyo"},{"t":"n","s":"暗闇の中で、耀平は目を閉じた。","f":"yohei"},{"t":"i","s":"（陽太。巌。慎吾。椿。副会長、書記の先輩）","f":"yohei"},{"t":"i","s":"（……柚月。乃亜）","f":"yohei"},{"t":"n","s":"名前を、順番に呼んだ。","f":"yohei"},{"t":"i","s":"（桜は、守りたいと願った時だけ咲く）","f":"yohei"},{"t":"n","s":"蓮の言葉だった。","f":"ren"},{"t":"i","s":"（なら、守れなかった時は）","f":"ren"},{"t":"n","s":"花びらが、舞った。","f":"ren"},{"t":"n","s":"万花繚乱。","f":"ren","fx":"bloom"},{"t":"n","s":"しかし、その色は、これまでと違っていた。","f":"ren"},{"t":"n","s":"桜の薄紅も、藤の紫も、菊の黄も、すべて暗く沈んで、夜の色に溶けていく。","f":"ren"},{"t":"cg","v":"cg_indigo"},{"t":"n","s":"黒に近い、濃い藍色の花。","f":"ren","fx":"indigo"},{"t":"d","s":"「……綺麗、だな」","f":"ren"},{"t":"n","s":"耀平は、自分の声が、他人のもののように聞こえた。","f":"yohei"},{"t":"n","s":"花びらが、訓練場の壁を斬り裂いた。","f":"yohei"},{"t":"n","s":"鉄の扉が、音もなく切れた。","f":"yohei"},{"t":"d","s":"「強い……」","f":"yohei"},{"t":"n","s":"呟いた。","f":"yohei"},{"t":"d","s":"「これなら、勝てる」","f":"yohei"},{"t":"n","s":"誰かが、ずっと入口に立っていたことに、耀平は気づかなかった。","f":"yohei"},{"t":"n","s":"蓮だった。","f":"ren"},{"t":"n","s":"蓮は、何も言わずに、その背中を見ていた。","f":"ren"},{"t":"n","s":"それから、静かに、扉を閉めた。","f":"ren"}]},{"key":"21-8","title":"ニュース","bg":"bg_classroom_e","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","jin"],"lines":[{"t":"n","s":"翌朝、Aが新聞を机に叩きつけた。","fx":"shake"},{"t":"d","s":"「見ろ。学園の件が、ついに出た」"},{"t":"n","s":"見出しには、こう書かれていた。"},{"t":"n","s":"〈名門学園、二度の襲撃　警備の甘さに批判〉"},{"t":"d","s":"「世論が動けば、国も動く。上は、ボスへの対応を前倒しにするそうだ」"},{"t":"d","s":"「前倒し、というと」"},{"t":"d","s":"「卒業式の日に、決着をつける」"},{"t":"n","s":"部屋が、静まった。"},{"t":"n","s":"Aは、全員の顔を見回した。"},{"t":"d","s":"「ボスは、必ず来る。あの男は、卒業式を狙うと言った。ならば、そこが最後の場所だ」"},{"t":"d","s":"「それまで、あと、半年ちょっと」"},{"t":"d","s":"「そうだ。……耀平」"},{"t":"d","s":"「はい」"},{"t":"d","s":"「お前の力が、要る」"},{"t":"n","s":"耀平は、頷いた。","f":"yohei"},{"t":"d","s":"「何でもやります」","f":"yohei"},{"t":"d","s":"「何でも、か」","f":"yohei"},{"t":"d","s":"「はい。……もう、誰にも、死んでほしくないので」","f":"yohei"},{"t":"n","s":"Aは、少しだけ黙った。","f":"yohei"},{"t":"n","s":"それから、小さく言った。","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"n","s":"迅が、部屋の隅で、何かを言いかけてやめた。","f":"jin"},{"t":"n","s":"子供が、じっと耀平を見ていた。","f":"yohei"},{"t":"n","s":"耀平だけが、自分の掌の中で、藍色の花びらが静かに揺れていることに、気づいていなかった。","f":"yohei","fx":"indigo"}]}]},{"n":22,"title":"竜馬との和解と学園へ","sub":"高校編","era":"high","lead":"藍色の花を咲かせたまま、耀平は冬の夜に学園へ戻ってきた。そこで待っていたのは、一人のライバルだった。","scenes":[{"key":"22-1","title":"冬の外出","bg":"bg_riverside","dark":false,"mood":"sad","bgm":"sad2","cast":["yohei"],"lines":[{"t":"d","s":"「今日は、外の用事だ」"},{"t":"n","s":"Cが、地図を耀平に渡した。","f":"yohei"},{"t":"n","s":"卒業式まで、あと三か月。SHITの訓練は、最終段階に入っていた。","f":"yohei"},{"t":"d","s":"「用事、ですか」","f":"yohei"},{"t":"d","s":"「第三席の動きの観測だ。この地点に、月に一度、羽虫が現れる」","f":"yohei"},{"t":"d","s":"「やり合うんですか」","f":"yohei"},{"t":"d","s":"「観るだけだ。手は出すな」","f":"yohei"},{"t":"n","s":"耀平は、地図を見た。","f":"yohei"},{"t":"n","s":"見覚えのある地名だった。学園から、電車で二駅のところ。","f":"yohei"},{"t":"d","s":"「……わかりました」","f":"yohei"},{"t":"n","s":"花びらの色が、手の中で、暗く沈んでいた。","f":"yohei"},{"t":"n","s":"気づいていないふりをして、耀平はポケットに仕舞った。","f":"yohei"},{"t":"n","s":"観測は、二時間で終わった。","f":"yohei"},{"t":"n","s":"羽虫は現れなかった。耀平は、駅に向かう道を、あえて逆に歩いた。","f":"yohei"},{"t":"i","s":"（あと二駅だけ。見るだけだ）","f":"yohei"},{"t":"n","s":"自分に、そう言い聞かせた。","f":"yohei"}]},{"key":"22-2","title":"校門","bg":"bg_gate","dark":true,"mood":"night","bgm":"night2","cast":["yohei","ryoma"],"lines":[{"t":"n","s":"夜の学園は、静かだった。"},{"t":"n","s":"崩れた校舎の壁は、深緑色のシートで覆われている。結界は張り直されていたが、耀平にとっては、超えることは造作もない。","f":"yohei"},{"t":"n","s":"校庭の端に、小さな花壇があった。","f":"yohei"},{"t":"n","s":"六つ。","f":"yohei"},{"t":"n","s":"それぞれに、黒い石と、枝の花が供えられている。誰かが、毎日供え替えているのだろう。どれも、枯れていない。","f":"yohei"},{"t":"d","s":"「……巌」","f":"yohei"},{"t":"n","s":"耀平は、一つ目の前にしゃがんだ。","f":"yohei"},{"t":"d","s":"「慎吾。椿。……陽太」","f":"yohei"},{"t":"n","s":"名前を呼ぶたびに、胸の奥が、重く沈んでいった。","f":"yohei"},{"t":"n","s":"花びらが、足元に舞った。","f":"yohei"},{"t":"n","s":"藍色だった。","f":"yohei"},{"t":"d","s":"「……綺麗だな」","f":"yohei"},{"t":"n","s":"その声が、黒い石に反響した。","f":"yohei"},{"t":"d","s":"「……お前、誰だ」","f":"yohei"},{"t":"n","s":"後ろから、声がした。","f":"yohei"},{"t":"n","s":"竜馬だった。","f":"ryoma"}]},{"key":"22-3","title":"竜馬","bg":"bg_grave","dark":true,"mood":"night","bgm":"night2","cast":["ryoma","yohei","yuzuki"],"lines":[{"t":"d","s":"「……竜馬」"},{"t":"d","s":"「名前は分かってるよな。で、もう一度言う。お前、誰だ」"},{"t":"n","s":"竜馬は、上着のポケットに両手を突っ込んでいた。着ているのは制服ではなく、部屋着に近いジャージだった。","f":"ryoma"},{"t":"d","s":"「俺の知ってる金井耀平は、花を咲かせて、そんな顔しない」","f":"ryoma"},{"t":"d","s":"「……どんな顔だ」","f":"ryoma"},{"t":"d","s":"「黒いのだ」","f":"ryoma"},{"t":"n","s":"竜馬は、耀平の手元を顔で示した。","f":"ryoma"},{"t":"d","s":"「その花と、同じだ。……明るくない」","f":"ryoma"},{"t":"n","s":"耀平は、拳を握った。","f":"yohei"},{"t":"d","s":"「竜馬には、関係ない」","f":"yohei"},{"t":"d","s":"「ある」","f":"yohei"},{"t":"d","s":"「ない」","f":"yohei"},{"t":"d","s":"「あるって言ってるだろ。俺は、お前のライバルだ」","f":"yohei"},{"t":"n","s":"竜馬は、ゆっくりと前に出た。","f":"ryoma"},{"t":"d","s":"「ライバルってのは、独りで落ちていくやつを、止める役目だろ。俺はそう思ってる」","f":"ryoma"},{"t":"d","s":"「……落ちてなんかいない」","f":"ryoma"},{"t":"d","s":"「落ちてる。自分で気づいてないだけで」","f":"ryoma"},{"t":"n","s":"ライバルの声は、落ち着いていた。","f":"ryoma"},{"t":"n","s":"それが、やけに耳に痛かった。","f":"ryoma"},{"t":"d","s":"「……退け。見るだけに来たんだ」","f":"ryoma"},{"t":"d","s":"「柚月に会うのか」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「今のお前で、会うのか」","f":"ryoma"},{"t":"n","s":"耀平は、答えなかった。","f":"yohei"},{"t":"n","s":"この男は、今の自分を見ている。","f":"yohei"},{"t":"n","s":"それが、耐えられなかった。","f":"yohei"},{"t":"d","s":"「……どけよ、竜馬」","f":"yohei"},{"t":"d","s":"「どかねえ」","f":"yohei"},{"t":"d","s":"「退けって言ってるんだ！」","f":"yohei"},{"t":"n","s":"花びらが、一気に舞い上がった。","f":"yohei"}]},{"key":"22-4","title":"殴り合い","bg":"bg_grave","dark":true,"mood":"battle","bgm":"battle2","cast":["ryoma","yohei"],"lines":[{"t":"cg","v":"cg_fistfight"},{"t":"n","s":"藍色の花が、竜馬を襲った。","f":"ryoma","fx":"indigo"},{"t":"n","s":"竜馬は、避けなかった。","f":"ryoma"},{"t":"n","s":"袖が裂け、頬が切れ、血が飛んだ。それでも、竜馬は、退かなかった。","f":"ryoma"},{"t":"d","s":"「やめろよ、竜馬。スキルを使えよ」","f":"ryoma"},{"t":"d","s":"「使わねえ」","f":"ryoma"},{"t":"d","s":"「なんで」","f":"ryoma"},{"t":"d","s":"「今のお前に、スキルで向かったら、本当に死ぬだろ。この花と同じになる」","f":"ryoma"},{"t":"n","s":"竜馬は、血を拭った。","f":"ryoma"},{"t":"d","s":"「俺は、拳でいい。拳で、止める」","f":"ryoma"},{"t":"n","s":"竜馬は、一歩、踏み込んだ。","f":"ryoma"},{"t":"n","s":"花びらが、腕を切った。竜馬は、そのまま、もう一歩。","f":"ryoma"},{"t":"d","s":"「……っ！」","f":"ryoma"},{"t":"n","s":"拳が、耀平の頬に当たった。","f":"yohei"},{"t":"n","s":"軽くはなかった。耀平は、地面に転がった。","f":"yohei"},{"t":"d","s":"「立てよ。この程度じゃ、まだ終わらねえ」","f":"yohei"},{"t":"n","s":"耀平は、立ち上がった。","f":"yohei"},{"t":"n","s":"花びらが、再び舞う。竜馬は、やはり、逃げなかった。","f":"ryoma"},{"t":"d","s":"「……なんでだ」","f":"ryoma"},{"t":"d","s":"「ああ？」","f":"ryoma"},{"t":"d","s":"「なんで、逃げないんだよ！」","f":"ryoma"},{"t":"d","s":"「逃げるやつに、ライバルは名乗れねえだろ」","f":"ryoma"},{"t":"n","s":"竜馬は、笑った。","f":"ryoma","m":"happy"},{"t":"n","s":"血だらけの顔で。","f":"ryoma"},{"t":"d","s":"「体育祭で、俺がアンカー走ったとき、お前、待ってたよな。ゴールの手前で、一番大きな声で」","f":"ryoma"},{"t":"d","s":"「……」","f":"ryoma"},{"t":"d","s":"「俺は、あれが忘れられねえんだ」","f":"ryoma"},{"t":"n","s":"耀平の手が、止まった。","f":"yohei"},{"t":"d","s":"「ありがとな。あのとき、言えてなかったこと、もう一つある」","f":"yohei"},{"t":"d","s":"「……何」","f":"yohei"},{"t":"d","s":"「負けたくねえって思ってた。でも、今は違う。ライバルとしてじゃねえ。……友達として、お前に戻ってほしい」","f":"yohei"},{"t":"n","s":"花びらの色が、わずかに揺れた。","f":"yohei"},{"t":"d","s":"「……黙れ」","f":"yohei"},{"t":"d","s":"「黙らねえ。俺は、お前を殴ってでも引き戻す」","f":"yohei"},{"t":"n","s":"竜馬は、もう一度、拳を握った。","f":"ryoma"},{"t":"n","s":"藍の花が、竜馬の胸を貫く直前、耀平は自分の手を、あらん限りの力で引いた。","f":"ryoma"}]},{"key":"22-5","title":"色が戻る","bg":"bg_grave","dark":false,"mood":"climax","bgm":"climax2","cast":["yohei","ryoma"],"lines":[{"t":"n","s":"花びらが、地面に落ちた。"},{"t":"n","s":"藍色の花びらが、ひとつ、ひとつ。","fx":"indigo"},{"t":"n","s":"その中に、一枚だけ、違う色が混じっていた。"},{"t":"n","s":"薄紅色だった。"},{"t":"d","s":"「……竜馬」"},{"t":"d","s":"「おう」"},{"t":"d","s":"「俺、今——」"},{"t":"d","s":"「分かってる。分かってるから、もういい」"},{"t":"n","s":"竜馬は、血を拭いて、耀平の隣に座り込んだ。","f":"ryoma"},{"t":"n","s":"耀平の目から、涙がこぼれた。","f":"yohei","m":"sad"},{"t":"n","s":"やっと、泣けた。","f":"yohei"},{"t":"d","s":"「……俺のせいで」","f":"yohei"},{"t":"d","s":"「誰のせいでもねえよ」","f":"yohei"},{"t":"d","s":"「耀平と、巌と、みんなが——」","f":"yohei"},{"t":"d","s":"「バカ。死んだやつを、盾にするな」","f":"yohei"},{"t":"n","s":"竜馬は、乱暴に耀平の頭を押さえた。","f":"ryoma"},{"t":"d","s":"「あいつらは、守って死んだ。お前が潰れたら、その意味が、なくなるだろ」","f":"ryoma"},{"t":"n","s":"耀平は、しばらくそのままでいた。","f":"yohei"},{"t":"n","s":"やがて、掠れた声で言った。","f":"yohei"},{"t":"d","s":"「……ゴール前で、確かに、叫んだよ。竜馬の名前を」","f":"yohei"},{"t":"d","s":"「知ってる」","f":"yohei"},{"t":"d","s":"「……ありがとう。戻ってきてくれて」","f":"yohei"},{"t":"d","s":"「俺は何もしてねえよ。お前が、自分で戻ってきたんだ」","f":"yohei"},{"t":"n","s":"竜馬は、顔を背けた。","f":"ryoma"},{"t":"n","s":"耐えているように見えたが、耀平は、見ないふりをした。","f":"yohei"}]},{"key":"22-6","title":"乃亜と柚月","bg":"bg_grave","dark":true,"mood":"climax","bgm":"climax2","cast":["yuzuki","noa","yohei"],"lines":[{"t":"d","s":"「……やっぱり、ここだった」"},{"t":"n","s":"声がした。"},{"t":"n","s":"振り返ると、乃亜と柚月が、花壇の前に立っていた。","f":"noa"},{"t":"n","s":"柚月は、変わらず車椅子だった。でも、自分で車輪を回している。","f":"yuzuki"},{"t":"d","s":"「……乃亜。柚月」","f":"yuzuki"},{"t":"d","s":"「毎週、ここに来てるんだよ。竜馬も、柚月も」","f":"yuzuki"},{"t":"d","s":"「あんたが来るかもって、メモを置いていった人がいるから」","f":"yuzuki"},{"t":"n","s":"乃亜は、腹を立てた顔で、泣いていた。","f":"noa","m":"sad"},{"t":"d","s":"「このバカ。この半年、何してたの」","f":"noa"},{"t":"d","s":"「……訓練」","f":"noa"},{"t":"d","s":"「それで、殴られて泣いてんの？　ダサい」","f":"noa"},{"t":"d","s":"「……ごめん」","f":"noa"},{"t":"d","s":"「謝んな。おかえり」","f":"noa"},{"t":"n","s":"乃亜は、耀平の頭を、くしゃっと撫でた。","f":"noa"},{"t":"n","s":"柚月は、車椅子を耀平の前へ進めた。","f":"yuzuki"},{"t":"d","s":"「耀平」","f":"yuzuki"},{"t":"d","s":"「……」","f":"yuzuki"},{"t":"d","s":"「最初に言う。あの日、あなたのせいじゃない。私の選んだことだった」","f":"yuzuki"},{"t":"d","s":"「でも——」","f":"yuzuki"},{"t":"d","s":"「私も、強くなる。この半年で、歩けるようになる」","f":"yuzuki"},{"t":"n","s":"柚月は、車椅子の肩掛けに手をついて、立ち上がろうとした。","f":"yuzuki"},{"t":"n","s":"膝が、震える。それでも、立ち上がった。","f":"yuzuki"},{"t":"n","s":"一歩。二歩。","f":"yuzuki"},{"t":"d","s":"「……どう？」","f":"yuzuki"},{"t":"d","s":"「……すごい」","f":"yuzuki"},{"t":"d","s":"「でしょ」","f":"yuzuki"},{"t":"n","s":"柚月は、初めて、笑った。","f":"yuzuki","m":"happy"},{"t":"n","s":"耀平は、その笑顔を、一生忘れないと思った。","f":"yohei"}]},{"key":"22-7","title":"学園へ","bg":"bg_gate","dark":false,"mood":"climax","bgm":"climax2","cast":["yohei","jin","principal"],"lines":[{"t":"n","s":"翌日、耀平は、正門から学園に入った。","f":"yohei"},{"t":"n","s":"隠れなどせず、堂々と。","f":"yohei"},{"t":"n","s":"門の横で、迅が待っていた。","f":"jin"},{"t":"d","s":"「……抱え込んでおいて、最初からこれか」","f":"jin"},{"t":"d","s":"「迅さん、止めなかったんですね」","f":"jin"},{"t":"d","s":"「止めて止まるツラじゃねえだろ」","f":"jin"},{"t":"n","s":"迅は、わずかに口角を上げた。","f":"jin"},{"t":"n","s":"学園長室では、学園長が、片腕を吊ったまま待っていた。","f":"principal"},{"t":"d","s":"「戻ってきたか」","f":"principal"},{"t":"d","s":"「はい」","f":"principal"},{"t":"d","s":"「顔つきが、変わった」","f":"principal"},{"t":"d","s":"「……色が、少しだけ、戻りました」","f":"principal"},{"t":"d","s":"「そうか」","f":"principal"},{"t":"n","s":"学園長は、窓の外を見た。","f":"principal"},{"t":"d","s":"「卒業式の日、天冠は来る。学園とSHITで、迎え撃つ」","f":"principal"},{"t":"d","s":"「はい」","f":"principal"},{"t":"d","s":"「金井君」","f":"principal"},{"t":"d","s":"「はい」","f":"principal"},{"t":"d","s":"「君の席は、まだ、E組にある」","f":"principal"},{"t":"n","s":"耀平は、深く頭を下げた。","f":"yohei"},{"t":"n","s":"教室の扉を開けると、残ったE組の面々が、振り返った。","f":"yohei"},{"t":"d","s":"「……おかえり、金井」","f":"yohei"},{"t":"d","s":"「ただいま」","f":"yohei"},{"t":"n","s":"空いた席が、六つ。","f":"yohei"},{"t":"n","s":"そのどれも、綺麗に拭かれていた。","f":"yohei"},{"t":"n","s":"耀平は、自分の席に座った。","f":"yohei"},{"t":"n","s":"窓の外で、花壇の花が、少しだけ揺れた。","f":"yohei"}]}]},{"n":23,"title":"決戦（前半）","sub":"高校編","era":"high","lead":"卒業式の朝、学園とSHITが並んで空を見上げる。夜が降りてくる前に、耀平は最後の仕込みを終えていた。","scenes":[{"key":"23-1","title":"卒業式の朝","bg":"bg_graduation","dark":true,"mood":"tense","bgm":"tense1","cast":["yohei","jin"],"lines":[{"t":"n","s":"三月の空は、よく晴れていた。"},{"t":"n","s":"花壇の六つの花が、風に揺れている。耀平はその前で、静かに手を合わせた。","f":"yohei"},{"t":"d","s":"「行ってくる」","f":"yohei"},{"t":"n","s":"返事はなかった。それでも、花は一度だけ、強く揺れた。","f":"yohei"},{"t":"n","s":"講堂には、卒業生の席が整えられていた。九十九先輩も結城先輩も、制服の胸に小さな花を挿している。だが、誰も笑っていなかった。","f":"yohei"},{"t":"d","s":"「来るぞ」","f":"yohei"},{"t":"d","s":"「分かってます」","f":"yohei"},{"t":"d","s":"「怖いか」","f":"yohei"},{"t":"d","s":"「……怖いです。でも、逃げません」","f":"yohei"},{"t":"n","s":"迅は、短く頷いた。","f":"jin"},{"t":"n","s":"校庭の隅では、SHITの四人と子供が、並んで空を見ていた。","f":"jin"},{"t":"d","s":"「Aさん」","f":"jin"},{"t":"d","s":"「何だ」","f":"jin"},{"t":"d","s":"「作戦、確認させてください」","f":"jin"},{"t":"d","s":"「簡単だ。お前が花を撒く。ボスが領域を張る。その一瞬で、全員が動く」","f":"jin"},{"t":"n","s":"Aは無精髭を撫でながら、にやりと笑った。","f":"jin","m":"happy"},{"t":"d","s":"「ま、その後はアドリブだがな」","f":"jin"},{"t":"d","s":"「それ、作戦って言うんですか」","f":"jin"},{"t":"d","s":"「言う」","f":"jin"}]},{"key":"23-2","title":"仕込み","bg":"bg_schoolyard_middle","dark":true,"mood":"tense","bgm":"tense1","cast":["ryoma","yohei","noa"],"lines":[{"t":"n","s":"耀平は、一人で校庭を歩いていた。","f":"yohei"},{"t":"n","s":"花びらを、一枚ずつ、地面に置いていく。桜、藤、菊、菫。色とりどりの花びらが、芝生の上に点々と並んだ。","f":"yohei"},{"t":"i","s":"（領域が張られる前に、先にここにある花びらなら）","f":"yohei"},{"t":"n","s":"Cの言葉を、思い出す。","f":"yohei"},{"t":"i","s":"（鈍る前に、動かせる）","f":"yohei"},{"t":"d","s":"「手伝う」","f":"yohei"},{"t":"n","s":"声がして、振り向くと、竜馬が立っていた。","f":"ryoma"},{"t":"d","s":"「これ、どこに置けばいい」","f":"ryoma"},{"t":"d","s":"「……竜馬、スキルは」","f":"ryoma"},{"t":"d","s":"「使わねえよ。ただの花びら拾いだ」","f":"ryoma"},{"t":"n","s":"竜馬は、ぶっきらぼうに花びらを受け取った。","f":"ryoma"},{"t":"cg","v":"cg_yuzuki_standalone"},{"t":"n","s":"乃亜も、柚月も、気づけばそこにいた。柚月は杖をついていたが、自分の足で立っている。","f":"noa"},{"t":"d","s":"「花びらの数、足りる？」","f":"noa"},{"t":"d","s":"「足りないかも」","f":"noa"},{"t":"d","s":"「じゃあ、みんなで作ればいい」","f":"noa"},{"t":"n","s":"乃亜が笑って、小さな水の粒を空に浮かべた。それが日の光を受けて、花びらのように光った。","f":"noa","fx":"flash"},{"t":"n","s":"耀平は、胸の奥が熱くなるのを感じた。","f":"yohei"},{"t":"i","s":"（この人たちを、守りたい）","f":"yohei"},{"t":"n","s":"花びらの色が、足元で、わずかに薄紅に染まった。","f":"yohei"}]},{"key":"23-3","title":"夜が来る","bg":"bg_schoolyard_middle","dark":true,"mood":"tense","bgm":"tense1","cast":["mumyo","genzo","hotaru"],"lines":[{"t":"n","s":"正午を、少し過ぎた頃だった。"},{"t":"n","s":"空が、暗くなった。"},{"t":"n","s":"雲ではない。日が落ちたのでもない。ただ、校庭の端から、夜が静かに染み込んでくる。"},{"t":"d","s":"「来た」"},{"t":"n","s":"誰かが呟いた。"},{"t":"n","s":"門の向こうから、七つの影が歩いてきた。"},{"t":"n","s":"先頭は、黒鉄玄蔵。その後ろに、細身の男と、風を纏った女。岩のような巨漢、時計を持った青年、耳に無数のピアスをつけた男、白い外套の女。","f":"genzo"},{"t":"n","s":"八天。第六席を欠いた、七人。","f":"genzo"},{"t":"n","s":"その第六席は、こちら側にいた。","f":"genzo"},{"t":"n","s":"SHITの隊員の隣で、薄紫の髪の女が、かつての仲間たちを眺めている。紫苑蛍。決戦の日に限って、地下から出ることを許された、元第六席だった。","f":"hotaru"},{"t":"d","s":"「みんな、怖い顔。……耀平くん、約束、忘れないでね」","f":"hotaru"},{"t":"d","s":"「今、それ言います？」","f":"hotaru"},{"t":"d","s":"「今だから言うの」","f":"hotaru"},{"t":"n","s":"乃亜が、無言で蛍を睨んだ。柚月は、困ったように小さく笑った。","f":"noa","m":"anger"},{"t":"n","s":"そして、一番後ろを、あの男が歩いていた。","f":"noa"},{"t":"d","s":"「やあ、約束通り来たよ」","f":"noa"},{"t":"n","s":"天城無明は、穏やかに微笑んだ。","f":"mumyo","m":"happy"},{"t":"d","s":"「卒業おめでとう、と言うべきかな」","f":"mumyo"},{"t":"d","s":"「言わなくていい」","f":"mumyo"},{"t":"d","s":"「そうかい」","f":"mumyo"},{"t":"n","s":"無明は、校庭を見渡した。咲いている花びらに目を留めて、少し首を傾げた。","f":"mumyo"},{"t":"d","s":"「ほう。準備をしてきたのか」","f":"mumyo"},{"t":"d","s":"「ああ」","f":"mumyo"},{"t":"d","s":"「感心だね。では、始めようか」","f":"mumyo"},{"t":"n","s":"無明が、手を上げた。","f":"mumyo"},{"t":"d","s":"「無明長夜」","f":"mumyo"},{"t":"n","s":"夜が、降りた。","f":"mumyo"}]},{"key":"23-4","title":"一瞬","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["mumyo","yohei","jin"],"lines":[{"t":"n","s":"視界が閉じていく。"},{"t":"n","s":"音が遠くなる。体が重くなる。スキルが、鈍る。"},{"t":"i","s":"（今だ）"},{"t":"n","s":"耀平は、拳を握った。","f":"yohei"},{"t":"n","s":"足元の花びらが、一斉に光った。","f":"yohei","fx":"flash"},{"t":"n","s":"夜が来る前に、そこにあった花びらは、鈍らなかった。","f":"yohei"},{"t":"cg","v":"cg_first_bloom"},{"t":"d","s":"「咲け——！」","f":"yohei"},{"t":"n","s":"千の花びらが、無明に向かって飛んだ。","f":"mumyo"},{"t":"n","s":"無明の動きが、一瞬だけ、止まった。","f":"mumyo"},{"t":"d","s":"「……ほう」","f":"mumyo"},{"t":"d","s":"「今です！」","f":"mumyo"},{"t":"n","s":"全員が、一斉に動いた。","f":"mumyo"},{"t":"n","s":"迅の刀が風を切った。蓮の剣が夜を割った。SHITの四人が、七人に向かって走り出した。","f":"jin"},{"t":"d","s":"「作戦、成功だ！」","f":"jin"},{"t":"d","s":"「ここからはアドリブだ！」","f":"jin"},{"t":"d","s":"「やっぱり作戦じゃないじゃないですか！」","f":"jin"},{"t":"n","s":"子供が、いつの間にか無明の目の前に立っていた。","f":"mumyo"},{"t":"d","s":"「おじさん、ひさしぶり」","f":"mumyo"},{"t":"d","s":"「……君か」","f":"mumyo"},{"t":"d","s":"「うん。ぼくも、強くなったよ」","f":"mumyo"},{"t":"n","s":"子供の掌に、真っ黒な光が灯った。","f":"mumyo"},{"t":"n","s":"無明の目が、わずかに細くなった。","f":"mumyo"}]},{"key":"23-5","title":"それぞれの相手","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["ren","saku","jin"],"lines":[{"t":"n","s":"戦場が、七つに割れた。"},{"t":"n","s":"蓮は、細身の男と向き合っていた。八天、第二席。宵待朔。","f":"ren"},{"t":"d","s":"「九条蓮。随分と痩せたな」","f":"ren"},{"t":"d","s":"「お前に言われたくない」","f":"ren"},{"t":"d","s":"「影縫幻夢」","f":"ren"},{"t":"n","s":"朔の影が、蓮の足元に絡みついた。蓮は剣で影を斬ったが、斬った端から影が増えていく。","f":"saku"},{"t":"d","s":"「厄介だな」","f":"saku"},{"t":"d","s":"「そうだろう。この影は、斬るほど増えるのだ」","f":"saku"},{"t":"d","s":"「ならば、斬らなければいい」","f":"saku"},{"t":"n","s":"蓮は、剣を鞘に収めた。","f":"ren"},{"t":"n","s":"朔の眉が、わずかに動いた。","f":"saku"},{"t":"n","s":"迅は、風を纏った女と向き合っていた。八天、第三席。鳳翠嵐。","f":"jin"},{"t":"d","s":"「剣聖の息子、か」","f":"jin"},{"t":"d","s":"「その呼び方は嫌いだ」","f":"jin"},{"t":"d","s":"「翠嵐疾風」","f":"jin"},{"t":"n","s":"風が、刃になって迅を襲った。迅は刀で受け、半歩、後ろへ下がる。","f":"jin"},{"t":"i","s":"（速い）","f":"jin"},{"t":"n","s":"空を飛ぶ相手に、地を這う刀は届かない。翠嵐は笑って、高く舞い上がった。","f":"suiran"},{"t":"d","s":"「飛べない者に、勝ち目はないぞ」","f":"suiran"},{"t":"d","s":"「そうか」","f":"suiran"},{"t":"n","s":"迅は、刀を低く構えた。","f":"jin"},{"t":"n","s":"父の構えだった。","f":"jin"}]},{"key":"23-6","title":"玄蔵","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle1","cast":["yohei","genzo","noa"],"lines":[{"t":"cg","v":"cg_vs_genzo"},{"t":"d","s":"「来い、花の少年」"},{"t":"n","s":"黒鉄玄蔵は、校庭の中央で待っていた。","f":"genzo"},{"t":"n","s":"耀平は、ゆっくりと歩み寄った。","f":"yohei"},{"t":"d","s":"「お前を倒す。そのために、ここまで来た」","f":"yohei"},{"t":"d","s":"「そうか」","f":"yohei"},{"t":"d","s":"「巌の分も、慎吾の分も、陽太の分も」","f":"yohei"},{"t":"d","s":"「名前を、覚えているのだな」","f":"yohei"},{"t":"d","s":"「忘れるはずがない」","f":"yohei"},{"t":"n","s":"玄蔵は、わずかに目を細めた。","f":"genzo"},{"t":"d","s":"「ならば、俺も名乗ろう。黒鉄玄蔵。お前が背負うその名の分だけ、お前を潰す」","f":"genzo"},{"t":"n","s":"重圧が、落ちた。","f":"genzo"},{"t":"n","s":"夜の領域の中で、その重さは倍になっていた。地面が割れ、空気が軋む。耀平は膝をついた。","f":"yohei"},{"t":"i","s":"（重い……）","f":"yohei"},{"t":"d","s":"「どうした。軽いか」","f":"yohei"},{"t":"n","s":"玄蔵が、一歩、踏み出した。","f":"genzo"},{"t":"n","s":"耀平の花びらが、鈍り始める。","f":"yohei"},{"t":"i","s":"（駄目だ。夜が、花を消していく）","f":"yohei"},{"t":"n","s":"その時だった。","f":"yohei"},{"t":"d","s":"「耀平！」","f":"yohei"},{"t":"n","s":"乃亜の声だった。","f":"noa"},{"t":"d","s":"「しっかりしなさいよ！　あんたの花は、そんなに軽くないでしょ！」","f":"noa"},{"t":"n","s":"続いて、竜馬の声。","f":"ryoma"},{"t":"d","s":"「立て！　まだ終わってねえだろ！」","f":"ryoma"},{"t":"n","s":"柚月の声も、聞こえた。","f":"yuzuki"},{"t":"d","s":"「耀平、咲いて」","f":"yuzuki"},{"t":"n","s":"耀平は、顔を上げた。","f":"yohei"},{"t":"n","s":"玄蔵の向こうに、彼らが立っていた。自分の足で、自分の意志で、そこに立っていた。","f":"genzo"},{"t":"i","s":"（そうだ）","f":"genzo"},{"t":"i","s":"（守りたいんだ）","f":"genzo"},{"t":"n","s":"花びらの色が、はっきりと、薄紅に染まった。","f":"genzo"},{"t":"d","s":"「……玄蔵」","f":"genzo"},{"t":"d","s":"「何だ」","f":"genzo"},{"t":"d","s":"「俺の花は、軽くない」","f":"genzo"},{"t":"n","s":"耀平は、立ち上がった。","f":"yohei"},{"t":"n","s":"夜の中で、一輪だけ、桜が咲いた。","f":"yohei"}]}]},{"n":24,"title":"決戦（後半）と卒業式","sub":"高校編","era":"high","lead":"夜の中で、桜が咲く。耀平の花は、闇に負けない形へと変わっていく。長い一日が終わり、旅立つ人を見送る朝が来る。","scenes":[{"key":"24-1","title":"夜桜繚蘭","bg":"bg_schoolyard_middle","dark":true,"mood":"awaken","bgm":"battle_emiya","cast":["genzo","yohei"],"lines":[{"t":"n","s":"玄蔵の重圧が、真上から落ちてきた。","f":"genzo"},{"t":"n","s":"耀平は、避けなかった。","f":"yohei"},{"t":"i","s":"（夜が、花を消すなら）","f":"yohei"},{"t":"i","s":"（夜の中でも、咲く花になればいい）","f":"yohei"},{"t":"n","s":"腰の刀を、抜いた。","f":"yohei"},{"t":"n","s":"祖父に教わった、ただの刃引きの刀だった。その刃に、細かな模様が浮かんでいる。波のような刃文が、ゆっくりと、花びらの形に変わっていく。","f":"yohei"},{"t":"n","s":"一枚。二枚。やがて、刀身いっぱいに、桜が咲いた。","f":"yohei"},{"t":"d","s":"「……何だ、それは」","f":"yohei"},{"t":"cg","v":"cg_yozakura"},{"t":"d","s":"「夜桜繚蘭」","f":"yohei","fx":"yozakura"},{"t":"n","s":"耀平の声は、静かだった。","f":"yohei"},{"t":"n","s":"暗い空の下で、桜がひらひらと舞い始める。昼の桜よりも、ずっと白く、ずっと淡く光っていた。","f":"yohei"},{"t":"d","s":"「花は、夜があるから綺麗に見えるんだ」","f":"yohei"},{"t":"d","s":"「戯れ言を」","f":"yohei"},{"t":"n","s":"玄蔵が、拳を握った。重圧が、耀平を押しつぶそうと迫る。","f":"genzo"},{"t":"n","s":"しかし、花びらは潰れなかった。","f":"genzo"},{"t":"n","s":"重さに逆らわず、ふわりと、重さの隙間を抜けていく。","f":"genzo"},{"t":"d","s":"「……何？」","f":"genzo"},{"t":"n","s":"花びらが、玄蔵の肩に触れた。それだけで、玄蔵の外套が、音もなく裂けた。","f":"genzo"}]},{"key":"24-2","title":"影を斬る","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["ren","saku"],"lines":[{"t":"n","s":"蓮の剣は、まだ鞘の中にあった。","f":"ren"},{"t":"n","s":"宵待朔の影が、蓮の体を縛り上げていく。足、腕、胸。それでも蓮は、動かなかった。","f":"saku"},{"t":"d","s":"「諦めたか」","f":"saku"},{"t":"d","s":"「いいや」","f":"saku"},{"t":"n","s":"蓮は、目を閉じた。","f":"ren"},{"t":"d","s":"「影は、斬れば増える。ならば、影を斬る必要はない」","f":"ren"},{"t":"d","s":"「……何を」","f":"ren"},{"t":"d","s":"「影の主を、斬る」","f":"ren"},{"t":"n","s":"朔の顔色が、変わった。","f":"saku"},{"t":"n","s":"影が増えているのではない。影の根元は、いつも一つだ。朔の足元の、その一点。蓮は、最初からそれだけを見ていた。","f":"saku"},{"t":"n","s":"鞘から、剣が走った。","f":"saku"},{"t":"n","s":"一太刀。","f":"saku"},{"t":"n","s":"縛っていた影が、一斉にほどけた。朔の膝が、崩れる。","f":"saku"},{"t":"d","s":"「……いつ、見抜いた」","f":"saku"},{"t":"d","s":"「お前が、私の足を狙った時だ。守りたい場所ほど、人は先に隠す」","f":"saku"},{"t":"n","s":"蓮は、剣を収めた。","f":"ren"},{"t":"d","s":"「学園には、副会長と書記がいた。私は、守れなかった。……だから、二度と、目を逸らさない」","f":"ren"}]},{"key":"24-3","title":"空を見る刀","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["suiran","jin","hotaru"],"lines":[{"t":"n","s":"迅は、まだ地面に立っていた。","f":"jin"},{"t":"n","s":"鳳翠嵐は、はるか上空から風の刃を降らせている。避けるだけで精一杯だった。","f":"suiran"},{"t":"d","s":"「どうした、剣聖の息子。飛べなければ、届かないぞ」","f":"suiran"},{"t":"d","s":"「そうだな」","f":"suiran"},{"t":"n","s":"迅は、刀を低く構えた。","f":"jin"},{"t":"n","s":"その肩越しに、紫の光が、ふわりと舞い上がった。","f":"jin"},{"t":"d","s":"「手伝ってあげる。耀平くんのお友達でしょ」","f":"jin"},{"t":"d","s":"「……誰が友達だ」","f":"jin"},{"t":"d","s":"「いいから。あの子、風で毒を散らすのは得意だけど、自分の羽までは守れないのよ」","f":"jin"},{"t":"n","s":"蛍だった。紫の群れが、細い糸のように空へ昇っていく。翠嵐の纏う風に、紫の粉が、ほんのわずかに混じった。","f":"hotaru"},{"t":"d","s":"「——っ、蛍、貴様！」","f":"hotaru"},{"t":"d","s":"「ごめんね、翠嵐ちゃん。わたし、もう、そっちじゃないの」","f":"hotaru"},{"t":"n","s":"翠嵐の風が、ほんの少しだけ、乱れた。痺れた羽では、空に長くは留まれない。","f":"suiran"},{"t":"n","s":"翠嵐が、歯を食いしばった。","f":"suiran"},{"t":"d","s":"「ならば、墜ちろ」","f":"suiran"},{"t":"n","s":"風が、渦を巻いた。翠嵐は急降下に入る。真上から、一直線に。","f":"suiran"},{"t":"n","s":"速かった。目で追えないほど。","f":"suiran"},{"t":"n","s":"だが、迅は目を閉じていた。","f":"jin"},{"t":"i","s":"（父さんは、いつも言っていた。速い相手には、動くな）","f":"jin"},{"t":"i","s":"（相手が来る場所に、先に、刀を置いておけ）","f":"jin"},{"t":"n","s":"風が、頬をかすめた。","f":"jin"},{"t":"n","s":"迅の刀が、ゆっくりと、斜めに上がった。","f":"jin"},{"t":"n","s":"何かを斬った感触があった。","f":"jin"},{"t":"n","s":"翠嵐が、地面に転がった。風が、止む。","f":"suiran"},{"t":"d","s":"「……お前、飛べないのでは、なかったのか」","f":"suiran"},{"t":"d","s":"「飛ぶ必要は、なかった」","f":"suiran"},{"t":"n","s":"迅は、刀を下ろした。","f":"jin"},{"t":"d","s":"「あんたが、降りてくれたからな」","f":"jin"}]},{"key":"24-4","title":"姉と妹","bg":"bg_schoolyard_middle","dark":false,"mood":"sad","bgm":"sad2","cast":["setsuka","yuzuki","yohei"],"lines":[{"t":"n","s":"雪華は、校庭の端に立っていた。","f":"setsuka"},{"t":"n","s":"白い外套の少女だった。柚月によく似た目をしている。","f":"yuzuki"},{"t":"d","s":"「お姉ちゃん」","f":"yuzuki"},{"t":"d","s":"「……雪華」","f":"yuzuki"},{"t":"d","s":"「迎えに来たよ。一緒に帰ろう」","f":"yuzuki"},{"t":"n","s":"柚月は、杖を握りしめたまま、動かなかった。","f":"yuzuki"},{"t":"d","s":"「ごめんね。ずっと、話せなくて」","f":"yuzuki"},{"t":"d","s":"「柚月」","f":"yuzuki"},{"t":"d","s":"「耀平。……今、話すね」","f":"yuzuki"},{"t":"n","s":"柚月は、静かに言った。","f":"yuzuki"},{"t":"d","s":"「私と雪華は、小さい頃、天冠にいたの」","f":"yuzuki"},{"t":"d","s":"「え」","f":"yuzuki"},{"t":"d","s":"「私は、逃げた。雪華は、逃げられなかった。……痛みを拒むスキルは、そこで、できたんだと思う」","f":"yuzuki"},{"t":"n","s":"雪華の目が、揺れた。","f":"setsuka"},{"t":"d","s":"「お姉ちゃんは、私を置いていった」","f":"setsuka"},{"t":"d","s":"「うん。ごめん。ずっと、謝りたかった」","f":"setsuka"},{"t":"d","s":"「謝らないでよ。帰ってきて。一緒なら、もう、痛くないって、玄蔵さんが——」","f":"setsuka"},{"t":"d","s":"「それは、嘘だよ」","f":"setsuka"},{"t":"n","s":"柚月は、はっきりと言った。","f":"yuzuki"},{"t":"d","s":"「痛みはね、なくならない。でも、一人じゃなければ、耐えられる。……私は、ここで、それを知った」","f":"yuzuki"},{"t":"n","s":"柚月は、手を差し出した。","f":"yuzuki"},{"t":"d","s":"「雪華。帰ろう。こっちに」","f":"yuzuki"},{"t":"n","s":"雪華は、長い間、その手を見ていた。","f":"setsuka"},{"t":"n","s":"唇が、震えた。","f":"setsuka"},{"t":"d","s":"「……やだ。やだよ。今更、そんな」","f":"setsuka"},{"t":"d","s":"「うん」","f":"setsuka"},{"t":"d","s":"「でも、……お姉ちゃん」","f":"setsuka"},{"t":"n","s":"雪華の足が、一歩だけ、前に出た。","f":"setsuka"},{"t":"n","s":"その時、夜が揺れた。","f":"setsuka"}]},{"key":"24-5","title":"無明の退却","bg":"bg_schoolyard_middle","dark":true,"mood":"battle","bgm":"battle2","cast":["mumyo","setsuka","genzo"],"lines":[{"t":"n","s":"子供の黒い光が、無明の腕を貫いた。","f":"mumyo"},{"t":"d","s":"「……やるね」","f":"mumyo"},{"t":"d","s":"「へへ。ぼく、ちゃんとした隊員だもん」","f":"mumyo"},{"t":"n","s":"Aが横から殴りかかり、Bの爪が閃いた。Cの計算が、無明の足元を崩す。Dの拳が、その背中を捉える。","f":"mumyo"},{"t":"n","s":"無明は、後ろへ跳んだ。","f":"mumyo"},{"t":"n","s":"初めて、その顔から、微笑みが消えていた。","f":"mumyo","m":"happy"},{"t":"d","s":"「SHIT……やはり、厄介だ」","f":"mumyo"},{"t":"n","s":"そこへ、花びらが降った。","f":"mumyo"},{"t":"n","s":"夜桜繚蘭。白い花びらが、無明の足元から立ち昇る。","f":"mumyo","fx":"yozakura"},{"t":"d","s":"「無明」","f":"mumyo"},{"t":"n","s":"玄蔵を倒した耀平が、静かに歩いてきた。","f":"genzo"},{"t":"d","s":"「この花は、夜の中でも咲く。あなたの夜は、もう、俺たちを閉じ込められない」","f":"genzo"},{"t":"n","s":"無明は、桜を見つめた。","f":"mumyo"},{"t":"n","s":"しばらく、何も言わなかった。","f":"mumyo"},{"t":"d","s":"「……美しいね」","f":"mumyo"},{"t":"d","s":"「俺の花じゃない。みんなで、咲かせた花だ」","f":"mumyo"},{"t":"n","s":"無明は、小さく笑った。","f":"mumyo","m":"happy"},{"t":"d","s":"「そうか。では、今日は、整理を延期しよう」","f":"mumyo"},{"t":"n","s":"夜が、ほどけていく。","f":"mumyo"},{"t":"n","s":"倒れた玄蔵と翠嵐と朔を、無明は影に引き寄せた。いや、引き寄せようとして、迅と蓮が前に立った。","f":"genzo"},{"t":"d","s":"「置いていけ」","f":"genzo"},{"t":"d","s":"「……ふむ。三人は、君たちに預けよう。その代わり」","f":"genzo"},{"t":"n","s":"無明は、校庭の端を見た。","f":"mumyo"},{"t":"d","s":"「雪華。帰るよ」","f":"mumyo"},{"t":"n","s":"雪華は、一度だけ、振り返った。","f":"setsuka"},{"t":"n","s":"柚月は、手を伸ばしたまま、動かなかった。","f":"yuzuki"},{"t":"d","s":"「お姉ちゃん。……また、来る」","f":"yuzuki"},{"t":"d","s":"「待ってる」","f":"yuzuki"},{"t":"n","s":"雪華の姿が、夜の中へ溶けた。","f":"setsuka"},{"t":"n","s":"そして、夜が明けた。","f":"setsuka"}]},{"key":"24-6","title":"朝","bg":"bg_gate","dark":true,"mood":"night","bgm":"night1","cast":["yohei","jin","ryoma"],"lines":[{"t":"n","s":"空が、青かった。"},{"t":"n","s":"校庭には、白い花びらが、一面に降り積もっていた。倒れた八天の三人は、SHITの手で運ばれていく。"},{"t":"n","s":"耀平は、膝をついた。","f":"yohei"},{"t":"n","s":"全身から、力が抜けた。","f":"yohei"},{"t":"d","s":"「……終わった、の？」","f":"yohei"},{"t":"d","s":"「今日は、な」","f":"yohei"},{"t":"n","s":"迅が、隣に座った。","f":"jin"},{"t":"d","s":"「無明は、また来る。八天も、新しい顔を揃えてくるだろう」","f":"jin"},{"t":"d","s":"「はい」","f":"jin"},{"t":"d","s":"「だが、今日は、勝った」","f":"jin"},{"t":"n","s":"迅は、空を見上げた。","f":"jin"},{"t":"d","s":"「父さんにも、聞こえてるかな」","f":"jin"},{"t":"d","s":"「きっと」","f":"jin"},{"t":"n","s":"竜馬が、駆け寄ってきた。","f":"ryoma"},{"t":"d","s":"「おい、耀平！　生きてるか！」","f":"ryoma"},{"t":"d","s":"「うん」","f":"ryoma"},{"t":"d","s":"「なら、立て。決着つけられるな」","f":"ryoma"},{"t":"d","s":"「え」","f":"ryoma"},{"t":"d","s":"「卒業したら、勝負だ。ちゃんと、ライバルとして」","f":"ryoma"},{"t":"n","s":"竜馬は、手を差し出した。","f":"ryoma"},{"t":"n","s":"耀平は、その手を握った。","f":"yohei"},{"t":"d","s":"「……望むところ」","f":"yohei"}]},{"key":"24-7","title":"卒業式","bg":"bg_graduation","dark":false,"mood":"climax","bgm":"climax2","cast":["ren","yohei","noa"],"lines":[{"t":"n","s":"数日後、卒業式が行われた。"},{"t":"n","s":"講堂には、六つの空席が、並べられていた。そのひとつひとつに、花が置かれている。"},{"t":"n","s":"九条蓮は、卒業生代表として、壇上に立った。","f":"ren"},{"t":"d","s":"「私は、この学園で、多くのものを失った」","f":"ren"},{"t":"n","s":"講堂が、静まり返った。","f":"ren"},{"t":"d","s":"「だが、同じだけのものを、受け取った。強さは、誰かを守るためにある。……私は、そう信じている」","f":"ren"},{"t":"n","s":"蓮の視線が、一瞬だけ、耀平を捉えた。","f":"ren"},{"t":"d","s":"「在校生の諸君。私は、先に行く。だが、後ろを振り返った時、笑って見送ってくれる者がいると、信じている」","f":"ren"},{"t":"n","s":"拍手が、鳴り響いた。","f":"ren"},{"t":"n","s":"耀平は、泣いていた。隣で、乃亜が、ハンカチを差し出してくれた。","f":"yohei","m":"sad"},{"t":"d","s":"「泣き虫」","f":"yohei"},{"t":"d","s":"「うるさい」","f":"yohei"},{"t":"d","s":"「……ねえ、耀平」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"cg","v":"cg_graduation"},{"t":"d","s":"「どこに行っても、あんたはあんただからね」","f":"yohei"},{"t":"d","s":"「うん」","f":"yohei"},{"t":"d","s":"「約束」","f":"yohei"},{"t":"d","s":"「約束」","f":"yohei"},{"t":"d","s":"「耀平くーん！　デートの約束も、忘れないでねー！」","f":"yohei"},{"t":"n","s":"講堂の外から、よく通る声が飛んできた。SHITの車の窓から、薄紫の髪が手を振っている。","f":"yohei"},{"t":"n","s":"乃亜が、深く、深くため息をついた。","f":"noa"},{"t":"d","s":"「……台無し」","f":"noa"},{"t":"d","s":"「おれのせいじゃないよ」","f":"noa"},{"t":"d","s":"「知ってる。だから、余計に腹立つの」","f":"noa"},{"t":"n","s":"少し離れたところで、柚月が、くすりと笑っていた。","f":"yuzuki"},{"t":"n","s":"式が終わった後、蓮は、校庭の花壇の前に立っていた。","f":"ren"},{"t":"d","s":"「会長」","f":"ren"},{"t":"d","s":"「もう会長ではない。……だが、悪い気はしないな」","f":"ren"},{"t":"n","s":"蓮は、小さく笑った。","f":"ren","m":"happy"},{"t":"d","s":"「金井。お前の桜は、咲いた」","f":"ren"},{"t":"d","s":"「はい」","f":"ren"},{"t":"d","s":"「ならば、次は、散らさないことだ。咲かせた花を、守り続けることが、本当の強さだ」","f":"ren"},{"t":"d","s":"「……はい」","f":"ren"},{"t":"n","s":"蓮は、花壇の花に、そっと手を触れた。","f":"ren"},{"t":"d","s":"「行ってくる。次は、先輩として会おう」","f":"ren"},{"t":"n","s":"蓮の背中が、春の光の中に遠ざかっていく。","f":"ren"},{"t":"n","s":"耀平は、その背中を、いつまでも見ていた。","f":"yohei"},{"t":"n","s":"風が、吹いた。","f":"yohei"},{"t":"n","s":"花壇の六つの花が、一斉に、同じ方向に揺れた。","f":"yohei"},{"t":"n","s":"まるで、誰かが、頷いたように。","f":"yohei"},{"t":"n","s":"耀平は、小さく息を吸った。","f":"yohei"},{"t":"i","s":"（行ってきます）","f":"yohei"},{"t":"n","s":"春は、まだ始まったばかりだった。","f":"yohei"}]}]}];
